INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('crazyguitar/cppcheatsheet/cpp', 'cpp', 'crazyguitar', 'cppcheatsheet', 'community', 'cpp crazyguitar cppcheatsheet community The cpp skill provides a complete C/C++ development reference, combining local documentation with live examples for comprehensive guidance. It benefits developers seeking detailed C/C++ syntax and development insights. C/C++开发参考大全，结合cppcheatsheet.com的实时示例和本地文档 C/C++プログラミングの総合リファレンス：cppcheatsheet.comのライブ例とローカルドキュメントをまとめたもの C/C++ 개발을 위한 종합 참조서: cppcheatsheet.com의 라이브 예제와 로컬 문서를 포함 Nuestro agente de IA para C/C++ proporciona respuestas completas y actualizadas, combinando documentación local con ejemplos en vivo de cppcheatsheet.com Notre outil d''IA pour C/C++ fournit des réponses complètes et à jour, en combinant la documentation locale avec des exemples en direct de cppcheatsheet.com Unser KI-Tool für C/C++ bietet umfassende und aktuelle Antworten, indem es lokale Dokumentation mit Live-Beispielen von cppcheatsheet.com kombiniert O C/C++ é uma linguagem de programação poderosa, com recursos avançados de programação de GPU e desenvolvimento de sistema C/C++ - это мощный язык программирования, включающий продвинутые возможности программирования GPU и системного развития سي++ هو لغة برمجة قوية، مع ميزات متقدمة للبرمجة gpu والتنمية النظمية cpp cheat sheet how to use cpp cpp vs c cpp alternative to c++ cpp install guide cpp setup for gpu programming what is cpp cpp development reference cpp system level programming cpp live examples C/C++开发 AI智能工具 cppcheatsheet.com GPU编程 系统级开发 C/C++参考大全 C/C++开发指南 Fetches live examples from https://cppcheatsheet.com/ Enhances with local documentation from the cppcheatsheet repository Provides comprehensive answers on basic syntax and advanced GPU programming Supports system-level development with detailed documentation Combines local and live resources for thorough C/C++ guidance Offers current and comprehensive C/C++ development reference cpp is a comprehensive C/C++ development reference, combining local documentation with live examples from cppcheatsheet.com for advanced development and system-level programming');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Piebald-AI/splitrail/tui', 'community', 'Piebald-AI', 'splitrail', 'Piebald-AI/splitrail', 'tui', 0, 0, 26, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.121Z', 'cdfa189fb1f61d0f56a151fa252f1922661bd1c520094c1ac01d41a53cd597d6', '{"id":"Piebald-AI/splitrail/tui","name":"tui","description":{"en":"The tui skill provides fast, cross-platform, real-time token usage tracking for various CLI tools. It benefits developers using Gemini CLI, Claude Code, and other compatible platforms.","zh":"TUI 是一个快速、跨平台的实时令牌使用跟踪和成本监控工具，支持 Gemini CLI、Claude Code 等","ja":"TUI は、Gemini CLI、Claude Code などをサポートする高速なクロスプラットフォームのリアルタイムトークン使用状況の監視とコスト管理ツール","ko":"TUI는 Gemini CLI, Claude Code 등에서 동작하는 빠른 크로스 플랫폼 실시간 토큰 사용량 모니터링 및 비용 관리 도구","es":"tui es un rastreador de uso de tokens en tiempo real y monitor de costos para Gemini CLI y otros. Proporciona actualizaciones en vivo en la interfaz de terminal","fr":"tui est un suivi en temps réel de l''utilisation des jetons et un moniteur de coûts pour Gemini CLI et d''autres. Fournit des mises à jour en temps réel dans l''interface de terminal","de":"tui ist ein Echtzeit-Überwachungstool für Token-Nutzung und ein Kosten-Monitor für Gemini CLI und andere. Bietet Live-Updates in der Terminal-Oberfläche","pt":"O TUI é um tracker de uso de tokens em tempo real para Gemini CLI, Claude Code e outros. Ele fornece atualizações em tempo real quando os arquivos de dados do analisador mudam.","ru":"TUI — это трекер использования токенов в реальном времени для Gemini CLI, Claude Code и других ИИ Агентов. Он предоставляет обновления в реальном времени при изменении файлов данных анализатора.","ar":"TUI هو مراقب لاستخدام الرموز في الوقت الفعلي لGemini CLI، Claude Code وأدوات ذكية أخرى. يتيح التحديثات في الوقت الفعلي عند تغيير ملفات بيانات المحلل"},"seo":{"title":{"en":"tui: Real-Time Token Usage Tracker Setup Guide | AI Agent...","zh":"TUI 快速设置指南：实时令牌使用跟踪","ja":"TUI のベストプラクティス：リアルタイムトークン使用状況の監視","ko":"TUI 설치 가이드: 실시간 토큰 사용량 모니터링","es":"Guía de configuración de tui: Monitor de uso de tokens en...","fr":"Guide de configuration de tui : Suivi en temps réel de l''...","de":"tui-Konfigurationsleitfaden: Echtzeit-Überwachung von Tok...","pt":"Guia de Configuração do TUI: Monitoramento em Tempo Real ...","ru":"Настройка TUI: Мониторинг Использования Токенов в Реально...","ar":"دليل إعداد TUI: مراقبة استخدام الرموز في الوقت الفعلي للأ..."},"description":{"en":"Discover how to monitor token usage in real-time with tui. Get started with our expert guide and optimize your workflow today!","zh":"了解 TUI 的工作原理和优势，实现实时令牌使用跟踪和成本监控","ja":"TUI の機能と利点を確認し、リアルタイムのトークン使用状況の監視とコスト管理を実現","ko":"TUI의 기능과 장점을 확인하고 실시간 토큰 사용량 모니터링 및 비용 관리를 구현","es":"Aprende a configurar tui para un seguimiento en tiempo real del uso de tokens en Gemini CLI, Claude Code y más","fr":"Découvrez comment configurer tui pour un suivi en temps réel de l''utilisation des jetons dans Gemini CLI, Claude Code et plus","de":"Erfahren Sie, wie Sie tui für die Echtzeit-Überwachung der Token-Nutzung in Gemini CLI, Claude Code und mehr konfigurieren","pt":"Aprenda a configurar o TUI para monitorar o uso de tokens em tempo real e otimizar o desempenho do seu projeto com Gemini CLI, Claude Code e outros","ru":"Узнайте, как настроить TUI для мониторинга использования токенов в реальном времени и оптимизации производительности вашего проекта с Gemini CLI, Claude Code...","ar":"تعرف على كيفية إعداد TUI لمراقبة استخدام الرموز في الوقت الفعلي وتحسين أداء مشروعك مع Gemini CLI، Claude Code وأدوات ذكية أخرى"},"definition":{"en":"tui is a terminal UI-based token usage tracker that offers live updates and incremental re-parsing on file changes.","zh":"TUI 是一个实时令牌使用跟踪和成本监控工具，用于监控和管理令牌使用情况","ja":"TUI は、トークンの使用状況をリアルタイムに監視して管理するためのツール","ko":"TUI는 토큰 사용량을 실시간으로 모니터링하고 관리하기 위한 도구","es":"tui es una herramienta de seguimiento en tiempo real para el uso de tokens y costos asociados","fr":"tui est un outil de suivi en temps réel pour l''utilisation des jetons et les coûts associés","de":"tui ist ein Tool für die Echtzeit-Überwachung der Token-Nutzung und der damit verbundenen Kosten","pt":"O TUI é um sistema de monitoramento em tempo real que acompanha o uso de tokens em projetos de desenvolvimento","ru":"TUI — это система мониторинга в реальном времени, которая отслеживает использование токенов в проектах разработки для ИИ Агентов","ar":"TUI هو نظام مراقبة في الوقت الفعلي يتابع استخدام الرموز في مشاريع التطوير للأدوات الذكية"},"features":{"en":["Provides a terminal UI with live updates using Splitrail","Watches analyzer data directories for changes using the notify crate","Triggers incremental re-parsing on file changes and updates TUI via channels","Supports Gemini CLI, Claude Code, Codex CLI, and other compatible platforms","Offers real-time monitoring and cost tracking for token usage","Includes a file watching implementation using src/watcher.rs"],"zh":["支持 Gemini CLI、Claude Code、Codex CLI 等多个平台","实时令牌使用跟踪和成本监控","基于 notify crate 的文件监视实现","TUI 界面实时更新","支持增量重新解析"],"ja":["Gemini CLI、Claude Code、Codex CLI など複数のプラットフォームをサポート","リアルタイムのトークン使用状況の監視とコスト管理","notify crate を基盤としたファイル監視の実装","TUI インターフェースのリアルタイム更新","増分再解析のサポート"],"ko":["Gemini CLI, Claude Code, Codex CLI 등 여러 플랫폼 지원","실시간 토큰 사용량 모니터링 및 비용 관리","notify crate 기반의 파일 감시 구현","TUI 인터페이스의 실시간 업데이트","증분 재파싱 지원"],"es":["Interfaz de terminal con actualizaciones en vivo","Seguimiento en tiempo real del uso de tokens en Gemini CLI y otros","Monitor de costos para optimizar el uso de tokens","Implementación de FileWatcher para detectar cambios en los archivos de datos del analizador","Gestión del estado de la interfaz de usuario y control de entrada en src/tui/logic.rs","Uso de la biblioteca notify para vigilar los directorios de datos del analizador"],"fr":["Interface de terminal avec mises à jour en temps réel","Suivi en temps réel de l''utilisation des jetons dans Gemini CLI et d''autres","Moniteur de coûts pour optimiser l''utilisation des jetons","Mise en œuvre de FileWatcher pour détecter les modifications des fichiers de données de l''analyseur","Gestion de l''état de l''interface utilisateur et contrôle de saisie dans src/tui/logic.rs","Utilisation de la bibliothèque notify pour surveiller les répertoires de données de l''analyseur"],"de":["Terminal-Oberfläche mit Live-Updates","Echtzeit-Überwachung der Token-Nutzung in Gemini CLI und anderen","Kosten-Monitor für die Optimierung der Token-Nutzung","Implementierung von FileWatcher zur Erkennung von Änderungen in den Daten-Dateien des Analyse-Tools","Verwaltung des Benutzeroberflächen-Zustands und Eingabe-Steuerung in src/tui/logic.rs","Verwendung der Bibliothek notify zur Überwachung der Daten-Verzeichnisse des Analyse-Tools"],"pt":["Monitoramento em tempo real do uso de tokens","Integração com Gemini CLI, Claude Code e outros","Atualizações em tempo real quando os arquivos de dados do analisador mudam","Implementação de arquivo de observação com o pacote notify","Gerenciamento de estado e tratamento de entrada via channels"],"ru":["Мониторинг использования токенов в реальном времени","Интеграция с Gemini CLI, Claude Code и другими ИИ Агентами","Обновления в реальном времени при изменении файлов данных анализатора","Реализация файла наблюдения с помощью пакета notify","Управление состоянием и обработка входных данных через каналы"],"ar":["مراقبة استخدام الرموز في الوقت الفعلي","التكامل مع Gemini CLI، Claude Code وأدوات ذكية أخرى","التحديثات في الوقت الفعلي عند تغيير ملفات بيانات المحلل","تنفيذ ملف مراقبة باستخدام حزمة الإعلام","إدارة الحالة ومعالجة الإدخال عبر القنوات"]},"keywords":{"en":["how to use tui","tui alternative","tui setup guide","what is tui","tui vs Codex CLI","tui install","real-time token usage tracking","Gemini CLI token usage","Claude Code token usage monitor"],"zh":["TUI","AI工具","实时令牌使用跟踪","成本监控","Gemini CLI","Claude Code","Codex CLI","notify crate","TUI 界面"],"ja":["TUI","AIエージェント","リアルタイムトークン使用状況の監視","コスト管理","Gemini CLI","Claude Code","Codex CLI","notify crate","TUI インターフェース"],"ko":["TUI","AI 에이전트","실시간 토큰 사용량 모니터링","비용 관리","Gemini CLI","Claude Code","Codex CLI","notify crate","TUI 인터페이스"],"es":["tui","seguimiento en tiempo real","uso de tokens","Gemini CLI","monitor de costos","FileWatcher","notify","terminal UI","desarrollo de software","herramientas de desarrollo"],"fr":["tui","suivi en temps réel","utilisation des jetons","Gemini CLI","moniteur de coûts","FileWatcher","notify","interface de terminal","développement de logiciels","outils de développement"],"de":["tui","Echtzeit-Überwachung","Token-Nutzung","Gemini CLI","Kosten-Monitor","FileWatcher","notify","Terminal-Oberfläche","Software-Entwicklung","Entwicklertools"],"pt":["tui","monitoramento em tempo real","uso de tokens","gemini cli","claude code","desenvolvimento de software","iot","inteligência artificial"],"ru":["tui","мониторинг в реальном времени","использование токенов","gemini cli","claude code","разработка программного обеспечения","ии агенты","искусственный интеллект"],"ar":["tui","مراقبة في الوقت الفعلي","استخدام الرموز","gemini cli","claude code","تطوير البرمجيات","أدوات ذكية","الذكاء الاصطناعي"]}},"owner":"Piebald-AI","repo":"splitrail","repoPath":"Piebald-AI/splitrail","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"tui","description":"Guide for Splitrails terminal UI and file watching. Use when modifying the TUI, stats display, or real-time update logic.","bodyPreview":"# Real-Time Monitoring & TUI\n\nSplitrail provides a terminal UI with live updates when analyzer data files change.\n\n## Source Files\n\n- `src/tui.rs` - TUI entry point and rendering\n- `src/tui/logic.rs` - TUI state management and input handling\n- `src/watcher.rs` - File watching implementation\n\n## Components\n\n### FileWatcher (`src/watcher.rs`)\n\nWatches analyzer data directories for changes using the `notify` crate. Triggers incremental re-parsing on file changes and updates TUI via channels.\n\n### R","body":"# Real-Time Monitoring & TUI\n\nSplitrail provides a terminal UI with live updates when analyzer data files change.\n\n## Source Files\n\n- `src/tui.rs` - TUI entry point and rendering\n- `src/tui/logic.rs` - TUI state management and input handling\n- `src/watcher.rs` - File watching implementation\n\n## Components\n\n### FileWatcher (`src/watcher.rs`)\n\nWatches analyzer data directories for changes using the `notify` crate. Triggers incremental re-parsing on file changes and updates TUI via channels.\n\n### RealtimeStatsManager\n\nCoordinates real-time updates: background file watching, auto-upload to Splitrail Cloud (if configured), and stats updates to TUI via `tokio::sync::watch`.\n\n### TUI (`src/tui.rs`, `src/tui/logic.rs`)\n\nTerminal interface using `ratatui`:\n- Daily stats view with date navigation\n- Session view with lazy message loading\n- Real-time stats refresh\n\n## Key Patterns\n\n- **Channel-based updates** - Stats flow through `tokio::sync::watch` channels\n- **Lazy message loading** - Messages loaded on-demand for session view to reduce memory\n\n## Adding Watch Support to an Analyzer\n\nImplement `get_watch_directories()` in your analyzer to return root directories for file watching. See `src/analyzer.rs` for the trait definition.\n"},"lastSynced":"2026-03-08T02:01:03.121Z","agentAnalysis":{"suitability":{"en":"Perfect for CLI-focused Agents needing real-time token usage tracking and cross-platform compatibility.","zh":"非常适合需要实时跟踪令牌使用情况和跨平台兼容性的CLI专注代理。","ja":"CLI中心のエージェントにリアルタイムのトークン使用状況の追跡とクロスプラットフォームの互換性が必要な場合に最適です。","ko":"CLI 중심 에이전트가 실시간 토큰 사용량 추적 및 크로스 플랫폼 호환성을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes centrados en CLI que necesitan un seguimiento del uso de tokens en tiempo real y compatibilidad entre plataformas.","fr":"Parfait pour les agents axés sur CLI nécessitant un suivi de l''utilisation de jetons en temps réel et une compatibilité multiplateforme.","de":"Perfekt für CLI-fokussierte Agenten, die ein Echtzeit-Tracking der Token-Nutzung und eine plattformübergreifende Kompatibilität benötigen.","pt":"Perfeito para agentes focados em CLI que necessitam de rastreamento de uso de token em tempo real e compatibilidade entre plataformas.","ru":"Идеально для агентов, ориентированных на CLI, которым необходима отслеживание использования токенов в реальном времени и совместимость между платформами.","ar":"مثالي للوكلاء الذين يركزون على CLI الذين يحتاجون إلى تتبع استخدام رمز الحصول في الوقت الفعلي وتوافق المنصات المتقاطعة."},"recommendation":{"en":"Empowers agents to monitor and analyze token usage in real-time, utilizing the notify crate for file watching and incremental re-parsing, and providing live updates via a terminal UI.","zh":"赋予代理监视和分析令牌使用情况的能力，利用notify crate进行文件监视和增量重新解析，并通过终端UI提供实时更新。","ja":"エージェントにトークンの使用状況をリアルタイムで監視および分析する能力を付与し、ファイルの監視とインクリメンタルな再解析のためにnotify crateを使用し、ターミナルUIを介してリアルタイムで更新を提供します。","ko":"에이전트가 토큰 사용량을 실시간으로 모니터링하고 분석할 수 있는 능력을 부여하며 notify crate를 사용하여 파일 감시 및 증분 다시 구문 분석을 수행하고 터미널 UI를 통해 실시간 업데이트를 제공합니다.","es":"Habilita a los agentes a monitorear y analizar el uso de tokens en tiempo real, utilizando el paquete notify para la vigilancia de archivos y el reanálisis incremental, y proporcionando actualizaciones en vivo a través de una interfaz de usuario de terminal.","fr":"Permet aux agents de surveiller et d''analyser l''utilisation de jetons en temps réel, en utilisant la boîte à outils notify pour la surveillance de fichiers et le réanalyse incrémental, et en fournissant des mises à jour en direct via une interface utilisateur de terminal.","de":"Ermächtigt Agenten, die Token-Nutzung in Echtzeit zu überwachen und zu analysieren, indem sie das notify-Paket für die Dateiüberwachung und die inkrementelle Neuanalyse verwenden und Live-Updates über eine Terminal-Benutzeroberfläche bereitstellen.","pt":"Habilita agentes a monitorar e analisar o uso de token em tempo real, utilizando a caixa de ferramentas notify para monitorar arquivos e reanálise incremental, e fornecendo atualizações ao vivo por meio de uma interface de usuário de terminal.","ru":"Наделяет агентов возможностью отслеживать и анализировать использование токенов в реальном времени, используя инструмент notify для наблюдения за файлами и инкрементальной переанализом, и предоставляя обновления в режиме реального времени через терминальный интерфейс пользователя.","ar":"يمنح الوكلاء القدرة على مراقبة وتحليل استخدام رمز الحصول في الوقت الفعلي، باستخدام حزمة الإشعار لتتبع الملفات وإعادة التحليل المتزايد، وتوفير التحديثات الحية عبر واجهة المستخدم الطرفية."},"useCases":{"en":["Monitoring token usage for Gemini CLI and Claude Code","Debugging issues with real-time file watching","Tracking changes in analyzer data directories"],"zh":["监视Gemini CLI和Claude Code的令牌使用情况","使用实时文件监视调试问题","跟踪分析器数据目录的更改"],"ja":["Gemini CLIおよびClaude Codeのトークン使用状況を監視する","リアルタイムのファイル監視を使用して問題をデバッグする","アナライザーのデータディレクトリの変更を追跡する"],"ko":["Gemini CLI 및 Claude Code의 토큰 사용량을 모니터링합니다.","실시간 파일 감시를 사용하여 문제를 디버깅합니다.","분석기 데이터 디렉토리의 변경 사항을 추적합니다."],"es":["Monitoreo del uso de tokens para Gemini CLI y Claude Code","Depuración de problemas con vigilancia de archivos en tiempo real","Seguimiento de cambios en los directorios de datos del analizador"],"fr":["Surveillance de l''utilisation de jetons pour Gemini CLI et Claude Code","Débogage de problèmes avec une surveillance de fichiers en temps réel","Suivi des modifications dans les répertoires de données de l''analyseur"],"de":["Überwachung der Token-Nutzung für Gemini CLI und Claude Code","Fehlerbehebung bei Problemen mit Echtzeit-Dateiüberwachung","Nachverfolgung von Änderungen in den Datenverzeichnissen des Analyzers"],"pt":["Monitoramento do uso de token para Gemini CLI e Claude Code","Depuração de problemas com monitoramento de arquivo em tempo real","Rastreamento de alterações em diretórios de dados do analisador"],"ru":["Отслеживание использования токенов для Gemini CLI и Claude Code","Отладка проблем с наблюдением за файлами в реальном времени","Отслеживание изменений в директориях данных анализатора"],"ar":["مراقبة استخدام رمز الحصول لجيميني CLI وكليد كلود","تصحيح مشاكل مع مراقبة الملفات في الوقت الفعلي","تتبع التغييرات في دليل بيانات المحلل"]},"limitations":{"en":["Requires compatible CLI tools","Dependent on notify crate for file system events"],"zh":["需要兼容的CLI工具","依赖notify crate进行文件系统事件"],"ja":["互換性のあるCLIツールが必要","ファイルシステムイベントのためにnotify crateに依存"],"ko":["호환되는 CLI 도구가 필요합니다.","파일 시스템 이벤트에 대해 notify crate에 의존합니다."],"es":["Requiere herramientas CLI compatibles","Dependiente del paquete notify para eventos del sistema de archivos"],"fr":["Nécessite des outils CLI compatibles","Dépend de la boîte à outils notify pour les événements du système de fichiers"],"de":["Benötigt kompatible CLI-Tools","Abhängig vom notify-Paket für Dateisystemereignisse"],"pt":["Requer ferramentas CLI compatíveis","Dependente da caixa de ferramentas notify para eventos do sistema de arquivos"],"ru":["Требует совместимых инструментов CLI","Зависит от инструмента notify для событий файловой системы"],"ar":["يتطلب أدوات CLI متوافقة","يعتمد على حزمة الإشعار لأحداث نظام الملفات"]},"version":4},"contentHash":"cdfa189fb1f61d0f56a151fa252f1922661bd1c520094c1ac01d41a53cd597d6","qualityScore":26}');
