INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Piebald-AI/splitrail/tui', 'tui', 'Piebald-AI', 'splitrail', 'community', 'tui Piebald-AI splitrail community The tui skill provides fast, cross-platform, real-time token usage tracking for various CLI tools. It benefits developers using Gemini CLI, Claude Code, and other compatible platforms. TUI 是一个快速、跨平台的实时令牌使用跟踪和成本监控工具，支持 Gemini CLI、Claude Code 等 TUI は、Gemini CLI、Claude Code などをサポートする高速なクロスプラットフォームのリアルタイムトークン使用状況の監視とコスト管理ツール TUI는 Gemini CLI, Claude Code 등에서 동작하는 빠른 크로스 플랫폼 실시간 토큰 사용량 모니터링 및 비용 관리 도구 tui es un rastreador de uso de tokens en tiempo real y monitor de costos para Gemini CLI y otros. Proporciona actualizaciones en vivo en la interfaz de terminal tui est un suivi en temps réel de l''utilisation des jetons et un moniteur de coûts pour Gemini CLI et d''autres. Fournit des mises à jour en temps réel dans l''interface de terminal tui ist ein Echtzeit-Überwachungstool für Token-Nutzung und ein Kosten-Monitor für Gemini CLI und andere. Bietet Live-Updates in der Terminal-Oberfläche O TUI é um tracker de uso de tokens em tempo real para Gemini CLI, Claude Code e outros. Ele fornece atualizações em tempo real quando os arquivos de dados do analisador mudam. TUI — это трекер использования токенов в реальном времени для Gemini CLI, Claude Code и других ИИ Агентов. Он предоставляет обновления в реальном времени при изменении файлов данных анализатора. TUI هو مراقب لاستخدام الرموز في الوقت الفعلي لGemini CLI، Claude Code وأدوات ذكية أخرى. يتيح التحديثات في الوقت الفعلي عند تغيير ملفات بيانات المحلل how to use tui tui alternative tui setup guide what is tui tui vs Codex CLI tui install real-time token usage tracking Gemini CLI token usage Claude Code token usage monitor TUI AI工具 实时令牌使用跟踪 成本监控 Gemini CLI Claude Code Codex CLI notify crate TUI 界面 Provides a terminal UI with live updates using Splitrail Watches analyzer data directories for changes using the notify crate Triggers incremental re-parsing on file changes and updates TUI via channels Supports Gemini CLI, Claude Code, Codex CLI, and other compatible platforms Offers real-time monitoring and cost tracking for token usage Includes a file watching implementation using src/watcher.rs tui is a terminal UI-based token usage tracker that offers live updates and incremental re-parsing on file changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('snakeying/Textum/textum', 'community', 'snakeying', 'Textum', 'snakeying/Textum', 'textum', 0, 0, 26, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:07.218Z', '1e1313ba41f3bfe5c941222554da5c332a5e447d0f6dc6a51cad94cfee2a1d88', '{"id":"snakeying/Textum/textum","name":"textum","description":{"en":"textum is a structured workflow that prevents AI from forgetting requirements. It benefits developers by providing a controllable process with 4 phases and validation gates.","zh":"Textum是一种结构化工作流程，确保AI满足您的需求，具有低噪音和多窗口特性","ja":"Textumは、AIエージェントが要件を満たすことを保証する構造化ワークフローで、低ノイズと多ウィンドウの特性を備えています","ko":"Textum은 요구 사항을 충족하도록 보장하는 구조화된 워크플로우로, 낮은 노이즈와 다중 창구의 특징을 가지고 있습니다","es":"Textum es un flujo de trabajo estructurado que evita la contaminación de contexto en la IA, con validación en 4 fases. Permite a los desarrolladores crear código que funciona.","fr":"Textum est un processus de travail structuré qui évite la pollution de contexte dans l''IA, avec validation en 4 phases. Il permet aux développeurs de créer du code qui fonctionne.","de":"Textum ist ein strukturierter Arbeitsablauf, der Kontextverunreinigung in der KI vermeidet, mit Validierung in 4 Phasen. Er ermöglicht es Entwicklern, funktionsfähigen Code zu erstellen.","pt":"O Textum é uma estrutura de fluxo de trabalho que evita o esquecimento de requisitos com 4 fases e portas de validação, garantindo um processo controllável","ru":"Textum - это структурированный рабочий процесс, который предотвращает забывание требований с 4 фазами и валидационными шлюзами, обеспечивая управляемый процесс","ar":"Textum هو هيكل تدفق عمل يمنع نسيان المتطلبات مع 4 مراحل وبوابات التحقق، مما يضمن عملية قابلة للسيطرة"},"seo":{"title":{"en":"textum: Structured Workflow Setup Guide | AI Agent Skill","zh":"Textum_SETUP GUIDE：结构化工作流程控制AI","ja":"Textumセットアップガイド：AIエージェントの構造化ワークフロー","ko":"Textum 설치 가이드: 구조화된 워크플로우로 AI 제어","es":"Guía de configuración de Textum: Flujo de trabajo estruct...","fr":"Guide de configuration de Textum: Processus de travail st...","de":"Textum-Setup-Leitfaden: Strukturierter Arbeitsablauf für KI","pt":"Guia de Configuração do Textum: Otimizando Fluxos de Trab...","ru":"Настройка Textum: ИИ Агенты с Управляемым Процессом","ar":"دليل إعداد Textum: تحسين تدفقات العمل مع التحكم في العملية"},"description":{"en":"Discover how textum''s 4-phase validation gates ensure controllable AI processes. Learn to install and sync textum with uv and .claude/skills/textum/scripts","zh":"Textum实现低噪音、多窗口的结构化工作流程，确保AI满足您的需求，支持PRD Plan、PRD Check和PRD Render阶段","ja":"Textumは低ノイズ、多ウィンドウの構造化ワークフローを実現し、AIエージェントが要件を満たすことを保証します。PRD Plan、PRD Check、PRD Renderステージをサポート","ko":"Textum은 낮은 노이즈와 다중 창구의 구조화된 워크플로우를 구현하여 AI가 요구 사항을 충족하도록 보장합니다. PRD Plan, PRD Check 및 PRD Render 단계 지원","es":"Aprende a implementar Textum, un flujo de trabajo estructurado que evita la contaminación de contexto en la IA, con validación en 4 fases","fr":"Découvrez comment mettre en œuvre Textum, un processus de travail structuré qui évite la pollution de contexte dans l''IA, avec validation en 4 phases","de":"Erfahren Sie, wie Sie Textum implementieren, einen strukturierten Arbeitsablauf, der Kontextverunreinigung in der KI vermeidet, mit Validierung in 4 Phasen","pt":"Aprenda a configurar o Textum para evitar esquecimento de requisitos e melhorar a produtividade com 4 fases e portas de validação","ru":"Узнайте, как настроить Textum, чтобы избежать забывания требований и повысить производительность с 4 фазами и валидационными шлюзами","ar":"تعرف على كيفية إعداد Textum لتجنب نسيان المتطلبات وتحسين الإنتاجية باستخدام 4 مراحل وبوابات التحقق"},"definition":{"en":"textum is a workflow that ensures low-noise and multi-window functionality, providing a structured approach to AI development","zh":"Textum是一种结构化工作流程，用于控制AI，具有低噪音和多窗口特性","ja":"Textumは、AIエージェントを制御する構造化ワークフローで、低ノイズと多ウィンドウの特性を備えています","ko":"Textum은 AI를 제어하는 구조화된 워크플로우로, 낮은 노이즈와 다중 창구의 특성을 가지고 있습니다","es":"Textum es un flujo de trabajo estructurado que evita la contaminación de contexto en la IA","fr":"Textum est un processus de travail structuré qui évite la pollution de contexte dans l''IA","de":"Textum ist ein strukturierter Arbeitsablauf, der Kontextverunreinigung in der KI vermeidet","pt":"O Textum é um framework de fluxo de trabalho que permite controlar o processo de desenvolvimento de software","ru":"Textum - это фреймворк рабочего процесса, который позволяет контролировать процесс разработки программного обеспечения","ar":"Textum هو إطار عمل لتدفق العمل الذي يسمح بالسيطرة على عملية تطوير البرمجيات"},"features":{"en":["Enforces low-noise constraints to avoid attention and context pollution","Supports multi-window functionality with self-contained stages","Requires uv installation and synchronization with .claude/skills/textum/scripts","Includes validation gates for 4-phase workflow","Outputs next step as a stage name only","Supports stages like PRD Plan, PRD Check, and PRD Render"],"zh":["低噪音设计","多窗口支持","PRD Plan、PRD Check和PRD Render阶段支持","uv安装要求","运行uv sync --project .claude/skills/textum/scripts命令"],"ja":["低ノイズ設計","多ウィンドウ対応","PRD Plan、PRD Check、PRD Renderステージ対応","uvインストール要件","uv sync --project .claude/skills/textum/scriptsコマンドの実行"],"ko":["낮은 노이즈 설계","다중 창구 지원","PRD Plan, PRD Check 및 PRD Render 단계 지원","uv 설치 요구 사항","uv sync --project .claude/skills/textum/scripts 명령 실행"],"es":["Flujo de trabajo estructurado en 4 fases","Validación en cada fase para evitar errores","Compatibilidad con tecnologías como uv y CLI","Creación de código que funciona mediante la integración de ideas","Soporte para múltiples ventanas y etapas autocontenidas"],"fr":["Processus de travail structuré en 4 phases","Validation à chaque phase pour éviter les erreurs","Compatibilité avec des technologies comme uv et CLI","Création de code qui fonctionne via l''intégration d''idées","Prise en charge de plusieurs fenêtres et étapes autocontenues"],"de":["Strukturierter Arbeitsablauf in 4 Phasen","Validierung in jeder Phase zur Fehlervermeidung","Kompatibilität mit Technologien wie uv und CLI","Erstellung von funktionsfähigem Code durch die Integration von Ideen","Unterstützung für mehrere Fenster und selbstständige Etappen"],"pt":["4 fases de fluxo de trabalho","Portas de validação para garantir a qualidade","Suporte a múltiplas janelas de trabalho","Integração com o CLI via `uv`"],"ru":["4 фазы рабочего процесса","Валидационные шлюзы для обеспечения качества","Поддержка нескольких окон работы","Интеграция с CLI через `uv`"],"ar":["4 مراحل من تدفق العمل","بوابات التحقق لضمان الجودة","دعم نوافذ العمل المتعددة","التكامل مع CLI عبر `uv`"]},"keywords":{"en":["how to use textum","textum setup guide","what is textum","textum alternative","textum vs other AI workflows","textum install with uv","textum sync with .claude/skills/textum/scripts","textum workflow for AI development","textum 4-phase validation gates","textum multi-window functionality"],"zh":["Textum","AIエージェント","结构化工作流程","低噪音","多窗口","PRD Plan","PRD Check","PRD Render","uv安装"],"ja":["Textum","AIエージェント","構造化ワークフロー","低ノイズ","多ウィンドウ","PRD Plan","PRD Check","PRD Render","uvインストール"],"ko":["Textum","AI 도구","구조화된 워크플로우","낮은 노이즈","다중 창구","PRD Plan","PRD Check","PRD Render","uv 설치"],"es":["Textum","flujo de trabajo estructurado","IA","validación en 4 fases","uv","CLI","integración de ideas","creación de código","desarrollo de software","herramientas de desarrollo"],"fr":["Textum","processus de travail structuré","IA","validation en 4 phases","uv","CLI","intégration d''idées","création de code","développement de logiciels","outils de développement"],"de":["Textum","strukturierter Arbeitsablauf","KI","Validierung in 4 Phasen","uv","CLI","Integration von Ideen","Erstellung von Code","Software-Entwicklung","Entwicklungstools"],"pt":["Textum","fluxo de trabalho","controle de processo","desenvolvimento de software","ferramentas de desenvolvimento","CLI","uv","IИ Агенты"],"ru":["Textum","рабочий процесс","управление процессом","разработка программного обеспечения","инструменты разработки","CLI","uv","ИИ Агенты"],"ar":["Textum","تدفق العمل","تحكم في العملية","تطوير البرمجيات","أدوات التطوير","CLI","uv","أدوات الذكاء الاصطناعي"]}},"owner":"snakeying","repo":"Textum","repoPath":"snakeying/Textum","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"textum","description":"Textum PRD→Scaffold→Story workflow for Codex with low-noise outputs and gate checks.","bodyPreview":"# Textum\n\nHard constraints:\n- Low-noise is non-negotiable (avoid attention/context pollution).\n- Multi-window: each stage is self-contained; do not narrate upstream/downstream flow.\n- Output “next step” as a stage name only.\n\nPrereq (runtime):\n- `uv` installed.\n- Run `uv sync --project .claude/skills/textum/scripts` once (creates `.claude/skills/textum/scripts/.venv`).\n\nSupported stages:\n- PRD Plan → `references/prd-plan.md`\n- PRD Check → `references/prd-check.md`\n- PRD Render → `references/prd-","body":"# Textum\n\nHard constraints:\n- Low-noise is non-negotiable (avoid attention/context pollution).\n- Multi-window: each stage is self-contained; do not narrate upstream/downstream flow.\n- Output “next step” as a stage name only.\n\nPrereq (runtime):\n- `uv` installed.\n- Run `uv sync --project .claude/skills/textum/scripts` once (creates `.claude/skills/textum/scripts/.venv`).\n\nSupported stages:\n- PRD Plan → `references/prd-plan.md`\n- PRD Check → `references/prd-check.md`\n- PRD Render → `references/prd-render.md`\n- PRD Slice → `references/prd-slice.md`\n- Scaffold Plan → `references/scaffold-plan.md`\n- Scaffold Render → `references/scaffold.md`\n- Scaffold Check → `references/scaffold-check.md`\n- Split Plan → `references/split-plan.md`\n- Split Generate → `references/split.md`\n- Split Check1 → `references/split-check1.md`\n- Split Check2 → `references/split-check2.md`\n- Split Checkout → `references/split-checkout.md`\n- Story Check → `references/story-check.md`\n- Story Pack → `references/story-pack.md`\n- Story Exec → `references/story.md`\n- Story Full Exec (experimental) → `references/story-full-exec.md`\n\nRouting:\n- CN intent examples:\n  - `PRD Plan`: 需求澄清 / 澄清需求 / PRD 计划\n  - `PRD Render`: 生成PRD / 渲染PRD / 输出PRD\n  - `PRD Check`: 校验PRD / 检查PRD / 门禁\n  - `PRD Slice`: PRD 切片 / 切片 / 低噪切片 / slice\n  - `Scaffold Plan`: 上下文提取 / 全局上下文 / Scaffold 计划\n  - `Scaffold Render`: 生成GLOBAL-CONTEXT / 渲染GLOBAL-CONTEXT / 输出GLOBAL-CONTEXT\n  - `Scaffold Check`: 校验GLOBAL-CONTEXT / 检查GLOBAL-CONTEXT / GC 门禁\n  - `Split Plan`: Story 拆分规划 / Split Plan / 拆分计划\n  - `Split Generate`: 生成Story / Split Generate / 拆分生成\n  - `Split Check1`: Split 校验1 / 拆分校验1 / 结构阈值校验\n  - `Split Check2`: Split 校验2 / 拆分校验2 / 引用一致性校验\n  - `Split Checkout`: Split Checkout / 依赖图 / 导出依赖图\n  - `Story Check`: Story 校验 / Story Check / 单 Story 门禁\n  - `Story Pack`: Story 执行包生成 / Story Pack / 生成执行包\n  - `Story Exec`: Story 执行 / Story Exec / 单 Story 执行\n  - `Story Full Exec`: Story 批量执行 / Story Full Exec / 试验性全执行\n- If intent is unclear, ask the user to pick one: `PRD Plan` / `PRD Check` / `PRD Render` / `PRD Slice` / `Scaffold Plan` / `Scaffold Render` / `Scaffold Check` / `Split Plan` / `Split Generate` / `Split Check1` / `Split Check2` / `Split Checkout` / `Story Check` / `Story Pack` / `Story Exec` / `Story Full Exec`.\n\nAlways:\n- For every `FAIL` item (in diagnostics/replan packs): include `loc/problem/expected/impact/fix`, and `fix` must be a single action.\n- Keep chat output low-noise: prefer paths (`wrote: docs/*`) over pasting long `FAIL` lists.\n"},"lastSynced":"2026-03-08T02:01:07.218Z","agentAnalysis":{"suitability":{"en":"Ideal for Structured Workflow Agents needing controllable processes with low-noise requirements","zh":"适合需要可控流程且低噪声要求的结构化工作流代理","ja":"制御可能なプロセスと低ノイズ要件を持つ構造化ワークフロー エージェントに適しています","ko":"제어 가능한 프로세스와 낮은 노이즈 요구 사항을 가진 구조화된 워크플로 에이전트에 적합합니다","es":"Ideal para Agentes de Flujo de Trabajo Estructurados que necesitan procesos controlables con requisitos de bajo ruido","fr":"Idéal pour les agents de workflow structurés nécessitant des processus contrôlables avec des exigences de faible bruit","de":"Ideal für strukturierte Workflow-Agents, die kontrollierbare Prozesse mit niedrigen Rausch-Anforderungen benötigen","pt":"Ideal para Agentes de Fluxo de Trabalho Estruturado que necessitam de processos controláveis com requisitos de baixo ruído","ru":"Идеально для Структурированных Агентов рабочего процесса, требующих контролируемых процессов с низкими требованиями шума","ar":"مثالي للوكلاء ذوي تدفق العمل المنظم الذين يحتاجون إلى عمليات قابلة للتحكم مع متطلبات منخفضة الضوضاء"},"recommendation":{"en":"Empowers agents to manage complex workflows using a 4-phase validation gate system, ensuring requirements are not forgotten, with support for stages like PRD Plan, PRD Check, and PRD Render, utilizing `uv` for synchronization","zh":"赋予代理管理复杂工作流的能力，使用 4 阶段验证门系统，确保不会遗忘要求，并支持 PRD 计划、PRD 检查和 PRD 渲染等阶段，利用 `uv` 进行同步","ja":"エージェントが複雑なワークフローを管理できるようにし、4 フェーズのバリデーション ゲート システムを使用して、要件が忘れられないようにし、PRD プラン、PRD チェック、PRD レンダリングなどのステージをサポートし、`uv` を使用して同期します","ko":"에이전트가 복잡한 워크플ロー를 관리할 수 있도록 하며, 4 단계의 유효성 검사 게이트 시스템을 사용하여 요구 사항이 忘れられないように 하며, PRD 계획, PRD 확인 및 PRD 렌더링 등의 단계를 지원하며, `uv`를 사용하여 동기화를 수행합니다","es":"Habilita a los agentes a gestionar flujos de trabajo complejos utilizando un sistema de puerta de validación de 4 fases, asegurando que los requisitos no sean olvidados, con soporte para etapas como PRD Plan, PRD Check y PRD Render, utilizando `uv` para la sincronización","fr":"Permet aux agents de gérer des flux de travail complexes en utilisant un système de validation à 4 phases, garantissant que les exigences ne soient pas oubliées, avec un support pour des étapes comme PRD Plan, PRD Check et PRD Render, en utilisant `uv` pour la synchronisation","de":"Ermächtigt Agents, komplexe Workflows mithilfe eines 4-Phasen-Validierungssystems zu verwalten, sicherzustellen, dass Anforderungen nicht vergessen werden, mit Unterstützung für Phasen wie PRD Plan, PRD Check und PRD Render, unter Verwendung von `uv` für die Synchronisierung","pt":"Habilita os agentes a gerenciar fluxos de trabalho complexos usando um sistema de portão de validação de 4 fases, garantindo que os requisitos não sejam esquecidos, com suporte a estágios como PRD Plan, PRD Check e PRD Render, utilizando `uv` para sincronização","ru":"Наделяет агентов возможностью управлять сложными рабочими процессами, используя систему валидации в 4 фазы, гарантируя, что требования не будут забыты, с поддержкой стадий, таких как PRD Plan, PRD Check и PRD Render, используя `uv` для синхронизации","ar":"يمنح الوكلاء القدرة على إدارة تدفقات العمل المعقدة باستخدام نظام بوابة التحقق من صحة 4 مراحل، مما يضمن عدم نسيان المتطلبات، مع دعم مراحل مثل خطة PRD، ومراجعة PRD، وعرض PRD، باستخدام `uv` للتزامن"},"useCases":{"en":["Managing multi-stage workflows","Validating requirements through gated phases","Generating next steps in a self-contained workflow"],"zh":["管理多阶段工作流","通过有门阶段验证要求","在自包含工作流中生成下一步"],"ja":["マルチステージ ワークフローの管理","ゲート フェーズを介した要件の検証","セルフ包含ワークフロー内での次のステップの生成"],"ko":["다단계 워크플로 관리","게이트 단계를 통한 요구 사항 유효성 검사","자체 포함 워크플로에서 다음 단계 생성"],"es":["Gestión de flujos de trabajo multietapa","Validación de requisitos a través de fases con puerta","Generación de los siguientes pasos en un flujo de trabajo autónomo"],"fr":["Gestion de flux de travail multietapes","Validation des exigences à travers des phases avec une porte","Génération des prochaines étapes dans un flux de travail autonome"],"de":["Verwaltung von mehrstufigen Workflows","Validierung von Anforderungen durch phasenweise gesteuerte Schranken","Generierung der nächsten Schritte in einem selbstständigen Workflow"],"pt":["Gerenciamento de fluxos de trabalho multietapa","Validação de requisitos por meio de fases com portão","Geração de próximas etapas em um fluxo de trabalho autônomo"],"ru":["Управление много