INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('snakeying/Textum/textum', 'textum', 'snakeying', 'Textum', 'community', 'textum snakeying Textum community textum is a structured workflow that prevents AI from forgetting requirements. It benefits developers by providing a controllable process with 4 phases and validation gates. Textum是一种结构化工作流程，确保AI满足您的需求，具有低噪音和多窗口特性 Textumは、AIエージェントが要件を満たすことを保証する構造化ワークフローで、低ノイズと多ウィンドウの特性を備えています Textum은 요구 사항을 충족하도록 보장하는 구조화된 워크플로우로, 낮은 노이즈와 다중 창구의 특징을 가지고 있습니다 Textum es un flujo de trabajo estructurado que evita la contaminación de contexto en la IA, con validación en 4 fases. Permite a los desarrolladores crear código que funciona. Textum est un processus de travail structuré qui évite la pollution de contexte dans l''IA, avec validation en 4 phases. Il permet aux développeurs de créer du code qui fonctionne. Textum ist ein strukturierter Arbeitsablauf, der Kontextverunreinigung in der KI vermeidet, mit Validierung in 4 Phasen. Er ermöglicht es Entwicklern, funktionsfähigen Code zu erstellen. O Textum é uma estrutura de fluxo de trabalho que evita o esquecimento de requisitos com 4 fases e portas de validação, garantindo um processo controllável Textum - это структурированный рабочий процесс, который предотвращает забывание требований с 4 фазами и валидационными шлюзами, обеспечивая управляемый процесс Textum هو هيكل تدفق عمل يمنع نسيان المتطلبات مع 4 مراحل وبوابات التحقق، مما يضمن عملية قابلة للسيطرة how to use textum textum setup guide what is textum textum alternative textum vs other AI workflows textum install with uv textum sync with .claude/skills/textum/scripts textum workflow for AI development textum 4-phase validation gates textum multi-window functionality Textum AIエージェント 结构化工作流程 低噪音 多窗口 PRD Plan PRD Check PRD Render uv安装 Enforces low-noise constraints to avoid attention and context pollution Supports multi-window functionality with self-contained stages Requires uv installation and synchronization with .claude/skills/textum/scripts Includes validation gates for 4-phase workflow Outputs next step as a stage name only Supports stages like PRD Plan, PRD Check, and PRD Render textum is a workflow that ensures low-noise and multi-window functionality, providing a structured approach to AI development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rolldown/rolldown/upgrade-oxc', 'community', 'rolldown', 'rolldown', 'rolldown/rolldown', 'upgrade-oxc', 0, 0, 26, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:11.488Z', '3e5b430e4e4486fabfd5bdafc4a83b94bb61ae7f64628550e9700c945f66610a', '{"id":"rolldown/rolldown/upgrade-oxc","name":"upgrade-oxc","description":{"en":"The upgrade-oxc skill provides a fast Rust bundler for JavaScript/TypeScript with a Rollup-compatible API, benefiting developers who need efficient project setup and management.","zh":"Upgrade OXC 是一个快速的 Rust 打包工具，支持 Rollup 兼容 API，用于 JavaScript/TypeScript 项目构建","ja":"Upgrade OXC は、Rollup 互換 API を備えた JavaScript/TypeScript プロジェクトを高速に構築するための、高速な Rust バンドルツールです","ko":"Upgrade OXC는 Rollup 호환 API를 갖춘 JavaScript/TypeScript 프로젝트를 빠르게 구축하는 빠른 Rust 번들링 도구입니다","es":"Upgrade-oxc es un empaquetador de Rust rápido para JavaScript/TypeScript con API compatible con Rollup. Sigue los pasos para configurarlo correctamente","fr":"Upgrade-oxc est un bundleur Rust rapide pour JavaScript/TypeScript avec API compatible Rollup. Suivez les étapes pour le configurer correctement","de":"Upgrade-oxc ist ein schneller Rust-Bundler für JavaScript/TypeScript mit Rollup-kompatibler API. Befolgen Sie die Schritte für eine korrekte Konfiguration","pt":"O Upgrade OXC é uma ferramenta de bundling Rust para JavaScript/TypeScript que oferece uma API compatível com Rollup. Siga os passos para configurá-la corretamente","ru":"Upgrade OXC - это инструмент для сборки Rust для JavaScript/TypeScript, предлагающий API, совместимый с Rollup. Следуйте инструкциям для правильной настройки","ar":"Upgrade OXC هو أداة Bundling Rust لجافا سكريبت/طيب سكريبت التي توفر واجهة برمجة تطبيقات متوافقة مع Rollup. اتبع الإرشادات لتهيئته بشكل صحيح"},"seo":{"title":{"en":"upgrade-oxc: Fast Rust Bundler Setup Guide | AI Agent Skill","zh":"Upgrade OXC 快速 Rust 打包工具安装指南","ja":"Upgrade OXC を使用した高速な Rust バンドルツールのセットアップガイド","ko":"Upgrade OXC 빠른 Rust 번들링 도구 설정 가이드","es":"Guía de configuración de upgrade-oxc: Herramientas de AI ...","fr":"Guide de configuration d''upgrade-oxc : Outils d''IA pour d...","de":"Upgrade-oxc-Konfigurationsleitfaden: KI-Tools für Entwickler","pt":"Guia de Configuração do Upgrade OXC: Ferramenta de Bundli...","ru":"ИИ Агент Upgrade OXC: Руководство по Настройке для JavaSc...","ar":"دليل إعداد Upgrade OXC: أداة Bundling Rust لجافا سكريبت/ط..."},"description":{"en":"Discover how to upgrade your JavaScript/TypeScript projects with upgrade-oxc, a fast Rust bundler. Learn the step-by-step setup process and optimize your dev...","zh":"使用 Upgrade OXC 快速 Rust 打包工具，实现 Rollup 兼容 API 的 JavaScript/TypeScript 项目构建","ja":"Upgrade OXC を使用して、Rollup 互換 API を備えた JavaScript/TypeScript プロジェクトを高速に構築します","ko":"Upgrade OXC 빠른 Rust 번들링 도구를 사용하여 Rollup 호환 API를 갖춘 JavaScript/TypeScript 프로젝트를 구축합니다","es":"Aprenda a configurar upgrade-oxc, un empaquetador de Rust rápido para JavaScript/TypeScript con API compatible con Rollup","fr":"Découvrez comment configurer upgrade-oxc, un bundleur Rust rapide pour JavaScript/TypeScript avec API compatible Rollup","de":"Erfahren Sie, wie Sie upgrade-oxc konfigurieren, einen schnellen Rust-Bundler für JavaScript/TypeScript mit Rollup-kompatibler API","pt":"Aprenda a configurar o Upgrade OXC, uma ferramenta de bundling Rust para JavaScript/TypeScript com API compatível com Rollup","ru":"Узнайте, как настроить Upgrade OXC, инструмент для сборки Rust для JavaScript/TypeScript с API, совместимым с Rollup","ar":"تعرف على كيفية إعداد Upgrade OXC، أداة Bundling Rust لجافا سكريبت/طيب سكريبت مع واجهة برمجة تطبيقات متوافقة مع Rollup"},"definition":{"en":"upgrade-oxc is a fast Rust bundler for JavaScript/TypeScript projects, utilizing a Rollup-compatible API for seamless integration and efficient development.","zh":"Upgrade OXC 是一个用于 JavaScript/TypeScript 项目的快速 Rust 打包工具","ja":"Upgrade OXC は、JavaScript/TypeScript プロジェクト用の高速な Rust バンドルツールです","ko":"Upgrade OXC는 JavaScript/TypeScript 프로젝트용 빠른 Rust 번들링 도구입니다","es":"Upgrade-oxc es una herramienta de AI que ofrece un empaquetador de Rust rápido para JavaScript/TypeScript","fr":"Upgrade-oxc est un outil d''IA qui propose un bundleur Rust rapide pour JavaScript/TypeScript","de":"Upgrade-oxc ist ein KI-Tool, das einen schnellen Rust-Bundler für JavaScript/TypeScript bietet","pt":"Upgrade OXC é uma ferramenta de bundling Rust para JavaScript/TypeScript que permite a configuração de projetos com API compatível com Rollup","ru":"Upgrade OXC - это инструмент для сборки Rust для JavaScript/TypeScript, позволяющий настроить проекты с API, совместимым с Rollup","ar":"Upgrade OXC هو أداة Bundling Rust لجافا سكريبت/طيب سكريبت التي تمكن من تهيئة المشاريع بواجهة برمجة تطبيقات متوافقة مع Rollup"},"features":{"en":["Runs sequential setup commands with dependencies, including `git checkout` and `just setup`","Updates `pnpm-workspace.yaml` file with the latest versions of `@oxc-project/runtime`, `@oxc-project/types`, and other dependencies","Utilizes `npm view` command to note the version of `@oxc-project/types`","Supports Rollup-compatible API for flexible and efficient bundling","Executes commands sequentially with `git pull` and `just setup` for reliable project setup"],"zh":["支持 Rollup 兼容 API","快速的 Rust 打包","用于 JavaScript/TypeScript 项目构建","支持多步骤构建过程","可更新依赖包版本"],"ja":["Rollup 互換 API をサポート","高速な Rust バンドル","JavaScript/TypeScript プロジェクトの構築に使用","複数のステップを含む構築プロセスをサポート","依存関係のバージョンを更新可能"],"ko":["Rollup 호환 API 지원","빠른 Rust 번들링","JavaScript/TypeScript 프로젝트 구축에 사용","여러 단계의 구축 프로세스를 지원","의존성 버전을 업데이트할 수 있음"],"es":["Empaquetador de Rust rápido para JavaScript/TypeScript","API compatible con Rollup","Actualización de versiones de @oxc-project/runtime, @oxc-project/types, oxc-minify, oxc-parser y oxc-transform","Uso de git para gestionar versiones","Uso de just y npm para la configuración","Compatibilidad con pnpm-workspace.yaml"],"fr":["Bundleur Rust rapide pour JavaScript/TypeScript","API compatible Rollup","Mise à jour des versions de @oxc-project/runtime, @oxc-project/types, oxc-minify, oxc-parser et oxc-transform","Utilisation de git pour la gestion des versions","Utilisation de just et npm pour la configuration","Compatibilité avec pnpm-workspace.yaml"],"de":["Schneller Rust-Bundler für JavaScript/TypeScript","Rollup-kompatible API","Aktualisierung der Versionen von @oxc-project/runtime, @oxc-project/types, oxc-minify, oxc-parser und oxc-transform","Verwendung von git für die Versionsverwaltung","Verwendung von just und npm für die Konfiguration","Kompatibilität mit pnpm-workspace.yaml"],"pt":["Suporte a JavaScript/TypeScript","API compatível com Rollup","Bundling com Rust","Configuração de projetos com just setup","Gerenciamento de dependências com pnpm-workspace.yaml","Verificação de versão com npm view"],"ru":["Поддержка JavaScript/TypeScript","API, совместимый с Rollup","Сборка с помощью Rust","Настройка проектов с just setup","Управление зависимостями с pnpm-workspace.yaml","Проверка версии с npm view"],"ar":["دعم جافا سكريبت/طيب سكريبت","واجهة برمجة تطبيقات متوافقة مع Rollup","Bundling مع Rust","تهيئة المشاريع مع just setup","إدارة الإعتماديات مع pnpm-workspace.yaml","التحقق من الإصدار مع npm view"]},"keywords":{"en":["how to use upgrade-oxc","upgrade-oxc setup guide","upgrade-oxc alternative","upgrade-oxc vs rollup","upgrade-oxc install","what is upgrade-oxc","upgrade-oxc for JavaScript developers","upgrade-oxc for TypeScript projects","fast Rust bundler","Rollup-compatible API"],"zh":["Upgrade OXC","Rust 打包工具","Rollup 兼容 API","JavaScript/TypeScript 项目构建","快速构建","依赖包管理","AI 工具","AIエージェント"],"ja":["Upgrade OXC","Rust バンドルツール","Rollup 互換 API","JavaScript/TypeScript プロジェクト構築","高速構築","依存関係管理","AI ツール","AIエージェント"],"ko":["Upgrade OXC","Rust 번들링 도구","Rollup 호환 API","JavaScript/TypeScript 프로젝트 구축","빠른 구축","의존성 관리","AI 도구","인공지능 에이전트"],"es":["upgrade-oxc","herramientas de AI para desarrolladores","empaquetador de Rust","JavaScript","TypeScript","Rollup","git","just","npm","pnpm-workspace.yaml"],"fr":["upgrade-oxc","outils d''IA pour développeurs","bundleur Rust","JavaScript","TypeScript","Rollup","git","just","npm","pnpm-workspace.yaml"],"de":["upgrade-oxc","KI-Tools für Entwickler","Rust-Bundler","JavaScript","TypeScript","Rollup","git","just","npm","pnpm-workspace.yaml"],"pt":["Upgrade OXC","bundling Rust","JavaScript/TypeScript","API Rollup","just setup","pnpm-workspace.yaml","npm view","configuração de projetos","gerenciamento de dependências"],"ru":["Upgrade OXC","сборка Rust","JavaScript/TypeScript","API Rollup","just setup","pnpm-workspace.yaml","npm view","настройка проектов","управление зависимостями"],"ar":["Upgrade OXC","Bundling Rust","جافا سكريبت/طيب سكريبت","واجهة برمجة تطبيقات Rollup","just setup","pnpm-workspace.yaml","npm view","تهيئة المشاريع","إدارة الإعتماديات"]}},"owner":"rolldown","repo":"rolldown","repoPath":"rolldown/rolldown","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"upgrade-oxc","description":"Upgrade oxc, run codegen, and fix any breaking changes.","bodyPreview":"# Upgrade OXC\n\nCRITICAL: Run each step sequentially ONE AT A TIME. Wait for each command to FULLY COMPLETE before proceeding to the next step. DO NOT run multiple commands in parallel - they have dependencies on each other.\n\n## Steps\n\n1. `git checkout main && git pull origin main`\n2. `just setup`\n3. `npm view @oxc-project/types version` - note the version\n4. Edit `pnpm-workspace.yaml`: update `@oxc-project/runtime`, `@oxc-project/types`, `oxc-minify`, `oxc-parser`, `oxc-transform` to the version","body":"# Upgrade OXC\n\nCRITICAL: Run each step sequentially ONE AT A TIME. Wait for each command to FULLY COMPLETE before proceeding to the next step. DO NOT run multiple commands in parallel - they have dependencies on each other.\n\n## Steps\n\n1. `git checkout main && git pull origin main`\n2. `just setup`\n3. `npm view @oxc-project/types version` - note the version\n4. Edit `pnpm-workspace.yaml`: update `@oxc-project/runtime`, `@oxc-project/types`, `oxc-minify`, `oxc-parser`, `oxc-transform` to the version from step 3 (use `=x.y.z` format)\n5. `cargo search oxc_allocator --limit 1` - note the version\n6. `cargo search oxc_resolver --limit 1` - note the version\n7. Edit `Cargo.toml`: update `oxc`, `oxc_allocator`, `oxc_ecmascript`, `oxc_minify_napi`, `oxc_parser_napi`, `oxc_transform_napi`, `oxc_traverse` to version from step 5; update `oxc_resolver`, `oxc_resolver_napi` to version from step 6\n8. `cargo update oxc oxc_allocator oxc_ecmascript oxc_minify_napi oxc_parser_napi oxc_transform_napi oxc_traverse oxc_resolver oxc_resolver_napi oxc_sourcemap oxc_index`\n9. `pnpm install` - install updated npm packages\n10. `cargo check` - if there are errors, fix all breaking changes before proceeding. Common breaking changes include renamed types, changed method signatures, or removed APIs. Study the error messages carefully and update the code accordingly.\n11. `just update-generated-code`\n12. `just test-update`\n13. `just ued`\n14. `just roll` - run the full build, lint, and test suite. Fix any remaining breaking changes or test failures before proceeding.\n15. `git status --short && git diff --stat` - verify expected files changed\n16. Summarize the upgrade by reporting: (a) the old and new versions, (b) number of files changed, (c) any breaking changes that were fixed, and (d) notable changes in the diff\n"},"lastSynced":"2026-03-08T02:01:11.488Z","agentAnalysis":{"suitability":{"en":"Perfect for JavaScript/TypeScript Agents needing efficient project setup and management with Rollup-compatible API","zh":"非常适合需要高效项目设置和管理的JavaScript/TypeScript Agents，支持Rollup兼容的API","ja":"JavaScript/TypeScriptエージェントが効率的なプロジェクト設定と管理を必要とする場合に最適で、Rollupと互換性のあるAPIをサポート","ko":"효율적인 프로젝트 설정 및 관리가 필요한 JavaScript/TypeScript 에이전트에게 적합하며 Rollup와 호환되는 API를 지원","es":"Perfecto para agentes JavaScript/TypeScript que necesitan una configuración y gestión de proyectos eficientes con API compatible con Rollup","fr":"Parfait pour les agents JavaScript/TypeScript ayant besoin d''une configuration et d''une gestion de projet efficaces avec API compatible Rollup","de":"Perfekt für JavaScript/TypeScript-Agents, die eine effiziente Projektsetup und -verwaltung mit Rollup-kompatibler API benötigen","pt":"Perfeito para agentes JavaScript/TypeScript que precisam de configuração e gerenciamento de projetos eficientes com API compatível com Rollup","ru":"Идеально подходит для агентов JavaScript/TypeScript, которым необходима эффективная настройка и управление проектами с помощью API, совместимого с Rollup","ar":"مثالي لعميل JavaScript/TypeScript الذي يحتاج إلى إعداد ومهام إدارة مشروع فعالة مع واجهة برمجة تطبيقات متوافقة مع Rollup"},"recommendation":{"en":"Empowers agents to efficiently manage projects with a fast Rust bundler, leveraging git, npm, and pnpm-workspace.yaml for seamless dependency updates and version management, utilizing libraries like @oxc-project/types and @oxc-project/runtime","zh":"赋予代理人使用快速的Rust打包工具来高效管理项目的能力，利用git、npm和pnpm-workspace.yaml实现无缝的依赖更新和版本管理，使用类似@oxc-project/types和@oxc-project/runtime的库","ja":"エージェントが高速なRustバンドラーを使用してプロジェクトを効率的に管理できるようにし、git、npm、pnpm-workspace.yamlを利用して依存関係の更新とバージョン管理をスムーズに行い、@oxc-project/typesや@oxc-project/runtimeのようなライブラリを利用","ko":"에이전트가 빠른 Rust 번들러를 사용하여 프로젝트를 효율적으로 관리할 수 있도록 하며, git, npm, pnpm-workspace.yaml를 이용하여 의존성 업데이트와 버전 관리를 원활하게 수행하며, @oxc-project/types 및 @oxc-project/runtime과 같은 라이브러리를 사용","es":"Habilita a los agentes a gestionar proyectos de manera eficiente con un empaquetador Rust rápido, aprovechando git, npm y pnpm-workspace.yaml para actualizaciones y gestión de versiones de dependencias sin problemas, utilizando bibliotecas como @oxc-project/types y @oxc-project/runtime","fr":"Permet aux agents de gérer les projets de manière efficace avec un bundleur Rust rapide, en exploitant git, npm et pnpm-workspace.yaml pour des mises à jour et une gestion de version de dépendances sans problème, en utilisant des bibliothèques comme @oxc-project/types et @oxc-project/runtime","de":"Ermächtigt Agenten, Projekte effizient zu verwalten, mit einem schnellen Rust-Bündler, der git, npm und pnpm-workspace.yaml für nahtlose Abhängigkeits-Updates und Versionsverwaltung nutzt, unter Verwendung von Bibliotheken wie @oxc-project/types und @oxc-project/runtime","pt":"Habilita os agentes a gerenciar projetos de forma eficiente com um empacotador Rust rápido, utilizando git, npm e pnpm-workspace.yaml para atualizações e gerenciamento de dependências e versões sem problemas, utilizando bibliotecas como @oxc-project/types e @oxc-project/runtime","ru":"Наделяет агентов возможностью эффективно управлять проектами с помощью быстрого сборщика Rust, используя git, npm и pnpm-workspace.yaml для бесперебойных обновлений зависимостей и управления версиями, используя библиотеки seperti @oxc-project/types и @oxc-project/runtime","ar":"يمنح العميل القدرة على إدارة المشاريع بفعالية باستخدام حزمة Rust سريعة، باستخدام git و npm و pnpm-workspace.yaml للحصول على تحديثات依赖 و إدارة إصدارات بدون مشاكل، باستخدام مكتبات مثل @oxc-project/types و @oxc-project/runtime"},"useCases":{"en":["Automating project setup with just setup","Updating dependencies with npm view and pnpm-workspace.yaml","Managing versions of oxc-minify, oxc-parser, and oxc-transform"],"zh":["使用仅设置来自动化项目设置","使用npm view和pnpm-workspace.yaml来更新依赖项","管理oxc-minify、oxc-parser和oxc-transform的版本"],"ja":["セットアップのみでプロジェクト設定を自動化する","npm viewとpnpm-workspace.yamlを使用して依存関係を更新する","oxc-minify、oxc-parser、oxc-transformのバージョンを管理する"],"ko":["설정만으로 프로젝트 설정을 자동화하는 것","npm view 및 pnpm-workspace.yaml를 사용하여 의존성을 업데이트하는 것","oxc-minify, oxc-parser, oxc-transform의 버전을 관리하는 것"],"es":["Automatizar la configuración del proyecto con solo setup","Actualizar dependencias con npm view y pnpm-workspace.yaml","Gestionar versiones de oxc-minify, oxc-parser y oxc-transform"],"fr":["Automatiser la configuration du projet avec juste setup","Mettre à jour les dépendances avec npm view et pnpm-workspace.yaml","Gérer les versions de oxc-minify, oxc-parser et oxc-transform"],"de":["Automatisieren der Projektsetup mit nur setup","Aktualisieren von Abhängigkeiten mit npm view und pnpm-workspace.yaml","Verwalten von Versionen von oxc-minify, oxc-parser und oxc-transform"],"pt":["Automatizar a configuração do projeto com apenas setup","Atualizar dependências com npm view e pnpm-workspace.yaml","Gerenciar versões de oxc-minify, oxc-parser e oxc-transform"],"ru":["Автоматизировать настройку проекта с помощью только setup","Обновлять зависимости с помощью npm view и pnpm-workspace.yaml","Управлять версиями oxc-minify, oxc-parser и oxc-transform"],"ar":["توفير إعداد المشروع تلقائيًا مع setup فقط","تحديث التبعيات باستخدام npm view و pnpm-workspace.yaml","إدارة إصدارات oxc-minify و oxc-parser و oxc-transform"]},"limitations":{"en":["Requires sequential execution of commands","Dependencies on git and npm","Specific version management with pnpm-workspace.yaml"],"zh":["需要顺序执行命令","依赖于git和npm","使用pnpm-workspace.yaml进行特定版本管理"],"ja":["コマンドの順次実行が必要","gitとnpmへの依存","pnpm-workspace.yamlを使用した特定のバージョン管理"],"ko":["명령어를 순차적으로 실행해야 하는 것","git 및 npm에 대한 의존성","pnpm-workspace.yaml를 사용한 특정 버전 관리"],"es":["Requiere ejecución secuencial de comandos","Dependencias de git y npm","Gestión de versiones específica con pnpm-workspace.yaml"],"fr":["Nécessite une exécution séquentielle des commandes","Dépendances de git et npm","Gestion de version spécifique avec pnpm-workspace.yaml"],"de":["Erfordert sequenzielle Ausführung von Befehlen","Abhängigkeiten von git und npm","Spezifische Versionsverwaltung mit pnpm-workspace.yaml"],"pt":["Requer execução sequencial de comandos","Dependências de git e npm","Gerenciamento de versão específico com pnpm-workspace.yaml"],"ru":["Требует последовательного выполнения команд","Зависимости от git и npm","Конкретное управление версиями с помощью pnpm-workspace.yaml"],"ar":["يتطلب تنفيذًا متسلسلاً للأوامر","اعتماديات على git و npm","إدارة إصدار محددة باستخدام pnpm-workspace.yaml"]},"version":4},"contentHash":"3e5b430e4e4486fabfd5bdafc4a83b94bb61ae7f64628550e9700c945f66610a","qualityScore":26}');
