INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('datorresb/vibecoding-starter/code-simplifier', 'code-simplifier', 'datorresb', 'vibecoding-starter', 'community', 'code-simplifier datorresb vibecoding-starter community The code-simplifier skill enhances code clarity and maintainability for AI coding projects, working with assistants like Claude Code and Copilot. It benefits developers seeking readable and explicit code solutions. 代码简化工具是一个项目模板，用于与AI助手（如Claude Code、Copilot等）进行协作，旨在提高代码的可读性和可维护性 コードシンプル化ツールは、AIアシスタント（Claude Code、Copilotなど）と共同で作業するためのプロジェクトテンプレートであり、コードの可読性とメンテナンス性を高めることを目的としています 코드 간소화 도구는 프로젝트 템플릿으로서 Claude Code, Copilot 등과 같은 AI 도구와 협업하여 코드의 가독성과 유지 보수성을 높이는 것을 목표로 합니다 Code-simplifier es un especialista en simplificación de código que mejora la claridad y la mantenibilidad del código sin alterar su funcionalidad Code-simplifier est un spécialiste de la simplification de code qui améliore la clarté et la maintenabilité du code sans en modifier le comportement Code-simplifier ist ein Spezialist für Code-Vereinfachung, der die Klarheit und Wartbarkeit des Codes verbessert, ohne dessen Funktionalität zu ändern O code-simplifier é um especialista em simplificação de código que melhora a clareza e manutenção do código sem alterar seu comportamento Code-Simplifier - это специалист по упрощению кода, который улучшает читаемость и поддерживаемость кода без изменения его поведения المبسّط للرمز هو خبير في تبسيط الرموز الذي يحسن وضوح وسهولة صيانة الرموز بدون تغيير سلوكه how to use code-simplifier code-simplifier alternative code-simplifier setup guide what is code-simplifier code-simplifier vs Copilot code-simplifier install for Claude Code 代码简化工具 AI助手 项目模板 代码可读性 代码可维护性 最佳实践 代码简化 代码优化 编程语言 代码一致性 Analyzes recently modified code for refactoring opportunities Applies project-specific best practices for improved code clarity Works with AI coding assistants like Claude Code and Copilot Prioritizes readable and explicit code over compact solutions Preserves exact functionality during code simplification code-simplifier is a project template for simplifying code with AI assistants, focusing on best practices for code clarity, consistency, and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ddoman90/claude-code-intro/clean-typescript', 'community', 'ddoman90', 'claude-code-intro', 'ddoman90/claude-code-intro', 'clean-typescript', 0, 0, 26, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:41.428Z', '2604a2aa60423b1fc2fa55512811e88c420a0ad8c72060fdfd161e0a9dcd9a35', '{"id":"ddoman90/claude-code-intro/clean-typescript","name":"clean-typescript","description":{"en":"clean-typescript is a style guide for writing clean, readable TypeScript code. It provides best practices for type declaration, function design, and nullability, benefiting developers who want to prioritize code correctness and clarity.","zh":"Clean TypeScript 是一种代码风格指南，优先考虑可读性和简洁性，帮助开发者编写高质量的 TypeScript 代码","ja":"Clean TypeScript は、可読性と簡潔性を優先するコードスタイルガイドです","ko":"Clean TypeScript는 타입스크립트 코드의 가독성과 명확성을 우선하는 코드 스타일 가이드입니다","es":"Clean TypeScript es un enfoque para utilizar TypeScript como herramienta de claridad y corrección, priorizando la legibilidad y la reducción de errores","fr":"Clean TypeScript est une approche pour utiliser TypeScript comme outil de clarté et de correction, en donnant la priorité à la lisibilité et à la réduction des erreurs","de":"Clean TypeScript ist ein Ansatz, um TypeScript als Werkzeug für Klarheit und Korrektheit zu verwenden, wobei die Lesbarkeit und die Fehlerreduzierung im Vordergrund stehen","pt":"O Clean TypeScript é um estilo de código que prioriza a clareza e a correção, utilizando tipos como ferramenta de redução de bugs","ru":"Чистый TypeScript - это стиль кода, который отдаёт приоритет ясности и правильности, используя типы как инструмент для уменьшения ошибок","ar":"Clean TypeScript هو أسلوب كود ي ưu tiên الوضوح والدقة، باستخدام الأنواع كأداة لتقليل الأخطاء"},"seo":{"title":{"en":"clean-typescript: Best Practices for AI Agents | AI Agent...","zh":"Clean TypeScript 代码风格指南","ja":"Clean TypeScript セットアップガイド","ko":"Clean TypeScript_best_practices","es":"Guía de configuración de Clean TypeScript para desarrolla...","fr":"Guide de mise en place de Clean TypeScript pour les dével...","de":"Einrichtungsleitfaden für Clean TypeScript-Entwickler","pt":"Guia de Configuração do Clean TypeScript para Desenvolved...","ru":"Настройка Чистого TypeScript: Лучшие Практики для Разрабо...","ar":"إعداد Clean TypeScript: دليل أفضل الممارسات للطورين"},"description":{"en":"Discover how to write clean, readable TypeScript code with our expert guide. Learn type declaration, function design, and nullability best practices today!","zh":"了解 Clean TypeScript 的最佳实践，包括类型声明、函数设计和可空性处理","ja":"Clean TypeScript のベストプラクティスを学ぶ、タイプ宣言、関数設計、nullability ハンドリング","ko":"Clean TypeScript를 위한 가이드, 타입 선언, 함수 설계, nullability 처리","es":"Aprende a utilizar Clean TypeScript para mejorar la claridad y corrección de tu código con nuestras mejores prácticas y guías","fr":"Découvrez comment utiliser Clean TypeScript pour améliorer la clarté et la correction de votre code avec nos meilleures pratiques et guides","de":"Erfahren Sie, wie Sie Clean TypeScript verwenden, um die Klarheit und Korrektheit Ihres Codes zu verbessern, mit unseren besten Praktiken und Anleitungen","pt":"Aprenda a configurar o Clean TypeScript para melhorar a clareza e a correção do seu código, com dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить Чистый TypeScript для повышения ясности и правильности вашего кода, с советами и лучшими практиками для разработчиков ИИ Агентов","ar":"تعرف على كيفية إعداد Clean TypeScript لتحسين الوضوح والدقة في كودك، مع نصائح وأفضل الممارسات للطورين"},"definition":{"en":"clean-typescript is a set of guidelines for using TypeScript as a correctness and clarity tool, prioritizing readable types and reducing bugs.","zh":"Clean TypeScript 是一种 TypeScript 代码风格指南，旨在提高代码的可读性和可维护性","ja":"Clean TypeScript は、TypeScript コードの可読性と保守性を高めるためのコードスタイルガイドです","ko":"Clean TypeScript는 타입스크립트 코드의 가독성과 유지보수성을 높이기 위한 코드 스타일 가이드입니다","es":"Clean TypeScript es un estilo de codificación que utiliza TypeScript para mejorar la claridad y corrección del código","fr":"Clean TypeScript est un style de codage qui utilise TypeScript pour améliorer la clarté et la correction du code","de":"Clean TypeScript ist ein Codierstil, der TypeScript verwendet, um die Klarheit und Korrektheit des Codes zu verbessern","pt":"Clean TypeScript é um estilo de código que visa melhorar a clareza e a correção do código TypeScript","ru":"Чистый TypeScript - это стиль кода, направленный на улучшение ясности и правильности кода TypeScript","ar":"Clean TypeScript هو أسلوب كود يهدف إلى تحسين الوضوح والدقة في كود TypeScript"},"features":{"en":["Uses `type` aliases for most situations","Employs `interface` for public, extensible object shapes","Prioritizes explicit return types for public functions","Handles nullability with care","Keeps types small and composable","Uses function overloads sparingly for enhanced API"],"zh":["类型别名优先","接口用于公共、可扩展的对象形状","保持类型小且可组合","显式返回类型用于公共函数","函数重载仅在必要时使用"],"ja":["タイプエイリアスを優先","インターフェイスを公開、拡張可能なオブジェクトシェイプに使用","タイプを小さくかつ組み合わせ可能に保つ","公開関数に明示的な戻り値タイプを使用","関数オーバーロードを必要な場合のみ使用"],"ko":["타입 에일리어스 우선","인터페이스를 공개, 확장 가능한 객체 형태에 사용","타입을 작고 조합 가능하게 유지","공개 함수에 명시적인 반환 타입 사용","함수 오버로드를 필요한 경우에만 사용"],"es":["Utiliza alias de tipo para la mayoría de las situaciones","Utiliza interfaces para formas de objeto públicas y extensibles","Mantiene los tipos pequeños y componibles","Preferencias de tipos de retorno explícitos para funciones públicas","Utiliza sobrecargas de funciones de manera limitada"],"fr":["Utilisez des alias de type pour la plupart des situations","Utilisez des interfaces pour les formes d''objet publiques et extensibles","Gardez les types petits et componibles","Préférez les types de retour explicites pour les fonctions publiques","Utilisez les surcharges de fonctions de manière limitée"],"de":["Verwenden Sie Typalias für die meisten Situationen","Verwenden Sie Schnittstellen für öffentliche und erweiterbare Objektformen","Halten Sie die Typen klein und komponierbar","Präferieren Sie explizite Rückgabetypen für öffentliche Funktionen","Verwenden Sie Funktionsüberladungen in begrenztem Umfang"],"pt":["Utilização de aliases de tipo para situações mais comuns","Uso de interfaces para objetos públicos e extensíveis","Tipos pequenos e compostos","Retornos de funções explícitos para funções públicas","Uso parcimonioso de sobrecargas de funções"],"ru":["Использование псевдонимов типов для наиболее распространенных ситуаций","Использование интерфейсов для публичных и расширяемых объектов","Маленькие и составные типы","Явные возвращаемые типы для публичных функций","Экономное использование перегрузок функций"],"ar":["استخدام 별칭ات النوع للمواقف الأكثر شيوعًا","استخدام الواجهات للكائنات العامة والقابلة للتوسيع","الأنواع الصغيرة والمركبة","إرجاع دالات明确 للدوال العامة","استخدام توفر دالات بحكمة"]},"keywords":{"en":["how to use clean-typescript","clean-typescript setup guide","clean-typescript vs JavaScript","clean-typescript install","what is clean-typescript","clean-typescript best practices","clean-typescript alternative","clean-typescript tutorial"],"zh":["Clean TypeScript","TypeScript 代码风格","类型声明","函数设计","可空性处理","AIエージェント","代码质量","可读性","简洁性"],"ja":["Clean TypeScript","TypeScript コードスタイル","タイプ宣言","関数設計","nullability ハンドリング","AIエージェント","コード品質","可読性","簡潔性"],"ko":["Clean TypeScript","타입스크립트 코드 스타일","타입 선언","함수 설계","nullability 처리","AI 에이전트","코드 품질","가독성","명확성"],"es":["Clean TypeScript","TypeScript para desarrolladores","Guía de estilo de codificación","Mejores prácticas de TypeScript","Desarrollo de software con TypeScript","Herramientas de desarrollo de TypeScript","Agentes de IA para desarrolladores","Herramientas de desarrollo de código"],"fr":["Clean TypeScript","TypeScript pour les développeurs","Guide de style de codage","Meilleures pratiques de TypeScript","Développement de logiciels avec TypeScript","Outils de développement de TypeScript","Agents d''IA pour les développeurs","Outils de développement de code"],"de":["Clean TypeScript","TypeScript für Entwickler","Codierstil-Leitfaden","Beste Praktiken für TypeScript","Software-Entwicklung mit TypeScript","Entwicklertools für TypeScript","KI-Agents für Entwickler","Code-Entwicklertools"],"pt":["Clean TypeScript","TypeScript para desenvolvedores","Guia de configuração do Clean TypeScript","Melhores práticas de código TypeScript","Desenvolvimento de software com Clean TypeScript","TypeScript como ferramenta de redução de bugs"],"ru":["Чистый TypeScript","TypeScript для разработчиков ИИ Агентов","Настройка Чистого TypeScript","Лучшие практики кода TypeScript","Разработка программного обеспечения с Чистым TypeScript","TypeScript как инструмент для уменьшения ошибок"],"ar":["Clean TypeScript","TypeScript للطورين","إعداد Clean TypeScript","أفضل الممارسات لكود TypeScript","تطوير البرمجيات مع Clean TypeScript","TypeScript كأداة لتقليل الأخطاء"]}},"owner":"ddoman90","repo":"claude-code-intro","repoPath":"ddoman90/claude-code-intro","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"clean-typescript","description":"Write clean, practical TypeScript focused on correctness over ceremony","bodyPreview":"# Clean TypeScript Style Guide\n\nUse TypeScript as a correctness and clarity tool, not as ceremony. Prioritize readable types that genuinely reduce bugs.\n\n## Type Declaration\n\n- **PREFER** `type` aliases for most situations\n- **USE** `interface` for public, extensible object shapes\n- Keep types small and composable\n\n## Function Design\n\n- **PREFER** explicit return types for public functions\n- Use function overloads sparingly, only when they meaningfully enhance the API\n\n## Nullability\n\n- Handle `","body":"# Clean TypeScript Style Guide\n\nUse TypeScript as a correctness and clarity tool, not as ceremony. Prioritize readable types that genuinely reduce bugs.\n\n## Type Declaration\n\n- **PREFER** `type` aliases for most situations\n- **USE** `interface` for public, extensible object shapes\n- Keep types small and composable\n\n## Function Design\n\n- **PREFER** explicit return types for public functions\n- Use function overloads sparingly, only when they meaningfully enhance the API\n\n## Nullability\n\n- Handle `null` and `undefined` explicitly through control flow and guards\n- **AVOID** non-null assertions (`!`) as regular practice\n\n## Avoid Anti-patterns\n\n- **AVOID** `enum` - use union types or `as const` objects instead\n- **AVOID** `any` - use `unknown` as the safer alternative\n\n## Error Handling\n\n- Type errors explicitly\n- Consider result objects or typed errors over broad exception throwing\n\n## Philosophy\n\nIf a type is hard to understand, it''s probably wrong. Prioritize maintainability and clear intent over theoretical type system completeness.\n"},"lastSynced":"2026-03-08T02:01:41.428Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Generation Agents needing high-quality, readable TypeScript code.","zh":"非常适合需要高质量、可读性强的TypeScript代码的代码生成代理。","ja":"高品質で読みやすいTypeScriptコードが必要なコード生成エージェントに最適です。","ko":"높은 품질과 가독성이 뛰어난 TypeScript 코드가 필요한 코드 생성 에이전트에게 적합합니다.","es":"Perfecto para los agentes de generación de código que necesitan código TypeScript de alta calidad y legible.","fr":"Parfait pour les agents de génération de code nécessitant un code TypeScript de haute qualité et lisible.","de":"Perfekt für Code-Generierungsagenten, die hochwertigen, lesbaren TypeScript-Code benötigen.","pt":"Perfeito para Agentes de Geração de Código que precisam de código TypeScript de alta qualidade e legível.","ru":"Идеально для агентов генерации кода, которым необходим высококачественный, читаемый код TypeScript.","ar":"مثالي لعميل توليد الكود الذي يحتاج إلى كود TypeScript عالي الجودة وقابل للقراءة."},"recommendation":{"en":"Empowers agents to write clean, maintainable TypeScript code using best practices for type declaration, function design, and nullability, prioritizing correctness and clarity with features like `type` aliases and explicit return types.","zh":"赋予代理写清晰、可维护的TypeScript代码的能力，使用类型声明、函数设计和可空性等最佳实践，优先考虑正确性和清晰度，具有`type`别名和显式返回类型等功能。","ja":"エージェントがクリーンでメンテナンス可能なTypeScriptコードを書く能力を付与し、型宣言、関数設計、nullabilityなどのベストプラクティスを使用して、正しさと明瞭性を優先し、`type`エイリアスや明示的な戻り値の型などの機能を備えています。","ko":"에이전트가 클린하고 유지 보수 가능한 TypeScript 코드를 작성할 수 있는 능력을 부여하며, 타입 선언, 함수 디자인, 및 널 가능성 등 최선의 관행을 사용하여 올바름과 명확성을 우선하며, `type` 별명 및 명시적 반환 유형 등의 기능을 제공합니다.","es":"Habilita a los agentes a escribir código TypeScript limpio y mantenible utilizando las mejores prácticas para la declaración de tipo, el diseño de funciones y la nulabilidad, priorizando la corrección y la claridad con características como alias de `type` y tipos de retorno explícitos.","fr":"Permet aux agents d''écrire du code TypeScript propre et maintenable en utilisant les meilleures pratiques pour la déclaration de type, la conception de fonctions et la nullité, en donnant la priorité à la correction et à la clarté avec des fonctionnalités comme les alias de `type` et les types de retour explicites.","de":"Ermächtigt Agenten, sauberen, wartbaren TypeScript-Code unter Verwendung der besten Praktiken für Typdeklaration, Funktionsdesign und Nullbarkeit zu schreiben, wobei Korrektheit und Klarheit mit Funktionen wie `type`-Aliassen und expliziten Rückgabetypen priorisiert werden.","pt":"Habilita os agentes a escreverem código TypeScript limpo e mantenedor, utilizando as melhores práticas para declaração de tipo, design de função e nulabilidade, priorizando a correção e a clareza com recursos como aliases de `type` e tipos de retorno explícitos.","ru":"Наделяет агентов возможностью писать чистый, поддерживаемый код TypeScript, используя лучшие практики для объявления типа, дизайна функции и нуллируемости, отдаёт приоритет правильности и ясности с помощью функций, таких как псевдонимы `type` и явные типы возвращаемых значений.","ar":"يمنح الوكلاء القدرة على كتابة كود TypeScript نظيف وقابل للصيانة، باستخدام أفضل الممارسات لتعريف النوع وتصميم الوظيفة والقابلية للتعديل، مع 優先考虑 الدقة والوضوح باستخدام ميزات مثل أسماء别ة `type` وأنواع الإرجاع الصريحة."},"useCases":{"en":["Enforcing coding standards with `interface` and `type` usage","Improving code readability through small, composable types","Reducing bugs with explicit nullability handling"],"zh":["使用`interface`和`type`强制执行编码标准","通过小的、可组合的类型提高代码可读性","使用显式的可空性处理来减少错误"],"ja":["`interface`と`type`を使用してコーディング規範を強制する","小さく組み合わせ可能な型を使用してコードの可読性を高める","明示的なnullabilityハンドリングを使用してバグを減らす"],"ko":["`interface`와 `type`을 사용하여 코딩 표준을 강제 적용함","작고 조합 가능한 타입을 사용하여 코드 가독성을 향상함","명시적인 널 가능성 처리를 사용하여 버그를 줄임"],"es":["Aplicar normas de codificación con el uso de `interface` y `type`","Mejorar la legibilidad del código a través de tipos pequeños y componibles","Reducir errores con el manejo explícito de nulabilidad"],"fr":["Mettre en œuvre des normes de codage avec l''utilisation de `interface` et `type`","Améliorer la lisibilité du code à l''aide de types petits et composable","Réduire les bogues avec la gestion explicite de la nullité"],"de":["Einhaltung von Codierungsstandards mit `interface`- und `type`-Verwendung","Verbesserung der Codelesbarkeit durch kleine, komponierbare Typen","Reduzierung von Fehlern durch explizite Nullbarkeitsbehandlung"],"pt":["Aplicar padrões de codificação com uso de `interface` e `type`","Melhorar a legibilidade do código por meio de tipos pequenos e compostos","Reduzir bugs com tratamento explícito de nulabilidade"],"ru":["Внедрение стандартов кодирования с использованием `interface` и `type`","Улучшение читаемости кода за счет небольших, составных типов","Снижение количества ошибок с помощью явного обработки нуллируемости"],"ar":["تطبيق معايير الترميز باستخدام `interface` و `type`","تحسين قراءة الكود من خلال أنواع صغيرة وقابلة للتكوين","تقليل الأخطاء مع معالجة واضحة للقابلية للتعديل"]},"limitations":{"en":["Requires TypeScript environment","Focus on code style and readability, not runtime performance optimization"],"zh":["需要TypeScript环境","注重代码样式和可读性，而不是运行时性能优化"],"ja":["TypeScript環境が必要","コードスタイルと可読性に重点を置き、ランタイムパフォーマンスの最適化には対処していない"],"ko":["TypeScript 환경이 필요함","코드 스타일과 가독성에 중점을 두고 있으며, 런타임 성능 최적화에는 대처하지 않음"],"es":["Requiere entorno de TypeScript","Se centra en el estilo de código y la legibilidad, no en la optimización del rendimiento en tiempo de ejecución"],"fr":["Nécessite un environnement TypeScript","Se concentre sur le style de code et la lisibilité, et non sur l''optimisation des performances en temps de execution"],"de":["Benötigt eine TypeScript-Umgebung","Konzentriert sich auf Code-Stil und Lesbarkeit, nicht auf Laufzeit-Performance-Optimierung"],"pt":["Requer ambiente TypeScript","Foco na estilo de código e legibilidade, não na otimização de desempenho em tempo de execução"],"ru":["Требуется среда TypeScript","Фокус на стиле кода и читаемости, а не на оптимизации производительности во время выполнения"],"ar":["يتطلب بيئة TypeScript","التركيز على أسلوب الكود وقراءته، وليس على تحسين أداء وقت التشغيل"]},"version":4},"contentHash":"2604a2aa60423b1fc2fa55512811e88c420a0ad8c72060fdfd161e0a9dcd9a35","qualityScore":26}');
