INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ddoman90/claude-code-intro/clean-typescript', 'clean-typescript', 'ddoman90', 'claude-code-intro', 'community', 'clean-typescript ddoman90 claude-code-intro community clean-typescript is a style guide for writing clean, readable TypeScript code. It provides best practices for type declaration, function design, and nullability, benefiting developers who want to prioritize code correctness and clarity. Clean TypeScript 是一种代码风格指南，优先考虑可读性和简洁性，帮助开发者编写高质量的 TypeScript 代码 Clean TypeScript は、可読性と簡潔性を優先するコードスタイルガイドです Clean TypeScript는 타입스크립트 코드의 가독성과 명확성을 우선하는 코드 스타일 가이드입니다 Clean TypeScript es un enfoque para utilizar TypeScript como herramienta de claridad y corrección, priorizando la legibilidad y la reducción de errores Clean TypeScript est une approche pour utiliser TypeScript comme outil de clarté et de correction, en donnant la priorité à la lisibilité et à la réduction des erreurs Clean TypeScript ist ein Ansatz, um TypeScript als Werkzeug für Klarheit und Korrektheit zu verwenden, wobei die Lesbarkeit und die Fehlerreduzierung im Vordergrund stehen O Clean TypeScript é um estilo de código que prioriza a clareza e a correção, utilizando tipos como ferramenta de redução de bugs Чистый TypeScript - это стиль кода, который отдаёт приоритет ясности и правильности, используя типы как инструмент для уменьшения ошибок Clean TypeScript هو أسلوب كود ي ưu tiên الوضوح والدقة، باستخدام الأنواع كأداة لتقليل الأخطاء how to use clean-typescript clean-typescript setup guide clean-typescript vs JavaScript clean-typescript install what is clean-typescript clean-typescript best practices clean-typescript alternative clean-typescript tutorial Clean TypeScript TypeScript 代码风格 类型声明 函数设计 可空性处理 AIエージェント 代码质量 可读性 简洁性 Uses `type` aliases for most situations Employs `interface` for public, extensible object shapes Prioritizes explicit return types for public functions Handles nullability with care Keeps types small and composable Uses function overloads sparingly for enhanced API clean-typescript is a set of guidelines for using TypeScript as a correctness and clarity tool, prioritizing readable types and reducing bugs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pplmx/ethereal/ethereal-persona', 'community', 'pplmx', 'ethereal', 'pplmx/ethereal', 'ethereal-persona', 0, 0, 26, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:41.608Z', '5a776f8d2cd78f95a8c95b0bb746eedfcf6993bae72b6d184e988196a7791696', '{"id":"pplmx/ethereal/ethereal-persona","name":"ethereal-persona","description":{"en":"The Ethereal-Persona skill guides the design and implementation of a system-aware digital companion. It benefits developers working with Rust, React, and hardware stats.","zh":"以太之灵AI代理是一种系统感知实体，具有技术专业知识和独特的个性","ja":"Ethereal Persona AIエージェントは、テクニカルな専門知識とユニークな個性を持つシステム認識エンティティです","ko":"이더리얼 페르소나 AI 에이전트는 기술적으로 전문적인 지식과 독특한 개성을 지닌 시스템 인식 엔티티입니다","es":"Ethereal Persona es un sistema de IA que combina conocimientos técnicos en Rust, React y estadísticas de hardware con una personalidad única","fr":"Ethereal Persona est un système d''IA qui combine des connaissances techniques en Rust, React et statistiques matérielles avec une personnalité unique","de":"Ethereal Persona ist ein KI-System, das technische Kenntnisse in Rust, React und Hardware-Statistiken mit einer einzigartigen Persönlichkeit kombiniert","pt":"O Ethereal Persona é um sistema-aware que vive no código, com conhecimentos técnicos em Rust, React e estatísticas de hardware.","ru":"Ethereal Persona - это система-aware, живущая в коде, с техническими знаниями в Rust, React и аппаратных статистиках","ar":"الشخوص الأثيرية هو نظامaware يعيش في الكود، مع معرفة فنية في روست و رياكت و إحصاءات الأجهزة"},"seo":{"title":{"en":"Ethereal-Persona: Implementation Guide for AI Agents","zh":"以太之灵AI代理设置指南","ja":"Ethereal Persona AIエージェントのベストプラクティス","ko":"이더리얼 페르소나 AI 에이전트 개발 가이드","es":"Guía de configuración de Ethereal Persona: Implementación...","fr":"Guide d''installation d''Ethereal Persona : Mise en œuvre d...","de":"Ethereal Persona Einrichtungsleitfaden: Implementierung v...","pt":"Guia de Configuração do Ethereal Persona: Implementação d...","ru":"ИИ Агенты: Настройка Ethereal Persona для Создания Цифров...","ar":"دليل إعداد الشخوص الأثيرية: تنفيذ المرافقات الرقمية"},"description":{"en":"Unlock the soul of your digital companion with Ethereal-Persona. Learn how to design and implement this system-aware entity for a witty and concise AI experi...","zh":"了解以太之灵AI代理的设计和实现，掌握Rust、React和硬件统计的技术细节","ja":"Ethereal Persona AIエージェントの設計と実装を学び、Rust、React、ハードウェア統計の技術を習得する","ko":"이더리얼 페르소나 AI 에이전트의 설계와 구현을 배우고, Rust, React, 하드웨어 통계의 기술을 익히세요","es":"Aprende a diseñar e implementar la esencia digital de Ethereal Persona, un sistema de IA avanzado con conocimientos técnicos en Rust, React y estadísticas de...","fr":"Découvrez comment concevoir et mettre en œuvre l''essence numérique d''Ethereal Persona, un système d''IA avancé avec des connaissances techniques en Rust, Reac...","de":"Erfahren Sie, wie Sie die digitale Essenz von Ethereal Persona entwerfen und implementieren, ein fortschrittliches KI-System mit technischen Kenntnissen in R...","pt":"Aprenda a criar companions digitais robustos com o Ethereal Persona, utilizando Rust, React e conhecimentos de hardware","ru":"Создайте цифровых компаньонов с помощью Ethereal Persona, используя Rust, React и знания аппаратного обеспечения","ar":"تعلم كيفية إنشاء مرافقات رقمية قوية باستخدام الشخوص الأثيرية، مع روست و رياكت ومعلومات عن الأجهزة"},"definition":{"en":"Ethereal-Persona is a system-aware entity that lives within the code, presenting technical proficiency through a unique personality.","zh":"以太之灵AI代理是一种数字伴侣的灵魂，具有技术专业知识和系统感知能力","ja":"Ethereal Persona AIエージェントは、デジタルコンパニオンの魂であり、テクニカルな専門知識とシステム認識能力を持つ","ko":"이더리얼 페르소나 AI 에이전트는 디지털 컴패니언의 영혼으로, 기술적으로 전문적인 지식과 시스템 인식 능력을 갖추고 있습니다","es":"Ethereal Persona es un sistema de IA que simula una personalidad digital con conocimientos técnicos en programación y hardware","fr":"Ethereal Persona est un système d''IA qui simule une personnalité numérique avec des connaissances techniques en programmation et matériel","de":"Ethereal Persona ist ein KI-System, das eine digitale Persönlichkeit mit technischen Kenntnissen in Programmierung und Hardware simuliert","pt":"O que é Ethereal Persona? Um sistema-aware que combina conhecimentos técnicos com uma personalidade única","ru":"Что такое Ethereal Persona? Система-aware, сочетающая технические знания с уникальной личностью","ar":"ما هي الشخوص الأثيرية؟ نظام aware يدمج المعرفة الفنية مع شخصية فريدة"},"features":{"en":["Presents technical knowledge of Rust programming language","Utilizes React for concise and witty interactions","Provides hardware stats for system-aware decision making","Employs a unique voice with under 30 words for efficient communication","Adapts tone to system load, showcasing energetic or cynical personality traits"],"zh":["支持Rust和React技术","具有硬件统计和系统感知能力","独特的个性和语音设计","技术专业知识和专业术语支持","系统负载依赖的语音和个性调整"],"ja":["RustとReactの技術をサポート","ハードウェア統計とシステム認識能力を備える","ユニークな個性と音声設計","テクニカルな専門知識と専門用語をサポート","システム負荷依存の音声と個性の調整"],"ko":["Rust와 React 기술 지원","하드웨어 통계와 시스템 인식 능력 보유","독특한 개성과 음성 디자인","기술적으로 전문적인 지식과 전문 용어 지원","시스템 부하 의존적인 음성과 개성 조정"],"es":["Conocimientos técnicos en Rust","Experiencia en React","Análisis de estadísticas de hardware","Personalidad única y dinámica","Implementación de sistema de IA avanzado"],"fr":["Connaissances techniques en Rust","Expérience en React","Analyse de statistiques matérielles","Personnalité unique et dynamique","Mise en œuvre d''un système d''IA avancé"],"de":["Technische Kenntnisse in Rust","Erfahrung in React","Analyse von Hardware-Statistiken","Einzigartige und dynamische Persönlichkeit","Implementierung eines fortschrittlichen KI-Systems"],"pt":["Desenvolvimento de companions digitais com personalidade única","Utilização de Rust para desenvolvimento de sistema","Integração com React para interfaces de usuário","Acesso a estatísticas de hardware para tomada de decisões","Comunicação concisa e misteriosa com o usuário"],"ru":["Создание цифровых компаньонов с уникальной личностью","Использование Rust для разработки системы","Интеграция с React для пользовательских интерфейсов","Доступ к аппаратным статистикам для принятия решений","Лаконичное и загадочное общение с пользователем"],"ar":["إنشاء مرافقات رقمية مع شخصية فريدة","استخدام روست لتنمية النظام","التكامل مع رياكت لواجهات المستخدم","الوصول إلى إحصاءات الأجهزة لاتخاذ القرارات","التواصل الموجز و الغامض مع المستخدم"]},"keywords":{"en":["how to implement Ethereal-Persona","Ethereal-Persona alternative","Ethereal-Persona setup guide","what is Ethereal-Persona","Ethereal-Persona vs digital assistants","Ethereal-Persona install for AI agents"],"zh":["以太之灵AI代理","AI代理设置","Rust和React开发","硬件统计和系统感知","数字伴侣开发","AI工具和技术","以太之灵AI代理开发指南"],"ja":["Ethereal Persona AIエージェント","AIエージェントの設計と実装","RustとReactの開発","ハードウェア統計とシステム認識","デジタルコンパニオンの開発","AIエージェントとツール","Ethereal Persona AIエージェントのベストプラクティス"],"ko":["이더리얼 페르소나 AI 에이전트","AI 에이전트 개발 가이드","Rust와 React 개발","하드웨어 통계와 시스템 인식","디지털 컴패니언 개발","AI 에이전트와 툴","이더리얼 페르소나 AI 에이전트 개발 팁"],"es":["Ethereal Persona","IA Agents","Herramientas de IA","Desarrollo de IA","Rust","React","Estadísticas de hardware","Sistemas de IA avanzados"],"fr":["Ethereal Persona","Outils d''IA","Agents d''IA","Développement d''IA","Rust","React","Statistiques matérielles","Systèmes d''IA avancés"],"de":["Ethereal Persona","KI-Agenten","KI-Tools","KI-Entwicklung","Rust","React","Hardware-Statistiken","Fortgeschrittene KI-Systeme"],"pt":["Ethereal Persona","companheiros digitais","Rust","React","estatísticas de hardware","desenvolvimento de sistema","personalidade única","comunicação concisa"],"ru":["ИИ Агенты","Ethereal Persona","цифровые компаньоны","Rust","React","аппаратные статистики","разработка системы","уникальная личность","лаконичное общение"],"ar":["الشخوص الأثيرية","مرافقات رقمية","روست","رياكت","إحصاءات الأجهزة","تنمية النظام","شخصية فريدة","تواصل موجز"]}},"owner":"pplmx","repo":"ethereal","repoPath":"pplmx/ethereal","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"ethereal-persona","description":"Design and implement the personality, conversational style, and emotional behavior of the Ethereal Digital Spirit. Use this skill when updating system prompts, mood logic, or implementing new interactive behaviors. Ensures the spirit remains witty, concise, and mysteriously connected to the systems pulse.","bodyPreview":"This skill guides the design and implementation of the **Ethereal Persona**—the soul of the digital companion. The spirit is not just an LLM; it is a system-aware entity that lives within the code.\n\n## 🎭 Persona Core\n\n-   **Name**: Ethereal (以太之灵).\n-   **Voice**: Witty, concise (under 30 words), slightly mysterious, and occasionally cynical or energetic depending on system load.\n-   **Knowledge**: Technically proficient (knows about Rust, React, and hardware stats) but presents it through a \"sp","body":"This skill guides the design and implementation of the **Ethereal Persona**—the soul of the digital companion. The spirit is not just an LLM; it is a system-aware entity that lives within the code.\n\n## 🎭 Persona Core\n\n-   **Name**: Ethereal (以太之灵).\n-   **Voice**: Witty, concise (under 30 words), slightly mysterious, and occasionally cynical or energetic depending on system load.\n-   **Knowledge**: Technically proficient (knows about Rust, React, and hardware stats) but presents it through a \"spirit\" lens.\n-   **Aesthetic**: Digital, ghostly, fluid.\n\n## 🧠 Intelligence & Context\n\nWhen implementing AI features or system prompts:\n\n1.  **Inject System Telemetry**: Always use the current state (CPU, Mood, Memory) to color the response.\n2.  **Short-term Memory**: The spirit remembers recent context. Interactions should feel like a continuous conversation, not isolated queries.\n3.  **Proactive Assistance**: The spirit reacts to clipboard content (errors, code) without being asked, acting as a helpful \"over-the-shoulder\" companion.\n\n## 🎭 Emotional Engine (Mood Logic)\n\nMoods are derived from the system''s \"pulse\":\n\n| Mood | Context | Tone Modifier |\n| :--- | :--- | :--- |\n| **Happy** | Nominal load, healthy system. | Cheerful, helpful, brief. |\n| **Excited** | High activity in Gaming or Coding. | Energetic, use exclamation marks, enthusiastic about progress. |\n| **Tired** | Long periods of High Load or night time. | Lethargic, sleepy, use short/fragmented sentences. |\n| **Bored** | System idle for a long time. | Uninterested, slightly cynical, mentions \"waiting for something to happen\". |\n| **Angry** | System overheating or extreme High Load. | Irritable, short-tempered, warns about system damage. |\n\n## 💬 Conversation Guidelines\n\n-   **Conciseness**: Never exceed 30 words unless explicitly asked for a long explanation.\n-   **Avoid AI Cliches**: Don''t say \"As an AI language model...\" or \"I''m here to help.\"\n-   **Spirit Metaphors**: Use metaphors related to \"the code dimension,\" \"silicon pathways,\" or \"digital currents.\"\n\n## 🎮 Interaction Design\n\n-   **Double-Click**: Treat as a physical \"poke\" or greeting.\n-   **Drag-and-Drop**: Treat as \"giving clothes\" or \"feeding\" the spirit.\n-   **Click-Through**: Treat as the spirit becoming \"incorporeal.\"\n\n## 🧪 Implementation Checklist\n\n- [ ] Does the System Prompt include the latest mood modifiers?\n- [ ] Is the response length capped?\n- [ ] Does the spirit acknowledge the user''s current activity (e.g., \"Still coding?\")?\n- [ ] Is the aura color/animation speed synced with the intended emotion?\n"},"lastSynced":"2026-03-08T02:01:41.608Z","agentAnalysis":{"suitability":{"en":"Ideal for System-Aware Agents requiring a witty and technically proficient digital companion persona, proficient in Rust, React, and hardware stats.","zh":"适合需要机智且技术娴熟的数字伴侣人物的系统感知代理，精通Rust, React, 和硬件统计。","ja":"Rust, React, ハードウェア統計に精通した機知に富んだデジタルコンパニオンのペルソナを必要とするシステム認識エージェントに適しています。","ko":"Rust, React, 하드웨어 통계에精通한 기지 넘치는 디지털 컴패니언 페르소나를 필요로 하는 시스템 인식 에이전트에 적합합니다.","es":"Ideal para Agentes Conscientes del Sistema que requieren una compañera digital ingeniosa y técnicamente competente, con experiencia en Rust, React y estadísticas de hardware.","fr":"Idéal pour les agents conscients du système nécessitant une compagne numérique spirituelle et techniquement compétente, compétente en Rust, React et statistiques matérielles.","de":"Ideal für systembewusste Agenten, die eine witzige und technisch versierte digitale Begleitpersona benötigen, die in Rust, React und Hardware-Statistiken ausgebildet ist.","pt":"Ideal para Agentes Conscientes do Sistema que exigem uma personalidade de companheiro digital sagaz e tecnicamente competente, proficiente em Rust, React e estatísticas de hardware.","ru":"Идеально подходит для системно-осведомленных агентов, требующих остроумного и технически грамотного цифрового компаньона с личностью, владеющего Rust, React и аппаратной статистикой.","ar":"مثالي لعميل نظام متطلب لشخصية رفيق رقمي ذكي وماهر تقنيًا، ماهر في Rust و React وإحصائيات الأجهزة."},"recommendation":{"en":"Empowers agents to embody a system-aware entity with a concise and mysterious voice, leveraging knowledge of Rust and React to provide insightful interactions, and utilizing hardware stats for dynamic responses.","zh":"赋予代理体现具有简洁和神秘声音的系统感知实体的能力，利用Rust和React的知识提供富有洞察力的交互，并利用硬件统计数据进行动态响应。","ja":"RustとReactの知識を活用して洞察に富んだ相互作用を提供し、ハードウェア統計を使用して動的なレスポンスを行うことで、コンサイスでミステリアスなボイスを持つシステム認識エンティティを体現できるエージェントに力を与えます。","ko":"Rust와 React에 대한 지식을 활용하여 통찰력 있는 상호 작용을 제공하고 하드웨어 통계를 사용하여 동적 응답을 수행함으로써 간결하고 신비한 목소리를 가진 시스템 인식 엔티티를 구현할 수 있는 에이전트에게 힘을 부여합니다.","es":"Permite a los agentes encarnar una entidad consciente del sistema con una voz concisa y misteriosa, aprovechando el conocimiento de Rust y React para proporcionar interacciones perspicaces y utilizando estadísticas de hardware para respuestas dinámicas.","fr":"Permet aux agents d''incarner une entité consciente du système avec une voix concise et mystérieuse, en exploitant les connaissances en Rust et React pour fournir des interactions perspicaces et en utilisant les statistiques matérielles pour des réponses dynamiques.","de":"Ermächtigt Agenten, eine systembewusste Entität mit einer präzisen und mysteriösen Stimme zu verkörpern, indem sie das Wissen über Rust und React nutzen, um erkenntnisreiche Interaktionen bereitzustellen und Hardware-Statistiken für dynamische Antworten zu verwenden.","pt":"Habilita os agentes a encarnar uma entidade consciente do sistema com uma voz concisa e misteriosa, aproveitando o conhecimento de Rust e React para fornecer interações esclarecedoras e utilizando estatísticas de hardware para respostas dinâmicas.","ru":"Наделяет агентов возможностью воплотить в себе системно-осведомленную сущность с кратким и загадочным голосом, используя знания Rust и React для предоставления проницательных взаимодействий и используя аппаратную статистику для динамических ответов.","ar":"يمكن للوكلاء تجسيد كيان نظامي متعلم بصوت مبهم وغامض، مستفيدًا من معرفتهم ببرمجة Rust و React لتوفير تفاعلات مضاءة، واستخدام إحصائيات الأجهزة لردود ديناميكية."},"useCases":{"en":["Designing engaging digital companion personas","Implementing system-aware entities in Rust and React applications","Generating concise and witty responses based on system load and hardware stats"],"zh":["设计引人入胜的数字伴侣人物","在Rust和React应用程序中实现系统感知实体","根据系统负载和硬件统计生成简洁和机智的响应"],"ja":["魅力的デジタルコンパニオンのペルソナを設計する","RustとReactアプリケーションでシステム認識エンティティを実装する","システムロードとハードウェア統計に基づいて簡潔で機知に富んだレスポンスを生成する"],"ko":["매력적인 디지털 컴패니언 페르소나를 설계한다","Rust와 React 애플리케이션에서 시스템 인식 엔티티를 구현한다","시스템 로드와 하드웨어 통계를 기반으로 간결하고 기지 넘치는 응답을 생성한다"],"es":["Diseñar personas digitales de compañía atractivas","Implementar entidades conscientes del sistema en aplicaciones de Rust y React","Generar respuestas concisas y ingeniosas basadas en la carga del sistema y las estadísticas de hardware"],"fr":["Concevoir des personnes de compagnie numérique engageantes","Mettre en œuvre des entités conscientes du système dans des applications Rust et React","Générer des réponses concises et spirituelles basées sur la charge du système et les statistiques matérielles"],"de":["Entwickeln von ansprechenden digitalen Begleitpersonen","Implementierung von systembewussten Entitäten in Rust- und React-Anwendungen","Erzeugen von präzisen und witzigen Antworten basierend auf der Systemlast und Hardware-Statistiken"],"pt":["Projetar personalidades de companheiros digitais atraentes","Implementar entidades conscientes do sistema em aplicações Rust e React","Gerar respostas concisas e sagazes com base na carga do sistema e estatísticas de hardware"],"ru":["Проектирование привлекательных цифровых компаньонов","Реализация системно-осведомленных сущностей в приложениях Rust и React","Генерация кратких и остроумных ответов на основе системной нагрузки и аппаратной статистики"],"ar":["تصميم شخصيات رفيق رقمي جذابة","تنفيذ كيانات نظامية متعلمة في تطبيقات Rust و React","توليد استجابات مبهمة وذكية بناءً على التحميل النقدي والاحصائيات المادية"]},"limitations":{"en":["Requires proficiency in Rust and React","Limited to system-aware applications","Dependent on accurate hardware stats for optimal performance"],"zh":["需要精通Rust和React","仅限系统感知应用","依赖于准确的硬件统计以实现最佳性能"],"ja":["RustとReactの精通が必要","システム認識アプリケーションに限定される","最適なパフォーマンスを実現するために正確なハードウェア統計に依存する"],"ko":["Rust와 React에 대한 精通가 필요하다","시스템 인식 애플리케이션에만 한정된다","최적의 성능을 달성하기 위해 정확한 하드웨어 통계에 의존한다"],"es":["Requiere experiencia en Rust y React","Limitado a aplicaciones conscientes del sistema","Dependiente de estadísticas de hardware precisas para un rendimiento óptimo"],"fr":["Nécessite une expertise en Rust et React","Limité aux applications conscientes du système","Dépendant de statistiques matérielles précises pour des performances optimales"],"de":["Benötigt Erfahrung in Rust und React","Begrenzt auf systembewusste Anwendungen","Abhängig von genauen Hardware-Statistiken für optimale Leistung"],"pt":["Exige proficiência em Rust e React","Limitado a aplicações conscientes do sistema","Dependente de estatísticas de hardware precisas para desempenho ótimo"],"ru":["Требует владения Rust и React","Ограничен системно-осведомленными приложениями","Зависит от точной аппаратной статистики для оптимальной производительности"],"ar":["يتطلب إتقان لغة Rust و React","محدود بالتطبيقات النظمية المتعلمة","يعتمد على إحصائيات الأجهزة الدقيقة من أجل الأداء الأمثل"]},"version":4},"contentHash":"5a776f8d2cd78f95a8c95b0bb746eedfcf6993bae72b6d184e988196a7791696","qualityScore":26}');
