INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pplmx/ethereal/ethereal-persona', 'ethereal-persona', 'pplmx', 'ethereal', 'community', 'ethereal-persona pplmx ethereal community The Ethereal-Persona skill guides the design and implementation of a system-aware digital companion. It benefits developers working with Rust, React, and hardware stats. 以太之灵AI代理是一种系统感知实体，具有技术专业知识和独特的个性 Ethereal Persona AIエージェントは、テクニカルな専門知識とユニークな個性を持つシステム認識エンティティです 이더리얼 페르소나 AI 에이전트는 기술적으로 전문적인 지식과 독특한 개성을 지닌 시스템 인식 엔티티입니다 Ethereal Persona es un sistema de IA que combina conocimientos técnicos en Rust, React y estadísticas de hardware con una personalidad única Ethereal Persona est un système d''IA qui combine des connaissances techniques en Rust, React et statistiques matérielles avec une personnalité unique Ethereal Persona ist ein KI-System, das technische Kenntnisse in Rust, React und Hardware-Statistiken mit einer einzigartigen Persönlichkeit kombiniert O Ethereal Persona é um sistema-aware que vive no código, com conhecimentos técnicos em Rust, React e estatísticas de hardware. Ethereal Persona - это система-aware, живущая в коде, с техническими знаниями в Rust, React и аппаратных статистиках الشخوص الأثيرية هو نظامaware يعيش في الكود، مع معرفة فنية في روست و رياكت و إحصاءات الأجهزة how to implement Ethereal-Persona Ethereal-Persona alternative Ethereal-Persona setup guide what is Ethereal-Persona Ethereal-Persona vs digital assistants Ethereal-Persona install for AI agents 以太之灵AI代理 AI代理设置 Rust和React开发 硬件统计和系统感知 数字伴侣开发 AI工具和技术 以太之灵AI代理开发指南 Presents technical knowledge of Rust programming language Utilizes React for concise and witty interactions Provides hardware stats for system-aware decision making Employs a unique voice with under 30 words for efficient communication Adapts tone to system load, showcasing energetic or cynical personality traits Ethereal-Persona is a system-aware entity that lives within the code, presenting technical proficiency through a unique personality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Maduixa/Glasstic/watch-connectivity', 'community', 'Maduixa', 'Glasstic', 'Maduixa/Glasstic', 'watch-connectivity', 0, 0, 26, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:51.050Z', 'cbc5f7814ffa666eb34c159ad31d663b16692afff8a38611368b4331983b90d4', '{"id":"Maduixa/Glasstic/watch-connectivity","name":"watch-connectivity","description":{"en":"The watch-connectivity skill enables developers to create iOS intermittent fasting tracker apps with SwiftUI, HealthKit integration, and glassmorphic design. It benefits developers building health and wellness applications.","zh":"Watch 连接性集成是一个 iOS 应用程序，使用 SwiftUI 和 HealthKit 进行间歇性禁食跟踪，具有玻璃形设计","ja":"Watch 接続性は、SwiftUI と HealthKit を使用した iOS 間歇性禁食トラッカー アプリです。ガラスモルフィック デザインを採用","ko":"ウォッチ 커넥티비티는 SwiftUI 및 HealthKit를 사용한 iOS 간歇적 금식 트래커 앱입니다. 유리 모르픽 디자인을採用","es":"watch-connectivity es una habilidad que permite a los desarrolladores crear aplicaciones de seguimiento de ayuno intermitente para iOS con SwiftUI y HealthKit. Ofrece diseño glassmorphic y funcionalidades de seguimiento de salud","fr":"watch-connectivity est une compétence qui permet aux développeurs de créer des applications de suivi du jeûne intermittent pour iOS avec SwiftUI et HealthKit. Elle offre un design glassmorphic et des fonctionnalités de suivi de la santé","de":"watch-connectivity ist eine Fähigkeit, die es Entwicklern ermöglicht, Apps zur Überwachung des intermittierenden Fastens für iOS mit SwiftUI und HealthKit zu erstellen. Sie bietet ein glassmorphic-Design und Gesundheitsüberwachungsfunktionen","pt":"O watch-connectivity é uma habilidade que permite criar aplicativos de jejum intermitente para iOS com integração do HealthKit e design glassmorphic","ru":"Watch-connectivity - это навык, который позволяет создавать приложения для часов iOS с интеграцией HealthKit и стекломорфным дизайном","ar":"ال