INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Maduixa/Glasstic/watch-connectivity', 'watch-connectivity', 'Maduixa', 'Glasstic', 'community', 'watch-connectivity Maduixa Glasstic community The watch-connectivity skill enables developers to create iOS intermittent fasting tracker apps with SwiftUI, HealthKit integration, and glassmorphic design. It benefits developers building health and wellness applications. Watch 连接性集成是一个 iOS 应用程序，使用 SwiftUI 和 HealthKit 进行间歇性禁食跟踪，具有玻璃形设计 Watch 接続性は、SwiftUI と HealthKit を使用した iOS 間歇性禁食トラッカー アプリです。ガラスモルフィック デザインを採用 ウォッチ 커넥티비티는 SwiftUI 및 HealthKit를 사용한 iOS 간歇적 금식 트래커 앱입니다. 유리 모르픽 디자인을採用 watch-connectivity es una habilidad que permite a los desarrolladores crear aplicaciones de seguimiento de ayuno intermitente para iOS con SwiftUI y HealthKit. Ofrece diseño glassmorphic y funcionalidades de seguimiento de salud watch-connectivity est une compétence qui permet aux développeurs de créer des applications de suivi du jeûne intermittent pour iOS avec SwiftUI et HealthKit. Elle offre un design glassmorphic et des fonctionnalités de suivi de la santé watch-connectivity ist eine Fähigkeit, die es Entwicklern ermöglicht, Apps zur Überwachung des intermittierenden Fastens für iOS mit SwiftUI und HealthKit zu erstellen. Sie bietet ein glassmorphic-Design und Gesundheitsüberwachungsfunktionen O watch-connectivity é uma habilidade que permite criar aplicativos de jejum intermitente para iOS com integração do HealthKit e design glassmorphic Watch-connectivity - это навык, который позволяет создавать приложения для часов iOS с интеграцией HealthKit и стекломорфным дизайном الوصول إلى الاتصال الساعي يسمح بإنشاء تطبيقات لمراقبة الصيام التقطعي على آي أو إس مع دمج HealthKit وتصميم زجاجي مورفي how to use watch-connectivity watch-connectivity setup guide watch-connectivity and HealthKit integration watch-connectivity vs Core Bluetooth watch-connectivity install what is watch-connectivity watch-connectivity alternative watch-connectivity and SwiftUI tutorial watch-connectivity failure handling watch-connectivity message schema Watch 连接性 SwiftUI HealthKit iOS 开发 间歇性禁食跟踪 玻璃形设计 WCSession 管理器 AI エージェント Generates Message schema with keys, payload types, and versioning Provides iOS WCSession manager and watch WCSession manager skeletons Includes failure handling strategy for not reachable and delays Supports minimal tests for encoding and decoding Integrates with HealthKit for health and wellness data Utilizes SwiftUI for building user interfaces watch-connectivity is an AI agent skill that facilitates integration with HealthKit and SwiftUI for building iOS apps with glassmorphic design');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OPS-PIvers/claude-resources/ops-brand-guidelines', 'community', 'OPS-PIvers', 'claude-resources', 'OPS-PIvers/claude-resources', 'ops-brand-guidelines', 0, 0, 26, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:52.841Z', '6faac055568820b3207fe81e692cf9bc0754f7b78c56825d2efc69a40bcea460', '{"id":"OPS-PIvers/claude-resources/ops-brand-guidelines","name":"ops-brand-guidelines","description":{"en":"The ops-brand-guidelines skill provides official brand styling for creating consistent materials, benefiting developers and marketers alike.","zh":"Ops品牌指南提供了创建一致、专业材料的官方指南，涵盖品牌风格、颜色和字体等技术细节。","ja":"Opsブランドガイドラインは、一貫したプロフェッショナルなマテリアルを作成するための公式ガイドラインを提供し、ブランドスタイル、カラー、フォントなどの技術的詳細を網羅しています。","ko":"Ops 브랜드 가이드라인은 일관성 있고 전문적인 자료를 생성하기 위한 공식 가이드라인을 제공하며, 브랜드 스타일, 색상 및 글꼴 등의 기술적 세부 사항을 다룹니다.","es":"El Skill ops-brand-guidelines proporciona las pautas oficiales de marca para crear materiales coherentes y profesionales","fr":"Le Skill ops-brand-guidelines fournit les directives de marque officielles pour créer des documents cohérents et professionnels","de":"Das Skill ops-brand-guidelines bietet die offiziellen Markenrichtlinien für die Erstellung konsistenter und professioneller Materialien","pt":"O Skill ops-brand-guidelines fornece diretrizes oficiais de marca para criar materiais consistentes e profissionais","ru":"Навык ops-brand-guidelines предоставляет официальные руководства по стилю бренда для создания последовательных и профессиональных материалов","ar":"مهارة ops-brand-guidelines توفر إرشادات العلامة التجارية الرسمية لإنشاء مواد متسقة ومحترفة"},"seo":{"title":{"en":"ops-brand-guidelines: Brand Styling Setup Guide | AI Agen...","zh":"Ops 品牌指南设置指南 - AI工具","ja":"Ops ブランドガイドラインベストプラクティス - AIエージェント","ko":"Ops 브랜드 가이드라인 설정 가이드 - AI 도구","es":"Guía de Estilo de Marca OPS: Mejores Prácticas para Desar...","fr":"Guide de Style de Marque OPS: Bonnes Pratiques pour les D...","de":"OPS-Markenstyleguide: Best Practices für Entwickler","pt":"Guia de Configuração de Estilo de Marca OPS","ru":"Настройка Руководства по Стилю Бренда OPS","ar":"إرشادات تنسيق العلامة التجارية OPS"},"description":{"en":"Discover the official Orono Technology brand guidelines and learn how to create consistent materials with our AI agent skill - get started now!","zh":"了解Ops品牌指南的技术细节，包括品牌风格、颜色和字体，确保您的材料符合Ops的视觉身份 - AI工具","ja":"Opsブランドガイドラインの技術的詳細を学び、ブランドスタイル、カラー、フォントを含む、すべてのマテリアルがOpsの視覚的なアイデンティティに準拠するようにする - AIエージェント","ko":"Ops 브랜드 가이드ライン의 기술적 세부 사항을 배우고, 브랜드 스타일, 색상 및 글꼴을 포함하여 모든 자료가 Ops의 시각적 정체성에 맞춰지도록 하십시오 - AI 도구","es":"Aprende a aplicar las pautas de marca oficiales de OPS para crear materiales profesionales y coherentes con nuestra identidad visual","fr":"Découvrez comment appliquer les directives de marque officielles d''OPS pour créer des documents professionnels et cohérents avec notre identité visuelle","de":"Erfahren Sie, wie Sie die offiziellen Markenrichtlinien von OPS anwenden, um professionelle und konsistente Materialien mit unserer visuellen Identität zu er...","pt":"Aprenda a aplicar as diretrizes de marca OPS para criar materiais consistentes e profissionais com nosso guia de estilo","ru":"Изучите руководство по стилю бренда OPS, чтобы создавать последовательные и профессиональные материалы с помощью ИИ Агентов","ar":"تعرف على إرشادات تنسيق العلامة التجارية OPS لإنشاء مواد متسقة ومحترفة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"ops-brand-guidelines is a set of official brand styling guidelines for creating consistent, professional materials that match the Orono Technology visual identity.","zh":"Ops品牌指南是创建一致、专业材料的官方标准，定义了品牌风格、颜色和字体等技术细节。","ja":"Opsブランドガイドラインは、一貫したプロフェッショナルなマテリアルを作成するための公式標準であり、ブランドスタイル、カラー、フォントなどの技術的詳細を定義しています。","ko":"Ops 브랜드 가이드라인은 일관성 있고 전문적인 자료를 생성하기 위한 공식 표준으로, 브랜드 스타일, 색상 및 글꼴 등의 기술적 세부 사항을 정의합니다.","es":"¿Qué es ops-brand-guidelines? Un conjunto de pautas de estilo de marca para crear materiales coherentes y profesionales","fr":"Qu''est-ce que ops-brand-guidelines? Un ensemble de directives de style de marque pour créer des documents cohérents et professionnels","de":"Was ist ops-brand-guidelines? Ein Satz von Markenstyleguides für die Erstellung konsistenter und professioneller Materialien","pt":"O que é ops-brand-guidelines? É um conjunto de diretrizes de marca para criar materiais visuais consistentes","ru":"Что такое ops-brand-guidelines? Это набор руководств по стилю бренда для создания последовательных визуальных материалов","ar":"ما هي إرشادات تنسيق العلامة التجارية OPS؟ هي مجموعة من الإرشادات لإنشاء مواد بصرية متسقة"},"features":{"en":["Provides official brand colors and font styles for consistent branding","Supports creation of professional presentations, documents, and marketing materials","Ensures consistent visual identity across all external-facing materials","References official OPS style guide for accurate branding","Applies to various document formats, including presentations and marketing materials"],"zh":["品牌风格指南","颜色和字体规范","部门格式指南","OPS风格指南","外部材料创建标准","视觉身份一致性"],"ja":["ブランドスタイルガイドライン","カラーとフォントの規範","部門フォーマットガイドライン","OPSスタイルガイドライン","外部マテリアル作成基準","視覚的なアイデンティティの一貫性"],"ko":["브랜드 스타일 가이드라인","색상 및 글꼴 규격","부서 서식 가이드라인","OPS 스타일 가이드라인","외부 자료 생성 기준","시각적 정체성 일관성"],"es":["Aplicación de colores de marca","Selección de fuentes adecuadas","Creación de materiales con formato coherente","Uso de la identidad visual de OPS","Creación de presentaciones y documentos profesionales","Aplicación de las pautas de estilo de marca en materiales externos"],"fr":["Application des couleurs de marque","Sélection de polices appropriées","Création de documents avec un format cohérent","Utilisation de l''identité visuelle d''OPS","Création de présentations et de documents professionnels","Application des directives de style de marque dans les documents externes"],"de":["Anwendung von Markenfarben","Auswahl geeigneter Schriftarten","Ers