INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OPS-PIvers/claude-resources/ops-brand-guidelines', 'ops-brand-guidelines', 'OPS-PIvers', 'claude-resources', 'community', 'ops-brand-guidelines OPS-PIvers claude-resources community The ops-brand-guidelines skill provides official brand styling for creating consistent materials, benefiting developers and marketers alike. Ops品牌指南提供了创建一致、专业材料的官方指南，涵盖品牌风格、颜色和字体等技术细节。 Opsブランドガイドラインは、一貫したプロフェッショナルなマテリアルを作成するための公式ガイドラインを提供し、ブランドスタイル、カラー、フォントなどの技術的詳細を網羅しています。 Ops 브랜드 가이드라인은 일관성 있고 전문적인 자료를 생성하기 위한 공식 가이드라인을 제공하며, 브랜드 스타일, 색상 및 글꼴 등의 기술적 세부 사항을 다룹니다. El Skill ops-brand-guidelines proporciona las pautas oficiales de marca para crear materiales coherentes y profesionales Le Skill ops-brand-guidelines fournit les directives de marque officielles pour créer des documents cohérents et professionnels Das Skill ops-brand-guidelines bietet die offiziellen Markenrichtlinien für die Erstellung konsistenter und professioneller Materialien O Skill ops-brand-guidelines fornece diretrizes oficiais de marca para criar materiais consistentes e profissionais Навык ops-brand-guidelines предоставляет официальные руководства по стилю бренда для создания последовательных и профессиональных материалов مهارة ops-brand-guidelines توفر إرشادات العلامة التجارية الرسمية لإنشاء مواد متسقة ومحترفة how to use ops-brand-guidelines ops-brand-guidelines setup guide Orono Technology brand styling brand guidelines for developers OPS style guide alternative creating consistent marketing materials what is ops-brand-guidelines ops-brand-guidelines install branding guidelines for AI agents Ops品牌指南 AI工具 品牌风格 颜色和字体 部门格式 OPS风格指南 外部材料创建 视觉身份一致性 Provides official brand colors and font styles for consistent branding Supports creation of professional presentations, documents, and marketing materials Ensures consistent visual identity across all external-facing materials References official OPS style guide for accurate branding Applies to various document formats, including presentations and marketing materials ops-brand-guidelines is a set of official brand styling guidelines for creating consistent, professional materials that match the Orono Technology visual identity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dave1010/tools/maps', 'community', 'dave1010', 'tools', 'dave1010/tools', 'maps', 0, 0, 26, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.209Z', 'ca956a26a4b364898bd1236666859175c382a3fb19d7b57bdeacc915cd9fb119', '{"id":"dave1010/tools/maps","name":"maps","description":{"en":"The maps skill provides a collection of tools for working with MapLibre, including setup and customization options for developers. It benefits developers who need to integrate interactive maps into their applications.","zh":"MapLibre是一套创建自定义地图的工具，包括CSS和JS加载、OpenFreeMap Liberty样式和导航控制","ja":"MapLibreはカスタムマップを作成するためのツールのコレクションです。CSSとJSのロード、OpenFreeMap Libertyスタイル、ナビゲーションコントロールなど","ko":"MapLibre는 사용자 지정 맵을 생성하기 위한 도구 모음입니다. CSS 및 JS 로드, OpenFreeMap Liberty 스타일, 탐색 제어 등","es":"MapLibre es una colección de herramientas para desarrolladores que necesitan integrar mapas en sus proyectos. Nuestra guía de configuración cubre los conceptos básicos de MapLibre","fr":"MapLibre est une collection d''outils pour les développeurs qui ont besoin d''intégrer des cartes dans leurs projets. Notre guide de configuration couvre les concepts de base de MapLibre","de":"MapLibre ist eine Sammlung von Tools für Entwickler, die Karten in ihre Projekte integrieren müssen. Unsere Einrichtungsanleitung deckt die Grundlagen von MapLibre ab","pt":"MapLibre é uma coleção de ferramentas para criar mapas personalizados. Aprenda a configurar mapas com estilos e controles de navegação","ru":"MapLibre - это коллекция инструментов для создания пользовательских карт. Узнайте, как настроить карты с помощью стилей и элементов управления навигацией","ar":"MapLibre هي مجموعة من الأدوات لإنشاء خرائط مخصصة. تعرف على كيفية إعداد الخرائط باستخدام أنماط و عناصر التحكم في الملاحة"},"seo":{"title":{"en":"Maps: MapLibre Setup Guide | AI Agent Skill","zh":"地图设置指南 - MapLibre基础","ja":"マップセットアップガイド - MapLibreベーシック","ko":"지도 설정 가이드 - MapLibre 기초","es":"Guía de configuración de MapLibre para desarrolladores","fr":"Guide de mise en place de MapLibre pour les développeurs","de":"Einrichtungsleitfaden für MapLibre-Entwickler","pt":"Guia de Configuração de Mapas com MapLibre","ru":"Настройка карт с помощью MapLibre: лучшие практики","ar":"إعداد خرائط مع MapLibre: دليل المستخدم"},"description":{"en":"Unlock the full potential of MapLibre with our expert setup guide. Learn how to integrate MapLibre-gl.js and customize your maps today!","zh":"学习如何使用MapLibre创建自定义地图，包括CSS和JS加载、OpenFreeMap Liberty样式和导航控制","ja":"MapLibreを使用してカスタムマップを作成する方法を学びます。CSSとJSのロード、OpenFreeMap Libertyスタイル、ナビゲーションコントロールなど","ko":"MapLibre를 사용하여 사용자 지정 맵을 생성하는 방법을 배우세요. CSS 및 JS 로드, OpenFreeMap Liberty 스타일, 탐색 제어 등","es":"Aprende a integrar MapLibre en tus proyectos con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment intégrer MapLibre dans vos projets avec notre guide de configuration et les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie MapLibre in Ihre Projekte integrieren, mit unserer Einrichtungsanleitung und Best Practices für Entwickler","pt":"Aprenda a configurar mapas com MapLibre, incluindo estilos de mapa e controles de navegação","ru":"Узнайте, как настроить карты с помощью MapLibre, включая стили карт и элементы управления навигацией","ar":"تعرف على كيفية إعداد الخرائط مع MapLibre، بما في ذلك أنماط الخريطة و عناصر التحكم في الملاحة"},"definition":{"en":"maps is a collection of tools for working with MapLibre, a JavaScript library for interactive maps","zh":"MapLibre是一套用于创建自定义地图的JavaScript库","ja":"MapLibreはカスタムマップを作成するためのJavaScriptライブラリ","ko":"MapLibre는 사용자 지정 맵을 생성하기 위한 JavaScript 라이브러리","es":"MapLibre es un conjunto de herramientas de código abierto para la creación de mapas web","fr":"MapLibre est un ensemble d''outils open source pour la création de cartes web","de":"MapLibre ist eine Sammlung von Open-Source-Tools für die Erstellung von Webkarten","pt":"MapLibre é uma biblioteca de código aberto para criação de mapas","ru":"MapLibre - это открытая библиотека для создания карт","ar":"MapLibre هي مكتبة مفتوحة المصدر لإنشاء الخرائط"},"features":{"en":["Loads MapLibre-gl.js script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Includes MapLibre''s CSS for styling and layout control","Uses the OpenFreeMap Liberty style for basemap rendering","Adds navigation controls with maplibregl.NavigationControl()","Supports absolute positioning of the map container for viewport filling"],"zh":["加载MapLibre的CSS和JS","使用OpenFreeMap Liberty样式","添加导航控制","支持绝对定位的容器","兼容多种浏览器"],"ja":["MapLibreのCSSとJSをロード","OpenFreeMap Libertyスタイルを使用","ナビゲーションコントロールを追加","絶対位置指定のコンテナをサポート","複数のブラウザに対応"],"ko":["MapLibre의 CSS 및 JS 로드","OpenFreeMap Liberty 스타일 사용","탐색 제어 추가","절대 위치 지정 컨테이너 지원","여러 브라우저 호환"],"es":["Incorporación de CSS de MapLibre antes de los estilos personalizados","Carga del script de MapLibre desde https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Uso del estilo OpenFreeMap Liberty como capa base","Adición de controles de navegación con map.addControl","Posicionamiento absoluto del contenedor del mapa para llenar la ventana gráfica"],"fr":["Intégration du CSS de MapLibre avant les styles personnalisés","Chargement du script de MapLibre depuis https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Utilisation du style OpenFreeMap Liberty comme calque de base","Ajout de contrôles de navigation avec map.addControl","Positionnement absolu du conteneur de la carte pour remplir la fenêtre graphique"],"de":["Einbindung des MapLibre-CSS vor den benutzerdefinierten Stilen","Laden des MapLibre-Skripts von https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Verwendung des OpenFreeMap-Liberty-Stils als Basisschicht","Hinzufügen von Navigationskontrollen mit map.addControl","Absolutes Positionieren des Kartencontainers, um die Grafikfenster zu füllen"],"pt":["Inclusão do CSS do MapLibre","Carga do script do MapLibre","Uso do estilo de mapa Liberty","Adição de controles de navegação","Posicionamento absoluto do contêiner do mapa"],"ru":["Включение CSS MapLibre","Загрузка скрипта MapLibre","Использование стиля карты Liberty","Добавление элементов управления навигацией","Абсолютное позиционирование контейнера карты"],"ar":["إضافة CSS من MapLibre","تحميل سكريبت MapLibre","استخدام نمط الخريطة Liberty","إضافة عناصر التحكم في الملاحة","التحديد المطلق ل حاوية الخريطة"]},"keywords":{"en":["how to use MapLibre","what is MapLibre","MapLibre alternative","MapLibre vs Leaflet","MapLibre setup guide","MapLibre install","interactive map development","map customization","MapLibre-gl.js integration"],"zh":["MapLibre","地图开发","JavaScript库","OpenFreeMap Liberty","导航控制","地图设置","AIエージェント","地图工具"],"ja":["MapLibre","マップ開発","JavaScriptライブラリ","OpenFreeMap Liberty","ナビゲーションコントロール","マップセットアップ","AIエージェント","マップツール"],"ko":["MapLibre","지도 개발","JavaScript 라이브러리","OpenFreeMap Liberty","탐색 제어","지도 설정","AI 에이전트","지도 도구"],"es":["MapLibre","desarrollo de mapas","cartografía web","herramientas de código abierto","integración de mapas","estilos de mapa","controles de navegación","posicionamiento absoluto"],"fr":["MapLibre","développement de cartes","cartographie web","outils open source","intégration de cartes","styles de carte","contrôles de navigation","positionnement absolu"],"de":["MapLibre","Kartenentwicklung","Webkartografie","Open-Source-Tools","Kartenintegration","Kartenstile","Navigationskontrollen","absolutes Positionieren"],"pt":["MapLibre","criação de mapas","estilos de mapa","controles de navegação","biblioteca de código aberto","desenvolvimento web","geolocalização","mapeamento"],"ru":["MapLibre","создание карт","стили карт","элементы управления навигацией","открытая библиотека","веб-разработка","геолокация","картофелина"],"ar":["MapLibre","إنشاء خرائط","أنماط الخريطة","عناصر التحكم في الملاحة","مكتبة مفتوحة المصدر","تطوير الويب","تحديد الموقع الجغرافي","خرائط"]}},"owner":"dave1010","repo":"tools","repoPath":"dave1010/tools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"maps","description":"Use when building interactive map tools - Explains MapLibre setup, tiles, and common UI patterns.","bodyPreview":"## MapLibre basics\n\n- Include MapLibre''s CSS before your styles and load the script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js.\n- Keep the map container absolutely positioned to fill the viewport (see `#map` styles in `tools/map-explorer/index.html`).\n- Use the OpenFreeMap Liberty style (`https://tiles.openfreemap.org/styles/liberty`) unless a different basemap is required.\n- Add navigation controls with `map.addControl(new maplibregl.NavigationControl(), ''top-right'');`.\n- Guar","body":"## MapLibre basics\n\n- Include MapLibre''s CSS before your styles and load the script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js.\n- Keep the map container absolutely positioned to fill the viewport (see `#map` styles in `tools/map-explorer/index.html`).\n- Use the OpenFreeMap Liberty style (`https://tiles.openfreemap.org/styles/liberty`) unless a different basemap is required.\n- Add navigation controls with `map.addControl(new maplibregl.NavigationControl(), ''top-right'');`.\n- Guard against missing globals: if `typeof maplibregl === ''undefined''`, disable map-dependent UI and show an error.\n\n## Geolocation pattern\n\n- Provide a dedicated button for `navigator.geolocation.getCurrentPosition`.\n- Disable the button while locating, apply a loading state, and reset it in success/error callbacks.\n- On success, create or update a `maplibregl.Marker` and `map.easeTo` the new center.\n- On errors, surface user-friendly messages for permission, availability, and timeout cases.\n\n## Overlay & interaction tips\n\n- Keep status text in small, unobtrusive elements and update it via helper functions.\n\n## Accessibility & layout\n\n- Generally prefer maps that take up the whole viewport, with UI controls and panels overlayed\n- Footer links in an overlay too.\n"},"lastSynced":"2026-03-08T02:03:06.209Z","agentAnalysis":{"suitability":{"en":"Perfect for Geospatial Analysis Agents needing interactive map integration capabilities with MapLibre","zh":"非常适合需要与 MapLibre 集成交互式地图功能的空间分析代理","ja":"MapLibre とのインタラクティブな地図統合機能が必要な地理空間分析エージェントに最適","ko":"MapLibre와의 상호작용형 맵 통합 기능이 필요한 지리공간 분석 에이전트에 적합","es":"Perfecto para Agentes de Análisis Geoespacial que necesitan capacidades de integración de mapas interactivos con MapLibre","fr":"Parfait pour les agents d''analyse géospatiale ayant besoin de capacités d''intégration de cartes interactives avec MapLibre","de":"Perfekt für Geospatial-Analyse-Agents, die interaktive Kartenintegrationsfunktionen mit MapLibre benötigen","pt":"Perfeito para Agentes de Análise Geoespacial que precisam de capacidades de integração de mapas interativos com MapLibre","ru":"Идеально подходит для агентов геопространственного анализа, которым необходимы возможности интерактивной интеграции карт с MapLibre","ar":"مثالي للوكلاء الذين يحتاجون إلى تحليلات جغرافية مكانية تتطلب إمكانيات التفاعل مع الخريطة مع MapLibre"},"recommendation":{"en":"Empowers agents to customize and interact with MapLibre maps using CSS and JavaScript, providing navigation controls and basemap styling with OpenFreeMap Liberty style, loaded from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","zh":"赋予代理自定义和与 MapLibre 地图交互的能力，使用 CSS 和 JavaScript 提供导航控件和底图样式，采用 OpenFreeMap Liberty 样式，从 https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js 加载","ja":"エージェントに MapLibre マップをカスタマイズしてインタラクションする能力を提供し、CSS と JavaScript を使用してナビゲーションコントロールとベースマップのスタイリングを行う、OpenFreeMap Liberty スタイルを使用、https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js からロード","ko":"에이전트에게 MapLibre 맵을 사용자 정의하고 상호작용할 수 있는 능력을 부여하며, CSS와 JavaScript를 사용하여 네비게이션 컨트롤과 베이스맵 스타일링을 제공하고, OpenFreeMap Liberty 스타일을 사용하여 https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js에서 로드","es":"Habilita a los agentes a personalizar e interactuar con mapas MapLibre utilizando CSS y JavaScript, proporcionando controles de navegación y estilo de mapa base con estilo OpenFreeMap Liberty, cargado desde https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","fr":"Permet aux agents de personnaliser et d''interagir avec les cartes MapLibre en utilisant CSS et JavaScript, fournissant des contrôles de navigation et un style de carte de base avec le style OpenFreeMap Liberty, chargé depuis https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","de":"Ermächtigt Agenten, MapLibre-Karten mit CSS und JavaScript zu personalisieren und zu interagieren, Navigationselemente und Basiskarten-Styling mit OpenFreeMap Liberty-Stil bereitzustellen, geladen von https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","pt":"Habilita os agentes a personalizar e interagir com mapas MapLibre usando CSS e JavaScript, fornecendo controles de navegação e estilização de mapa base com estilo OpenFreeMap Liberty, carregado de https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","ru":"Позволяет агентам настраивать и взаимодействовать с картами MapLibre, используя CSS и JavaScript, обеспечивая навигационные элементы управления и стилизацию базовой карты с помощью стиля OpenFreeMap Liberty, загружаемого из https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","ar":"تمكين الوكلاء من تخصيص الخريطة MapLibre والتفاعل معها باستخدام CSS و JavaScript ، وتوفير عناصر تحكم في الملاحة وتصميم الخريطة الأساسية باستخدام نمط OpenFreeMap Liberty ، الذي يتم تحميله من https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js"},"useCases":{"en":["Customizing interactive maps for web applications","Integrating navigation controls into map interfaces","Styling basemaps with OpenFreeMap Liberty style"],"zh":["为 Web 应用程序自定义交互式地图","将导航控件集成到地图接口中","使用 OpenFreeMap Liberty 样式对底图进行样式设置"],"ja":["Web アプリケーション用のインタラクティブマップのカスタマイズ","マップインターフェイスにナビゲーションコントロールを統合","OpenFreeMap Liberty スタイルを使用したベースマップのスタイリング"],"ko":["웹 애플리케이션을 위한 상호작용형 맵 사용자 정의","맵 인터페이스에 네비게이션 컨트롤을 통합","OpenFreeMap Liberty 스타일을 사용한 베이스맵 스타일링"],"es":["Personalizar mapas interactivos para aplicaciones web","Integrar controles de navegación en interfaces de mapas","Estilar mapas base con estilo OpenFreeMap Liberty"],"fr":["Personnaliser des cartes interactives pour des applications web","Intégrer des contrôles de navigation dans les interfaces de cartes","Styler les cartes de base avec le style OpenFreeMap Liberty"],"de":["Interaktive Karten für Webanwendungen anpassen","Navigationssteuerung in Kartenoberflächen integrieren","Basiskarten mit OpenFreeMap Liberty-Stil stylen"],"pt":["Personalizar mapas interativos para aplicações web","Integrar controles de navegação em interfaces de mapa","Estilizar mapas base com estilo OpenFreeMap Liberty"],"ru":["Настройка интерактивных карт для веб-приложений","Интеграция элементов навигации в интерфейсы карт","Стилизация базовых карт с помощью стиля OpenFreeMap Liberty"],"ar":["تخصيص الخريطة التفاعلية للتطبيقات الويب","دمج عناصر التحكم في الملاحة في واجهات الخريطة","تصميم الخريطة الأساسية باستخدام نمط OpenFreeMap Liberty"]},"limitations":{"en":["Requires MapLibre script loaded from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Map container must be absolutely positioned"],"zh":["需要从 https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js 加载 MapLibre 脚本","地图容器必须是绝对定位"],"ja":["https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js から MapLibre スクリプトをロードする必要がある","マップコンテナは絶対位置指定である必要がある"],"ko":["https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js에서 MapLibre 스크립트를 로드해야 함","맵 컨테이너는 절대 위치 지정이어야 함"],"es":["Requiere el script MapLibre cargado desde https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","El contenedor de mapas debe estar posicionado de forma absoluta"],"fr":["Nécessite le script MapLibre chargé depuis https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Le conteneur de cartes doit être positionné de manière absolue"],"de":["Benötigt das MapLibre-Skript, das von https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js geladen wird","Der Kartencontainer muss absolut positioniert sein"],"pt":["Requer o script MapLibre carregado de https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","O contêiner do mapa deve ser posicionado absolutamente"],"ru":["Требуется загрузка скрипта MapLibre из https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","Контейнер карты должен быть абсолютным"],"ar":["يتطلب تحميل سكريبت MapLibre من https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js","يجب وضع حاوية الخريطة بشكل مطلق"]},"version":4},"contentHash":"ca956a26a4b364898bd1236666859175c382a3fb19d7b57bdeacc915cd9fb119","qualityScore":26}');
