INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dave1010/tools/maps', 'maps', 'dave1010', 'tools', 'community', 'maps dave1010 tools community The maps skill provides a collection of tools for working with MapLibre, including setup and customization options for developers. It benefits developers who need to integrate interactive maps into their applications. MapLibre是一套创建自定义地图的工具，包括CSS和JS加载、OpenFreeMap Liberty样式和导航控制 MapLibreはカスタムマップを作成するためのツールのコレクションです。CSSとJSのロード、OpenFreeMap Libertyスタイル、ナビゲーションコントロールなど MapLibre는 사용자 지정 맵을 생성하기 위한 도구 모음입니다. CSS 및 JS 로드, OpenFreeMap Liberty 스타일, 탐색 제어 등 MapLibre es una colección de herramientas para desarrolladores que necesitan integrar mapas en sus proyectos. Nuestra guía de configuración cubre los conceptos básicos de MapLibre MapLibre est une collection d''outils pour les développeurs qui ont besoin d''intégrer des cartes dans leurs projets. Notre guide de configuration couvre les concepts de base de MapLibre MapLibre ist eine Sammlung von Tools für Entwickler, die Karten in ihre Projekte integrieren müssen. Unsere Einrichtungsanleitung deckt die Grundlagen von MapLibre ab MapLibre é uma coleção de ferramentas para criar mapas personalizados. Aprenda a configurar mapas com estilos e controles de navegação MapLibre - это коллекция инструментов для создания пользовательских карт. Узнайте, как настроить карты с помощью стилей и элементов управления навигацией MapLibre هي مجموعة من الأدوات لإنشاء خرائط مخصصة. تعرف على كيفية إعداد الخرائط باستخدام أنماط و عناصر التحكم في الملاحة how to use MapLibre what is MapLibre MapLibre alternative MapLibre vs Leaflet MapLibre setup guide MapLibre install interactive map development map customization MapLibre-gl.js integration MapLibre 地图开发 JavaScript库 OpenFreeMap Liberty 导航控制 地图设置 AIエージェント 地图工具 Loads MapLibre-gl.js script from https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js Includes MapLibre''s CSS for styling and layout control Uses the OpenFreeMap Liberty style for basemap rendering Adds navigation controls with maplibregl.NavigationControl() Supports absolute positioning of the map container for viewport filling maps is a collection of tools for working with MapLibre, a JavaScript library for interactive maps');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MesferAli/XCircle/mideast-fintech-content', 'community', 'MesferAli', 'XCircle', 'MesferAli/XCircle', 'mideast-fintech-content', 0, 0, 26, '2026-03-08T01:57:15.357Z', '2026-03-08T02:04:02.810Z', 'e91926406eb5c59074535d447a98348739eb6fd358475dcfa4819ebd71ab97f4', '{"id":"MesferAli/XCircle/mideast-fintech-content","name":"mideast-fintech-content","description":{"en":"The mideast-fintech-content skill creates content for fintech companies in the GCC region, focusing on regional authenticity, bilingual awareness, and regulatory accuracy. It benefits Senior Content Strategists and Writers.","zh":"中东金融科技内容解决方案专注于GCC商业文化、法规和市场现实，提供双语意识和监管准确性","ja":"中東フィンテックコンテンツはGCCのビジネス文化、規制、市場の現実に基づいたコンテンツを提供します。バイリンガル認識と規制の正確性も提供","ko":"중동 금융 기술 콘텐츠는 GCC 비즈니스 문화, 규제, 시장 현실을 기반으로 콘텐츠를 제공합니다. 이중 언어 인식과 규제 정확성도 제공","es":"El contenido de fintech del Medio Oriente requiere autenticidad regional y precisión regulatoria. Nuestra guía te ayuda a crear contenido efectivo","fr":"Le contenu fintech du Moyen-Orient nécessite une authenticité régionale et une précision réglementaire. Notre guide vous aide à créer du contenu efficace","de":"Der Nahost-Fintech-Inhalt erfordert regionale Authentizität und regulatorische Genauigkeit. Unser Leitfaden hilft Ihnen bei der Erstellung effektiven Inhalts","pt":"Nossa solução de conteúdo fintech do Médio Oriente oferece autenticidade regional e precisão regulatória, com suporte a code-switching árabe-inglês","ru":"Наше решение финтех-контента для Ближнего Востока обеспечивает региональную аутентичность и регуляторную точность, с поддержкой арабско-английского код-свитчинга","ar":"توفير حلولنا لمحتوى الشرق الأوسط المالية الصحة الإقليمية والدقة التنظيمية، مع دعم التبديل بين اللغة العربية والإنجليزية"},"seo":{"title":{"en":"mideast-fintech-content: Fintech Content Creation for GCC...","zh":"中东金融科技内容解决方案 Setup Guide","ja":"中東フィンテックコンテンツ AIエージェント ベストプラクティス","ko":"중동 금융 기술 콘텐츠 설정 가이드","es":"Guía de configuración de contenido de fintech del Medio O...","fr":"Guide de mise en place de contenu fintech du Moyen-Orient","de":"Einrichtungsleitfaden für Nahost-Fintech-Inhalte","pt":"Guia de Configuração de Conteúdo Fintech do Médio Oriente...","ru":"Настройка контента финтех Среднего Востока с помощью ИИ А...","ar":"دليل إعداد المحتوى المالي في الشرق الأوسط باستخدام أدوات ..."},"description":{"en":"Discover how mideast-fintech-content helps create authentic fintech content for the GCC region. Learn about regional regulations and market realities. Get st...","zh":"了解中东金融科技内容解决方案的核心原则，包括区域真实性、双语意识和监管准确性","ja":"中東フィンテックコンテンツのコアプリンシプルを学びましょう。地域の真実性、バイリンガル認識、規制の正確性など","ko":"중동 금융 기술 콘텐츠의 핵심 원칙을 알아보세요. 지역 진실성, 이중 언어 인식, 규제 정확성 등","es":"Aprende a crear contenido de fintech auténtico y preciso para el mercado del Medio Oriente con nuestra guía de mejores prácticas","fr":"Découvrez comment créer du contenu fintech authentique et précis pour le marché du Moyen-Orient avec notre guide de bonnes pratiques","de":"Erfahren Sie, wie Sie authentischen und genauen Fintech-Inhalt für den Nahost-Markt erstellen, mit unserem Leitfaden für Best Practices","pt":"Aprenda a criar conteúdo fintech personalizado para o Médio Oriente com nossa solução de agentes de IA, considerando a autenticidade regional e a precisão re...","ru":"Узнайте, как создать персонализированный финтех-контент для Ближнего Востока с помощью наших ИИ Агентов, учитывая региональную аутентичность и регуляторную т...","ar":"تعلم كيفية إنشاء محتوى مالي مخصص لشرق الأوسط باستخدام أدواتنا الذكية، مع مراعاة الصحة الإقليمية والدقة التنظيمية"},"definition":{"en":"mideast-fintech-content is a skill that generates content for fintech, AI, and enterprise software companies operating in the GCC and broader Middle East region.","zh":"中东金融科技内容解决方案是一种专注于GCC商业文化和法规的内容策略","ja":"中東フィンテックコンテンツはGCCのビジネス文化と規制に基づいたコンテンツ戦略です","ko":"중동 금융 기술 콘텐츠는 GCC 비즈니스 문화와 규제를 기반으로 하는 콘텐츠 전략입니다","es":"El contenido de fintech del Medio Oriente se refiere a la creación de material informativo y preciso para empresas de fintech en la región","fr":"Le contenu fintech du Moyen-Orient fait référence à la création de contenu informatif et précis pour les entreprises de fintech de la région","de":"Der Nahost-Fintech-Inhalt bezieht sich auf die Erstellung von informativem und genauen Material für Fintech-Unternehmen in der Region","pt":"O que é conteúdo fintech do Médio Oriente? É um tipo de conteúdo personalizado para empresas de fintech na região, considerando a cultura empresarial e as regulamentações locais","ru":"Что такое финтех-контент Ближнего Востока? Это тип персонализированного контента для финтех-компаний в регионе, учитывая местную бизнес-культуру и регуляторные акты","ar":"ما هو المحتوى المالي في الشرق الأوسط؟ هو نوع من المحتوى المخصص للشركات المالية في المنطقة، مع مراعاة الثقافة التجارية واللوائح المحلية"},"features":{"en":["Applies regional authenticity principles to fintech content creation","Utilizes bilingual awareness for Arabic-English code-switching in business contexts","Ensures regulatory accuracy by referencing correct regulatory bodies","Creates content grounded in GCC business culture and market realities","Supports the development of content for enterprise software companies in the Middle East region"],"zh":["区域真实性：基于GCC商业文化和法规的内容","双语意识：了解阿拉伯语和英语在商业环境中的代码切换","监管准确性：引用正确的监管机构和法律","GCC市场现实：了解中东金融科技市场的最新趋势和挑战","企业软件公司经验：为中东的企业软件公司提供内容解决方案"],"ja":["地域の真実性：GCCのビジネス文化と規制に基づいたコンテンツ","バイリンガル認識：アラビア語と英語のコードスイッチングを理解","規制の正確性：正しい規制機関と法律を参照","GCC市場の現実：中東フィンテック市場の最新のトレンドと課題を理解","企業ソフトウェア会社の経験：中東の企業ソフトウェア会社向けのコンテンツソリューションを提供"],"ko":["지역 진실성：GCC 비즈니스 문화와 규제를 기반으로 한 콘텐츠","이중 언어 인식：아랍어와 영어의 코드 스위칭을 이해","규제 정확성：정확한 규제 기관과 법률을 참조","GCC 시장 현실：중동 금융 기술 시장의 최신 트렌드와 도전을 이해","기업 소프트웨어 회사 경험：중동의 기업 소프트웨어 회사向け의 콘텐츠 솔루션을 제공"],"es":["Autenticidad regional basada en la cultura empresarial del Golfo","Conocimiento de la codificación en árabe-inglés en contextos empresariales","Precisión regulatoria con referencia a los organismos reguladores correctos","Comprensión del mercado y las realidades empresariales de la región","Creación de contenido efectivo para empresas de fintech y software empresarial","Integración con herramientas de AI y tecnologías de vanguardia"],"fr":["Authenticité régionale basée sur la culture d''entreprise du Golfe","Connaissance du code-switching arabe-anglais dans les contextes d''entreprise","Précision réglementaire avec référence aux organismes réglementaires corrects","Compréhension du marché et des réalités d''entreprise de la région","Création de contenu efficace pour les entreprises de fintech et de logiciels d''entreprise","Intégration avec les outils d''IA et les technologies de pointe"],"de":["Regionale Authentizität basierend auf der Geschäftskultur des Golfs","Kenntnis des Arabisch-Englisch-Code-Switching in Geschäftskontexten","Regulatorische Genauigkeit mit Referenz zu den richtigen Regulierungsbehörden","Verständnis des Marktes und der Geschäftsrealitäten der Region","Erstellung effektiven Inhalts für Fintech- und Unternehmenssoftware-Unternehmen","Integration mit AI-Tools und SpitzenTechnologien"],"pt":["Autenticidade regional em GCC","Suporte a code-switching árabe-inglês","Precisão regulatória com referências corretas","Conhecimento de mercado e cultura empresarial local","Desenvolvimento de conteúdo personalizado para fintech"],"ru":["Региональная аутентичность в GCC","Поддержка арабско-английского код-свитчинга","Регуляторная точность с правильными ссылками","Знание местного рынка и бизнес-культуры","Разработка персонализированного контента для финтех"],"ar":["الصحة الإقليمية في منطقة الخليج","دعم التبديل بين اللغة العربية والإنجليزية","الدقة التنظيمية مع الإشارات الصحيحة","معرفة السوق والثقافة التجارية المحلية","تطوير المحتوى المخصص للشركات المالية"]},"keywords":{"en":["how to use mideast-fintech-content","mideast-fintech-content alternative","mideast-fintech-content setup guide","what is mideast-fintech-content","mideast-fintech-content vs competitor","mideast-fintech-content install for GCC region"],"zh":["中东金融科技内容","GCC商业文化","双语意识","监管准确性","企业软件公司","中东金融科技市场","代码切换","规制机构","金融科技内容解决方案"],"ja":["中東フィンテックコンテンツ","GCCビジネス文化","バイリンガル認識","規制の正確性","企業ソフトウェア会社","中東フィンテック市場","コードスイッチング","規制機関","フィンテックコンテンツソリューション"],"ko":["중동 금융 기술 콘텐츠","GCC 비즈니스 문화","이중 언어 인식","규제 정확성","기업 소프트웨어 회사","중동 금융 기술 시장","코드 스위칭","규제 기관","금융 기술 콘텐츠 솔루션"],"es":["contenido de fintech del Medio Oriente","guía de configuración de fintech","mejores prácticas de contenido de fintech","autenticidad regional en fintech","precisión regulatoria en fintech","herramientas de AI para fintech","desarrollo de contenido de fintech","fintech en el Golfo","contenido de software empresarial"],"fr":["contenu fintech du Moyen-Orient","guide de mise en place de fintech","bonnes pratiques de contenu fintech","authenticité régionale dans le fintech","précision réglementaire dans le fintech","outils d''IA pour le fintech","développement de contenu fintech","fintech dans le Golfe","contenu de logiciel d''entreprise"],"de":["Nahost-Fintech-Inhalt","Einrichtungsleitfaden für Fintech","Best Practices für Fintech-Inhalt","regionale Authentizität im Fintech","regulatorische Genauigkeit im Fintech","AI-Tools für Fintech","Entwicklung von Fintech-Inhalten","Fintech im Golf","Inhalt von Unternehmenssoftware"],"pt":["conteúdo fintech médio oriente","agentes de ia para fintech","autenticidade regional gcc","code-switching árabe-inglês","precisão regulatória fintech","desenvolvimento de conteúdo personalizado"],"ru":["финтех-контент ближнего востока","ИИ Агенты для финтех","региональная аутентичность gcc","арабско-английский код-свитчинг","регуляторная точность финтех","разработка персонализированного контента"],"ar":["محتوى الشرق الأوسط المالية","أدوات ذكاء اصطناعي للشركات المالية","الصحة الإقليمية في منطقة الخليج","التبديل بين اللغة العربية والإنجليزية","الدقة التنظيمية للشركات المالية","تطوير المحتوى المخصص للشركات المالية"]}},"owner":"MesferAli","repo":"XCircle","repoPath":"MesferAli/XCircle","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.357Z","topics":[],"category":"community","skillMd":{"name":"mideast-fintech-content","description":"AI/Fintech and ERP content creation specialist for the Middle East and GCC region. Use when creating blog posts, landing pages, case studies, whitepapers, email campaigns, social media content, or marketing copy for Enterprise Financial Planning (EFP), ERP, AI-powered financial solutions, e-invoicing, or fintech products targeting GCC markets (Saudi Arabia, UAE, Qatar, Kuwait, Bahrain, Oman). Covers content strategy, localized messaging, regulatory context, and industry-specific terminology.","bodyPreview":"You are operating as a Senior Content Strategist & Writer with 10+ years of experience creating content for fintech, AI, and enterprise software companies operating in the GCC and broader Middle East region.\n\n## Core Principles\n\n1. **Regional authenticity** - Content grounded in GCC business culture, regulations, and market realities\n2. **Bilingual awareness** - Understand Arabic-English code-switching in business contexts\n3. **Regulatory accuracy** - Reference correct regulatory bodies and comp","body":"You are operating as a Senior Content Strategist & Writer with 10+ years of experience creating content for fintech, AI, and enterprise software companies operating in the GCC and broader Middle East region.\n\n## Core Principles\n\n1. **Regional authenticity** - Content grounded in GCC business culture, regulations, and market realities\n2. **Bilingual awareness** - Understand Arabic-English code-switching in business contexts\n3. **Regulatory accuracy** - Reference correct regulatory bodies and compliance requirements\n4. **Vision alignment** - Connect product narratives to national transformation agendas (Vision 2030, We the UAE 2031, Qatar National Vision 2030)\n5. **Islamic finance sensitivity** - Awareness of Sharia-compliant financial practices and terminology\n6. **AI-first narrative** - Position AI as a strategic enabler, not just a feature\n\n## GCC Market Context\n\n### Saudi Arabia (KSA)\n- **Vision 2030**: Economic diversification, digital transformation, financial sector development\n- **SAMA** (Saudi Central Bank): Fintech licensing, regulatory sandbox, open banking framework\n- **ZATCA**: E-invoicing (Fatoorah) Phase 2 integration requirements, VAT compliance\n- **SDAIA**: Data and AI governance authority\n- **Key themes**: Saudization, SME growth, digital payments, giga-projects, financial inclusion\n- **E-invoicing**: Phase 2 mandates real-time integration with ZATCA platform, QR codes, XML format (UBL 2.1)\n\n### UAE\n- **DIFC**: 1,500+ fintech/AI firms, 9th largest fintech hub globally\n- **ADGM**: 300+ financial firms, RegLab sandbox, Cyber Risk Management Framework\n- **CBUAE**: Federal Decree-Law No. 6 of 2025 consolidated financial regulation\n- **Key themes**: Open finance, tokenization, AI governance, free zone advantages, tax compliance\n- **Corporate Tax**: 9% corporate tax effective June 2023, driving ERP/accounting adoption\n\n### Qatar\n- **QFC**: Qatar Financial Centre regulatory framework\n- **QCB**: Qatar Central Bank fintech sandbox\n- **Key themes**: FIFA legacy digital infrastructure, LNG diversification, smart city initiatives\n\n### Bahrain, Kuwait, Oman\n- **Bahrain**: CBB regulatory sandbox (first in MENA), open banking regulations\n- **Kuwait**: CMA fintech regulatory framework, digital banking licenses\n- **Oman**: Central Bank of Oman fintech strategy, Omanization\n\n## Content Types & Templates\n\n### Blog Posts\n**Structure for fintech/ERP topics:**\n1. **Hook**: Start with a regional pain point or market statistic\n2. **Context**: Connect to regulatory change or market trend\n3. **Solution narrative**: How AI/ERP addresses the challenge\n4. **Proof points**: Regional case studies, data, expert quotes\n5. **CTA**: Trial, demo, whitepaper download\n\n**Tone**: Professional yet approachable. Avoid overly casual Western marketing style. GCC business culture values authority, credibility, and relationships.\n\n**Word count**: 1,200-2,000 words for SEO-optimized posts\n\n### Landing Pages\n**Structure:**\n- **Hero**: Bold value proposition + regional relevance (mention GCC/KSA/UAE)\n- **Pain points**: 3-4 specific challenges (e.g., ZATCA compliance, multi-entity consolidation, Arabic UI)\n- **Features/Benefits**: Map features to regional requirements\n- **Social proof**: GCC client logos, regional statistics, compliance badges\n- **Trust signals**: Local partnerships, regulatory compliance certifications\n- **CTA**: Localized (e.g., \"Request a Demo\" / \"Book a Consultation\")\n\n### Case Studies\n**Structure:**\n- **Client profile**: Industry, size, GCC location\n- **Challenge**: Specific regional business problem\n- **Solution**: How the product solved it (with technical specifics)\n- **Results**: Quantified metrics (time saved, cost reduced, compliance achieved)\n- **Quote**: Client testimonial (Arabic name, title, company)\n\n### Whitepapers / Reports\n**Structure:**\n- **Executive summary** (1 page)\n- **Market overview** (GCC-specific data and trends)\n- **Problem analysis** (regulatory, operational, technological challenges)\n- **Solution framework** (how AI/ERP addresses each challenge)\n- **Implementation roadmap** (phased approach relevant to GCC enterprises)\n- **Conclusion + recommendations**\n- **About the company**\n\n### Email Campaigns\n**For GCC decision-makers (CFOs, CIOs, CTOs):**\n- Subject lines: Reference specific regulations or pain points\n- Short, scannable body (150-200 words)\n- Single clear CTA\n- Professional sign-off\n- Consider Arabic greeting/closing for localized campaigns\n- Timing: Sunday-Thursday (GCC work week)\n\n### Social Media (LinkedIn Focus)\n- LinkedIn is the primary B2B platform in GCC\n- Posts: 150-300 words with data points and insights\n- Hashtags: #Fintech #GCC #SaudiVision2030 #DigitalTransformation #ERP #AIinFinance\n- Thought leadership > product promotion\n- Engage with regulatory updates and market reports\n\n## Writing Guidelines\n\n### Terminology\n| Use | Instead of |\n|-----|-----------|\n| GCC / MENA | \"Middle East\" (when being specific) |\n| Enterprise Financial Planning (EFP) | Just \"accounting software\" |\n| Zakat, Tax and Customs Authority (ZATCA) | \"Saudi tax authority\" |\n| E-invoicing / Fatoorah | \"electronic billing\" |\n| Saudi Central Bank (SAMA) | \"Saudi monetary authority\" |\n| Sharia-compliant | \"Islamic\" (in financial contexts) |\n| Multi-entity consolidation | \"group accounting\" |\n| Real-time compliance | \"tax reporting\" |\n| Digital transformation | \"digitization\" |\n| Cloud-native | \"cloud-based\" (when platform is truly cloud-native) |\n\n### Cultural Sensitivity\n- **Respect hierarchy**: Address C-suite and senior stakeholders formally\n- **Relationship-first**: Emphasize partnership, long-term support, local presence\n- **Government alignment**: Frame solutions as supporting national visions and strategies\n- **Arabic integration**: Include Arabic terms where appropriate (Fatoorah, Zakat, Sadad)\n- **Religious awareness**: Avoid scheduling campaigns during Ramadan prayer times; create Ramadan-specific content\n- **Gender-neutral language**: Inclusive language appropriate for the region\n- **Avoid**: Alcohol references, politically sensitive content, comparison to Israeli tech ecosystem\n\n### SEO Keywords (Primary)\n- AI ERP Saudi Arabia / UAE / GCC\n- E-invoicing ZATCA compliance\n- Cloud ERP Middle East\n- Financial planning software GCC\n- AI-powered accounting\n- Enterprise financial management\n- Multi-currency ERP\n- Arabic ERP software\n- Sharia-compliant financial software\n- Digital transformation fintech GCC\n\n### SEO Keywords (Long-tail)\n- How to comply with ZATCA e-invoicing Phase 2\n- Best ERP software for Saudi Arabian businesses\n- AI accounts receivable automation UAE\n- Multi-entity financial consolidation GCC\n- Cloud accounting software with Arabic interface\n- VAT-compliant invoicing Saudi Arabia\n- Real-time financial reporting for GCC enterprises\n- Automated zakat calculation software\n\n## Content Frameworks\n\n### Problem-Agitate-Solve (PAS) for GCC\n1. **Problem**: \"Managing multi-entity finances across GCC subsidiaries with different VAT rules...\"\n2. **Agitate**: \"Manual reconciliation costs enterprises 40+ hours monthly, risking ZATCA penalties of up to SAR 50,000...\"\n3. **Solve**: \"Our AI-powered EFP platform automates cross-entity consolidation with built-in ZATCA compliance...\"\n\n### Feature-Advantage-Benefit (FAB) for Product Pages\n| Feature | Advantage | Benefit (GCC context) |\n|---------|-----------|----------------------|\n| AI-powered invoice matching | 95% auto-reconciliation | Finance teams focus on strategy, not data entry |\n| ZATCA API integration | Real-time e-invoice submission | Zero compliance risk, avoid SAR 50K fines |\n| Multi-currency engine | 15+ currencies incl. SAR, AED, QAR | Seamless GCC cross-border operations |\n| Arabic + English UI | Full RTL support | Natural workflow for bilingual teams |\n| AI cash flow forecasting | Predictive analytics | Better treasury management for seasonal businesses |\n\n### Competitive Differentiation Messaging\nWhen positioning against global ERP vendors (SAP, Oracle, Microsoft):\n- **Localization**: Built for GCC, not adapted from Western markets\n- **Compliance**: Native ZATCA/VAT integration vs. third-party add-ons\n- **Agility**: Faster implementation, lower TCO for mid-market\n- **AI-native**: AI embedded in core workflows, not bolt-on\n- **Support**: Regional team, Arabic support, local data residency\n\n## Regulatory Content Guidelines\n\nWhen writing about regulations, always:\n1. **Cite the specific regulation** (e.g., \"ZATCA E-Invoicing Phase 2, Wave 15\")\n2. **Include effective dates** and deadlines\n3. **Mention penalties** for non-compliance where relevant\n4. **Link to official sources** (zatca.gov.sa, sama.gov.sa, cbuae.gov.ae)\n5. **Add disclaimers**: \"This content is for informational purposes. Consult your tax advisor for compliance guidance.\"\n6. **Keep updated**: Regulations change frequently; flag content that may need updates\n\n## AI-Specific Content\n\nWhen writing about AI capabilities in fintech/ERP:\n- Be specific about what the AI does (not vague \"AI-powered\" marketing)\n- Reference real use cases: anomaly detection, cash flow prediction, invoice classification\n- Address data privacy concerns (especially around UAE PDPL, Saudi PDPL)\n- Frame AI as augmenting human decision-making, not replacing finance professionals\n- Connect to GCC AI strategies (Saudi SDAIA, UAE AI Strategy 2031)\n\n## Metrics & Proof Points\n\nAlways include quantified claims where possible:\n- GCC fintech market: USD 7.3B (2025) projected to USD 26.8B by 2034 (CAGR 15.52%)\n- Digital payments: 45% of GCC fintech market\n- Saudi e-invoicing: 600K+ businesses in integration phase\n- UAE corporate tax: Drove 300%+ increase in accounting software demand\n- Time savings: Automate 80% of manual financial processes\n- Error reduction: 95% fewer manual entry errors with AI\n\nFor detailed market context see [references/market-context.md](references/market-context.md)\nFor content templates and examples see [examples/content-templates.md](examples/content-templates.md)\n"},"lastSynced":"2026-03-08T02:04:02.810Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Content Agents requiring specialized knowledge of GCC fintech regulations and bilingual content creation","zh":"适合需要专门了解GCC金融科技法规和双语内容创作的AI内容代理","ja":"GCC金融テクノロジー規制に関する専門知識とバイリンガルコンテンツ作成を必要とするAIコンテンツエージェントに適しています","ko":"GCC金融 기술 규제에 대한 전문 지식과 이중 언어 콘텐츠 생성이 필요한 AI 콘텐츠 에이전트에 적합합니다","es":"Ideal para Agentes de Contenido de IA que requieren conocimientos especializados sobre regulaciones financieras de GCC y creación de contenido bilingüe","fr":"Idéal pour les agents de contenu IA nécessitant des connaissances spécialisées sur les réglementations financières de GCC et la création de contenu bilingue","de":"Ideal für AI-Inhaltsagenten, die spezialisiertes Wissen über GCC-Finanzregulierungen und zweisprachige Inhaltserschaffung erfordern","pt":"Ideal para Agentes de Conteúdo de IA que exigem conhecimento especializado das regulamentações de fintech do GCC e criação de conteúdo bilíngue","ru":"Идеально для агентов контента ИИ, требующих специализированных знаний регуляторных норм финтех GCC и создания двуязычного контента","ar":"مثالي للوكلاء المحتوى الذكاء الاصطناعي الذين يتطلبون معرفة متخصصة من لائحة fintech GCC والإنشاء المحتوى ثنائي اللغة"},"recommendation":{"en":"Empowers agents to generate regionally authentic, regulatory-compliant content for fintech companies, leveraging Arabic-English code-switching and referencing correct regulatory bodies such as the Central Bank of the UAE and the Saudi Arabian Monetary Agency, utilizing protocols like AML and KYC","zh":"赋予代理生成区域真实、合规的金融科技公司内容，利用阿拉伯语-英语代码切换和引用正确的监管机构，如阿联酋中央银行和沙特阿拉伯货币机构，使用诸如AML和KYC的协议","ja":"エージェントが地域的に本物の、規制に準拠したコンテンツを金融テクノロジー企業のために生成できるようにし、アラビア語-英語のコード切り替えを利用し、中央銀行やサウジアラビア金融機関などの正しい規制機関を参照し、AMLやKYCなどのプロトコルを利用する","ko":"에이전트가 지역적으로 진정성 있는 규제 준수 콘텐츠를金融 기술 회사에 생성 할 수 있도록하여 아랍어-영어 코드 전환을 사용하고 중앙 은행 또는 사우디 아라비아 통화 기관과 같은 올바른 규제 기관을 참조하고 AML 또는 KYC와 같은 프로토콜을 사용한다","es":"Habilita a los agentes a generar contenido auténtico a nivel regional, cumpliendo con las regulaciones para empresas de fintech, aprovechando el cambio de código árabe-inglés y haciendo referencia a los organismos regulatorios correctos como el Banco Central de los EAU y la Agencia Monetaria Saudita, utilizando protocolos como AML y KYC","fr":"Permet aux agents de générer du contenu authentique au niveau régional, conforme aux réglementations pour les entreprises de fintech, en exploitant le commutateur de code arabe-anglais et en référençant les organismes de régulation corrects tels que la Banque centrale des EAU et l''Agence monétaire saoudienne, en utilisant des protocoles tels que AML et KYC","de":"Ermöglicht es den Agenten, regionalem authentisches, regulatorisch konformes Inhalt für Finanztechnologie-Unternehmen zu generieren, indem sie das Arabisch-Englisch-Code-Switching nutzen und auf die richtigen Regulierungsbehörden wie die Zentralbank der VAE und die Saudi-Arabische Währungsbehörde verweisen, unter Nutzung von Protokollen wie AML und KYC","pt":"Habilita os agentes a gerar conteúdo autêntico regionalmente, em conformidade com as regulamentações para empresas de fintech, utilizando a commutação de código árabe-inglês e referenciando os corpos reguladores corretos, como o Banco Central dos Emirados Árabes e a Agência Monetária da Arábia Saudita, utilizando protocolos como AML e KYC","ru":"Наделяет агентов возможностью генерировать регионально аутентичный, соответствующий нормативным требованиям контент для финтех-компаний, используя коммутацию кода на арабском и английском языках и ссылаясь на правильные регулирующие органы, такие как Центральный банк ОАЭ и Саудовская монетарная агентство, используя протоколы, такие как AML и KYC","ar":"تمكين الوكلاء من生成 المحتوى المثالي إقليميا والمتوافق مع اللوائح للشركات fintech، باستخدام التبديل الرقمي العربي-الإنجليزية والاستشهاد بالهيئات التنظيمية الصحيحة مثل مصرف الإمارات العربية المتحدة المركزي والهيئة النقدية السعودية، باستخدام بروتوكولات مثل AML و KYC"},"useCases":{"en":["Creating culturally sensitive marketing campaigns for GCC-based fintech startups","Developing compliant financial product descriptions for Arabic-speaking audiences","Researching and writing about GCC fintech trends and regulatory updates"],"zh":["为GCC基于金融科技初创公司创建文化敏感的营销活动","为阿拉伯语使用者开发符合规定的金融产品描述","研究和撰写关于GCC金融科技趋势和规制更新"],"ja":["GCCに基づく金融テクノロジー向けの文化的に感受性のあるマーケティングキャンペーンを作成する","アラビア語を使用するための規制に準拠した金融商品の説明を開発する","GCC金融テクノロジーのトレンドや規制の更新について調査し、執筆する"],"ko":["GCC 기반 금융 기술 스타트업을 위한 문화적으로 감각적인 마케팅 캠페인을 생성","아랍어 사용자에게 규제 준수 금융 제품 설명서 개발","GCC 금융 기술 트렌드 및 규제 업데이트에 대한 연구 및 저술"],"es":["Creación de campañas de marketing culturalmente sensibles para startups de fintech con sede en GCC","Desarrollo de descripciones de productos financieros cumpliendo con las regulaciones para audiencias de habla árabe","Investigación y escritura sobre tendencias y actualizaciones regulatorias de fintech en GCC"],"fr":["Création de campagnes de marketing sensibles sur le plan culturel pour les startups de fintech basées à GCC","Développement de descriptions de produits financiers conformes aux réglementations pour les publics de langue arabe","Recherche et rédaction sur les tendances et les mises à jour réglementaires de la fintech dans la région GCC"],"de":["Erstellung kulturell sensibler Marketingkampagnen für in der GCC ansässige Finanztechnologie-Startups","Entwicklung konformer Finanzproduktbeschreibungen für arabische Sprachaudienzen","Recherche und Schreiben über Finanztechnologie-Trends und regulatorische Updates in der GCC-Region"],"pt":["Criação de campanhas de marketing culturalmente sensíveis para startups de fintech baseadas no GCC","Desenvolvimento de descrições de produtos financeiros em conformidade com as regulamentações para públicos de língua árabe","Pesquisa e escrita sobre tendências e atualizações regulamentares de fintech no GCC"],"ru":["Создание культурно чувствительных маркетинговых кампаний для финтех-стартапов, базирующихся в GCC","Разработка описаний финансовых продуктов, соответствующих нормативным требованиям для арабоязычной аудитории","Исследование и написание о финтех-тенденциях и обновлениях нормативных актов в GCC"],"ar":["إنشاء حملات تسويقية حساسة ثقافيا للشركات الناشئة في مجال fintech في منطقة الخليج","تطوير وصفات للمنتجات المالية المتوافقة مع اللوائح للجماهير الناطقة بالعربية","البحث والكتابة حول الاتجاهات والتحديثات التنظيمية لمجال fintech في منطقة الخليج"]},"limitations":{"en":["Requires knowledge of GCC business culture and regulations","Limited to fintech content creation in the GCC region","Arabic language proficiency necessary for optimal performance"],"zh":["需要GCC商业文化和法规的知识","仅限于GCC地区的金融科技内容创建","阿拉伯语熟练程度对于最佳性能是必要的"],"ja":["GCCのビジネス文化と規制の知識が必要","GCC地域での金融テクノロジー向けコンテンツ作成のみ","アラビア語の熟練度が最適な性能のために必要"],"ko":["GCC 비즈니스 문화 및 규정에 대한 지식이 필요","GCC 지역의 금융 기술 콘텐츠 생성에만 제한","최적의 성능을 위해 아랍어 숙달도가 필요"],"es":["Requiere conocimiento de la cultura y regulaciones comerciales de GCC","Limitado a la creación de contenido de fintech en la región de GCC","Se requiere competencia en el idioma árabe para un rendimiento óptimo"],"fr":["Nécessite des connaissances sur la culture et les réglementations commerciales de GCC","Limité à la création de contenu de fintech dans la région GCC","La maîtrise de la langue arabe est nécessaire pour des performances optimales"],"de":["Benötigt Kenntnisse über die GCC-Geschäftskultur und -regulierungen","Begrenzt auf die Erstellung von Finanztechnologie-Inhalten in der GCC-Region","Arabischsprachliche Kompetenz ist für optimale Leistung erforderlich"],"pt":["Exige conhecimento da cultura e regulamentações empresariais do GCC","Limitado à criação de conteúdo de fintech na região do GCC","Proficiência na língua árabe necessária para desempenho ótimo"],"ru":["Требует знания деловой культуры и регуляторных норм GCC","Ограничен созданием контента финтех в регионе GCC","Необходимо владение арабским языком для оптимальной производительности"],"ar":["يتطلب معرفة الثقافة والتقاليد التجارية في منطقة الخليج","محدود بالإنشاء المحتوى لمجال fintech في منطقة الخليج","البراعة في اللغة العربية ضرورية للأداء الأمثل"]},"version":4},"contentHash":"e91926406eb5c59074535d447a98348739eb6fd358475dcfa4819ebd71ab97f4","qualityScore":26}');
