INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('teren-papercutlabs/pcl-workshop-setup/plan-app', 'plan-app', 'teren-papercutlabs', 'pcl-workshop-setup', 'community', 'plan-app teren-papercutlabs pcl-workshop-setup community The plan-app skill enables developers to build a complete app in ~2 hours through guided planning and parallel sub-agent execution. It benefits developers who want to quickly create apps. Plan App 是一个快速构建应用的技术，通过 2 小时的指导规划和并行子代理执行，帮助开发者完成完整应用 Plan App は、2 時間以内にアプリを構築するための技術で、ガイド付き計画と並行サブエージェント実行を実現 Plan App는 2시간 내에 완전한 애플리케이션을 구축하는 기술로, 가이드 계획 및 병렬 서브 에이전트 실행을 통해 개발자를 도와줍니다 El plan-app es una herramienta para crear aplicaciones en ~2 horas mediante una guía de planificación y ejecución paralela de subagentes. Incluye fases como la entrevista para entender el concepto de la aplicación. Le plan-app est un outil pour créer des applications en ~2 heures via une guide de planification et d''exécution parallèle de sous-agents. Il inclut des phases comme l''entretien pour comprendre le concept de l''application. Der plan-app ist ein Werkzeug zum Erstellen von Anwendungen in ~2 Stunden durch eine Planungsanleitung und parallele Sub-Agent-Ausführung. Er umfasst Phasen wie das Interview, um das AnwendungsKonzept zu verstehen. O Plan App é uma ferramenta de configuração de workshop para treinamento de código Claude. Ele permite criar um aplicativo completo em 2 horas. Plan App - это инструмент настройки семинара для обучения коду Claude. Он позволяет создать полноценное приложение за 2 часа. PLAN التطبيق هو أداة إعداد ورشة عمل لتدريب كلود كود. يسمح بإنشاء تطبيق كامل في غضون ساعتين. how to use plan-app plan-app setup guide what is plan-app plan-app alternative plan-app vs Claude Code plan-app install guided app planning parallel sub-agent execution Claude Code training Plan App AI 工具 快速应用构建 指导规划 并行子代理执行 应用开发 原型设计 Executes a phased approach with mandatory flow Reads reference files in MD format, such as `reference/01-interview.md` Supports parallel sub-agent execution for efficient app building Guides developers through an interview phase to understand app concepts Enables developers to describe the app concept back to users plan-app is a skill that provides a workshop setup bootstrap for Claude Code training, guiding developers through a phased approach to build a complete app.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ll7/robot_sf_ll7/clean-up', 'community', 'll7', 'robot_sf_ll7', 'll7/robot_sf_ll7', 'clean-up', 0, 0, 26, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:31.058Z', '1fb768f345f9dbe0f0193711f85e727c6953bf5f50c076dded4fd8975b7ab778', '{"id":"ll7/robot_sf_ll7/clean-up","name":"clean-up","description":{"en":"The clean-up skill automates branch validation for Robot SF repositories, applying the dev guide workflow and running Ruff format/fix and parallel tests. This benefits developers working with the Robot SF repo.","zh":"Clean Up技能用于清理和验证Robot SF仓库，通过应用开发指南工作流、运行Ruff格式化和并行测试","ja":"Clean Upスキルは、開発ガイドのワークフローを適用し、Ruff形式を実行し、並列テストを実行して、Robot SFリポジトリをクリーンアップします","ko":"클린업 스킬은 로봇 SF 저장소를 정리하고 확인하는 데 사용되며 개발 가이드 워크플로우, Ruff 형식 및 병렬 테스트를 적용합니다","es":"La herramienta clean-up limpia y valida la rama actual para el repositorio Robot SF aplicando el flujo de trabajo de la guía de desarrollo","fr":"L''outil clean-up nettoie et valide la branche actuelle pour le référentiel Robot SF en appliquant le workflow de la guide de développement","de":"Das Clean-up-Tool bereinigt und überprüft den aktuellen Branch für das Robot-SF-Repository, indem es den Workflow der Entwicklerleitfaden anwendet","pt":"O clean-up é uma ferramenta que valida e limpa o branch atual do repositório Robot SF aplicando o fluxo de trabalho do guia de desenvolvimento","ru":"Clean-up - это инструмент, который проверяет и очищает текущую ветку репозитория Robot SF, применяя рабочий процесс руководства по разработке","ar":"Clean-up هو أداة لتحقق وتنظيف الفرع الحالي لمخزن Robot SF بتطبيق تدفق عمل دليل التطوير"},"seo":{"title":{"en":"Clean-up: Automated Branch Validation for Robot SF | AI A...","zh":"AI工具清理设置指南 - Clean Up","ja":"AIエージェントのクリーンアップベストプラクティス","ko":"AI 도구 클린업 설정 가이드 - Clean Up","es":"Guía de configuración de clean-up para Robot SF","fr":"Guide de configuration de clean-up pour Robot SF","de":"Einrichtungsleitfaden für clean-up in Robot SF","pt":"Guia de Configuração do Clean-up: Ferramentas de Limpeza ...","ru":"Настройка Clean-up: Инструменты для очистки кода ИИ Агентов","ar":"دليل إعداد Clean-up: أدوات تنظيف الكود للوكلاء الذكاء الا..."},"description":{"en":"Discover how to streamline your development workflow with clean-up, a skill that validates and cleans your Robot SF repo branch. Learn more and get started t...","zh":"了解Clean Up技能的技术细节，包括验证Git仓库、运行Ruff格式化和并行测试","ja":"Clean Upスキルの技術的詳細を確認しましょう。Gitリポジトリの検証、Ruff形式の適用、並列テストの実行など","ko":"클린업 설정 가이드: Git 저장소 확인, Ruff 형식 및 병렬 테스트 실행","es":"Aprende a limpiar y validar la rama actual para el repositorio Robot SF con la herramienta de clean-up","fr":"Découvrez comment nettoyer et valider la branche actuelle pour le référentiel Robot SF avec l''outil clean-up","de":"Erfahren Sie, wie Sie den aktuellen Branch für das Robot-SF-Repository mit dem Clean-up-Tool bereinigen und überprüfen","pt":"Aprenda a configurar o clean-up para validar e limpar o branch atual do repositório Robot SF com Ruff format/fix e testes paralelos","ru":"Узнайте, как настроить clean-up для валидации и очистки текущей ветки репозитория Robot SF с помощью Ruff format/fix и параллельных тестов","ar":"تعلم كيفية إعداد Clean-up لتحقق وتنظيف الفرع الحالي لمخزن Robot SF باستخدام Ruff format/fix والاختبارات الموازية"},"definition":{"en":"clean-up is a skill that automates the validation and cleaning of the current branch for the Robot SF repository, ensuring consistency and accuracy.","zh":"Clean Up是一种AI工具技能，用于清理和验证Git仓库","ja":"Clean Upは、GitリポジトリをクリーンアップするAIエージェントのスキルです","ko":"클린업은 Git 저장소를 정리하고 확인하는 AI 도구 스킬입니다","es":"Clean-up es una herramienta que limpia y valida la rama actual para el repositorio Robot SF","fr":"Clean-up est un outil qui nettoie et valide la branche actuelle pour le référentiel Robot SF","de":"Clean-up ist ein Tool, das den aktuellen Branch für das Robot-SF-Repository bereinigt und überprüft","pt":"Clean-up é uma ferramenta de limpeza de código que valida e reformata o código-fonte","ru":"Clean-up - это инструмент очистки кода, который проверяет и форматирует исходный код","ar":"Clean-up هو أداة تنظيف الكود التي تحقق وتنسيق الكود المصدري"},"features":{"en":["Applies the dev guide workflow to the Robot SF repository","Runs Ruff format/fix to standardize code formatting","Executes parallel tests to ensure code validity","Verifies the working directory matches the Robot SF repo structure","Reads and applies guidance from docs/dev_guide.md and .github/copilot-instructions.md"],"zh":["验证Git仓库结构","运行Ruff格式化和修复","执行并行测试","应用开发指南工作流","检查特定文件存在性（.git、docs/dev_guide.md等）"],"ja":["Gitリポジトリ構造の検証","Ruff形式の適用と修正","並列テストの実行","開発ガイドのワークフローの適用","特定ファイルの存在性の確認（.git、docs/dev_guide.mdなど）"],"ko":["Git 저장소 구조 확인","Ruff 형식 및 수정 적용","병렬 테스트 실행","개발 가이드 워크플로우 적용","특정 파일 존재성 확인（.git, docs/dev_guide.md 등）"],"es":["Verificación del directorio de trabajo para el repositorio Robot SF","Aplicación del flujo de trabajo de la guía de desarrollo","Ejecución de Ruff format/fix","Ejecución de pruebas paralelas","Validación de la rama actual"],"fr":["Vérification du répertoire de travail pour le référentiel Robot SF","Application du workflow de la guide de développement","Exécution de Ruff format/fix","Exécution de tests parallèles","Validation de la branche actuelle"],"de":["Überprüfung des Arbeitsverzeichnisses für das Robot-SF-Repository","Anwendung des Workflows der Entwicklerleitfaden","Ausführung von Ruff format/fix","Ausführung von Paralleltests","Überprüfung des aktuellen Branch"],"pt":["Validação do repositório Robot SF","Aplicação do fluxo de trabalho do guia de desenvolvimento","Execução de Ruff format/fix","Execução de testes paralelos","Verificação da existência de arquivos específicos","Leitura do guia de desenvolvimento e da constituição"],"ru":["Проверка репозитория Robot SF","Применение рабочего процесса руководства по разработке","Выполнение Ruff format/fix","Выполнение параллельных тестов","Проверка существования определенных файлов","Чтение руководства по разработке и конституции"],"ar":["التحقق من مخزن Robot SF","تطبيق تدفق عمل دليل التطوير","تشغيل Ruff format/fix","تشغيل الاختبارات الموازية","التحقق من وجود الملفات المحددة","قراءة دليل التطوير والدستور"]},"keywords":{"en":["how to use clean-up","clean-up for Robot SF","what is clean-up","clean-up alternative","clean-up vs manual validation","clean-up install guide","clean-up setup for developers","automated branch validation","Ruff format/fix integration"],"zh":["AI工具清理","Git仓库验证","Ruff格式化","并行测试","开发指南工作流","Robot SF仓库","AI工具设置","代码质量检查","自动化测试"],"ja":["AIエージェントのクリーンアップ","Gitリポジトリの検証","Ruff形式の適用","並列テスト","開発ガイドのワークフロー","Robot SFリポジトリ","AIエージェントの設定","コード品質の確認","自動テスト"],"ko":["AI 도구 클린업","Git 저장소 확인","Ruff 형식","병렬 테스트","개발 가이드 워크플로우","로봇 SF 저장소","AI 도구 설정","코드 품질 확인","자동 테스트"],"es":["clean-up","Robot SF","herramienta de clean-up","guía de desarrollo","Ruff format/fix","pruebas paralelas","validación de rama","Herramientas de AI","Agentes de AI"],"fr":["clean-up","Robot SF","outil clean-up","guide de développement","Ruff format/fix","tests parallèles","validation de branche","Outils d''IA","Agents d''IA"],"de":["clean-up","Robot SF","Clean-up-Tool","Entwicklerleitfaden","Ruff format/fix","Paralleltests","Überprüfung von Branch","AI-Tools","KI-Agents"],"pt":["clean-up","ferramentas de limpeza de código","validação de repositório","Ruff format/fix","testes paralelos","guia de desenvolvimento","Robot SF","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["clean-up","инструменты очистки кода","проверка репозитория","Ruff format/fix","параллельные тесты","руководство по разработке","Robot SF","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["clean-up","أدوات تنظيف الكود","التحقق من مخزن","Ruff format/fix","الاختبارات الموازية","دليل التطوير","Robot SF","تطوير البرمجيات","أدوات التطوير","الوكلاء الذكاء الاصطناعي"]}},"owner":"ll7","repo":"robot_sf_ll7","repoPath":"ll7/robot_sf_ll7","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"clean-up","description":"Clean up the current branch in the Robot SF repo by following docs/dev_guide.md and reusable scripts/dev commands; use when asked to tidy a branch, run Ruff format/fix, or run parallel pytest before sharing changes.","bodyPreview":"# Clean Up\n\n## Overview\n\nClean and validate the current branch for the Robot SF repo by applying the dev guide\nworkflow, running Ruff format/fix, and running parallel tests.\n\n## Cleanup Workflow\n\n1. Confirm repo and guidance\n   - Verify the working directory looks like the Robot SF repo (e.g., `.git`,\n     `docs/dev_guide.md`, `.specify/memory/constitution.md`, and\n     `.github/copilot-instructions.md` exist).\n   - Read `docs/dev_guide.md`, `.specify/memory/constitution.md`, and\n     `.github/c","body":"# Clean Up\n\n## Overview\n\nClean and validate the current branch for the Robot SF repo by applying the dev guide\nworkflow, running Ruff format/fix, and running parallel tests.\n\n## Cleanup Workflow\n\n1. Confirm repo and guidance\n   - Verify the working directory looks like the Robot SF repo (e.g., `.git`,\n     `docs/dev_guide.md`, `.specify/memory/constitution.md`, and\n     `.github/copilot-instructions.md` exist).\n   - Read `docs/dev_guide.md`, `.specify/memory/constitution.md`, and\n     `.github/copilot-instructions.md` to align with required rules.\n\n2. Ensure environment\n   - If `VIRTUAL_ENV` is empty and `.venv/bin/activate` exists, run\n     `source .venv/bin/activate`.\n   - If `.venv/bin/activate` is missing, follow dev guide setup:\n     `uv sync --all-extras`, `source .venv/bin/activate`, and\n     `uv run pre-commit install`.\n\n3. Run formatting and fixes first\n   - Use the shared script:\n     `scripts/dev/ruff_fix_format.sh`\n   - If Ruff reports issues, fix them and rerun until clean.\n\n4. Run tests in parallel\n   - Use the shared script:\n     `scripts/dev/run_tests_parallel.sh`\n   - Default behavior is fail-fast + failed-first ordering:\n     `pytest -n auto -x --failed-first`\n   - Optional ordering toggle:\n     `scripts/dev/run_tests_parallel.sh --new-first`\n   - To disable fail-fast when you need a full failure set:\n     `scripts/dev/run_tests_parallel.sh --no-fast-fail`\n   - If tests fail, evaluate test value first (Constitution Principle XIII /\n     dev guide testing strategy). Classify failures and decide whether to fix,\n     defer, or ask for direction before removing or relaxing tests.\n\n5. Run diff-based quality gates and fix them.\n   - Run changed-files coverage check:\n     `BASE_REF=origin/main scripts/dev/check_changed_coverage.sh`\n     - If you changed any test files, run these new tests locally.\n   - Run touched-definition TODO docstring check:\n     `BASE_REF=origin/main scripts/dev/check_docstring_todos_diff.sh`\n\n6. Report and follow-ups\n   - Summarize commands run and results.\n   - Note remaining failures, flaky tests, or follow-up tasks (for example,\n     GUI tests if rendering changes were made, or CHANGELOG updates for\n     user-facing changes).\n  - Suggest commit batches and messages for any uncommited changes.\n"},"lastSynced":"2026-03-08T02:04:31.058Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated branch validation and code formatting for Robot SF repositories.","zh":"适合需要自动分支验证和代码格式化的 Robot SF 仓库的开发代理。","ja":"Robot SF リポジトリの自動分支検証とコード整形が必要な開発エージェントに最適です。","ko":"Robot SF 저장소의 자동 분기 유효성 검사 및 코드 형식화가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren validación de rama automatizada y formato de código para repositorios de Robot SF.","fr":"Idéal pour les Agents de Développement nécessitant une validation de branche automatisée et un formatage de code pour les référentiels Robot SF.","de":"Ideal für Entwicklungssagenten, die eine automatisierte Validierung von Zweigen und Codeformatierung für Robot-SF-Repositorys erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem validação de branch automatizada e formatação de código para repositórios Robot SF.","ru":"Идеально подходит для агентов разработки, требующих автоматической проверки веток и форматирования кода для репозиториев Robot SF.","ar":"مثالي لعميل التطوير الذين يتطلبون التحقق التلقائي من الفرع وتشكيل الكود لمستودعات Robot SF."},"recommendation":{"en":"Empowers agents to automate branch validation by applying the dev guide workflow, running Ruff format/fix, and executing parallel tests, ensuring consistency and accuracy in Robot SF repositories using Ruff and parallel testing protocols.","zh":"赋予代理自动分支验证的能力，通过应用开发指南工作流、运行 Ruff 格式/修复并执行并行测试，确保 Robot SF 仓库使用 Ruff 和并行测试协议的一致性和准确性。","ja":"開発ガイドのワークフローを適用して Ruff 形式/修正を実行し、並行テストを実行することで、エージェントに自動分支検証を可能にし、Ruff と並行テストのプロトコルを使用する Robot SF リポジトリの一貫性と正確性を確保します。","ko":"개발 가이드 워크플로를 적용하여 Ruff 형식/수정 및 병렬 테스트를 실행하여 에이전트가 자동 분기 유효성 검사를 수행할 수 있도록 하여 Ruff 및 병렬 테스트 프로토콜을 사용하는 Robot SF 저장소의 일관성 및 정확성을 보장합니다.","es":"Habilita a los agentes a automatizar la validación de ramas aplicando el flujo de trabajo de la guía de desarrollo, ejecutando Ruff format/fix y ejecutando pruebas paralelas, garantizando la consistencia y precisión en los repositorios de Robot SF utilizando protocolos de prueba paralela y Ruff.","fr":"Permet aux agents d''automatiser la validation des branches en appliquant le workflow du guide de développement, en exécutant Ruff format/fix et en exécutant des tests parallèles, garantissant la cohérence et la précision dans les référentiels Robot SF en utilisant les protocoles de test parallèle et Ruff.","de":"Ermächtigt Agenten, die Validierung von Zweigen zu automatisieren, indem der Workflow der Entwicklerhandbuch-Richtlinie angewendet, Ruff format/fix ausgeführt und parallele Tests ausgeführt werden, um Konsistenz und Genauigkeit in Robot-SF-Repositorys unter Verwendung von Ruff und parallelen Testprotokollen sicherzustellen.","pt":"Habilita os agentes a automatizar a validação de branch aplicando o fluxo de trabalho do guia de desenvolvimento, executando Ruff format/fix e testes paralelos, garantindo consistência e precisão nos repositórios Robot SF usando Ruff e protocolos de teste paralelo.","ru":"Позволяет агентам автоматизировать проверку веток, применяя рабочий процесс руководства по разработке, запуская Ruff format/fix и параллельные тесты, обеспечивая последовательность и точность в репозиториях Robot SF с помощью Ruff и параллельных протоколов тестирования.","ar":"تمكين الوكيل من تلقين التحقق من الفرع عن طريق تطبيق تدفق عمل دليل التطوير، وتشغيل Ruff format/fix واختبارات متوازية، مما يضمن الاتساق والدقة في مستودعات Robot SF باستخدام Ruff وبروتوكولات الاختبار المتوازي."},"useCases":{"en":["Automating branch validation for Robot SF repositories","Running Ruff format/fix for code consistency","Executing parallel tests for efficient validation"],"zh":["自动为 Robot SF 仓库验证分支","运行 Ruff 格式/修复以保持代码一致性","执行并行测试以实现高效验证"],"ja":["Robot SF リポジトリの分支を自動検証する","コードの一貫性を維持するために Ruff 形式/修正を実行する","効率的な検証を実現するために並行テストを実行する"],"ko":["Robot SF 저장소의 분기 자동 유효성 검사","코드 일관성을 유지하기 위해 Ruff 형식/수정을 실행하는 것","효율적인 유효성 검사를 thực現하기 위해 병렬 테스트를 실행하는 것"],"es":["Automatización de la validación de ramas para repositorios de Robot SF","Ejecución de Ruff format/fix para la consistencia del código","Ejecución de pruebas paralelas para una validación eficiente"],"fr":["Automatisation de la validation des branches pour les référentiels Robot SF","Exécution de Ruff format/fix pour la cohérence du code","Exécution de tests parallèles pour une validation efficace"],"de":["Automatisierung der Validierung von Zweigen für Robot-SF-Repositorys","Ausführung von Ruff format/fix für die Konsistenz des Codes","Ausführung von parallelen Tests für eine effiziente Validierung"],"pt":["Automatizar a validação de branch para repositórios Robot SF","Executar Ruff format/fix para consistência de código","Executar testes paralelos para validação eficiente"],"ru":["Автоматизация проверки веток для репозиториев Robot SF","Запуск Ruff format/fix для согласованности кода","Выполнение параллельных тестов для эффективной проверки"],"ar":["تلقين التحقق التلقائي من الفرع لمستودعات Robot SF","تشغيل Ruff format/fix لاتساق الكود","تشغيل الاختبارات المتوازية للتحقق الفعال"]},"limitations":{"en":["Requires Robot SF repository structure","Dependent on Ruff format/fix and parallel testing tools","Limited to validating branches according to the dev guide workflow"],"zh":["需要 Robot SF 仓库结构","依赖于 Ruff 格式/修复和并行测试工具","仅限于根据开发指南工作流验证分支"],"ja":["Robot SF リポジトリ構造が必要","Ruff 形式/修正および並行テストツールに依存する","開発ガイドのワークフローに従って分支を検証することのみ"],"ko":["Robot SF 저장소 구조가 필요함","Ruff 형식/수정 및 병렬 테스트 도구에 의존함","개발 가이드 워크플로에 따라 분기를 유효성 검사하는 것만으로 제한됨"],"es":["Requiere estructura de repositorio de Robot SF","Dependiente de las herramientas Ruff format/fix y de pruebas paralelas","Limitado a la validación de ramas según el flujo de trabajo de la guía de desarrollo"],"fr":["Nécessite une structure de référentiel Robot SF","Dépendant des outils Ruff format/fix et de tests parallèles","Limité à la validation des branches selon le workflow du guide de développement"],"de":["Benötigt Struktur des Robot-SF-Repositorys","Abhängig von den Ruff format/fix- und parallelen Test-Tools","Begrenzt auf die Validierung von Zweigen gemäß dem Workflow der Entwicklerhandbuch-Richtlinie"],"pt":["Exige estrutura de repositório Robot SF","Depende de Ruff format/fix e ferramentas de teste paralelo","Limitado à validação de branches de acordo com o fluxo de trabalho do guia de desenvolvimento"],"ru":["Требует структуры репозитория Robot SF","Зависит от Ruff format/fix и инструментов параллельного тестирования","Ограничен проверкой веток в соответствии с рабочим процессом руководства по разработке"],"ar":["يتطلب هيكل مستودع Robot SF","يعتمد على Ruff format/fix وأدوات الاختبار المتوازي","محدود بالتحقق من الفروع وفقًا لتدفق عمل دليل التطوير"]},"version":4},"contentHash":"1fb768f345f9dbe0f0193711f85e727c6953bf5f50c076dded4fd8975b7ab778","qualityScore":26}');
