INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ll7/robot_sf_ll7/clean-up', 'clean-up', 'll7', 'robot_sf_ll7', 'community', 'clean-up ll7 robot_sf_ll7 community The clean-up skill automates branch validation for Robot SF repositories, applying the dev guide workflow and running Ruff format/fix and parallel tests. This benefits developers working with the Robot SF repo. Clean Up技能用于清理和验证Robot SF仓库，通过应用开发指南工作流、运行Ruff格式化和并行测试 Clean Upスキルは、開発ガイドのワークフローを適用し、Ruff形式を実行し、並列テストを実行して、Robot SFリポジトリをクリーンアップします 클린업 스킬은 로봇 SF 저장소를 정리하고 확인하는 데 사용되며 개발 가이드 워크플로우, Ruff 형식 및 병렬 테스트를 적용합니다 La herramienta clean-up limpia y valida la rama actual para el repositorio Robot SF aplicando el flujo de trabajo de la guía de desarrollo L''outil clean-up nettoie et valide la branche actuelle pour le référentiel Robot SF en appliquant le workflow de la guide de développement Das Clean-up-Tool bereinigt und überprüft den aktuellen Branch für das Robot-SF-Repository, indem es den Workflow der Entwicklerleitfaden anwendet O clean-up é uma ferramenta que valida e limpa o branch atual do repositório Robot SF aplicando o fluxo de trabalho do guia de desenvolvimento Clean-up - это инструмент, который проверяет и очищает текущую ветку репозитория Robot SF, применяя рабочий процесс руководства по разработке Clean-up هو أداة لتحقق وتنظيف الفرع الحالي لمخزن Robot SF بتطبيق تدفق عمل دليل التطوير how to use clean-up clean-up for Robot SF what is clean-up clean-up alternative clean-up vs manual validation clean-up install guide clean-up setup for developers automated branch validation Ruff format/fix integration AI工具清理 Git仓库验证 Ruff格式化 并行测试 开发指南工作流 Robot SF仓库 AI工具设置 代码质量检查 自动化测试 Applies the dev guide workflow to the Robot SF repository Runs Ruff format/fix to standardize code formatting Executes parallel tests to ensure code validity Verifies the working directory matches the Robot SF repo structure Reads and applies guidance from docs/dev_guide.md and .github/copilot-instructions.md clean-up is a skill that automates the validation and cleaning of the current branch for the Robot SF repository, ensuring consistency and accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kunhuang12345/team-skill/tmux-workflow', 'community', 'kunhuang12345', 'team-skill', 'kunhuang12345/team-skill', 'tmux-workflow', 0, 0, 26, '2026-03-08T01:57:15.380Z', '2026-03-08T02:05:37.885Z', '845f3a0f328e43c253732171d2802540289425d1d891caf18888750aebf119b3', '{"id":"kunhuang12345/team-skill/tmux-workflow","name":"tmux-workflow","description":{"en":"The tmux-workflow skill is a self-contained toolkit for managing workflows. It benefits developers by providing a configurable state directory and support for worker management.","zh":"tmux-workflow 是一个自包含的工具包，提供快速启动和状态目录配置等功能","ja":"tmux-workflow は、クイックスタートとステートディレクトリの設定などの機能を提供するセルフコンテイナ型ツールキットです","ko":"tmux-workflow는 빠른 시작과 상태 디렉토리 구성 등 기능을 제공하는 자체 포함형 툴킷입니다","es":"tmux-workflow es una herramienta de flujo de trabajo que mejora la productividad de los desarrolladores. Utiliza scripts de bash para automatizar tareas","fr":"tmux-workflow est un outil de flux de travail qui améliore la productivité des développeurs. Il utilise des scripts bash pour automatiser les tâches","de":"tmux-workflow ist ein Werkzeug für den Arbeitsfluss, das die Produktivität von Entwicklern verbessert. Es verwendet Bash-Skripte, um Aufgaben zu automatisieren","pt":"O tmux-workflow é uma ferramenta de automação de fluxo de trabalho que utiliza scripts em bash e gerenciamento de dependências","ru":"tmux-workflow - это инструмент для автоматизации рабочих процессов, использующий скрипты bash и управление зависимостями","ar":"tmux-workflow هو أداة لتحسين مسارات العمل باستخدام سكريبتات bash وإدارة الإعتماديات"},"seo":{"title":{"en":"tmux-workflow: Setup Guide for AI Agents | AI Agent Skill","zh":"tmux-workflow 集成指南 - 优化开发工作流","ja":"tmux-workflow 導入ガイド - 開発ワークフローの最適化","ko":"tmux-workflow 설정 가이드 - 개발 워크플로우 최적화","es":"Guía de configuración de tmux-workflow para desarrolladores","fr":"Configurer tmux-workflow : Le guide des meilleures pratiques","de":"tmux-workflow Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do tmux-workflow: Ferramentas de Aut...","ru":"ИИ Агенты: Руководство по Настройке tmux-workflow для Авт...","ar":"دليل إعداد tmux-workflow: أدوات ت自动ية لمسارات العمل"},"description":{"en":"Discover how to configure tmux-workflow for optimal performance. Learn to deploy and manage tmux-workflow with our expert guide and maximize your AI agent''s ...","zh":"了解如何集成 tmux-workflow 以优化您的开发工作流，提高生产力","ja":"tmux-workflow を導入して開発ワークフローを最適化し、生産性を向上させる方法を学びましょう","ko":"tmux-workflow를 설정하여 개발 워크플로우를 최적화하고 생산성을 향상시키는 방법을 알아보세요","es":"Aprende a configurar tmux-workflow para mejorar tu flujo de trabajo como desarrollador con esta guía paso a paso","fr":"Découvrez comment configurer tmux-workflow pour améliorer votre productivité en tant que développeur avec ce guide étape par étape","de":"Erfahren Sie, wie Sie tmux-workflow konfigurieren, um Ihren Arbeitsfluss als Entwickler zu optimieren, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o tmux-workflow para automatizar fluxos de trabalho com scripts em bash e gerenciamento de dependências","ru":"Узнайте, как настроить tmux-workflow для автоматизации рабочих процессов с помощью скриптов bash и управления зависимостями","ar":"تعلم كيفية إعداد tmux-workflow لتحسين مسارات العمل باستخدام سكريبتات bash وإدارة الإعتماديات"},"definition":{"en":"tmux-workflow is a toolkit for managing workflows, providing a set of scripts for checking dependencies and starting workers.","zh":"tmux-workflow 是一个用于优化开发工作流的工具包","ja":"tmux-workflow は、開発ワークフローを最適化するためのツールキットです","ko":"tmux-workflow는 개발 워크플로우를 최적화하기 위한 툴킷입니다","es":"tmux-workflow es un kit de herramientas autocontenidas que utiliza scripts de bash para automatizar tareas","fr":"tmux-workflow est un kit d''outils autocontenus qui utilise des scripts bash pour automatiser les tâches","de":"tmux-workflow ist ein selbstenthaltenes Toolkit, d