INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kunhuang12345/team-skill/tmux-workflow', 'tmux-workflow', 'kunhuang12345', 'team-skill', 'community', 'tmux-workflow kunhuang12345 team-skill community The tmux-workflow skill is a self-contained toolkit for managing workflows. It benefits developers by providing a configurable state directory and support for worker management. tmux-workflow 是一个自包含的工具包，提供快速启动和状态目录配置等功能 tmux-workflow は、クイックスタートとステートディレクトリの設定などの機能を提供するセルフコンテイナ型ツールキットです tmux-workflow는 빠른 시작과 상태 디렉토리 구성 등 기능을 제공하는 자체 포함형 툴킷입니다 tmux-workflow es una herramienta de flujo de trabajo que mejora la productividad de los desarrolladores. Utiliza scripts de bash para automatizar tareas tmux-workflow est un outil de flux de travail qui améliore la productivité des développeurs. Il utilise des scripts bash pour automatiser les tâches tmux-workflow ist ein Werkzeug für den Arbeitsfluss, das die Produktivität von Entwicklern verbessert. Es verwendet Bash-Skripte, um Aufgaben zu automatisieren O tmux-workflow é uma ferramenta de automação de fluxo de trabalho que utiliza scripts em bash e gerenciamento de dependências tmux-workflow - это инструмент для автоматизации рабочих процессов, использующий скрипты bash и управление зависимостями tmux-workflow هو أداة لتحسين مسارات العمل باستخدام سكريبتات bash وإدارة الإعتماديات how to use tmux-workflow tmux-workflow setup guide tmux-workflow alternative what is tmux-workflow tmux-workflow install tmux-workflow vs other workflow tools configuring tmux-workflow state directory tmux-workflow worker management tmux-workflow bash scripts tmux-workflow 开发工作流 优化生产力 工具包 快速启动 状态目录配置 AI工具 AIエージェント Includes a check_deps.sh script for verifying dependencies Supports starting workers with configurable state directories Utilizes bash scripts for workflow management Provides a twf script for interacting with workers Allows for customization of the state directory path Supports short names for worker interaction tmux-workflow is a toolkit for managing workflows, providing a set of scripts for checking dependencies and starting workers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PinedaTec-EU/SphereIntegrationHub/dotnet', 'community', 'PinedaTec-EU', 'SphereIntegrationHub', 'PinedaTec-EU/SphereIntegrationHub', 'dotnet', 0, 0, 26, '2026-03-08T01:57:15.386Z', '2026-03-08T02:05:50.578Z', 'a30eb315864ec35ac7a94efcc6efa0d00328b7c9601eb9582a16f1ca92ecce08', '{"id":"PinedaTec-EU/SphereIntegrationHub/dotnet","name":"dotnet","description":{"en":"The dotnet skill provides a .NET framework for building AI agents, utilizing a CLI tool and xUnit tests for efficient development. It benefits developers working with .NET applications.","zh":"dotnet 是一个 .NET CLI 工具，用于构建和测试应用程序。它遵循 SOLID 原则和清晰的变量命名","ja":"dotnet は、.NET CLI ツールを使用してアプリケーションを構築およびテストするためのものです。SOLID 原則と明確な変数命名に従います","ko":"dotnet은 .NET CLI 도구를 사용하여 애플리케이션을 구축하고 테스트하는 데 사용됩니다. SOLID 원칙과 명확한 변수 이름을 따릅니다","es":"dotnet es un framework que requiere una configuración y estructura específicas para funcionar de manera efectiva","fr":"dotnet est un framework qui nécessite une configuration et une structure spécifiques pour fonctionner de manière efficace","de":"dotnet ist ein Framework, das eine spezifische Konfiguration und Struktur erfordert, um effektiv zu funktionieren","pt":"O .NET é uma plataforma de desenvolvimento que segue os princípios SOLID e utiliza CancellationToken para melhorar a eficiência","ru":".NET - это платформа разработки, которая следует принципам SOLID и использует CancellationToken для повышения эффективности","ar":".NET هو منصة تطوير تتبع مبادئ SOLID و تستخدم CancellationToken لتحسين الكفاءة"},"seo":{"title":{"en":"dotnet: Setup Guide for AI Agents | AI Agent Skill","zh":"dotnet 设置指南：.NET CLI 工具最佳实践","ja":"dotnet セットアップガイド：.NET CLI ツールのベストプラクティス","ko":"dotnet 설정 가이드: .NET CLI 도구 최적화","es":"Guía de configuración de dotnet para desarrolladores","fr":"Guide de mise en place de dotnet pour les développeurs","de":"Einrichtungsleitfaden für dotnet-Entwickler","pt":"Guia de Configuração do .NET: Melhores Práticas para Dese...","ru":"Настройка .NET: Руководство по Лучшим Практикам для Разра...","ar":"دليل إعداد .NET: أفضل الممارسات لمنصة تطوير الإي إجنت"},"description":{"en":"Discover how to leverage dotnet for AI agents, explore its CLI tool and xUnit tests, and learn best practices for implementation","zh":"了解如何使用 dotnet 设置 .NET CLI 工具，并遵循最佳实践来提高代码质量","ja":"dotnet を使用して .NET CLI ツールを設定し、ベストプラクティスに従ってコード品質を向上させる方法を学びます","ko":"dotnet을 사용하여 .NET CLI 도구를 설정하고 코드 품질을 향상시키는最佳实践을 따르는 방법을 알아보세요","es":"Aprende a configurar y utilizar dotnet de manera efectiva con nuestras mejores prácticas y consideraciones técnicas","fr":"Découvrez comment configurer et utiliser dotnet de manière efficace avec nos meilleures pratiques et considérations techniques","de":"Erfahren Sie, wie Sie dotnet effektiv konfigurieren und verwenden können, mit unseren besten Praktiken und technischen Überlegungen","pt":"Aprenda a configurar o .NET com as melhores práticas para desenvolvedores, incluindo SOLID principles e uso de CancellationToken","ru":"Узнайте, как настроить .NET с лучшими практиками для разработчиков ИИ Агентов, включая принципы SOLID и использование CancellationToken","ar":"تعرف على كيفية إعداد .NET بأفضل الممارسات لتطوير الإي إجنت، بما في ذلك مبادئ SOLID واستخدام CancellationToken"},"definition":{"en":"dotnet is a .NET framework skill that provides a set of guidelines and tools for building AI agents, following SOLID principles and descriptive variable naming","zh":"dotnet 是一个用于构建和测试 .NET 应用程序的 CLI 工具","ja":"dotnet は、.NET アプリケーションを構築およびテストするための CLI ツールです","ko":"dotnet은 .NET 애플리케이션을 구축하고 테스트하는 CLI 도구입니다","es":"dotnet es un framework de aplicaciones que utiliza la línea de comandos CLI y sigue los principios SOLID","fr":"dotnet est un framework d''applications qui utilise la ligne de commande CLI et suit les principes SOLID","de":"dotnet ist ein Framework für Anwendungen, das die Befehlszeile CLI verwendet und den SOLID-Prinzipien folgt","pt":"O .NET é uma plataforma de desenvolvimento que permite a criação de aplicações robustas e escaláveis","ru":".NET - это платформа разработки, которая позволяет создавать надежные и масштабируемые приложения","ar":".NET هو منصة تطوير تمكن من إنشاء تطبيقات قوية ومرنة"},"features":{"en":["Utilizes a CLI tool via `src/SphereIntegrationHub` for application development","Employs xUnit tests via `tests/SphereIntegrationHub.cli.tests` for testing","Enforces SOLID principles for maintainable code","Requires descriptive variable naming for clarity","Follows a specific method order in classes: public, protected, then private","Avoids magic numbers and strings using private constants"],"zh":["遵循 SOLID 原则","使用清晰的变量命名","避免魔术数字和字符串","支持 CancellationToken","遵循特定的方法顺序"],"ja":["SOLID 原則に従う","明確な変数命名を使用","マジックナンバーと文字列を避ける","CancellationToken をサポート","特定のメソッド順序に従う"],"ko":["SOLID 원칙을 따름","명확한 변수 이름을 사용","마법숫자와 문자열을 피함","CancellationToken을 지원","특정 메서드 순서를 따름"],"es":["Utiliza la línea de comandos CLI para la ejecución de aplicaciones","Seguimiento de los principios SOLID para una mejor estructura de código","Utiliza xUnit para pruebas unitarias","Requiere una estructura de métodos específica en las clases","Evita el uso de números y cadenas mágicas","Utiliza tokens de cancelación para una mejor gestión de recursos"],"fr":["Utilise la ligne de commande CLI pour l''exécution des applications","Suivi des principes SOLID pour une meilleure structure de code","Utilise xUnit pour les tests unitaires","Requiert une structure de méthodes spécifique dans les classes","Évite l''utilisation de nombres et de chaînes magiques","Utilise des jetons d''annulation pour une meilleure gestion des ressources"],"de":["Verwenden der Befehlszeile CLI für die Ausführung von Anwendungen","Befolgen der SOLID-Prinzipien für eine bessere Codestruktur","Verwenden von xUnit für Unit-Tests","Erfordert eine spezifische Methodenstruktur in den Klassen","Vermeidet die Verwendung von magischen Zahlen und Zeichenfolgen","Verwenden von Abbruchtoken für eine bessere Ressourcenverwaltung"],"pt":["Uso de CLI tool para aplicativos","Implementação de testes com xUnit","Seguimento dos princípios SOLID","Uso de CancellationToken para melhorar a eficiência","Organização de métodos em classes de acordo com a ordem pública, protegida e privada"],"ru":["Использование инструмента CLI для приложений","Реализация тестов с помощью xUnit","Следование принципам SOLID","Использование CancellationToken для повышения эффективности","Организация методов в классах в соответствии с порядком публичного, защищенного и приватного"],"ar":["استخدام أداة CLI لتطبيقات","تنفيذ الاختبارات باستخدام xUnit","اتباع مبادئ SOLID","استخدام CancellationToken لتحسين الكفاءة","تنظيم الأساليب في الفئات وفقًا للترتيب العام والخاص والمحمي"]},"keywords":{"en":["how to use dotnet for AI agents","dotnet vs java","dotnet setup guide","what is dotnet framework","dotnet alternative to python","dotnet install for windows","dotnet CLI tool tutorial","xUnit tests for dotnet","SOLID principles in dotnet","dotnet best practices for AI development"],"zh":["dotnet",".NET CLI","SOLID 原则","变量命名","CancellationToken","魔术数字",".NET 应用程序","CLI 工具"],"ja":["dotnet",".NET CLI","SOLID 原則","変数命名","CancellationToken","マジックナンバー",".NET アプリケーション","CLI ツール"],"ko":["dotnet",".NET CLI","SOLID 원칙","변수 이름","CancellationToken","마법숫자",".NET 애플리케이션","CLI 도구"],"es":["dotnet","CLI","SOLID","xUnit","pruebas unitarias","estructura de código","tokens de cancelación","números mágicos","cadenas mágicas","desarrollo de aplicaciones"],"fr":["dotnet","CLI","SOLID","xUnit","tests unitaires","structure de code","jetons d''annulation","nombres magiques","chaînes magiques","développement d''applications"],"de":["dotnet","CLI","SOLID","xUnit","Unit-Tests","Codestruktur","Abbruchtoken","magische Zahlen","magische Zeichenfolgen","Anwendungsentwicklung"],"pt":["desenvolvimento de aplicativos .NET","melhores práticas .NET","SOLID principles","CancellationToken","xUnit","CLI tool","desenvolvimento de software"],"ru":["разработка приложений .NET","лучшие практики .NET","принципы SOLID","CancellationToken","xUnit","инструмент CLI","разработка программного обеспечения","ИИ Агенты"],"ar":["تطوير تطبيقات .NET","أفضل الممارسات .NET","مبادئ SOLID","CancellationToken","xUnit","أداة CLI","تطوير البرمجيات","منصة تطوير الإي إجنت"]}},"owner":"PinedaTec-EU","repo":"SphereIntegrationHub","repoPath":"PinedaTec-EU/SphereIntegrationHub","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.386Z","topics":[],"category":"community","skillMd":{"name":"dotnet","description":"Work on the .NET solution for SphereIntegrationHub. Use this when editing services, components, JSON data, or tests.","bodyPreview":"# .NET\n\n## Main structure\n\n- CLI tool: `src/SphereIntegrationHub` (Application).\n- Tests: `tests/SphereIntegrationHub.cli.tests` (xUnit).\n\n## Considerations\n\n- If a method has a `CancellationToken`, it must be the last parameter in the method signature.\n- SOLID principles must be followed.\n- Variables must be descriptive and clear, without being excessively long.\n- The order of methods in classes must be: public, protected, then private.\n- Magic numbers, strings, etc. must be avoided. Use `priva","body":"# .NET\n\n## Main structure\n\n- CLI tool: `src/SphereIntegrationHub` (Application).\n- Tests: `tests/SphereIntegrationHub.cli.tests` (xUnit).\n\n## Considerations\n\n- If a method has a `CancellationToken`, it must be the last parameter in the method signature.\n- SOLID principles must be followed.\n- Variables must be descriptive and clear, without being excessively long.\n- The order of methods in classes must be: public, protected, then private.\n- Magic numbers, strings, etc. must be avoided. Use `private const` when elements are exclusive to a class, or, if shared, a `XxxxConsts` class with `internal const` members and reduced visibility.\n- When possible, components should use a fluent style for construction/configuration.\n- Methods must have clearly bounded responsibilities; actions should be focused and the code readable, split into small chunks (ideally no more than 50 lines of code).\n\n## Tests\n\n- Reusable, associated fixtures must be used, with methods that create common elements for multiple tests, reducing complexity and improving readability.\n- Tests must be unit tests, using mocks or WireMock (for endpoints).\n- Interfaces of the elements under test must be used, for example:  \n  `IWorkflowExecutor executor = new WorkflowExecutor()`, ensuring that the interface is fully implemented and complete.\n"},"lastSynced":"2026-03-08T02:05:50.578Z","agentAnalysis":{"suitability":{"en":"Perfect for .NET Developer Agents needing efficient application development with CLI tools and xUnit tests.","zh":"非常适合需要使用CLI工具和xUnit测试进行高效应用开发的.NET Developer Agents。","ja":".NET Developer AgentsがCLIツールおよびxUnitテストを使用して効率的なアプリケーション開発を行う必要がある場合に最適です。","ko":"CLI 도구 및 xUnit 테스트를 사용하여 효율적인 애플리케이션 개발이 필요한 .NET Developer Agents에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador .NET que necesitan un desarrollo de aplicaciones eficiente con herramientas CLI y pruebas xUnit.","fr":"Parfait pour les Agents de Développeur .NET ayant besoin d''un développement d''applications efficace avec des outils CLI et des tests xUnit.","de":"Perfekt für .NET-Entwickler-Agenten, die einen effizienten Anwendungsentwicklungsprozess mit CLI-Tools und xUnit-Tests benötigen.","pt":"Perfeito para Agentes de Desenvolvedores .NET que necessitam de desenvolvimento de aplicativos eficiente com ferramentas CLI e testes xUnit.","ru":"Идеально для агентов разработчиков .NET, которым необходим эффективный разработка приложений с помощью инструментов CLI и тестов xUnit.","ar":"مثالي لموكلات مطورين .NET الذين يحتاجون إلى تطوير تطبيقات فعال مع أدوات CLI واختبارات xUnit."},"recommendation":{"en":"Empowers agents to build scalable .NET applications using SOLID principles, descriptive variable naming, and organized method structures, while leveraging the .NET framework and CancellationToken for efficient development.","zh":"赋予代理构建可扩展的.NET应用程序的能力，使用SOLID原则、描述性变量命名和组织化方法结构，同时利用.NET框架和CancellationToken进行高效开发。","ja":"SOLID原則、記述的な変数命名、組織化されたメソッド構造を使用して、拡張可能な.NETアプリケーションを構築するエージェントをエンパワーメントし、.NETフレームワークとCancellationTokenを使用して効率的な開発を行う。","ko":"SOLID 원칙, 설명적인 변수 명명 및 조직화된 메서드 구조를 사용하여 확장 가능한 .NET 애플리케이션을 구축할 수 있도록 에이전트를赋予权限하고, .NET 프레임워크 및 CancellationToken을 사용하여 효율적인 개발을进行합니다.","es":"Habilita a los agentes a construir aplicaciones .NET escalables utilizando principios SOLID, nombres de variables descriptivos y estructuras de métodos organizadas, aprovechando al mismo tiempo el marco .NET y CancellationToken para un desarrollo eficiente.","fr":"Permet aux agents de construire des applications .NET escalables en utilisant des principes SOLID, des noms de variables descriptifs et des structures de méthodes organisées, tout en exploitant le framework .NET et CancellationToken pour un développement efficace.","de":"Ermächtigt die Agenten, skalierbare .NET-Anwendungen mithilfe von SOLID-Prinzipien, beschreibenden Variablenamen und organisierten Methodenstrukturen zu erstellen, während sie gleichzeitig das .NET-Framework und CancellationToken für eine effiziente Entwicklung nutzen.","pt":"Habilita os agentes a construir aplicações .NET escaláveis usando princípios SOLID, nomeação de variáveis descritiva e estruturas de método organizadas, aproveitando o framework .NET e CancellationToken para desenvolvimento eficiente.","ru":"Наделяет агентов возможностью создавать масштабируемые приложения .NET, используя принципы SOLID, описательное именование переменных и организованные структуры методов, используя при этом фреймворк .NET и CancellationToken для эффективной разработки.","ar":"تمكّن الوكلاء من بناء تطبيقات .NET قابلة للتوسيع باستخدام مبادئ SOLID، وتسمية المتغيرات الوصفية، وهيكل الطرق المنظّم، مع الاستفادة من إطار .NET و CancellationToken من أجل التطوير الفعال."},"useCases":{"en":["Developing .NET applications with CLI tools","Implementing xUnit tests for efficient testing","Building scalable applications using SOLID principles"],"zh":["使用CLI工具开发.NET应用程序","实现xUnit测试以进行高效测试","使用SOLID原则构建可扩展的应用程序"],"ja":[".NETアプリケーションのCLIツールを使用した開発","xUnitテストの実装による効率的なテスト","SOLID原則を使用した拡張可能なアプリケーションの構築"],"ko":[".NET 애플리케이션 개발을 위한 CLI 도구 사용","효율적인 테스트를 위한 xUnit 테스트 구현","확장 가능한 애플리케이션 구축을 위한 SOLID 원칙 사용"],"es":["Desarrollar aplicaciones .NET con herramientas CLI","Implementar pruebas xUnit para pruebas eficientes","Construir aplicaciones escalables utilizando principios SOLID"],"fr":["Développer des applications .NET avec des outils CLI","Mettre en œuvre des tests xUnit pour des tests efficaces","Construire des applications escalables en utilisant des principes SOLID"],"de":["Entwicklung von .NET-Anwendungen mit CLI-Tools","Implementierung von xUnit-Tests für effiziente Tests","Erstellung von skalierbaren Anwendungen unter Verwendung von SOLID-Prinzipien"],"pt":["Desenvolver aplicações .NET com ferramentas CLI","Implementar testes xUnit para testes eficientes","Construir aplicações escaláveis usando princípios SOLID"],"ru":["Разработка приложений .NET с помощью инструментов CLI","Реализация тестов xUnit для эффективного тестирования","Построение масштабируемых приложений с использованием принципов SOLID"],"ar":["تطوير تطبيقات .NET مع أدوات CLI","تنفيذ اختبارات xUnit لاختبارات فعالة","بناء تطبيقات قابلة للتوسيع باستخدام مبادئ SOLID"]},"limitations":{"en":["Requires .NET framework knowledge","Must follow specific coding conventions and principles","xUnit tests required for validation"],"zh":[".NET框架知识是必需的","必须遵循特定的编码约定和原则","需要xUnit测试进行验证"],"ja":[".NETフレームワークの知識が必要","特定のコーディング規約と原則に従う必要がある","検証のためにxUnitテストが必要"],"ko":[".NET 프레임워크 지식이 필수입니다","특정 코딩 규칙 및 원칙을 따라야 합니다","검증을 위해 xUnit 테스트가 필요합니다"],"es":["Requiere conocimiento del marco .NET","Debe seguir convenciones y principios de codificación específicos","Se requieren pruebas xUnit para la validación"],"fr":["Nécessite des connaissances sur le framework .NET","Doit suivre des conventions et des principes de codage spécifiques","Des tests xUnit sont requis pour la validation"],"de":["Benötigt Kenntnisse des .NET-Frameworks","Muss bestimmte Kodierkonventionen und -prinzipien befolgen","xUnit-Tests sind für die Überprüfung erforderlich"],"pt":["Exige conhecimento do framework .NET","Deve seguir convenções e princípios de codificação específicos","Testes xUnit necessários para validação"],"ru":["Требует знания фреймворка .NET","Должно следовать конкретным соглашениям и принципам кодирования","Тесты xUnit необходимы для валидации"],"ar":["يتطلب معرفة إطار .NET","يجب اتباع اتفاقيات و مبادئ ترميز محددة","اختبارات xUnit مطلوبة للتحقق"]},"version":4},"contentHash":"a30eb315864ec35ac7a94efcc6efa0d00328b7c9601eb9582a16f1ca92ecce08","qualityScore":26}');
