INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PinedaTec-EU/SphereIntegrationHub/dotnet', 'dotnet', 'PinedaTec-EU', 'SphereIntegrationHub', 'community', 'dotnet PinedaTec-EU SphereIntegrationHub community The dotnet skill provides a .NET framework for building AI agents, utilizing a CLI tool and xUnit tests for efficient development. It benefits developers working with .NET applications. dotnet 是一个 .NET CLI 工具，用于构建和测试应用程序。它遵循 SOLID 原则和清晰的变量命名 dotnet は、.NET CLI ツールを使用してアプリケーションを構築およびテストするためのものです。SOLID 原則と明確な変数命名に従います dotnet은 .NET CLI 도구를 사용하여 애플리케이션을 구축하고 테스트하는 데 사용됩니다. SOLID 원칙과 명확한 변수 이름을 따릅니다 dotnet es un framework que requiere una configuración y estructura específicas para funcionar de manera efectiva dotnet est un framework qui nécessite une configuration et une structure spécifiques pour fonctionner de manière efficace dotnet ist ein Framework, das eine spezifische Konfiguration und Struktur erfordert, um effektiv zu funktionieren O .NET é uma plataforma de desenvolvimento que segue os princípios SOLID e utiliza CancellationToken para melhorar a eficiência .NET - это платформа разработки, которая следует принципам SOLID и использует CancellationToken для повышения эффективности .NET هو منصة تطوير تتبع مبادئ SOLID و تستخدم CancellationToken لتحسين الكفاءة how to use dotnet for AI agents dotnet vs java dotnet setup guide what is dotnet framework dotnet alternative to python dotnet install for windows dotnet CLI tool tutorial xUnit tests for dotnet SOLID principles in dotnet dotnet best practices for AI development dotnet .NET CLI SOLID 原则 变量命名 CancellationToken 魔术数字 .NET 应用程序 CLI 工具 Utilizes a CLI tool via `src/SphereIntegrationHub` for application development Employs xUnit tests via `tests/SphereIntegrationHub.cli.tests` for testing Enforces SOLID principles for maintainable code Requires descriptive variable naming for clarity Follows a specific method order in classes: public, protected, then private Avoids magic numbers and strings using private constants dotnet is a .NET framework skill that provides a set of guidelines and tools for building AI agents, following SOLID principles and descriptive variable naming');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ahupp/diet-python/python-monitoring-trace', 'community', 'ahupp', 'diet-python', 'ahupp/diet-python', 'python-monitoring-trace', 0, 0, 26, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:56.577Z', 'df5959f0fef76e839db2bba4c163696ce55e2f35e073d866ebf82260743c1d03', '{"id":"ahupp/diet-python/python-monitoring-trace","name":"python-monitoring-trace","description":{"en":"The python-monitoring-trace skill allows developers to monitor and analyze Python scripts by running a helper script with specific commands and options. This skill benefits developers who need to debug and optimize their Python code.","zh":"python-monitoring-trace 是一个用于监控和跟踪 Python 脚本执行的工具。它支持自定义事件监控和日志输出。","ja":"Python モニタリング トレースは、Python スクリプトの実行を監視してトレースするためのツールです。カスタム イベントの監視とログ出力をサポートしています。","ko":"Python 모니터링 트레이스는 Python 스크립트의 실행을 모니터링하고 추적하는 데 사용되는 도구입니다. 사용자 지정 이벤트 모니터링 및 로그 출력을 지원합니다.","es":"Python-monitoring-trace es una herramienta para monitorear y depurar scripts de Python. Se ejecuta con ''python scripts/monitor_trace.py''","fr":"Python-monitoring-trace est un outil de débogage pour les scripts Python. Il s''exécute avec ''python scripts/monitor_trace.py''","de":"Python-monitoring-trace ist ein Tool zur Überwachung und Fehlerbehebung von Python-Skripten. Es wird mit ''python scripts/monitor_trace.py'' ausgeführt","pt":"O python-monitoring-trace é uma ferramenta para monitorar scripts Python com eventos personalizados e logs detalhados.","ru":"Python-monitoring-trace - это инструмент для мониторинга скриптов Python с настраиваемыми событиями и подробными журналами.","ar":"python-monitoring-trace هو أداة لمراقبة البرامج النصية Python مع أحداث مخصصة وسجلات مفصلة."},"seo":{"title":{"en":"python-monitoring-trace: Advanced Python Script Tracing S...","zh":"Python 监控跟踪工具 - Setup Guide","ja":"Python モニタリング トレース - ベスト プラクティス","ko":"Python 모니터링 트레이스 도구 - 시작 가이드","es":"Guía de configuración de python-monitoring-trace","fr":"Configurer python-monitoring-trace pour le débogage","de":"Einrichten von python-monitoring-trace für die Ablaufverf...","pt":"Guia de Configuração do python-monitoring-trace para Dese...","ru":"Настройка python-monitoring-trace: Руководство для Разраб...","ar":"دليل إعداد python-monitoring-trace لتنمية أدوات الذكاء ال..."},"description":{"en":"Unlock the full potential of your Python scripts with python-monitoring-trace. Learn how to run, list, and filter events with ease. Get started now and optim...","zh":"了解如何使用 python-monitoring-trace AIエージェント工具监控和跟踪 Python 脚本的执行","ja":"Python モニタリング トレース AIエージェントを使用して Python スクリプトの実行を監視してみましょう","ko":"Python 모니터링 트레이스 AI 도구를 사용하여 Python 스크립트의 실행을 모니터링하고 추적하는 방법에 대해 알아보세요","es":"Aprenda a utilizar python-monitoring-trace para monitorear y depurar scripts de Python de manera efectiva","fr":"Découvrez comment configurer python-monitoring-trace pour améliorer vos capacités de débogage Python","de":"Erfahren Sie, wie Sie python-monitoring-trace einrichten, um Python-Skripte effizient zu überwachen und zu debuggen","pt":"Aprenda a usar o python-monitoring-trace para monitorar scripts Python com eventos personalizados e logs detalhados","ru":"Откройте для себя возможности python-monitoring-trace для мониторинга скриптов Python с настраиваемыми событиями и подробными журналами","ar":"اكتشف كيفية استخدام python-monitoring-trace لمراقبة البرامج النصية Python مع أحداث مخصصة وسجلات مفصلة"},"definition":{"en":"python-monitoring-trace is a Python script monitoring tool that enables developers to run, list, and filter events, and write logs to a file or stdout.","zh":"python-monitoring-trace 是一个 Python 脚本监控和跟踪工具","ja":"Python モニタリング トレースは Python スクリプトの監視とトレースのためのツールです","ko":"Python 모니터링 트레이스는 Python 스크립트의 모니터링과 추적을 위한 도구입니다","es":"Python-monitoring-trace es una herramienta de línea de comandos para monitorear eventos de Python","fr":"Python-monitoring-trace est un outil en ligne de commande pour surveiller les événements Python","de":"Python-monitoring-trace ist ein Kommandozeilen-Tool zur Überwachung von Python-Ereignissen","pt":"O python-monitoring-trace é uma ferramenta de monitoramento que executa scripts Python com eventos personalizados","ru":"Python-monitoring-trace - это инструмент мониторинга, который запускает скрипты Python с настраиваемыми событиями","ar":"python-monitoring-trace هو أداة مراقبة تنفذ البرامج النصية Python مع أحداث مخصصة"},"features":{"en":["Run the helper script with `python scripts/monitor_trace.py` command","List available events with `--list-events` option","Include specific events with `--include` option (e.g., `LINE`, `INSTRUCTION`)","Exclude events with `--exclude` option (e.g., `C_RETURN`, `C_RAISE`)","Write logs to a file with `--output` option (e.g., `trace.log`)"],"zh":["支持自定义事件监控","支持日志输出到文件或标准输出","支持排除指定事件","支持包含指定事件","使用 `--list-events` 参数列出可用事件","使用 `--output` 参数指定日志文件"],"ja":["カスタム イベントの監視をサポート","ログ出力をファイルまたは標準出力にサポート","指定されたイベントを除外することをサポート","指定されたイベントを含めることをサポート","`--list-events` パラメータを使用して利用可能なイベントをリスト","`--output` パラメータを使用してログファイルを指定"],"ko":["사용자 지정 이벤트 모니터링을 지원","로그 출력을 파일 또는 표준 출력으로 지원","지정된 이벤트를 제외하는 것을 지원","지정된 이벤트를 포함하는 것을 지원","`--list-events` 매개 변수를 사용하여 사용 가능한 이벤트를 나열","`--output` 매개 변수를 사용하여 로그 파일을 지정"],"es":["Ejecutar con ''python scripts/monitor_trace.py'' para monitorear scripts de Python","Listar eventos disponibles con ''--list-events''","Incluir eventos específicos con ''--include''","Excluir eventos con ''--exclude''","Escribir registros en un archivo con ''--output''"],"fr":["Exécuter avec ''python scripts/monitor_trace.py'' pour surveiller les scripts Python","Lister les événements disponibles avec ''--list-events''","Inclure des événements spécifiques avec ''--include''","Exclure des événements avec ''--exclude''","Écrire les journaux dans un fichier avec ''--output''"],"de":["Ausführen mit ''python scripts/monitor_trace.py'' zur Überwachung von Python-Skripten","Verfügbare Ereignisse mit ''--list-events'' auflisten","Spezifische Ereignisse mit ''--include'' einbeziehen","Ereignisse mit ''--exclude'' ausschließen","Protokolle in eine Datei mit ''--output'' schreiben"],"pt":["Execução de scripts Python com eventos personalizados","Lista de eventos disponíveis com --list-events","Inclusão de eventos específicos com --include","Exclusão de eventos com --exclude","Gravação de logs em arquivo com --output"],"ru":["Запуск скриптов Python с настраиваемыми событиями","Список доступных событий с --list-events","Включение конкретных событий с --include","Исключение событий с --exclude","Запись журналов в файл с --output"],"ar":["تشغيل البرامج النصية Python مع أحداث مخصصة","قائمة بالأحداث المتاحة مع --list-events","إدراج أحداث محددة مع --include","استبعاد الأحداث مع --exclude","كتابة السجلات في ملف مع --output"]},"keywords":{"en":["how to use python-monitoring-trace","python-monitoring-trace setup guide","python script tracing","python-monitoring-trace alternative","python-monitoring-trace vs py-spy","python-monitoring-trace install","python event tracing","python script debugging","python-monitoring-trace tutorial"],"zh":["Python 监控","Python 跟踪","AIエージェント工具","Python 脚本监控","自定义事件监控","日志输出","Python 开发工具"],"ja":["Python モニタリング","Python トレース","AIエージェントツール","Python スクリプトの監視","カスタム イベントの監視","ログ出力","Python 開発ツール"],"ko":["Python 모니터링","Python 트레이스","AI 도구","Python 스크립트 모니터링","사용자 지정 이벤트 모니터링","로그 출력","Python 개발 도구"],"es":["python monitoring","python debugging","python trace","herramientas de python","monitoreo de python","depuración de python","Agente de IA para Python","Herramientas de desarrollo de Python"],"fr":["python monitoring","python debugging","python trace","outils python","surveillance python","débogage python","Outil d''IA pour Python","Outils de développement Python"],"de":["python überwachung","python debuggen","python trace","python tools","python überwachung","fehlerbehebung python","AI-Tool für Python","Python-Entwicklungstools"],"pt":["python monitoring","python logging","python eventos","ferramentas de monitoramento python","desenvolvimento python","scripts python","python-monitoring-trace"],"ru":["мониторинг python","журналирование python","события python","инструменты мониторинга python","разработка python","скрипты python","python-monitoring-trace","ИИ Агенты"],"ar":["مراقبة بايثون","تسجيل بايثون","أحداث بايثون","أدوات مراقبة بايثون","تنمية بايثون","برامج نصية بايثون","python-monitoring-trace","أدوات الذكاء الاصطناعي"]}},"owner":"ahupp","repo":"diet-python","repoPath":"ahupp/diet-python","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"python-monitoring-trace","description":"Use when you need a detailed execution trace of a Python script using sys.monitoring, including logging every operation with include/exclude event controls.","bodyPreview":"# Python Monitoring Trace\n\n- Run the helper with `python scripts/monitor_trace.py path/to/script.py -- arg1 arg2`.\n- List available events with `--list-events` and choose events by name.\n- Include only specific events with `--include LINE,INSTRUCTION` (comma-separated or repeatable).\n- Exclude events with `--exclude C_RETURN,C_RAISE` (comma-separated or repeatable).\n- Write logs to a file with `--output trace.log`; omit `--output` to write to stdout.","body":"# Python Monitoring Trace\n\n- Run the helper with `python scripts/monitor_trace.py path/to/script.py -- arg1 arg2`.\n- List available events with `--list-events` and choose events by name.\n- Include only specific events with `--include LINE,INSTRUCTION` (comma-separated or repeatable).\n- Exclude events with `--exclude C_RETURN,C_RAISE` (comma-separated or repeatable).\n- Write logs to a file with `--output trace.log`; omit `--output` to write to stdout.\n"},"lastSynced":"2026-03-08T02:05:56.577Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Debugging Agents needing advanced code analysis and optimization capabilities.","zh":"非常适合需要高级代码分析和优化能力的Python调试代理。","ja":"Pythonデバッグエージェントが高度なコード分析および最適化機能を必要とする場合に最適です。","ko":"고급 코드 분석 및 최적화 기능이 필요한 Python 디버깅 에이전트에 적합합니다.","es":"Perfecto para agentes de depuración de Python que necesitan capacidades de análisis y optimización de código avanzadas.","fr":"Parfait pour les agents de débogage Python nécessitant des capacités d''analyse et d''optimisation de code avancées.","de":"Perfekt für Python-Debugging-Agents, die erweiterte Codeanalyse- und Optimierungsfunktionen benötigen.","pt":"Perfeito para agentes de depuração Python que necessitam de capacidades avançadas de análise e otimização de código.","ru":"Идеально подходит для агентов отладки Python, которым необходимы расширенные возможности анализа и оптимизации кода.","ar":"مثالي للوكلاء تصحيح أخطاء Python الذين يحتاجون إلى возможات تحليل و تحسين شفرة متقدمة."},"recommendation":{"en":"Empowers agents to monitor and analyze Python scripts using specific commands and options, including event filtering with --include and --exclude, and log output to files or stdout, thereby enhancing their ability to debug and optimize code with features like --list-events and customizable event tracing.","zh":"赋予代理监控和分析Python脚本的能力，使用特定的命令和选项，包括使用--include和--exclude进行事件过滤，以及将日志输出到文件或stdout，从而增强代理调试和优化代码的能力，具有诸如--list-events和可自定义的事件追踪等功能。","ja":"エージェントが特定のコマンドとオプションを使用してPythonスクリプトを監視および分析する機能を提供します。--includeおよび--excludeを使用したイベントフィルタリングや、ログ出力をファイルまたはstdoutに出力するなど、コードのデバッグと最適化機能を強化します。--list-eventsやカスタマイズ可能なイベントトレーシングなどの機能が含まれます。","ko":"에이전트가 특정 명령과 옵션을 사용하여 Python 스크립트를 모니터링하고 분석할 수 있는 기능을 제공하여 --include 및 --exclude를 사용한 이벤트 필터링과 로그 출력을 파일 또는 stdout으로 출력하는 등 코드 디버깅 및 최적화 기능을 강화합니다. --list-events 및 사용자 지정 가능한 이벤트 추적과 같은 기능이 포함됩니다.","es":"Habilita a los agentes a monitorear y analizar scripts de Python utilizando comandos y opciones específicas, incluyendo filtrado de eventos con --include y --exclude, y salida de registro a archivos o stdout, lo que mejora su capacidad para depurar y optimizar el código con características como --list-events y trazado de eventos personalizable.","fr":"Permet aux agents de surveiller et d''analyser des scripts Python en utilisant des commandes et des options spécifiques, notamment le filtrage d''événements avec --include et --exclude, et la sortie de journal dans des fichiers ou stdout, ce qui améliore leur capacité à déboguer et à optimiser le code avec des fonctionnalités comme --list-events et traçage d''événements personnalisable.","de":"Ermöglicht es Agenten, Python-Skripte mithilfe spezifischer Befehle und Optionen zu überwachen und zu analysieren, einschließlich Ereignisfilterung mit --include und --exclude sowie Protokollausgabe in Dateien oder stdout, wodurch ihre Fähigkeit zur Fehlersuche und Optimierung des Codes mit Funktionen wie --list-events und anpassbarem Ereignistracing verbessert wird.","pt":"Habilita os agentes a monitorar e analisar scripts Python usando comandos e opções específicas, incluindo filtragem de eventos com --include e --exclude, e saída de log para arquivos ou stdout, melhorando assim sua capacidade de depurar e otimizar o código com recursos como --list-events e rastreamento de eventos personalizável.","ru":"Наделяет агентов возможностью отслеживать и анализировать скрипты Python с помощью конкретных команд и опций, включая фильтрацию событий с --include и --exclude, а также вывод журнала в файлы или stdout, тем самым повышая их способность отлаживать и оптимизировать код с функциями, такими как --list-events и настраиваемое отслеживание событий.","ar":"تمكّن الوكلاء من مراقبة و تحليل سكريبتات Python باستخدام أوامر و خيارات محددة، بما في ذلك تصفية الأحداث باستخدام --include و --exclude، و إخراج سجل إلى الملفات أو stdout، و بذلك تعزيز قدرتهم على تصحيح الأخطاء و تحسين الشفرة باستخدام ميزات مثل --list-events و تتبع الأحداث قابل للتعديل."},"useCases":{"en":["Debugging complex Python scripts","Optimizing code performance by tracing specific events","Analyzing Python code execution with customizable logging"],"zh":["调试复杂的Python脚本","通过追踪特定事件来优化代码性能","使用可自定义的日志分析Python代码执行"],"ja":["複雑なPythonスクリプトのデバッグ","特定のイベントをトレースしてコードのパフォーマンスを最適化する","カスタマイズ可能なログを使用してPythonコードの実行を分析する"],"ko":["복잡한 Python 스크립트 디버깅","특정 이벤트를 추적하여 코드 성능 최적화","사용자 지정 가능한 로그를 사용하여 Python 코드 실행 분석"],"es":["Depuración de scripts de Python complejos","Optimización del rendimiento del código mediante el trazado de eventos específicos","Análisis de la ejecución de código de Python con registro personalizable"],"fr":["Débogage de scripts Python complexes","Optimisation des performances du code en traçant des événements spécifiques","Analyse de l''exécution du code Python avec journalisation personnalisable"],"de":["Fehlersuche in komplexen Python-Skripten","Optimierung der Codeleistung durch Nachverfolgen spezifischer Ereignisse","Analyse der Ausführung von Python-Code mit anpassbarer Protokollierung"],"pt":["Depuração de scripts Python complexos","Otimização do desempenho do código rastreando eventos específicos","Análise da execução do código Python com registro personalizável"],"ru":["Отладка сложных скриптов Python","Оптимизация производительности кода путем отслеживания конкретных событий","Анализ выполнения кода Python с настраиваемой журнализацией"],"ar":["تصحيح أخطاء سكريبتات Python المعقدة","تحسين أداء الشفرة عن طريق تتبع أحداث محددة","تحليل تنفيذ شفرة Python مع تسجيل مخصص"]},"limitations":{"en":["Requires Python script execution","Limited to Python scripts only","Needs specific command-line options for event filtering and logging"],"zh":["需要Python脚本执行","仅限Python脚本","需要特定的命令行选项来进行事件过滤和日志输出"],"ja":["Pythonスクリプトの実行が必要","Pythonスクリプトのみに限定","イベントフィルタリングとログ出力を行うために特定のコマンドラインオプションが必要"],"ko":["Python 스크립트 실행이 필요","Python 스크립트만 해당","이벤트 필터링 및 로그 출력을 위해 특정 명령줄 옵션이 필요"],"es":["Requiere la ejecución de scripts de Python","Limitado a scripts de Python solo","Necesita opciones de línea de comandos específicas para filtrado de eventos y registro"],"fr":["Nécessite l''exécution de scripts Python","Limité aux scripts Python uniquement","Nécessite des options de ligne de commande spécifiques pour le filtrage d''événements et la journalisation"],"de":["Erfordert die Ausführung von Python-Skripten","Begrenzt auf Python-Skripte nur","Benötigt spezifische Befehlszeilenoptionen für Ereignisfilterung und Protokollierung"],"pt":["Requer execução de script Python","Limitado a scripts Python apenas","Necessita de opções de linha de comando específicas para filtragem de eventos e registro"],"ru":["Требует выполнения скрипта Python","Ограничен только скриптами Python","Требует конкретных опций командной строки для фильтрации событий и журналирования"],"ar":["يتطلب تنفيذ سكريبت Python","محدود بسكريبتات Python فقط","يحتاج إلى خيارات سطر أوامر محددة لتصفية الأحداث و التسجيل"]},"version":4},"contentHash":"df5959f0fef76e839db2bba4c163696ce55e2f35e073d866ebf82260743c1d03","qualityScore":26}');
