INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ahupp/diet-python/python-monitoring-trace', 'python-monitoring-trace', 'ahupp', 'diet-python', 'community', 'python-monitoring-trace ahupp diet-python community The python-monitoring-trace skill allows developers to monitor and analyze Python scripts by running a helper script with specific commands and options. This skill benefits developers who need to debug and optimize their Python code. python-monitoring-trace 是一个用于监控和跟踪 Python 脚本执行的工具。它支持自定义事件监控和日志输出。 Python モニタリング トレースは、Python スクリプトの実行を監視してトレースするためのツールです。カスタム イベントの監視とログ出力をサポートしています。 Python 모니터링 트레이스는 Python 스크립트의 실행을 모니터링하고 추적하는 데 사용되는 도구입니다. 사용자 지정 이벤트 모니터링 및 로그 출력을 지원합니다. Python-monitoring-trace es una herramienta para monitorear y depurar scripts de Python. Se ejecuta con ''python scripts/monitor_trace.py'' Python-monitoring-trace est un outil de débogage pour les scripts Python. Il s''exécute avec ''python scripts/monitor_trace.py'' Python-monitoring-trace ist ein Tool zur Überwachung und Fehlerbehebung von Python-Skripten. Es wird mit ''python scripts/monitor_trace.py'' ausgeführt O python-monitoring-trace é uma ferramenta para monitorar scripts Python com eventos personalizados e logs detalhados. Python-monitoring-trace - это инструмент для мониторинга скриптов Python с настраиваемыми событиями и подробными журналами. python-monitoring-trace هو أداة لمراقبة البرامج النصية Python مع أحداث مخصصة وسجلات مفصلة. how to use python-monitoring-trace python-monitoring-trace setup guide python script tracing python-monitoring-trace alternative python-monitoring-trace vs py-spy python-monitoring-trace install python event tracing python script debugging python-monitoring-trace tutorial Python 监控 Python 跟踪 AIエージェント工具 Python 脚本监控 自定义事件监控 日志输出 Python 开发工具 Run the helper script with `python scripts/monitor_trace.py` command List available events with `--list-events` option Include specific events with `--include` option (e.g., `LINE`, `INSTRUCTION`) Exclude events with `--exclude` option (e.g., `C_RETURN`, `C_RAISE`) Write logs to a file with `--output` option (e.g., `trace.log`) python-monitoring-trace is a Python script monitoring tool that enables developers to run, list, and filter events, and write logs to a file or stdout.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Silviase/default-python-project/basic_uv', 'community', 'Silviase', 'default-python-project', 'Silviase/default-python-project', 'basic_uv', 0, 0, 26, '2026-03-08T01:57:15.389Z', '2026-03-08T02:05:59.854Z', 'bdef8f8c29a531cd03068ae1ddef1cefa571f8730e5003713bdf462bb91f5039', '{"id":"Silviase/default-python-project/basic_uv","name":"basic_uv","description":{"en":"The basic_uv skill provides command-first guidance for managing projects with uv and ty, ensuring accurate type checks and efficient workflow. It benefits developers working with pyproject.toml and uv.lock files.","zh":"basic_uv 是一个使用 uv 作为项目包管理器和运行器的技能，提供命令行指导和状态更新","ja":"basic_uv は、uv をプロジェクトパッケージマネージャーおよびランナーとして使用するスキルです。コマンドラインガイダンスとステータス更新を提供します","ko":"basic_uv는 uv를 프로젝트 패키지 관리자 및 실행기로 사용하는技能입니다. 명령줄 가이드와 상태 업데이트를 제공합니다","es":"Basic_uv es una habilidad que permite utilizar uv como gestor de paquetes y ejecutor de proyectos, y ty para comprobaciones de tipos","fr":"Basic_uv est une compétence qui permet d''utiliser uv comme gestionnaire de packages et exécuteur de projets, et ty pour les vérifications de types","de":"Basic_uv ist eine Fähigkeit, die es ermöglicht, uv als Paketmanager und Projekt-Ausführer und ty für Typüberprüfungen zu verwenden","pt":"O basic_uv é uma ferramenta de gerenciamento de projetos que utiliza uv como gerenciador de pacotes e executador, e ty para verificações de tipo.","ru":"Basic_uv - это инструмент управления проектами, использующий uv в качестве менеджера пакетов и исполнителя, и ty для проверок типов для ИИ Агентов.","ar":"basic_uv هو أداة لإدارة المشاريع التي تستخدم uv كمسؤول للحزم وتنفيذ، و ty للتحقق من النوع لآلات الإعتبار."},"seo":{"title":{"en":"basic_uv: Project Management Setup Guide | AI Agent Skill","zh":"basic_uv 项目管理和运行设置指南","ja":"basic_uv プロジェクト管理と実行のベストプラクティス - AIエージェント","ko":"basic_uv 프로젝트 관리 및 실행 가이