INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Silviase/default-python-project/basic_uv', 'basic_uv', 'Silviase', 'default-python-project', 'community', 'basic_uv Silviase default-python-project community The basic_uv skill provides command-first guidance for managing projects with uv and ty, ensuring accurate type checks and efficient workflow. It benefits developers working with pyproject.toml and uv.lock files. basic_uv 是一个使用 uv 作为项目包管理器和运行器的技能，提供命令行指导和状态更新 basic_uv は、uv をプロジェクトパッケージマネージャーおよびランナーとして使用するスキルです。コマンドラインガイダンスとステータス更新を提供します basic_uv는 uv를 프로젝트 패키지 관리자 및 실행기로 사용하는技能입니다. 명령줄 가이드와 상태 업데이트를 제공합니다 Basic_uv es una habilidad que permite utilizar uv como gestor de paquetes y ejecutor de proyectos, y ty para comprobaciones de tipos Basic_uv est une compétence qui permet d''utiliser uv comme gestionnaire de packages et exécuteur de projets, et ty pour les vérifications de types Basic_uv ist eine Fähigkeit, die es ermöglicht, uv als Paketmanager und Projekt-Ausführer und ty für Typüberprüfungen zu verwenden O basic_uv é uma ferramenta de gerenciamento de projetos que utiliza uv como gerenciador de pacotes e executador, e ty para verificações de tipo. Basic_uv - это инструмент управления проектами, использующий uv в качестве менеджера пакетов и исполнителя, и ty для проверок типов для ИИ Агентов. basic_uv هو أداة لإدارة المشاريع التي تستخدم uv كمسؤول للحزم وتنفيذ، و ty للتحقق من النوع لآلات الإعتبار. how to use basic_uv basic_uv setup guide uv project management ty type checks pyproject.toml configuration uv.lock file management basic_uv vs uv basic_uv install project management with uv and ty basic_uv uv 项目管理 uv 运行 pyproject.toml uv.lock 命令行工具 项目环境管理 AI 项目管理 Detects uv project state by checking for pyproject.toml and uv.lock files Syncs project environment with uv sync command Runs tools through uv to ensure project environment usage Supports running python scripts and modules with uv run python command Provides command-first guidance for accurate project management basic_uv is a project management skill that utilizes uv as the project package manager and runner, and ty for type checks, to ensure efficient and accurate project workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('johnhuang316/code-index-mcp/release-prep', 'community', 'johnhuang316', 'code-index-mcp', 'johnhuang316/code-index-mcp', 'release-prep', 0, 0, 26, '2026-03-08T01:57:15.393Z', '2026-03-08T02:06:15.226Z', '4045205c3fe955a35660bc67d71adeb8a67924214d658a5897ef5546b4c15b1d', '{"id":"johnhuang316/code-index-mcp/release-prep","name":"release-prep","description":{"en":"The release-prep skill helps large language models index, search, and analyze code repositories with minimal setup, benefiting developers and development teams. It automates tasks using the Model Context Protocol (MCP) server.","zh":"Release Prep是一个MCP服务器，帮助大型语言模型索引、搜索和分析代码仓库，具有最小的设置要求","ja":"Release Prepは、MCPサーバーであり、大規模な言語モデルがコードリポジトリをインデックス化、検索、分析するのに役立ち、最小限の設定が必要です","ko":"Release Prep는 MCP 서버로, 대규모 언어 모델이 코드 저장소를 인덱싱, 검색 및 분석하는 것을 도와주며, 최소한의 설정이 필요합니다","es":"release-prep es un servidor MCP que ayuda a los modelos de lenguaje a indexar, buscar y analizar repositorios de código con mínimo setup","fr":"release-prep est un serveur MCP qui aide les modèles de langage à indexer, rechercher et analyser les dépôts de code avec un setup minimal","de":"release-prep ist ein MCP-Server, der großen Sprachmodellen hilft, Code-Repositorys mit minimalem Setup zu indexieren, zu durchsuchen und zu analysieren","pt":"O Release-Prep é uma ferramenta de preparação de lançamento de código que ajuda a indexar, buscar e analisar repositórios de código com mínimo setup, utilizando o protocolo MCP","ru":"Release-Prep - это ИИ Агент для подготовки кода к релизу, который помогает индексировать, искать и анализировать репозитории кода с минимальной настройкой, используя протокол MCP","ar":"Release-Prep هو أداة إعداد код الإصدار التي تساعد في فهرسة و البحث و تحليل مستودعات الشفرة بتحديث بسيط، باستخدام بروتوكول MCP"},"seo":{"title":{"en":"release-prep: Automated Code Repositor