INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('FrontMage/codex_helper/node-llm-web-automation', 'node-llm-web-automation', 'FrontMage', 'codex_helper', 'community', 'node-llm-web-automation FrontMage codex_helper community node-llm-web-automation automates manual Codex-driven page exploration using Electron UI and Puppeteer. It benefits developers by providing a low-cost Node.js automation flow. Node LLM Web Automation 是一个使用 Electron UI 和 Puppeteer_runner 实现智能教育自动化的工具 Node LLM Web Automation は Electron UI と Puppeteer_runner を使用してスマート教育の自動化を実現するツールです Node LLM Web Automation은 Electron UI와 Puppeteer_runner를 사용하여 스마트 교육 자동화를 구현하는 도구입니다 node-llm-web-automation es una herramienta de automatización web que combina Electron UI y Puppeteer para realizar flujos de trabajo deterministas node-llm-web-automation est un outil d''automatisation web qui combine Electron UI et Puppeteer pour effectuer des flux de travail déterministes node-llm-web-automation ist ein Tool für die Webautomatisierung, das Electron UI und Puppeteer für deterministische Arbeitsflüsse kombiniert O node-llm-web-automation é uma ferramenta de automação web que utiliza Electron UI e Puppeteer para automatizar tarefas Node-llm-web-automation - это инструмент для автоматизации веб-приложений, использующий Electron UI и Puppeteer node-llm-web-automation هو أداة للتحكم الآلي في التطبيقات الويب التي تستخدم Electron UI و Puppeteer node-llm-web-automation setup guide how to use node-llm-web-automation what is node-llm-web-automation node-llm-web-automation alternative node-llm-web-automation vs puppeteer node-llm-web-automation install electron ui automation puppeteer automation flow node.js automation tools Node LLM Web Automation AI工具 Electron UI Puppeteer_runner 自动化 智能教育 自动化范围 手动步骤 结束条件 Defines automation scope with entry URLs and manual step marking Implements deterministic UI flows using Puppeteer Supports pause and resume checkpoints for manual steps like captcha and 2FA Decides end conditions based on completion badges, video end, or DOM state changes Uses a single LLM call to pick DOM candidates Drives UI deterministically for low-cost automation node-llm-web-automation is a Node.js automation tool that uses Electron UI and Puppeteer to drive UI deterministically');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('classferreiracode/track-my-task/wayfinder-development', 'community', 'classferreiracode', 'track-my-task', 'classferreiracode/track-my-task', 'wayfinder-development', 0, 0, 26, '2026-03-08T01:57:15.398Z', '2026-03-08T02:06:31.308Z', '2f0edd3ba15dfe0856cae88144ae95c57c88c9b1293da7d9e6ac25041c9c1b24', '{"id":"classferreiracode/track-my-task/wayfinder-development","name":"wayfinder-development","description":{"en":"wayfinder-development facilitates efficient backend route management for frontend components, enabling seamless integration with Laravel routes and TypeScript/JavaScript applications","zh":"Wayfinder 开发是一种用于管理后端路由的技术，提供了生成路由和文档搜索的功能","ja":"Wayfinder 開発は、バックエンドルートを管理する技術で、ルート生成とドキュメント検索の機能を提供します","ko":"Wayfinder 개발은 백엔드 라우트를 관리하는 기술로 라우트 생성 및 문서 검색 기능을 제공합니다","es":"Wayfinder Development es una herramienta para gestionar rutas de backend en frontend. Permite importar rutas desde @/actions/ o @/routes/ y crear enlaces a endpoints de backend","fr":"Wayfinder Development est un outil pour gérer les routes backend dans les composants frontend. Il permet d''importer des routes depuis @/actions/ ou @/routes/ et de créer des liens vers les points de terminaison de backend","de":"Wayfinder Development ist ein Tool zur Verwaltung von Backend-Routen in Frontend-Komponenten. Es ermöglicht das Importieren von Routen aus @/actions/ oder @/routes/ und das Erstellen von Links zu Backend-Endpunkten","pt":"Wayfinder Development é uma ferramenta para gerenciar rotas de backend em componentes frontend","ru":"Wayfinder Development — это инструмент для управления маршрутами бэкенда в компонентах фронтенда","ar":"Wayfinder Development هو أداة لإدارة مسارات الخادم في مكونات الواجهة"},"seo":{"title":{"en":"wayfinder-development: Laravel Route Management Setup Gui...","zh":"Wayfinder 开发设置指南 - AI 工具","ja":"Wayfinder 開発セットアップガイド - AI エージェント","ko":"Wayfinder 개발 설정 가이드 - AI 에이전트","es":"Guía de configuración de Wayfinder Development para rutas...","fr":"Guide de mise en route de Wayfinder Development pour les ...","de":"Einrichtungsleitfaden für Wayfinder Development zur Verwe...","pt":"Guia de Configuração Wayfinder Development para Desenvolv...","ru":"Руководство по настройке Wayfinder Development для разраб...","ar":"دليل إعداد Wayfinder Development للهندسة"},"description":{"en":"Discover how to streamline backend route management with wayfinder-development. Learn how to generate routes and integrate with Laravel for seamless development","zh":"了解 Wayfinder 开发的最佳实践，包括生成路由和文档搜索","ja":"Wayfinder 開発のベストプラクティスを学ぶ - ルート生成とドキュメント検索","ko":"Wayfinder 개발의 최선의 방법을 배우세요 - 라우트 생성 및 문서 검색","es":"Aprende a implementar Wayfinder Development en tus proyectos para mejorar la gestión de rutas de backend en frontend","fr":"Découvrez comment utiliser Wayfinder Development pour améliorer la gestion des routes backend dans vos applications frontend","de":"Erfahren Sie, wie Sie Wayfinder Development in Ihren Projekten einsetzen, um die Verwaltung von Backend-Routen in der Frontend-Komponente zu verbessern","pt":"Aprenda a configurar o Wayfinder Development para melhorar a navegação em sua aplicação","ru":"Узнайте, как настроить Wayfinder Development для улучшения навигации в вашем приложении","ar":"تعلم كيفية إعداد Wayfinder Development لتحسين التنقل في تطبيقك"},"definition":{"en":"wayfinder-development is a technical skill for managing backend routes in frontend components, utilizing Laravel and TypeScript/JavaScript","zh":"Wayfinder 开发是一种用于管理后端路由的技术","ja":"Wayfinder 開発は、バックエンドルートを管理する技術です","ko":"Wayfinder 개발은 백엔드 라우트를 관리하는 기술입니다","es":"Wayfinder Development es una herramienta de desarrollo que facilita la gestión de rutas de backend en aplicaciones frontend","fr":"Wayfinder Development est un outil de développement qui facilite la gestion des routes backend dans les applications frontend","de":"Wayfinder Development ist ein Entwicklungstool, das die Verwaltung von Backend-Routen in Frontend-Anwendungen erleichtert","pt":"Wayfinder Development é uma técnica para gerenciar rotas de backend em aplicações web","ru":"Wayfinder Development — это метод управления маршрутами бэкенда в веб-приложениях","ar":"Wayfinder Development هو طريقة لإدارة مسارات الخادم في التطبيقات الويب"},"features":{"en":["Generates routes using the php artisan wayfinder:generate command","Supports integration with Laravel routes and TypeScript/JavaScript applications","Enables creation of links and navigation to backend endpoints","Utilizes Vite plugin for automated route generation","Provides detailed documentation via search-docs"],"zh":["生成路由","文档搜索","支持 TypeScript/JavaScript","支持 Laravel 路由","提供快速参考指南"],"ja":["ルート生成","ドキュメント検索","TypeScript/JavaScript 対応","Laravel ルート対応","クイックリファレンスガイド提供"],"ko":["라우트 생성","문서 검색","TypeScript/JavaScript 지원","Laravel 라우트 지원","빠른 참조 가이드 제공"],"es":["Importación de rutas desde @/actions/ o @/routes/","Creación de enlaces a endpoints de backend","Generación de rutas con el comando php artisan wayfinder:generate","Compatibilidad con Laravel y TypeScript/JavaScript","Integración con Vite para una mejor experiencia de desarrollo"],"fr":["Importation de routes depuis @/actions/ ou @/routes/","Création de liens vers les points de terminaison de backend","Génération de routes avec la commande php artisan wayfinder:generate","Compatibilité avec Laravel et TypeScript/JavaScript","Intégration avec Vite pour une meilleure expérience de développement"],"de":["Importieren von Routen aus @/actions/ oder @/routes/","Erstellen von Links zu Backend-Endpunkten","Generieren von Routen mit dem Befehl php artisan wayfinder:generate","Kompatibilität mit Laravel und TypeScript/JavaScript","Integration mit Vite für eine bessere Entwicklererfahrung"],"pt":["Geração de rotas com o comando php artisan wayfinder:generate","Integração com Laravel e TypeScript/JavaScript","Criação de links e navegação para endpoints de backend","Importação de rotas de @/actions/ e @/routes/","Compatibilidade com o plugin Vite"],"ru":["Генерация маршрутов с помощью команды php artisan wayfinder:generate","Интеграция с Laravel и TypeScript/JavaScript","Создание ссылок и навигации для конечных точек бэкенда","Импорт маршрутов из @/actions/ и @/routes/","Совместимость с плагином Vite"],"ar":["إنشاء مسارات باستخدام الأمر php artisan wayfinder:generate","التكامل مع Laravel و TypeScript/JavaScript","إنشاء روابط وتنقل إلى نهايات الخادم","استيراد مسارات من @/actions/ و @/routes/","التوافق مع الإضافة Vite"]},"keywords":{"en":["how to use wayfinder-development","wayfinder-development setup guide","wayfinder-development alternative","wayfinder-development vs Laravel","wayfinder-development install","what is wayfinder-development","wayfinder-development tutorial","wayfinder-development and TypeScript","wayfinder-development and JavaScript"],"zh":["Wayfinder 开发","AI 工具","后端路由管理","生成路由","文档搜索","TypeScript/JavaScript","Laravel 路由"],"ja":["Wayfinder 開発","AI エージェント","バックエンドルート管理","ルート生成","ドキュメント検索","TypeScript/JavaScript","Laravel ルート"],"ko":["Wayfinder 개발","AI 에이전트","백엔드 라우트 관리","라우트 생성","문서 검색","TypeScript/JavaScript","Laravel 라우트"],"es":["wayfinder development","rutas de backend","frontend","laravel","typescript","javascript","vite","desarrollo web","herramientas de desarrollo"],"fr":["wayfinder development","routes backend","frontend","laravel","typescript","javascript","vite","développement web","outils de développement"],"de":["wayfinder development","backend-routen","frontend","laravel","typescript","javascript","vite","webentwicklung","entwicklungstools"],"pt":["wayfinder development","gerenciamento de rotas","laravel","typescript","javascript","vite","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["wayfinder development","управление маршрутами","laravel","typescript","javascript","vite","веб-разработка","инструменты разработки"],"ar":["wayfinder development","إدارة مسارات","laravel","typescript","javascript","vite","تطوير الويب","أدوات التطوير"]}},"owner":"classferreiracode","repo":"track-my-task","repoPath":"classferreiracode/track-my-task","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.398Z","topics":[],"category":"community","skillMd":{"name":"wayfinder-development","description":">-","bodyPreview":"# Wayfinder Development\n\n## When to Apply\n\nActivate whenever referencing backend routes in frontend components:\n- Importing from `@/actions/` or `@/routes/`\n- Calling Laravel routes from TypeScript/JavaScript\n- Creating links or navigation to backend endpoints\n\n## Documentation\n\nUse `search-docs` for detailed Wayfinder patterns and documentation.\n\n## Quick Reference\n\n### Generate Routes\n\nRun after route changes if Vite plugin isn''t installed:\n\nphp artisan wayfinder:generate --no-interaction\n\nFor","body":"# Wayfinder Development\n\n## When to Apply\n\nActivate whenever referencing backend routes in frontend components:\n- Importing from `@/actions/` or `@/routes/`\n- Calling Laravel routes from TypeScript/JavaScript\n- Creating links or navigation to backend endpoints\n\n## Documentation\n\nUse `search-docs` for detailed Wayfinder patterns and documentation.\n\n## Quick Reference\n\n### Generate Routes\n\nRun after route changes if Vite plugin isn''t installed:\n\nphp artisan wayfinder:generate --no-interaction\n\nFor form helpers, use `--with-form` flag:\n\nphp artisan wayfinder:generate --with-form --no-interaction\n\n### Import Patterns\n\n<code-snippet name=\"Controller Action Imports\" lang=\"typescript\">\n\n// Named imports for tree-shaking (preferred)...\nimport { show, store, update } from ''@/actions/App/Http/Controllers/PostController''\n\n// Named route imports...\nimport { show as postShow } from ''@/routes/post''\n\n</code-snippet>\n\n### Common Methods\n\n<code-snippet name=\"Wayfinder Methods\" lang=\"typescript\">\n\n// Get route object...\nshow(1) // { url: \"/posts/1\", method: \"get\" }\n\n// Get URL string...\nshow.url(1) // \"/posts/1\"\n\n// Specific HTTP methods...\nshow.get(1)\nstore.post()\nupdate.patch(1)\ndestroy.delete(1)\n\n// Form attributes for HTML forms...\nstore.form() // { action: \"/posts\", method: \"post\" }\n\n// Query parameters...\nshow(1, { query: { page: 1 } }) // \"/posts/1?page=1\"\n\n</code-snippet>\n\n## Wayfinder + Inertia\n\nUse Wayfinder with the `<Form>` component:\n<code-snippet name=\"Wayfinder Form (Vue)\" lang=\"vue\">\n\n<Form v-bind=\"store.form()\"><input name=\"title\" /></Form>\n\n</code-snippet>\n\n## Verification\n\n1. Run `php artisan wayfinder:generate` to regenerate routes if Vite plugin isn''t installed\n2. Check TypeScript imports resolve correctly\n3. Verify route URLs match expected paths\n\n## Common Pitfalls\n\n- Using default imports instead of named imports (breaks tree-shaking)\n- Forgetting to regenerate after route changes\n- Not using type-safe parameter objects for route model binding"},"lastSynced":"2026-03-08T02:06:31.308Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing seamless backend route management for frontend components in Laravel and TypeScript/JavaScript applications","zh":"非常适合需要无缝后端路由管理的全栈代理，用于Laravel和TypeScript/JavaScript应用程序的前端组件","ja":"LaravelとTypeScript/JavaScriptアプリケーションのフロントエンドコンポーネントに対するシームレスなバックエンドルート管理が必要なフルスタックエージェントに最適","ko":"Laravel 및 TypeScript/JavaScript 애플리케이션의 프론트엔드 구성 요소에 대한 무縫한 백엔드 라우트 관리가 필요한 풀 스택 에이전트에 적합합니다","es":"Perfecto para Agentes Full Stack que necesitan una gestión de rutas de backend sin problemas para componentes de frontend en Laravel y aplicaciones de TypeScript/JavaScript","fr":"Parfait pour les agents Full Stack qui ont besoin d''une gestion de routes de backend transparente pour les composants de frontend dans Laravel et les applications TypeScript/JavaScript","de":"Perfekt für Full Stack-Agents, die eine nahtlose Verwaltung von Backend-Routen für Frontend-Komponenten in Laravel und TypeScript/JavaScript-Anwendungen benötigen","pt":"Perfeito para Agentes Full Stack que necessitam de gerenciamento de rotas de backend sem interrupção para componentes frontend em Laravel e aplicações TypeScript/JavaScript","ru":"Идеально подходит для агентов Full Stack, которым требуется бесперебойное управление маршрутами бэкенда для компонентов frontend в Laravel и приложениях TypeScript/JavaScript","ar":"مثالي للوكلاء الكاملون الذين يحتاجون إلى إدارة مسار الخلفية بدون انقطاع لمكونات الواجهة في Laravel وتطبيقات TypeScript/JavaScript"},"recommendation":{"en":"Empowers agents to efficiently manage backend routes with Laravel routes and TypeScript/JavaScript applications, utilizing Vite plugin for automated route generation and facilitating seamless integration with frontend components via @/actions/ or @/routes/ imports","zh":"赋予代理高效管理后端路由的能力，利用Laravel路由和TypeScript/JavaScript应用程序，并通过Vite插件实现自动路由生成，并通过@/actions/或@/routes/导入实现与前端组件的无缝集成","ja":"LaravelルートとTypeScript/JavaScriptアプリケーションを使用して、エージェントがバックエンドルートを効率的に管理できるようにし、Viteプラグインを使用して自動ルート生成を実現し、@/actions/または@/routes/のインポートを介してフロントエンドコンポーネントとのシームレスな統合を促進する","ko":"Laravel ル트와 TypeScript/JavaScript 애플리케이션을 사용하여 에이전트가 백엔드 라우트를 효율적으로 관리할 수 있도록 하며, Vite 플러그인을 사용하여 자동 라우트 생성을 구현하고, @/actions/ 또는 @/routes/ 가져오기를 통해 프론트엔드 구성 요소와의 무縫한 통합을促进합니다","es":"Habilita a los agentes a gestionar eficientemente las rutas de backend con rutas de Laravel y aplicaciones de TypeScript/JavaScript, utilizando el plugin Vite para la generación automática de rutas y facilitando una integración transparente con componentes de frontend a través de importaciones @/actions/ o @/routes/","fr":"Permet aux agents de gérer efficacement les routes de backend avec les routes de Laravel et les applications TypeScript/JavaScript, en utilisant le plugin Vite pour la génération automatique de routes et en facilitant une intégration transparente avec les composants de frontend via les imports @/actions/ ou @/routes/","de":"Ermöglicht es den Agenten, Backend-Routen mit Laravel-Routen und TypeScript/JavaScript-Anwendungen effizient zu verwalten, indem es das Vite-Plugin für die automatische Routengenerierung verwendet und eine nahtlose Integration mit Frontend-Komponenten über @/actions/- oder @/routes-Imports ermöglicht","pt":"Habilita os agentes a gerenciar eficientemente as rotas de backend com rotas Laravel e aplicações TypeScript/JavaScript, utilizando o plugin Vite para geração automática de rotas e facilitando a integração sem interrupção com componentes frontend via importações @/actions/ ou @/routes/","ru":"Наделяет агентов возможностью эффективно управлять маршрутами бэкенда с помощью маршрутов Laravel и приложений TypeScript/JavaScript, используя плагин Vite для автоматической генерации маршрутов и облегчая бесперебойную интеграцию с компонентами frontend через импорты @/actions/ или @/routes/","ar":"يمنح الوكلاء القدرة على إدارة مسارات الخلفية بكفاءة مع مسارات Laravel وتطبيقات TypeScript/JavaScript، باستخدام إضافة Vite لتوليد المسارات تلقائيًا وتسهيل التكامل دون انقطاع مع مكونات الواجهة عبر الاستيراد @/actions/ أو @/routes/"},"useCases":{"en":["Automating route updates in TypeScript/JavaScript applications","Generating links or navigation to backend endpoints in Laravel","Debugging route issues between frontend and backend components"],"zh":["在TypeScript/JavaScript应用程序中自动更新路由","在Laravel中生成到后端端点的链接或导航","调试前端和后端组件之间的路由问题"],"ja":["TypeScript/JavaScriptアプリケーションでのルートの自動更新","Laravelでのバックエンドエンドポイントへのリンクまたはナビゲーションの生成","フロントエンドとバックエンドコンポーネント間のルートの問題のデバッグ"],"ko":["TypeScript/JavaScript 애플리케이션에서 라우트를 자동으로 업데이트하는 것","Laravel에서 백엔드 엔드ポイント로의 링크 또는 네비게이션을 생성하는 것","프론트엔드와 백엔드 구성 요소 간의 라우트 문제를 디버그하는 것"],"es":["Automatización de actualizaciones de rutas en aplicaciones de TypeScript/JavaScript","Generación de enlaces o navegación a puntos de conexión de backend en Laravel","Depuración de problemas de rutas entre componentes de frontend y backend"],"fr":["Automatisation des mises à jour de routes dans les applications TypeScript/JavaScript","Génération de liens ou de navigation vers les points de terminaison de backend dans Laravel","Débogage des problèmes de routes entre les composants de frontend et de backend"],"de":["Automatisierung von Routenaktualisierungen in TypeScript/JavaScript-Anwendungen","Generierung von Links oder Navigierung zu Backend-Endpunkten in Laravel","Fehlerbehebung bei Routenproblemen zwischen Frontend- und Backend-Komponenten"],"pt":["Automatizar atualizações de rotas em aplicações TypeScript/JavaScript","Gerar links ou navegação para pontos de extremidade de backend em Laravel","Depurar problemas de rotas entre componentes frontend e backend"],"ru":["Автоматизировать обновления маршрутов в приложениях TypeScript/JavaScript","Генерировать ссылки или навигацию на конечные точки бэкенда в Laravel","Отлаживать проблемы с маршрутами между компонентами frontend и бэкенда"],"ar":["توفير تحديثات تلقائية للمسارات في تطبيقات TypeScript/JavaScript","توليد الروابط أو التنقل إلى نقاط النهاية الخلفية في Laravel","تصحيح الأخطاء في المسارات بين مكونات الواجهة والخلفية"]},"limitations":{"en":["Requires Laravel and TypeScript/JavaScript environment","Vite plugin installation necessary for automated route generation","Manual route generation via php artisan wayfinder:generate command required if Vite plugin isn''t installed"],"zh":["需要Laravel和TypeScript/JavaScript环境","Vite插件安装是自动路由生成所必需的","如果未安装Vite插件，则需要通过php artisan wayfinder:generate命令手动生成路由"],"ja":["LaravelとTypeScript/JavaScript環境が必要","自動ルート生成にはViteプラグインのインストールが必要","Viteプラグインがインストールされていない場合は、php artisan wayfinder:generateコマンドを使用して手動でルートを生成する必要がある"],"ko":["Laravel 및 TypeScript/JavaScript 환경이 필요합니다","자동 라우트 생성을 위해서는 Vite 플러그인의 설치가 필요합니다","Vite 플러그인이 설치되지 않은 경우에는 php artisan wayfinder:generate 명령을 사용하여 수동으로 라우트를 생성해야 합니다"],"es":["Requiere un entorno de Laravel y TypeScript/JavaScript","La instalación del plugin Vite es necesaria para la generación automática de rutas","Se requiere generación de rutas manual a través del comando php artisan wayfinder:generate si el plugin Vite no está instalado"],"fr":["Nécessite un environnement Laravel et TypeScript/JavaScript","L''installation du plugin Vite est nécessaire pour la génération automatique de routes","La génération manuelle de routes via la commande php artisan wayfinder:generate est requise si le plugin Vite n''est pas installé"],"de":["Benötigt eine Laravel- und TypeScript/JavaScript-Umgebung","Die Installation des Vite-Plugins ist für die automatische Routengenerierung erforderlich","Eine manuelle Routengenerierung über den Befehl php artisan wayfinder:generate ist erforderlich, wenn das Vite-Plugin nicht installiert ist"],"pt":["Requer ambiente Laravel e TypeScript/JavaScript","Instalação do plugin Vite necessária para geração automática de rotas","Geração manual de rotas via comando php artisan wayfinder:generate necessária se o plugin Vite não estiver instalado"],"ru":["Требуется среда Laravel и TypeScript/JavaScript","Установка плагина Vite необходима для автоматической генерации маршрутов","Ручная генерация маршрутов через команду php artisan wayfinder:generate необходима, если плагин Vite не установлен"],"ar":["يتطلب بيئة Laravel و TypeScript/JavaScript","التثبيت اللازم لإضافة Vite لتوليد المسارات تلقائيًا","التوليد اليدوي للمسارات عبر الأمر php artisan wayfinder:generate ضروري إذا لم يتم تثبيت إضافة Vite"]},"version":4},"contentHash":"2f0edd3ba15dfe0856cae88144ae95c57c88c9b1293da7d9e6ac25041c9c1b24","qualityScore":26}');
