INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('classferreiracode/track-my-task/wayfinder-development', 'wayfinder-development', 'classferreiracode', 'track-my-task', 'community', 'wayfinder-development classferreiracode track-my-task community wayfinder-development facilitates efficient backend route management for frontend components, enabling seamless integration with Laravel routes and TypeScript/JavaScript applications Wayfinder 开发是一种用于管理后端路由的技术，提供了生成路由和文档搜索的功能 Wayfinder 開発は、バックエンドルートを管理する技術で、ルート生成とドキュメント検索の機能を提供します Wayfinder 개발은 백엔드 라우트를 관리하는 기술로 라우트 생성 및 문서 검색 기능을 제공합니다 Wayfinder Development es una herramienta para gestionar rutas de backend en frontend. Permite importar rutas desde @/actions/ o @/routes/ y crear enlaces a endpoints de backend Wayfinder Development est un outil pour gérer les routes backend dans les composants frontend. Il permet d''importer des routes depuis @/actions/ ou @/routes/ et de créer des liens vers les points de terminaison de backend Wayfinder Development ist ein Tool zur Verwaltung von Backend-Routen in Frontend-Komponenten. Es ermöglicht das Importieren von Routen aus @/actions/ oder @/routes/ und das Erstellen von Links zu Backend-Endpunkten Wayfinder Development é uma ferramenta para gerenciar rotas de backend em componentes frontend Wayfinder Development — это инструмент для управления маршрутами бэкенда в компонентах фронтенда Wayfinder Development هو أداة لإدارة مسارات الخادم في مكونات الواجهة how to use wayfinder-development wayfinder-development setup guide wayfinder-development alternative wayfinder-development vs Laravel wayfinder-development install what is wayfinder-development wayfinder-development tutorial wayfinder-development and TypeScript wayfinder-development and JavaScript Wayfinder 开发 AI 工具 后端路由管理 生成路由 文档搜索 TypeScript/JavaScript Laravel 路由 Generates routes using the php artisan wayfinder:generate command Supports integration with Laravel routes and TypeScript/JavaScript applications Enables creation of links and navigation to backend endpoints Utilizes Vite plugin for automated route generation Provides detailed documentation via search-docs wayfinder-development is a technical skill for managing backend routes in frontend components, utilizing Laravel and TypeScript/JavaScript');
