INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('koala-man-64/asset-allocation/delivery-engineer-agent', 'delivery-engineer-agent', 'koala-man-64', 'asset-allocation', 'community', 'delivery-engineer-agent koala-man-64 asset-allocation community The delivery-engineer-agent translates requirements into testable code changes and deployment-ready configuration. It benefits developers by providing a telemetry plan and operational readiness. Delivery Engineer Agent 是一种可以将需求转化为生产就绪、可测试的代码变更和部署就绪配置的工具 Delivery Engineer Agent は、要件を生産就緒のコード変更とデプロイ就緒の構成に変換するツールです Delivery Engineer Agent는 요구사항을 생산 준비 코드 변경과 배포 준비 구성으로 변환하는 도구입니다 El Agente de Ingeniero de Entrega es una herramienta que traduce requisitos en código de producción y configuraciones de despliegue con observabilidad y notas de libro de ejecución L''Agent Ingénieur de Livraison est un outil qui traduit les exigences en code de production et configurations de déploiement avec observabilité et notes de livre de exécution Der Delivery Engineer Agent ist ein Tool, das Anforderungen in Produktionscode und Bereitstellungskonfigurationen mit Observierbarkeit und Runbook-Notizen übersetzt O agente de engenheiro de entrega traduz requisitos em alterações de código testáveis e configurados para produção com observabilidade e notas de runbook ИИ Агент инженера доставки переводит требования в тестируемые изменения кода и конфигурации для производства с наблюдаемостью и заметками рунбука وكيل مهندس التسليم يترجم المتطلبات إلى تغييرات كود قابلة للاختبار وملائمة للإنتاج مع مراقبة وملحوظات تشغيل الكتاب how to use delivery-engineer-agent delivery-engineer-agent setup guide what is delivery-engineer-agent delivery-engineer-agent alternative delivery-engineer-agent vs competitor delivery-engineer-agent implementation report delivery-engineer-agent installation delivery-engineer-agent tutorial delivery-engineer-agent best practices Delivery Engineer Agent AI 工具 自动化部署 观察性 代码变更 部署配置 遥测计划 运营准备 Produces Implementation Report artifact in a specified format Follows directives from references/agent.md for scope and constraints Provides a telemetry plan for operational readiness Generates deployment-ready configuration with observability Creates runbook notes for efficient deployment Reads references/agent.md for output format and stop conditions delivery-engineer-agent is a skill that generates production-ready code changes and deployment configuration with observability and runbook notes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenPeopleStudio/open_people/sam', 'community', 'OpenPeopleStudio', 'open_people', 'OpenPeopleStudio/open_people', 'sam', 0, 0, 26, '2026-03-08T01:57:15.380Z', '2026-03-08T02:06:49.009Z', 'c14b6aceb8159caabe12d5ed9360ab060d960fe3312db2a473ee5473608b20b5', '{"id":"OpenPeopleStudio/open_people/sam","name":"sam","description":{"en":"sam is an AI agent that identifies commercialization paths and partner API opportunities for retail brands. It analyzes market trends and provides ranked lists of partner opportunities.","zh":"sam是一种AI驱动的商业基础设施，帮助雄心勃勃的零售品牌识别商业化路径和合作伙伴API机会。它通过市场扫描、适应性分析和输出三个阶段提供排名的合作伙伴机会列表","ja":"samは、野心的なリテールブランドが商業化パスとパートナーAPIの機会を識別するのを支援するAI駆動の商業インフラストラクチャです。マーケットスキャン、フィット分析、出力の3つのステージでランク付けされたパートナーの機会の一覧を提供します","ko":"sam은 야심있는 리테일 브랜드가 상업화 경로와 파트너 API 기회를 식별하는 것을 지원하는 AI 기반의 상업 인프라입니다. 시장 스캔, 적합성 분석, 출력의 3个 단계에서 순위가 매겨진 파트너 기회 목록을 제공합니다","es":"Sam es una infraestructura de comercio AI que identifica rutas de comercialización y oportunidades de API para marcas de retail. Analiza el mercado y las capacidades actuales para recomendar oportunidades de partner","fr":"Sam est une infrastructure de commerce IA qui identifie les voies de commercialisation et les opportunités d''API pour les marques de détail. Il analyse le marché et les capacités actuelles pour recommander des opportunités de partenariat","de":"Sam ist eine KI-basierte Commerce-Infrastruktur, die Vermarktungspfade und API-Möglichkeiten für Einzelhandelsmarken identifiziert. Sie analysiert den Markt und die aktuellen Fähigkeiten, um Partnermöglichkeiten zu empfehlen","pt":"O Sam é uma infraestrutura de comércio AI que ajuda marcas varejistas a identificar caminhos de comercialização e oportunidades de API. Ele realiza uma varredura de mercado e análise de adequação para recomendar parcerias","ru":"Sam - это ИИ Агенты для коммерческой инфраструктуры, которая помогает розничным брендам определить пути коммерциализации и возможности API. Он выполняет сканирование рынка и анализ соответствия для рекомендации партнерств","ar":"سام هو بنية تجارية مدعومة بالذكاء الاصطناعي التي تساعد العلامات التجارية على تحديد مسارات التوسع التجاري وفرص API. يقوم بفحص السوق وتحليل الملاءمة لتوصية بالشراكات"},"seo":{"title":{"en":"sam: AI-Powered Commerce Infrastructure Setup Guide | AI ...","zh":"sam 商业化路径识别和合作伙伴API整合设置指南","ja":"samの商業化パス識別とパートナーAPI機会設定ガイド","ko":"sam 상업화 경로 식별 및 파트너 API 기회 설정 가이드","es":"Guía de configuración de Sam: Infraestructura de comercio AI","fr":"Guide de mise en place de Sam: Infrastructure de commerce IA","de":"Einrichtungsleitfaden für Sam: KI-basierte Commerce-Infra...","pt":"Guia de Configuração do Sam: Infraestrutura de Comércio AI","ru":"Настройка Sam: ИИ Агенты для коммерческой инфраструктуры","ar":"إعداد سام: بنية تجارية مدعومة بالذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of OpenPeople.ai with sam, the AI-powered commerce infrastructure. Discover how to integrate adjacent platforms and APIs for ambiti...","zh":"了解sam的商业化路径识别和合作伙伴API整合功能，提升您的零售品牌竞争力","ja":"samの商業化パス識別とパートナーAPI機会の機能を理解し、リテールブランドの競争力を高める","ko":"sam의 상업화 경로 식별 및 파트너 API 기회 기능을 이해하여 리테일 브랜드의 경쟁력을 높여보세요","es":"Descubre cómo Sam de OpenPeople.ai identifica rutas de comercialización y oportunidades de API para marcas de retail ambiciosas","fr":"Découvrez comment Sam d''OpenPeople.ai identifie les voies de commercialisation et les opportunités d''API pour les marques de détail ambitionnées","de":"Erfahren Sie, wie Sam von OpenPeople.ai Vermarktungspfade und API-Möglichkeiten für ambitionierte Einzelhandelsmarken identifiziert","pt":"Aprenda a configurar o Sam, uma infraestrutura de comércio AI para marcas varejistas ambiciosas, e descubra como identificar caminhos de comercialização e op...","ru":"Узнайте, как настроить Sam, ИИ Агенты для коммерческой инфраструктуры, и发现 как определить пути коммерциализации и возможности API","ar":"تعرف على كيفية إعداد سام، بنية تجارية مدعومة بالذكاء الاصطناعي، واكتشف كيفية تحديد مسارات التوسع التجاري وفرص API"},"definition":{"en":"sam is an AI-powered commerce infrastructure that analyzes market trends and identifies partner API opportunities for ambitious retail brands.","zh":"sam是一种AI驱动的商业基础设施，用于识别商业化路径和合作伙伴API机会","ja":"samは、商業化パスとパートナーAPIの機会を識別するためのAI駆動の商業インフラストラクチャです","ko":"sam은 상업화 경로와 파트너 API 기회를 식별하는 데 사용되는 AI 기반의 상업 인프라입니다","es":"Sam es un agente de IA que identifica oportunidades de comercialización y API para marcas de retail","fr":"Sam est un agent IA qui identifie les opportunités de commercialisation et d''API pour les marcas de détail","de":"Sam ist ein KI-Agent, der Vermarktungsmöglichkeiten und API-Möglichkeiten für Einzelhandelsmarken identifiziert","pt":"O que é Sam? É uma infraestrutura de comércio AI que identifica oportunidades de API e caminhos de comercialização para marcas varejistas","ru":"Что такое Sam? Это ИИ Агенты для коммерческой инфраструктуры, который определяет возможности API и пути коммерциализации для розничных брендов","ar":"ما هو سام? هو بنية تجارية مدعومة بالذكاء الاصطناعي التي تحدد فرص API ومسارات التوسع التجاري للعلامات التجارية"},"features":{"en":["Conducts market scans to identify adjacent platforms and APIs worth integrating","Maps opportunities to current repository capabilities and roadmap","Flags dependencies, missing features, and security constraints","Provides ranked lists of partner opportunities","Recommends next steps for integration and implementation","Analyzes typical pricing models and distribution channels"],"zh":["市场扫描：识别相邻平台和API","适应性分析：映射机会到当前仓库能力和路线图","输出：提供排名的合作伙伴机会列表","依赖性标志：识别缺失的功能和安全约束","安全约束：标志安全相关的依赖性和功能"],"ja":["マーケットスキャン：隣接プラットフォームとAPIを識別","フィット分析：機会を現在のリポジトリ機能とロードマップにマッピング","出力：ランク付けされたパートナーの機会の一覧を提供","依存関係のフラグ：欠けている機能とセキュリティの制約を識別","セキュリティの制約：セキュリティ関連の依存関係と機能をフラグ"],"ko":["시장 스캔：인접 플랫폼과 API를 식별","적합성 분석：기회를 현재 리포지토리 기능과 로드맵에 매핑","출력：순위가 매겨진 파트너 기회 목록을 제공","의존성 플래그：결손된 기능과 보안 제약을 식별","보안 제약：보안 관련 의존성과 기능을 플래그"],"es":["Análisis de mercado para identificar plataformas y API de integración","Análisis de ajuste para mapear oportunidades con capacidades actuales","Generación de una lista clasificada de oportunidades de partner","Recomendación de próximos pasos para la integración","Identificación de dependencias y limitaciones de seguridad","Análisis de modelos de precios y canales de distribución"],"fr":["Analyse de marché pour identifier les plateformes et les API d''intégration","Analyse de correspondance pour mapper les opportunités avec les capacités actuelles","Génération d''une liste classée d''opportunités de partenariat","Recommandation des prochaines étapes pour l''intégration","Identification des dépendances et des limites de sécurité","Analyse des modèles de prix et des canaux de distribution"],"de":["Marktanalyse zur Identifizierung von Plattformen und API-Integrationen","Anpassungsanalyse zur Abbildung von Möglichkeiten auf aktuelle Fähigkeiten","Erstellung einer priorisierten Liste von Partnermöglichkeiten","Empfehlung der nächsten Schritte für die Integration","Identifizierung von Abhängigkeiten und Sicherheitseinschränkungen","Analyse von Preismodellen und Vertriebskanälen"],"pt":["Realiza varredura de mercado para identificar plataformas e APIs adjacentes","Análise de adequação para mapear oportunidades de API ao repositório atual","Recomenda parcerias com base em análise de adequação","Fornece lista ranqueada de oportunidades de parceria","Identifica dependências, recursos ausentes e restrições de segurança"],"ru":["Выполняет сканирование рынка для определения смежных платформ и API","Анализ соответствия для сопоставления возможностей API с текущим репозиторием","Рекомендует партнерства на основе анализа соответствия","Предоставляет ранжированный список возможностей партнерства","Определяет зависимости, отсутствующие функции и ограничения безопасности"],"ar":["يقوم بفحص السوق لتحديد المنصات والواجهات البرمجية المجاورة","تحليل الملاءمة لربط فرص API بال仓 مخزون الحالي","يوصي بالشراكات بناءً على تحليل الملاءمة","يقدم قائمة مصنفة من فرص الشراكة","يحدد الاعتماديات والميزات الناقصة والقيود الأمنية"]},"keywords":{"en":["how to use sam","sam alternative","sam setup guide","what is sam","sam vs OpenPeople.ai","sam install","sam integration","AI-powered commerce infrastructure","retail brand API integration"],"zh":["AI驱动的商业基础设施","商业化路径识别","合作伙伴API整合","市场扫描","适应性分析","输出","依赖性标志","安全约束","零售品牌"],"ja":["AI駆動の商業インフラストラクチャ","商業化パス識別","パートナーAPI機会","マーケットスキャン","フィット分析","出力","依存関係のフラグ","セキュリティの制約","リテールブランド"],"ko":["AI 기반의 상업 인프라","상업화 경로 식별","파트너 API 기회","시장 스캔","적합성 분석","출력","의존성 플래그","보안 제약","리테일 브랜드"],"es":["agente de IA para comercio","infraestructura de comercio AI","oportunidades de API para retail","análisis de mercado para comercio","integración de API para comercio","comercio electrónico con IA","Herramientas de IA para comercio","Agentes de IA para comercio en línea"],"fr":["agent IA pour le commerce","infrastructure de commerce IA","opportunités d''API pour le détail","analyse de marché pour le commerce","intégration d''API pour le commerce","commerce électronique avec IA","Outils d''IA pour le commerce","Agents d''IA pour le commerce en ligne"],"de":["KI-Agent für den Handel","KI-basierte Commerce-Infrastruktur","API-Möglichkeiten für den Einzelhandel","Marktanalyse für den Handel","API-Integration für den Handel","E-Commerce mit KI","KI-Tools für den Handel","KI-Agents für den Online-Handel"],"pt":["infraestrutura de comércio AI","comércio eletrônico","API","parcerias","análise de mercado","varredura de mercado","recomendação de parcerias","infraestrutura de varejo","soluções de comércio"],"ru":["ИИ Агенты для коммерческой инфраструктуры","электронная коммерция","API","партнерства","анализ рынка","сканирование рынка","рекомендация партнерств","розничная инфраструктура","коммерческие решения"],"ar":["بنية تجارية مدعومة بالذكاء الاصطناعي","التجارة الإلكترونية","واجهة برمجة التطبيقات","الشراكات","تحليل السوق","فحص السوق","توصية بالشراكات","بنية بيع بالتجزئة","حلول تجارية"]}},"owner":"OpenPeopleStudio","repo":"open_people","repoPath":"OpenPeopleStudio/open_people","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.380Z","topics":[],"category":"community","skillMd":{"name":"sam","description":"Commercialization and platform partnership strategy for org run sam requests. Use when asked to evaluate APIs, integrations, pricing, or go-to-market opportunities.","bodyPreview":"# Sam\n\n## Overview\n\nIdentify commercialization paths and partner API opportunities that align with product direction.\n\n## Workflow\n\n### 1) Market scan\n\n- List adjacent platforms and APIs worth integrating.\n- Note typical pricing models and distribution channels.\n\n### 2) Fit analysis\n\n- Map opportunities to current repo capabilities and roadmap.\n- Flag dependencies, missing features, and security constraints.\n\n### 3) Output\n\n- Provide a ranked list of partner opportunities.\n- Recommend next steps","body":"# Sam\n\n## Overview\n\nIdentify commercialization paths and partner API opportunities that align with product direction.\n\n## Workflow\n\n### 1) Market scan\n\n- List adjacent platforms and APIs worth integrating.\n- Note typical pricing models and distribution channels.\n\n### 2) Fit analysis\n\n- Map opportunities to current repo capabilities and roadmap.\n- Flag dependencies, missing features, and security constraints.\n\n### 3) Output\n\n- Provide a ranked list of partner opportunities.\n- Recommend next steps, costs, and risks.\n"},"lastSynced":"2026-03-08T02:06:49.009Z","agentAnalysis":{"suitability":{"en":"Perfect for Retail Agents needing advanced market trend analysis and partner API opportunity identification.","zh":"非常适合需要高级市场趋势分析和合作伙伴API机会识别的零售代理。","ja":"リテールエージェントが高度な市場動向分析とパートナーAPIの機会識別を必要とする場合に最適です。","ko":"고급 시장 동향 분석 및 파트너 API 기회 식별이 필요한 소매 에이전트에게 적합합니다.","es":"Perfecto para agentes de venta al detalle que necesitan un análisis avanzado de tendencias del mercado y la identificación de oportunidades de API de socios.","fr":"Parfait pour les agents de détail ayant besoin d''une analyse avancée des tendances du marché et d''identification des opportunités d''API de partenariat.","de":"Perfekt für Einzelhandelsagenten, die eine fortschrittliche Markttrendanalyse und die Identifizierung von Partner-API-Möglichkeiten benötigen.","pt":"Perfeito para Agentes de Varejo que necessitam de análise avançada de tendências de mercado e identificação de oportunidades de API de parceiros.","ru":"Идеально подходит для розничных агентов, которым требуется продвинутый анализ рыночных тенденций и выявление возможностей партнерской API.","ar":"مثالي لعمليات وكيل التجزئة التي تحتاج إلى تحليل متقدم لاتجاهات السوق والفرص لتحديد واجهة برمجة التطبيقات للشركاء."},"recommendation":{"en":"Empowers agents to analyze market trends, identify commercialization paths, and provide ranked lists of partner opportunities using API integration and market scan capabilities, flagging dependencies and security constraints.","zh":"赋予代理分析市场趋势、识别商业化路径，并提供合作伙伴机会的排名列表，使用API集成和市场扫描功能，标记依赖关系和安全约束。","ja":"エージェントが市場動向を分析し、商業化パスを特定し、API統合および市場スキャン機能を使用してパートナーオプションのランク付けリストを提供し、依存関係およびセキュリティ制約をフラグ付けすることを可能にします。","ko":"에이전트가 시장 동향을 분석하고 상업화 경로를 식별하며 API 통합 및 시장 스캔 기능을 사용하여 파트너 옵션의 순위 목록을 제공하고 종속성 및 보안 제약을 플래그 지정할 수 있도록 합니다.","es":"Habilita a los agentes a analizar tendencias del mercado, identificar caminos de comercialización y proporcionar listas clasificadas de oportunidades de socios utilizando la integración de API y las capacidades de análisis de mercado, marcando las dependencias y las restricciones de seguridad.","fr":"Permet aux agents d''analyser les tendances du marché, d''identifier les parcours de commercialisation et de fournir des listes classées d''opportunités de partenariat en utilisant l''intégration d''API et les capacités d''analyse de marché, en signalant les dépendances et les contraintes de sécurité.","de":"Ermächtigt die Agenten, Markttrends zu analysieren, Vermarktungspfade zu identifizieren und rangierte Listen von Partnermöglichkeiten unter Verwendung von API-Integration und Marktsuchfunktionen bereitzustellen, wobei Abhängigkeiten und Sicherheitsbeschränkungen gekennzeichnet werden.","pt":"Permite que os agentes analisem tendências de mercado, identifiquem caminhos de comercialização e forneçam listas classificadas de oportunidades de parceiros usando integração de API e capacidades de digitalização de mercado, sinalizando dependências e restrições de segurança.","ru":"Наделяет агентов возможностью анализировать рыночные тенденции, выявлять пути коммерциализации и предоставлять ранжированные списки возможностей партнеров, используя интеграцию API и возможности сканирования рынка, флагируя зависимости и ограничения безопасности.","ar":"يمنح الوكلاء القدرة على تحليل اتجاهات السوق وتحديد مسارات للتوظيف التجاري وتقديم قوائم مصنفة لفرص الشراكة باستخدام دمج واجهة برمجة التطبيقات وقدرات مسح السوق ، مع العلم بالاعتماديات وقيود الأمان."},"useCases":{"en":["Identifying adjacent platforms for integration","Analyzing market trends for retail brands","Mapping partner opportunities to product roadmaps"],"zh":["识别用于集成的相邻平台","分析零售品牌的市场趋势","将合作伙伴机会映射到产品路线图"],"ja":["統合のために隣接プラットフォームを識別する","小売ブランドの市場動向を分析する","パートナーオプションを製品ロードマップにマッピングする"],"ko":["통합을 위한 인접 플랫폼 식별","소매 브랜드의 시장 동향 분석","제품 로드맵에 파트너 기회 매핑"],"es":["Identificar plataformas adyacentes para integración","Analizar tendencias del mercado para marcas de venta al detalle","Asignar oportunidades de socios a hojas de ruta de productos"],"fr":["Identifier les plateformes adjacentes pour l''intégration","Analyser les tendances du marché pour les marques de détail","Mapper les opportunités de partenariat aux feuilles de route de produits"],"de":["Angrenzende Plattformen für die Integration identifizieren","Markttrends für Einzelhandelsmarken analysieren","Partnermöglichkeiten Produkt-Roadmaps zuweisen"],"pt":["Identificar plataformas adjacentes para integração","Analisar tendências de mercado para marcas de varejo","Mapear oportunidades de parceiros para planos de produtos"],"ru":["Выявление смежных платформ для интеграции","Анализ рыночных тенденций для розничных брендов","Сопоставление возможностей партнеров с планами развития продукта"],"ar":["تحديد المنصات المجاورة للتكامل","تحليل اتجاهات السوق للعلامات التجارية للبيع بالتجزئة","ربط فرص الشراكة بخطط الطريق للمنتجات"]},"limitations":{"en":["Requires access to market trend data","Limited to retail brand analysis"],"zh":["需要访问市场趋势数据","仅限于零售品牌分析"],"ja":["市場動向データへのアクセスが必要","小売ブランド分析のみ"],"ko":["시장 동향 데이터에 대한 액세스가 필요","소매 브랜드 분석만 가능"],"es":["Requiere acceso a datos de tendencias del mercado","Limitado al análisis de marcas de venta al detalle"],"fr":["Nécessite un accès aux données de tendances du marché","Limité à l''analyse des marques de détail"],"de":["Benötigt Zugang zu Markttrend-Daten","Begrenzt auf die Analyse von Einzelhandelsmarken"],"pt":["Requer acesso a dados de tendências de mercado","Limitado à análise de marcas de varejo"],"ru":["Требует доступа к данным о рыночных тенденциях","Ограничен анализом розничных брендов"],"ar":["يتطلب الوصول إلى بيانات اتجاهات السوق","محدود بالتحليل العلامة التجارية للبيع بالتجزئة"]},"version":4},"contentHash":"c14b6aceb8159caabe12d5ed9360ab060d960fe3312db2a473ee5473608b20b5","qualityScore":26}');
