INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RefoundAI/lenny-skills/vibe-coding', 'vibe-coding', 'RefoundAI', 'lenny-skills', 'community', 'vibe-coding RefoundAI lenny-skills community Vibe-coding helps developers build software using AI tools and natural language, with insights from 3 product leaders. It assists in breaking down problems into smaller pieces for iterative AI prompts. Vibe Coding 是一种使用 AI 工具和自然语言开发软件的方法。它可以帮助用户快速原型开发和迭代 Vibe Coding は、AIエージェントと自然言語を使用してソフトウェアを開発する方法です。迅速なプロトタイピングとイテレーションを実現します Vibe Coding은 AI 도구와 자연어를 사용하여 소프트웨어를 개발하는 방법입니다. 빠른 프로토 타이핑과 반복을实现합니다 Vibe Coding es una técnica que ayuda a los desarrolladores a crear software utilizando herramientas de IA y lenguaje natural Vibe Coding est une technique qui aide les développeurs à créer des logiciels en utilisant des outils d''IA et le langage naturel Vibe Coding ist eine Technik, die Entwicklern hilft, Software mit KI-Tools und natürlicher Sprache zu erstellen O vibe coding é uma técnica de desenvolvimento de software que utiliza ferramentas de IA para criar soluções personalizadas Vibe Coding - это техника разработки программного обеспечения с помощью ИИ Агентов التشفير بالآلة هو تقنية لتطوير البرمجيات باستخدام أدوات الذكاء الاصطناعي how to use vibe-coding what is vibe-coding vibe-coding alternative vibe-coding vs traditional coding vibe-coding install vibe-coding setup guide vibe-coding for AI agents vibe-coding for software development vibe-coding best practices Vibe Coding AI 工具 自然语言开发 软件开发方法 快速原型开发 迭代开发 AI 提示 Helps users break down problems into smaller pieces for iterative AI prompts Guides the approach to software development using frameworks from 3 product leaders Sets expectations for what vibe-coding is good for, such as prototyping Assists in understanding the goal of the software development project Supports the development of prototypes, internal tools, and production apps Vibe-coding is a software development approach that leverages AI tools and natural language to build prototypes, internal tools, and production apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('acquia/nebula/canvas-component-definition', 'community', 'acquia', 'nebula', 'acquia/nebula', 'canvas-component-definition', 0, 0, 26, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:13.138Z', '4381dd0acfedcd11b84bb6775b757e68870371419d4565401b16461b1d1d9ce7', '{"id":"acquia/nebula/canvas-component-definition","name":"canvas-component-definition","description":{"en":"The canvas-component-definition skill helps developers create compatible Canvas components for Drupal Canvas, ensuring proper React implementation and metadata. It benefits developers working with Canvas components.","zh":"Canvas 组件定义是 React 实现、元数据和兼容性要求的组合","ja":"Canvas コンポーネント定義は React 実装、メタデータ、兼容性要件の組み合わせです","ko":"Canvas 컴포넌트 정의는 React 구현, 메타데이터, 호환성 요구 사항의 조합입니다","es":"La definición de un componente de Canvas implica una implementación de React, metadatos y una estructura de compatibilidad. Aprende a crear componentes compatibles con Drupal Canvas.","fr":"La définition d''un composant Canvas implique une mise en œuvre de React, des métadonnées et une structure de compatibilité. Découvrez comment créer des composants compatibles avec Drupal Canvas.","de":"Die Definition einer Canvas-Komponente umfasst eine React-Implementierung, Metadaten und eine Kompatibilitätsstruktur. Erfahren Sie, wie Sie kompatible Komponenten für Drupal Canvas erstellen.","pt":"O canvas-component-definition é um pacote que inclui implementação React, metadados Canvas e estrutura de pasta compatível","ru":"Canvas-component-definition - это пакет, включающий реализацию React, метаданные Canvas и совместимую структуру папок","ar":"مركب Canvas هو حزمة تحتوي على تنفيذ React وبيانات تعريف Canvas وهيكل مجلد متوافق"},"seo":{"title":{"en":"canvas-component-definition: Setup Guide for AI Agents | ...","zh":"Canvas 组件定义设置指南","ja":"Canvas コンポーネント定義のベストプラクティス","ko":"Canvas 컴포넌트 정의 