INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('acquia/nebula/canvas-component-definition', 'canvas-component-definition', 'acquia', 'nebula', 'community', 'canvas-component-definition acquia nebula community The canvas-component-definition skill helps developers create compatible Canvas components for Drupal Canvas, ensuring proper React implementation and metadata. It benefits developers working with Canvas components. Canvas 组件定义是 React 实现、元数据和兼容性要求的组合 Canvas コンポーネント定義は React 実装、メタデータ、兼容性要件の組み合わせです Canvas 컴포넌트 정의는 React 구현, 메타데이터, 호환성 요구 사항의 조합입니다 La definición de un componente de Canvas implica una implementación de React, metadatos y una estructura de compatibilidad. Aprende a crear componentes compatibles con Drupal Canvas. La définition d''un composant Canvas implique une mise en œuvre de React, des métadonnées et une structure de compatibilité. Découvrez comment créer des composants compatibles avec Drupal Canvas. Die Definition einer Canvas-Komponente umfasst eine React-Implementierung, Metadaten und eine Kompatibilitätsstruktur. Erfahren Sie, wie Sie kompatible Komponenten für Drupal Canvas erstellen. O canvas-component-definition é um pacote que inclui implementação React, metadados Canvas e estrutura de pasta compatível Canvas-component-definition - это пакет, включающий реализацию React, метаданные Canvas и совместимую структуру папок مركب Canvas هو حزمة تحتوي على تنفيذ React وبيانات تعريف Canvas وهيكل مجلد متوافق how to use canvas-component-definition what is canvas-component-definition canvas-component-definition setup guide canvas-component-definition install canvas-component-definition vs Drupal components canvas-component-definition alternative creating compatible Canvas components React implementation for Canvas Canvas metadata/schema best practices Canvas 组件定义 React 实现 元数据定义 兼容性要求 Drupal Canvas AIエージェント Canvas 组件设置 React 开发 元数据管理 Requires a React implementation via index.jsx Incorporates Canvas metadata/schema via component.yml Ensures naming and structure compatibility with machineName and folder path Supports Canvas-compatible props/slots modeling Mandates a specific folder structure at components-root/machine-name/ Enforces a minimum contract for usability in Drupal Canvas canvas-component-definition is a set of requirements for creating compatible Canvas components, including React implementation, metadata, and naming conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ymsjl/page-scaffold-builder/pro-components-guide', 'community', 'ymsjl', 'page-scaffold-builder', 'ymsjl/page-scaffold-builder', 'pro-components-guide', 0, 0, 26, '2026-03-08T01:57:15.418Z', '2026-03-08T02:07:21.567Z', 'c28398d8068f7dc70adfabad13d5fa4a4310b1ceed8f81fe707ff1813d2b9d64', '{"id":"ymsjl/page-scaffold-builder/pro-components-guide","name":"pro-components-guide","description":{"en":"The pro-components-guide skill provides documentation and guidance for Ant Design Pro components, helping developers build efficient backend pages. It benefits developers working with Ant Design Pro.","zh":"ProComponents Guide提供了Ant Design Pro组件的详细文档和使用指南，帮助您快速搭建后台页面","ja":"ProComponentsガイドは、Ant Design Proコンポーネントの詳細なドキュメントと使用方法を提供し、バックエンドページの構築を支援","ko":"ProComponents 가이드는 Ant Design Pro 컴포넌트의詳細한 문서와 사용법을 제공하여 백엔드 페이지 구축을 지원","es":"ProComponents es una guía para construir páginas de administración con Ant Design Pro. Incluye componentes como ProLayout, PageContainer y FooterToolbar","fr":"ProComponents est un guide pour construire des pages d''administration avec Ant Design Pro. Il comprend des composants tels que ProLayout, PageContainer et FooterToolbar","de":"ProComponents ist ein Leitfaden für den Bau von Administrationsseiten mit Ant Design Pro. Er umfasst Komponenten wie ProLayout, PageContainer und FooterToolbar","pt":"O ProComponents é uma biblioteca de componentes React para criar layouts personalizados. Aprenda a usá-lo com nosso guia.","ru":"ProComponents - это библиотека компонентов React для создания индивидуальных макетов. Узнайте, как им пользоваться с помощью нашего руководства.","ar":"مكونات Pro هي مكتبة مكونات ریکت لإنشاء تخطيطات مخصصة. تعلم كيفية استخدامها مع دليلنا"},"seo":{"title":{"en":"pro-components-guide: Setup Guide for Ant Design Pro | AI...","zh":"ProComponents Guide - Ant Design Pro 组件搭建后台页面最佳实践","ja":"ProComponents ガイド - AIエージェントによるAnt Design Pro コンポーネント構築","ko":"ProComponents 가이드 - Ant Design Pro 컴포넌트로 백엔드 페이지 구축하기","es":"Guía de Configuración de ProComponents","fr":"Guide de Mise en Route de ProComponents","de":"ProComponents Einrichtungsleitfaden","pt":"Guia de Configuração do ProComponents: Melhores Práticas","ru":"Руководство по настройке ProComponents: Лучшие практики д...","ar":"دليل إعداد مكونات Pro: إرشادات وتوجيهات لمنصة الفرونت إند"},"description":{"en":"Discover how to master Ant Design Pro components with our expert guide. Learn to build efficient backend pages and unlock pro-components-guide''s full potential.","zh":"了解ProComponents的核心组件，包括ProLayout、PageContainer、FooterToolbar等，快速搭建后台页面","ja":"ProComponentsのコアコンポーネントを紹介します。ProLayout、PageContainer、FooterToolbarなどを使用してバックエンドページを構築","ko":"ProComponents의 핵심 컴포넌트를 소개합니다. ProLayout, PageContainer, FooterToolbar 등을 사용하여 백엔드 페이지를 구축","es":"Descubre cómo configurar ProComponents para construir páginas de administración con Ant Design Pro. Consulta nuestra guía para obtener más información","fr":"Découvrez comment configurer ProComponents pour construire des pages d''administration avec Ant Design Pro. Consultez notre guide pour plus d''informations","de":"Erfahren Sie, wie Sie ProComponents für den Bau von Administrationsseiten mit Ant Design Pro konfigurieren. Lesen Sie unsere Anleitung für weitere Informationen","pt":"Aprenda a configurar o ProComponents com nosso guia passo a passo. Descubra como criar layouts personalizados e melhorar a experiência do usuário.","ru":"Узнайте, как настроить ProComponents с помощью нашего пошагового руководства. Откройте для себя, как создавать индивидуальные макеты и улучшать пользовательс...","ar":"تعلم كيفية تنظیم مكونات Pro مع دليلنا خطوة بخطوة. اكتشف كيفية إنشاء تخطيطات مخصصة وتحسين تجربة المستخدم"},"definition":{"en":"pro-components-guide is a comprehensive resource for Ant Design Pro components, offering documentation and guidance for building backend pages.","zh":"ProComponents是Ant Design Pro的组件库，提供了一系列的React组件用于搭建后台页面","ja":"ProComponentsは、Ant Design Proのコンポーネントライブラリであり、バックエンドページの構築に使用するReactコンポーネントを提供","ko":"ProComponents는 Ant Design Pro의 컴포넌트 라이브러리로서, 백엔드 페이지 구축에 사용되는 React 컴포넌트를 제공","es":"ProComponents es una guía de componentes para Ant Design Pro que ayuda a los desarrolladores a construir páginas de administración","fr":"ProComponents est un guide de composants pour Ant Design Pro qui aide les développeurs à construire des pages d''administration","de":"ProComponents ist ein Komponentenleitfaden für Ant Design Pro, der Entwicklern hilft, Administrationsseiten zu erstellen","pt":"ProComponents é uma biblioteca de componentes React para criar layouts personalizados e melhorar a experiência do usuário.","ru":"ProComponents - это библиотека компонентов React для создания индивидуальных макетов и улучшения пользовательского опыта.","ar":"مكونات Pro هي مكتبة مكونات ریکت لإنشاء تخطيطات مخصصة وتحسين تجربة المستخدم"},"features":{"en":["Utilizes ProLayout for global layout management","Employs PageContainer for standard page containers with automatic breadcrumb and title generation","Supports FooterToolbar for bottom-fixed toolbars","Provides detailed documentation for layout components via https://pro-components.antdigital.dev/components/layout","Includes guidelines for using the Browsing Tool to read URL parameters","Offers solutions for configuring Props, such as request return value formats and columns configurations"],"zh":["ProLayout: 解决侧边栏、顶部导航、面包屑等全局布局","PageContainer: 页面的标准容器，自动生成面包屑和标题","FooterToolbar: 底部固定工具栏","支持React和Ant Design Pro组件"],"ja":["ProLayout: サイドバー、トップナビゲーション、パンくずリストなどを含むグローバルレイアウト","PageContainer: 標準的なページコンテナー、自動的にパンくずリストとタイトルを生成","FooterToolbar: フッターの固定ツールバー","ReactとAnt Design Proコンポーネントをサポート"],"ko":["ProLayout: 사이드바, 상단 네비게이션, 빵屑 등 toàn局 레이아웃을 해결","PageContainer: 표준 페이지 컨테이너, 자동으로 빵屑과 제목을 생성","FooterToolbar: 푸터의 고정된 툴바","React와 Ant Design Pro 컴포넌트를 지원"],"es":["ProLayout para la gestión de la disposición de la página","PageContainer para la creación de contenedores de página estándar","FooterToolbar para la creación de barras de herramientas fijas","Compatibilidad con Ant Design Pro","Documentación detallada para cada componente"],"fr":["ProLayout pour la gestion de la disposition de la page","PageContainer pour la création de conteneurs de page standard","FooterToolbar pour la création de barres d''outils fixes","Compatibilité avec Ant Design Pro","Documentation détaillée pour chaque composant"],"de":["ProLayout für die Verwaltung der Seitenanordnung","PageContainer für die Erstellung von Standardseitencontainern","FooterToolbar für die Erstellung von festen Werkzeugleisten","Kompatibilität mit Ant Design Pro","Detaillierte Dokumentation für jeden Komponenten"],"pt":["ProLayout para criar layouts personalizados","PageContainer para criar contêineres de página padrão","FooterToolbar para criar toolbars fixas no rodapé","Suporte a breadcrumbs e títulos de página","Customização de layouts com props personalizados"],"ru":["ProLayout для создания индивидуальных макетов","PageContainer для создания стандартных контейнеров страниц","FooterToolbar для создания фиксированных панелей инструментов в подвале","Поддержка крошек и заголовков страниц","Настройка макетов с помощью пользовательских пропсов"],"ar":["ProLayout لإنشاء تخطيطات مخصصة","PageContainer لإنشاء حاويات صفحة قياسية","FooterToolbar لإنشاء أدوات مخصصة في التذييل","دعم الرابط والعناوين الصفحة","تخصيص التخطيطات باستخدام الخصائص المخصصة"]},"keywords":{"en":["how to use pro-components-guide","pro-components-guide documentation","Ant Design Pro components guide","pro-components-guide setup","pro-components-guide vs Ant Design","pro-components-guide install","pro-components-guide layout management","pro-components-guide PageContainer","pro-components-guide FooterToolbar"],"zh":["ProComponents","Ant Design Pro","React","后台页面搭建","组件库","ProLayout","PageContainer","FooterToolbar"],"ja":["ProComponents","Ant Design Pro","React","バックエンドページ構築","コンポーネントライブラリ","ProLayout","PageContainer","FooterToolbar","AIエージェント"],"ko":["ProComponents","Ant Design Pro","React","백엔드 페이지 구축","컴포넌트 라이브러리","ProLayout","PageContainer","FooterToolbar","AI 에이전트"],"es":["procomponents guía","ant design pro","componentes de página","disposición de página","contenedores de página","barras de herramientas fijas","documentación de componentes"],"fr":["procomponents guide","ant design pro","composants de page","disposition de page","conteneurs de page","barres d''outils fixes","documentation de composants"],"de":["procomponents anleitung","ant design pro","seitenkomponenten","seitenanordnung","seitencontainer","feste werkzeugleisten","komponentendokumentation"],"pt":["procomponents","react","layout","componentes react","desenvolvimento web","guias de configuração","melhores práticas","tutoriais de programação"],"ru":["procomponents","react","layout","компоненты react","разработка веб-приложений","руководства по настройке","лучшие практики","уроки по программированию","ИИ Агенты"],"ar":["مكونات برو","رياكت","التخطيط","مكونات رياكت","تطوير الويب","دلائل الإعداد","أفضل الممارسات","دروس البرمجة","منصات الفرونت إند"]}},"owner":"ymsjl","repo":"page-scaffold-builder","repoPath":"ymsjl/page-scaffold-builder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.418Z","topics":[],"category":"community","skillMd":{"name":"pro-components-guide","description":"包含 Ant Design Pro Components (ProComponents) 的组件列表、适用场景及官方文档链接。用于辅助代码生成和参数查询。","bodyPreview":"# ProComponents Guide & Documentation\n\n当用户询问 Ant Design Pro 组件、构建后台页面或需要查找具体组件参数时，请参考以下目录。\n**关键指令**：如果需要编写详细代码且不确定某个 Props（如 `request` 的返回值格式、`columns` 的具体配置），请使用浏览工具（Browsing Tool）读取对应的 URL。\n\n## 1. Layout 布局组件\n**核心组件**: `ProLayout`\n- **文档链接**: [https://pro-components.antdigital.dev/components/layout](https://pro-components.antdigital.dev/components/layout)\n- **包含**:\n    - `ProLayout`: 解决侧边栏、顶部导航、面包屑等全局布局。\n    - `PageContainer`: 页面的标准容器，自动生成面包屑和标题。\n    - `FooterToolbar`: 底部固定工具栏。\n    - `WaterMar","body":"# ProComponents Guide & Documentation\n\n当用户询问 Ant Design Pro 组件、构建后台页面或需要查找具体组件参数时，请参考以下目录。\n**关键指令**：如果需要编写详细代码且不确定某个 Props（如 `request` 的返回值格式、`columns` 的具体配置），请使用浏览工具（Browsing Tool）读取对应的 URL。\n\n## 1. Layout 布局组件\n**核心组件**: `ProLayout`\n- **文档链接**: [https://pro-components.antdigital.dev/components/layout](https://pro-components.antdigital.dev/components/layout)\n- **包含**:\n    - `ProLayout`: 解决侧边栏、顶部导航、面包屑等全局布局。\n    - `PageContainer`: 页面的标准容器，自动生成面包屑和标题。\n    - `FooterToolbar`: 底部固定工具栏。\n    - `WaterMark`: 水印组件。\n\n## 2. Table 表格与列表\n**核心组件**: `ProTable`\n- **ProTable (超级表格)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/table](https://pro-components.antdigital.dev/components/table)\n    - **用途**: 包含查询表单、工具栏、表格体的全功能表格，CRUD 标配。\n- **EditableProTable (可编辑表格)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/editable-table](https://pro-components.antdigital.dev/components/editable-table)\n    - **用途**: 行内编辑、实时保存。\n- **DragSortTable (拖拽排序)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/drag-sort-table](https://pro-components.antdigital.dev/components/drag-sort-table)\n- **ProList (高级列表)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/list](https://pro-components.antdigital.dev/components/list)\n    - **用途**: 卡片列表、文章列表，支持展开、选择。\n\n## 3. Form 表单组件\n**核心组件**: `ProForm`\n- **通用表单 (ProForm, ModalForm, DrawerForm, StepsForm)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/form](https://pro-components.antdigital.dev/components/form)\n    - **用途**:\n        - `ProForm`: 标准页面表单。\n        - `ModalForm`: 弹窗表单。\n        - `DrawerForm`: 抽屉表单。\n        - `StepsForm`: 分步表单。\n        - `LoginForm`: 登录页专用。\n- **SchemaForm (JSON配置表单)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/schema-form](https://pro-components.antdigital.dev/components/schema-form)\n- **QueryFilter (筛选表单)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/query-filter](https://pro-components.antdigital.dev/components/query-filter)\n\n## 4. Data Display 数据展示\n- **ProCard (高级卡片)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/card](https://pro-components.antdigital.dev/components/card)\n    - **用途**: 页面切分、分栏布局、栅格布局。\n- **ProDescriptions (定义列表)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/descriptions](https://pro-components.antdigital.dev/components/descriptions)\n    - **用途**: 详情页展示，支持 `columns` 定义。\n- **StatisticCard (指标卡)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/statistic-card](https://pro-components.antdigital.dev/components/statistic-card)\n\n## 5. Other 其他\n- **ProSkeleton (骨架屏)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/skeleton](https://pro-components.antdigital.dev/components/skeleton)\n- **ProField (原子组件)**:\n    - **文档链接**: [https://pro-components.antdigital.dev/components/field](https://pro-components.antdigital.dev/components/field)\n    - **用途**: 根据 valueType 渲染只读/编辑模式的原子组件。\n\n## 最佳实践提醒\n1. **Request 模式**: ProTable 和 ProForm 推荐使用 `request` 属性配合 `async` 函数来接管数据加载，而不是手动管理 loading 和 data state。详情请查阅 ProTable 文档中的 `request` 部分。\n2. **ValueType**: 善用 `valueType` (''money'', ''date'', ''select'' 等) 来自动格式化显示和表单项，减少手写 render 代码。"},"lastSynced":"2026-03-08T02:07:21.567Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing comprehensive Ant Design Pro component guidance.","zh":"非常适合需要全面Ant Design Pro组件指导的前端代理。","ja":"Ant Design Proコンポーネントの包括的なガイダンスが必要なフロントエンドエージェントに最適です。","ko":"전체적인 Ant Design Pro 구성 요소 가이드가 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan una guía integral de los componentes de Ant Design Pro.","fr":"Parfait pour les agents Frontend ayant besoin d''une guidance complète sur les composants Ant Design Pro.","de":"Perfekt für Frontend-Agents, die eine umfassende Anleitung zu den Ant Design Pro-Komponenten benötigen.","pt":"Perfeito para Agentes Frontend que precisam de orientação abrangente sobre componentes do Ant Design Pro.","ru":"Идеально подходит для агентов Frontend, которым требуется всестороннее руководство по компонентам Ant Design Pro.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إرشادات شاملة لمكونات Ant Design Pro."},"recommendation":{"en":"Empowers agents to efficiently build backend pages with Ant Design Pro components, utilizing ProLayout, PageContainer, and FooterToolbar, while referencing detailed documentation and parameter configurations for props like ''request'' and ''columns''.","zh":"使代理能够利用Ant Design Pro组件、ProLayout、PageContainer和FooterToolbar高效地构建后端页面，同时参考详细的文档和参数配置，如''请求''和''列''等属性。","ja":"エージェントがAnt Design Proコンポーネント、ProLayout、PageContainer、FooterToolbarを使用してバックエンドページを効率的に構築できるようにし、''request''や''columns''などのプロパティに関する詳細なドキュメントとパラメータ設定を参照できるようにします。","ko":"에이전트가 Ant Design Pro 구성 요소, ProLayout, PageContainer 및 FooterToolbar를 사용하여 백엔드 페이지를 효율적으로 빌드할 수 있도록 하며, ''요청'' 및 ''열''과 같은 속성에 대한 자세한 문서 및 매개 변수 구성에 액세스할 수 있습니다.","es":"Permite a los agentes construir páginas de backend de manera eficiente con componentes de Ant Design Pro, utilizando ProLayout, PageContainer y FooterToolbar, mientras se hacen referencia a la documentación detallada y configuraciones de parámetros para props como ''request'' y ''columns''.","fr":"Permet aux agents de construire des pages de backend de manière efficace avec des composants Ant Design Pro, en utilisant ProLayout, PageContainer et FooterToolbar, tout en référençant la documentation détaillée et les configurations de paramètres pour des props comme ''request'' et ''columns''.","de":"Ermöglicht es den Agenten, Backend-Seiten effizient mit Ant Design Pro-Komponenten zu erstellen, indem sie ProLayout, PageContainer und FooterToolbar verwenden, während sie auf detaillierte Dokumentation und Parameterkonfigurationen für Props wie ''request'' und ''columns'' verweisen.","pt":"Habilita os agentes a construir páginas de backend de forma eficiente com componentes do Ant Design Pro, utilizando ProLayout, PageContainer e FooterToolbar, enquanto se referem à documentação detalhada e configurações de parâmetros para props como ''request'' e ''columns''.","ru":"Наделяет агентов возможностью эффективно создавать страницы бэкэнда с помощью компонентов Ant Design Pro, используя ProLayout, PageContainer и FooterToolbar, а также ссылается на подробную документацию и конфигурации параметров для свойств, таких как ''request'' и ''columns''.","ar":"يمنح الوكلاء القدرة على بناء صفحات الخلفية بفعالية باستخدام مكونات Ant Design Pro، باستخدام ProLayout و PageContainer و FooterToolbar، مع الإشارة إلى الوثائق التفصيلية وتفاصيل параметر الخصائص مثل ''request'' و ''columns''."},"useCases":{"en":["Generating detailed code snippets for Ant Design Pro components","Configuring layout components like ProLayout and PageContainer","Debugging issues with component props and parameters"],"zh":["为Ant Design Pro组件生成详细的代码片段","配置布局组件，如ProLayout和PageContainer","调试组件属性和参数的问题"],"ja":["Ant Design Proコンポーネントの詳細なコードスニペットを生成する","ProLayoutやPageContainerなどのレイアウトコンポーネントを構成する","コンポーネントのプロパティやパラメータに関する問題をデバッグする"],"ko":["Ant Design Pro 구성 요소에 대한 자세한 코드 조각 생성","ProLayout 및 PageContainer와 같은 레이아웃 구성 요소 구성","구성 요소 속성 및 매개 변수 관련 문제 디버깅"],"es":["Generar fragmentos de código detallados para componentes de Ant Design Pro","Configurar componentes de diseño como ProLayout y PageContainer","Depurar problemas con props y parámetros de componentes"],"fr":["Générer des extraits de code détaillés pour les composants Ant Design Pro","Configurer des composants de disposition comme ProLayout et PageContainer","Déboguer les problèmes avec les props et les paramètres des composants"],"de":["Erstellen von detaillierten Code-Snippets für Ant Design Pro-Komponenten","Konfigurieren von Layout-Komponenten wie ProLayout und PageContainer","Fehlerbehebung bei Problemen mit Komponenten-Props und -Parametern"],"pt":["Gerar trechos de código detalhados para componentes do Ant Design Pro","Configurar componentes de layout como ProLayout e PageContainer","Depurar problemas com props e parâmetros de componentes"],"ru":["Генерировать подробные фрагменты кода для компонентов Ant Design Pro","Настраивать компоненты макета, такие как ProLayout и PageContainer","Отладить проблемы с свойствами и параметрами компонентов"],"ar":["генерировать شفرة مفصلة لمكونات Ant Design Pro","تكوين مكونات التصميم مثل ProLayout و PageContainer","تصحيح مشاكل مع الخصائص ومحددات المكونات"]},"limitations":{"en":["Requires knowledge of Ant Design Pro and its components","Limited to Ant Design Pro ecosystem","Needs access to ProComponents documentation and browsing tools"],"zh":["需要了解Ant Design Pro及其组件","仅限于Ant Design Pro生态系统","需要访问ProComponents文档和浏览工具"],"ja":["Ant Design Proとそのコンポーネントに関する知識が必要","Ant Design Proエコシステムに限定される","ProComponentsのドキュメントとブラウジングツールへのアクセスが必要"],"ko":["Ant Design Pro 및 해당 구성 요소에 대한 지식이 필요합니다.","Ant Design Pro 생태계에만 제한됩니다.","ProComponents 문서 및 브라우징 도구에 액세스해야 합니다."],"es":["Requiere conocimiento de Ant Design Pro y sus componentes","Limitado al ecosistema de Ant Design Pro","Necesita acceso a la documentación de ProComponents y herramientas de navegación"],"fr":["Nécessite une connaissance d''Ant Design Pro et de ses composants","Limité à l''écosystème Ant Design Pro","A besoin d''un accès à la documentation de ProComponents et d''outils de navigation"],"de":["Benötigt Kenntnisse von Ant Design Pro und seinen Komponenten","Begrenzt auf das Ant Design Pro-Ökosystem","Benötigt Zugriff auf die ProComponents-Dokumentation und Browser-Tools"],"pt":["Exige conhecimento do Ant Design Pro e seus componentes","Limitado ao ecossistema do Ant Design Pro","Necessita acesso à documentação do ProComponents e ferramentas de navegação"],"ru":["Требует знания Ant Design Pro и его компонентов","Ограничен экосистемой Ant Design Pro","Требует доступа к документации ProComponents и инструментам навигации"],"ar":["يتطلب معرفة Ant Design Pro ومكوناته","محدود بنطاق نظام Ant Design Pro","يتطلب الوصول إلى توثيق ProComponents وأدوات المتصفح"]},"version":4},"contentHash":"c28398d8068f7dc70adfabad13d5fa4a4310b1ceed8f81fe707ff1813d2b9d64","qualityScore":26}');
