INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ymsjl/page-scaffold-builder/pro-components-guide', 'pro-components-guide', 'ymsjl', 'page-scaffold-builder', 'community', 'pro-components-guide ymsjl page-scaffold-builder community The pro-components-guide skill provides documentation and guidance for Ant Design Pro components, helping developers build efficient backend pages. It benefits developers working with Ant Design Pro. ProComponents Guide提供了Ant Design Pro组件的详细文档和使用指南，帮助您快速搭建后台页面 ProComponentsガイドは、Ant Design Proコンポーネントの詳細なドキュメントと使用方法を提供し、バックエンドページの構築を支援 ProComponents 가이드는 Ant Design Pro 컴포넌트의詳細한 문서와 사용법을 제공하여 백엔드 페이지 구축을 지원 ProComponents es una guía para construir páginas de administración con Ant Design Pro. Incluye componentes como ProLayout, PageContainer y FooterToolbar ProComponents est un guide pour construire des pages d''administration avec Ant Design Pro. Il comprend des composants tels que ProLayout, PageContainer et FooterToolbar ProComponents ist ein Leitfaden für den Bau von Administrationsseiten mit Ant Design Pro. Er umfasst Komponenten wie ProLayout, PageContainer und FooterToolbar O ProComponents é uma biblioteca de componentes React para criar layouts personalizados. Aprenda a usá-lo com nosso guia. ProComponents - это библиотека компонентов React для создания индивидуальных макетов. Узнайте, как им пользоваться с помощью нашего руководства. مكونات Pro هي مكتبة مكونات ریکت لإنشاء تخطيطات مخصصة. تعلم كيفية استخدامها مع دليلنا how to use pro-components-guide pro-components-guide documentation Ant Design Pro components guide pro-components-guide setup pro-components-guide vs Ant Design pro-components-guide install pro-components-guide layout management pro-components-guide PageContainer pro-components-guide FooterToolbar ProComponents Ant Design Pro React 后台页面搭建 组件库 ProLayout PageContainer FooterToolbar Utilizes ProLayout for global layout management Employs PageContainer for standard page containers with automatic breadcrumb and title generation Supports FooterToolbar for bottom-fixed toolbars Provides detailed documentation for layout components via https://pro-components.antdigital.dev/components/layout Includes guidelines for using the Browsing Tool to read URL parameters Offers solutions for configuring Props, such as request return value formats and columns configurations pro-components-guide is a comprehensive resource for Ant Design Pro components, offering documentation and guidance for building backend pages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SBY7219/homepage/academic-homepage', 'community', 'SBY7219', 'homepage', 'SBY7219/homepage', 'academic-homepage', 0, 0, 26, '2026-03-08T01:57:15.419Z', '2026-03-08T02:07:22.124Z', '3dc46e2a029dfef5971d1a3dc4e3108f4265f85a90befdc69648ba99a1c1c9bd', '{"id":"SBY7219/homepage/academic-homepage","name":"academic-homepage","description":{"en":"The academic-homepage skill helps maintain an academic homepage with top navigation and research summary, benefiting researchers and academics. It provides a structured format for showcasing research and publications.","zh":"academic-homepage技能帮助您创建结构化的学术主页，包括顶部导航、研究摘要和关键链接","ja":"アカデミックホームページの構築を支援するacademic-homepageスキル。トップナビゲーション、研究サマリー、キーリンクなどを含みます","ko":"academic-homepage 스킬은 학술 홈페이지를 구조화된 형태로 생성하는 것을 도와줍니다. 상단 내비게이션, 연구 요약, 주요 링크 등이 포함됩니다","es":"La página académica es un componente crucial para los investigadores, con secciones como investigación, publicaciones y enseñanza. Utiliza herramientas de AI para mejorar su página.","fr":"La page académique est un composant essentiel pour les chercheurs, avec des sections comme recherche, publications et enseignement. Utilisez des outils d''IA pour améliorer votre page.","de":"Die akademische Homepage ist ein wichtiger Bestandteil für Forscher, mit Abschnitten wie Forschung, Veröffentlichungen und Lehre. Nutzen Sie AI-Tools, um Ihre Seite zu verbessern.","pt":"A página de início acadêmica é uma ferramenta essencial para pesquisadores e acadêmicos, fornecendo informações de navegação e resumo de pesquisa.","ru":"Страница академического дома является важнейшим инструментом для исследователей и академиков, предоставляя информацию о навигации и резюме исследований.","ar":"الصفحة الرئيسية الأكاديمية هي أداة أساسية للباحثين والأكاديميين، حيث توفر معلومات التنقل وملخص البحث."},"seo":{"title":{"en":"academic-homepage: Setup Guide for AI Agents","zh":"学术主页设置指南 - academic-homepage","ja":"アカデミックホームページの構築 - academic-homepage Setup Guide","ko":"학술 홈페이지 구축 가이드 - academic-homepage","es":"Configuración de Página Académica: Guía de Implementación","fr":"Mise en Place de Page Académique: Meilleures Pratiques","de":"Akademische Homepage Einrichten: Technischer Leitfaden","pt":"Guia de Configuração de Página de Início Acadêmica","ru":"Настройка Страницы Академического Дома ИИ Агентов","ar":"دليل إعداد الصفحة الرئيسية الأكاديمية للوكلاء الذكية"},"description":{"en":"Discover how to maintain an academic homepage with our AI agent skill, featuring top navigation and research summary. Learn more and get started today!","zh":"了解如何使用academic-homepage技能创建结构化的学术主页，包括顶部导航、研究摘要和关键链接","ja":"アカデミックホームページの構築方法について学びます。トップナビゲーション、研究サマリー、キーリンクなどを含みます","ko":"학술 홈페이지를 구조화된 형태로 생성하는 방법에 대해 알아보세요. 상단 내비게이션, 연구 요약, 주요 링크 등이 포함됩니다","es":"Aprende a configurar una página académica con enlaces clave, resumen de investigación y navegación superior con herramientas de AI como agente de página acad...","fr":"Découvrez comment mettre en place une page académique avec des liens clés, un résumé de recherche et une navigation supérieure avec des outils d''IA comme l''a...","de":"Erfahren Sie, wie Sie eine akademische Homepage mit Schlüssellinks, Forschungszusammenfassung und oberer Navigation mit AI-Tools wie dem akademischen Homepag...","pt":"Aprenda a configurar uma página de início acadêmica com informações de navegação, resumo de pesquisa e links importantes.","ru":"Узнайте, как настроить страницу академического дома с навигацией, резюме исследований и важными ссылками с помощью ИИ Агентов.","ar":"تعرف على كيفية إعداد صفحة رئيسية أكاديمية تحتوي على معلومات التنقل وملخص البحث والروابط المهمة للوكلاء الذكية."},"definition":{"en":"academic-homepage is a repository for maintaining an academic''s online presence, featuring information architecture and technical guidelines.","zh":"academic-homepage是一种帮助创建结构化学术主页的技能，包括顶部导航和研究摘要","ja":"アカデミックホームページは、トップナビゲーションや研究サマリーを含む構造化された学術ホームページを作成するためのスキルです","ko":"academic-homepage는 상단 내비게이션과 연구 요약을 포함한 구조화된 학술 홈페이지를 생성하는 스킬입니다","es":"Un agente de página académica es una herramienta de software que ayuda a crear y mantener una página web para académicos y investigadores","fr":"Un agent de page académique est un outil logiciel qui aide à créer et à maintenir un site web pour les universitaires et les chercheurs","de":"Ein akademischer Homepage-Agent ist ein Software-Tool, das dabei hilft, eine Webseite für Akademiker und Forscher zu erstellen und zu warten","pt":"Uma página de início acadêmica é uma página web que fornece informações sobre um pesquisador ou acadêmico, incluindo navegação e resumo de pesquisa.","ru":"Страница академического дома - это веб-страница, содержащая информацию об исследователе или академике, включая навигацию и резюме исследований.","ar":"الصفحة الرئيسية الأكاديمية هي صفحة ويب توفر معلومات عن باحث أو أكاديمي، بما في ذلك معلومات التنقل وملخص البحث."},"features":{"en":["Provides top navigation with Home, Research, Publications, Teaching, Notes, Blog, CV, and Contact sections","Displays a one-paragraph research summary on the Home section","Includes a compact list of key links such as email, CV, GitHub, and Google Scholar","Supports a visible placeholder for a profile photo","Follows specific technical guidelines for information architecture"],"zh":["顶部导航：Home、Research、Publications、Teaching、Notes、Blog、CV、Contact","研究摘要和关键链接","支持个人资料照片","结构化的信息架构"],"ja":["トップナビゲーション：Home、Research、Publications、Teaching、Notes、Blog、CV、Contact","研究サマリーとキーリンク","プロフィール写真のサポート","構造化された情報アーキテクチャ"],"ko":["상단 내비게이션：Home、Research、Publications、Teaching、Notes、Blog、CV、Contact","연구 요약과 주요 링크","개인 프로필 사진 지원","구조화된 정보 아키텍처"],"es":["Navegación superior con enlaces a secciones como investigación y publicaciones","Resumen de investigación en el área de inicio","Lista compacta de enlaces clave como correo electrónico y perfil de GitHub","Soporte para foto de perfil del investigador","Estructura de información con secciones como enseñanza y notas"],"fr":["Navigation supérieure avec des liens vers des sections comme recherche et publications","Résumé de recherche dans la zone d''accueil","Liste compacte de liens clés comme courriel et profil GitHub","Prise en charge de la photo de profil du chercheur","Structure d''information avec des sections comme enseignement et notes"],"de":["Oberere Navigation mit Links zu Abschnitten wie Forschung und Veröffentlichungen","Forschungszusammenfassung im Startbereich","Kompakte Liste von Schlüssellinks wie E-Mail und GitHub-Profil","Unterstützung für das Profilfoto des Forschers","Informationsstruktur mit Abschnitten wie Lehre und Notizen"],"pt":["Navegação superior com links para Home, Pesquisa, Publicações, Ensino, Notas, Blog, CV e Contato","Resumo de pesquisa de um parágrafo","Lista compacta de links importantes, incluindo e-mail, CV, GitHub e Google Scholar","Espaço para foto de perfil","Estrutura de informação personalizada"],"ru":["Верхняя навигация с ссылками на Home, Research, Публикации, Обучение, Notes, Блог, CV и Контакт","Резюме исследований в одном абзаце","Компактный список важных ссылок, включая электронную почту, CV, GitHub и Google Scholar","Место для фотографии профиля","Настраиваемая структура информации"],"ar":["تنقل 상위 مع روابط إلى الصفحة الرئيسية، البحث، المنشورات، التدريس، الملاحظات، المدونة، السيرة الذاتية، والاتصال","ملخص البحث في فقرة واحدة","قائمة مدمجة من الروابط المهمة، بما في ذلك البريد الإلكتروني، السيرة الذاتية، جيثب، وجوجل سكولار","مساحة للصورة الشخصية","هيكل معلومات قابل للتعديل"]},"keywords":{"en":["how to use academic-homepage","academic-homepage setup guide","what is academic-homepage","academic-homepage alternative","academic-homepage vs website builders","academic-homepage install","maintaining an academic homepage","academic homepage design","research summary template"],"zh":["学术主页","academic-homepage","结构化信息","研究摘要","顶部导航","AI工具","学术网站建设"],"ja":["アカデミックホームページ","academic-homepage","構造化情報","研究サマリー","トップナビゲーション","AIエージェント","学術ウェブサイト構築"],"ko":["학술 홈페이지","academic-homepage","구조화된 정보","연구 요약","상단 내비게이션","AI 툴","학술 웹사이트 구축"],"es":["agente de página académica","herramientas de AI para académicos","creación de página web para investigadores","diseño de página académica","desarrollo web para universitarios","tecnologías web para investigación","pagina academica con react","pagina academica con python"],"fr":["agent de page académique","outils d''IA pour universitaires","création de site web pour chercheurs","conception de page académique","développement web pour universitaires","technologies web pour recherche","page academique avec react","page academique avec python"],"de":["akademischer Homepage-Agent","AI-Tools für Akademiker","Erstellung von Websites für Forscher","Design von akademischer Homepage","Webentwicklung für Universitäten","Webtechnologien für Forschung","akademische Homepage mit react","akademische Homepage mit python"],"pt":["página de início acadêmica","configuração de página de início","navegação superior","resumo de pesquisa","links importantes","foto de perfil","estrutura de informação","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["страница академического дома","настройка страницы академического дома","верхняя навигация","резюме исследований","важные ссылки","фотография профиля","структура информации","веб-разработка","инструменты разработки","ИИ Агенты"],"ar":["الصفحة الرئيسية الأكاديمية","إعداد الصفحة الرئيسية الأكاديمية","تنقل 상위","ملخص البحث","الروابط المهمة","الصورة الشخصية","هيكل المعلومات","تطوير الويب","أدوات التطوير","الوكلاء الذكية"]}},"owner":"SBY7219","repo":"homepage","repoPath":"SBY7219/homepage","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.419Z","topics":[],"category":"community","skillMd":{"name":"academic-homepage","description":"Design and maintain a minimal academic personal website using only static HTML and CSS, organizing notes and a static blog.","bodyPreview":"You are helping maintain my academic homepage in this repository.\n\nFollow these guidelines:\n\n1. Information architecture\n   - Provide top navigation with: Home, Research, Publications, Teaching, Notes, Blog, CV, Contact.\n   - The Home section should show:\n     - Name, current position and affiliation.\n     - One-paragraph research summary.\n     - A compact list of key links (email, CV, GitHub, Google Scholar if available).\n     - A visible placeholder for my profile photo (e.g., `/img/profile.jp","body":"You are helping maintain my academic homepage in this repository.\n\nFollow these guidelines:\n\n1. Information architecture\n   - Provide top navigation with: Home, Research, Publications, Teaching, Notes, Blog, CV, Contact.\n   - The Home section should show:\n     - Name, current position and affiliation.\n     - One-paragraph research summary.\n     - A compact list of key links (email, CV, GitHub, Google Scholar if available).\n     - A visible placeholder for my profile photo (e.g., `/img/profile.jpg` with good alt text).\n   - Research / Publications / Teaching can start as simple static pages, but they should have clear headings and room for future content.\n   - The Notes section should organize existing `*.html` notes (e.g., `calculus.html`, `linear_algebra.html`, `logic.html`) into themed groups like:\n     - Mathematics\n     - Programming languages and type theory\n     - Category theory and logic\n     - Miscellaneous\n     Use whatever structure you can infer from filenames and titles.\n\n2. Visual style\n   - Minimal light theme: white or very light background, dark text, and a single accent color used sparingly.\n   - Use a system font stack for body text (e.g., `-apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif`).\n   - Use consistent spacing scale (e.g., 1rem / 1.5rem / 2rem) for margins and paddings.\n   - Make the layout responsive:\n     - On mobile: stacked layout, navigation collapses into a vertical list.\n     - On larger screens: a centered content column with max width around 800–900px.\n\n3. Implementation rules\n   - Keep everything as static HTML + CSS. No build tools, no bundlers, no JS frameworks.\n   - Prefer semantic HTML5 tags. Use descriptive class names in CSS.\n   - Reuse the existing `styles.css` file; refactor or simplify it as needed.\n   - Keep fonts in the existing `fonts/` directory and only load fonts that are actually used.\n\n4. Notes and blog\n   - Treat `*.html` files whose names look like course or topic notes (for example `calculus.html`, `linear_algebra.html`, `logic.html`, `sicm.html`) as study notes.\n   - Create a `notes.html` (or similar) index page that groups and links to these notes.\n   - Create a `blog.html` index page for future static posts:\n     - Initially, you can add 1–2 sample posts as placeholders with title, date, and short summary.\n     - Link individual posts as separate HTML files under a `blog/` directory.\n\n5. Safety and cleanup\n   - Before deleting or moving any file, propose a cleanup plan:\n     - Category A: essential site assets (index, styles, fonts, key pages).\n     - Category B: intermediate or source files (for example Racket `.rkt` files under `source/`).\n     - Category C: clearly unused or obsolete files, if any.\n   - Ask for explicit confirmation before removing or moving Category B/C files.\n   - Always summarize changes and show high-level `git diff` summaries.\n"},"lastSynced":"2026-03-08T02:07:22.124Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Assistant Agents requiring structured academic content management and HTML formatting capabilities.","zh":"适用于需要结构化学术内容管理和HTML格式化功能的研究助理代理。","ja":"構造化された学術的コンテンツ管理とHTMLフォーマット機能を必要とする研究アシスタントエージェントに適しています。","ko":"구조화된 학술 콘텐츠 관리 및 HTML 형식 지정 기능이 필요한 연구 보조 에이전트에 적합합니다.","es":"Ideal para Agentes de Asistentes de Investigación que requieren una gestión de contenido académico estructurado y capacidades de formato HTML.","fr":"Idéal pour les agents d''assistants de recherche nécessitant une gestion de contenu académique structurée et des capacités de mise en forme HTML.","de":"Ideal für Forschungsassistenten-Agenten, die eine strukturierte akademische Inhaltsverwaltung und HTML-Formatierungsfähigkeiten erfordern.","pt":"Ideal para Agentes de Assistente de Pesquisa que requerem gerenciamento de conteúdo acadêmico estruturado e capacidades de formatação HTML.","ru":"Идеально для агентов-ассистентов исследований, требующих структурированного управления академическим контентом и возможностей форматирования HTML.","ar":"مثالي لعميل مساعد البحث الذي يتطلب إدارة المحتوى الأكاديمي المجزأ وقدرات التنسيق HTML."},"recommendation":{"en":"Empowers agents to create and manage comprehensive academic homepages with top navigation, research summaries, and publication lists using HTML and CSS, while also providing a structured format for showcasing research and publications in a compact and visible manner.","zh":"能够赋予代理创建和管理综合学术主页的能力，包括顶部导航、研究摘要和出版物列表，使用HTML和CSS，同时也提供一种结构化的格式来展示研究和出版物，以紧凑且可见的方式。","ja":"エージェントが、HTMLとCSSを使用して、包括的な学術的ホームページを作成、管理できるようにし、トップナビゲーション、研究サマリー、出版物リストを提供するとともに、研究と出版物をコンパクトで可視的な方法で展示するための構造化されたフォーマットを提供します。","ko":"에이전트가 HTML과 CSS를 사용하여 포괄적인 학술 홈페이지를 생성하고 관리할 수 있도록 하며, 상단 내비게이션, 연구 요약 및 출판물 목록을 제공함으로써 연구 및 출판물을紧凑하고 가시적인 방법으로展示할 수 있는 구조화된 형식을 제공합니다.","es":"Habilita a los agentes a crear y gestionar páginas de inicio académicas completas con navegación superior, resúmenes de investigación y listas de publicaciones utilizando HTML y CSS, mientras también proporciona un formato estructurado para mostrar la investigación y las publicaciones de manera compacta y visible.","fr":"Permet aux agents de créer et de gérer des pages d''accueil académiques complètes avec une navigation supérieure, des résumés de recherche et des listes de publications en utilisant HTML et CSS, tout en fournissant un format structuré pour présenter la recherche et les publications de manière compacte et visible.","de":"Ermächtigt Agenten, umfassende akademische Startseiten mit oberer Navigation, Forschungszusammenfassungen und Publikationslisten mit HTML und CSS zu erstellen und zu verwalten, während auch ein strukturierter Format für die Darstellung von Forschung und Publikationen in kompakter und sichtbarer Weise bereitgestellt wird.","pt":"Habilita os agentes a criar e gerenciar páginas iniciais acadêmicas abrangentes com navegação superior, resumos de pesquisa e listas de publicações usando HTML e CSS, além de fornecer um formato estruturado para exibir pesquisas e publicações de forma compacta e visível.","ru":"Наделяет агентов возможностью создавать и управлять всесторонними академическими домашними страницами с верхней навигацией, резюме исследований и списками публикаций, используя HTML и CSS, а также обеспечивает структурированный формат для демонстрации исследований и публикаций в компактной и наглядной форме.","ar":"يمكن العميل من إنشاء وإدارة صفحات رئيسية أكاديمية شاملة مع التنقل العلوي والملخصات البحثية وقوائم المنشورات باستخدام HTML و CSS، بالإضافة إلى توفير تنسيق منظم لعرض الأبحاث والمنشورات بطريقة مضغوطة ومرئية."},"useCases":{"en":["Generating researcher profiles with key links and profile photos","Organizing research summaries and publication lists","Creating structured academic homepages with top navigation and research highlights"],"zh":["生成研究人员个人资料，包括关键链接和个人照片","组织研究摘要和出版物列表","创建具有顶部导航和研究亮点的结构化学术主页"],"ja":["研究者のプロフィールを生成し、重要なリンクとプロフィール写真を含む","研究サマリーと出版物リストを整理する","トップナビゲーションと研究のハイライトを備えた構造化された学術的ホームページを作成する"],"ko":["연구자 프로필을 생성하여 주요 링크와 프로필 사진을 포함하는 것","연구 요약 및 출판물 목록을 조직화하는 것","상단 내비게이션 및 연구 하이라이트가 포함된 구조화된 학술 홈페이지를 생성하는 것"],"es":["Generar perfiles de investigadores con enlaces clave y fotos de perfil","Organizar resúmenes de investigación y listas de publicaciones","Crear páginas de inicio académicas estructuradas con navegación superior y destacados de investigación"],"fr":["Générer des profils de chercheurs avec des liens clés et des photos de profil","Organiser des résumés de recherche et des listes de publications","Créer des pages d''accueil académiques structurées avec une navigation supérieure et des faits saillants de recherche"],"de":["Forscherprofile mit Schlüssellinks und Profilfotos generieren","Forschungszusammenfassungen und Publikationslisten organisieren","Strukturierte akademische Startseiten mit oberer Navigation und Forschungshighlights erstellen"],"pt":["Geração de perfis de pesquisadores com links-chave e fotos de perfil","Organização de resumos de pesquisa e listas de publicações","Criação de páginas iniciais acadêmicas estruturadas com navegação superior e destaques de pesquisa"],"ru":["Генерация профилей исследователей с ключевыми ссылками и фотографиями профиля","Организация резюме исследований и списков публикаций","Создание структурированных академических домашних страниц с верхней навигацией и резюме исследований"],"ar":["إنشاء ملفات تعريف للباحثين مع روابط رئيسية وصور الملفات الشخصية","تنظيم ملخصات البحث وقوائم المنشورات","إنشاء صفحات رئيسية أكاديمية مجزأة مع التنقل العلوي والتسجيلات البحثية"]},"limitations":{"en":["Requires HTML and CSS knowledge for customization","Limited to academic homepage use cases"],"zh":["需要HTML和CSS知识来进行自定义","仅限于学术主页的使用场景"],"ja":["カスタマイズするためにHTMLとCSSの知識が必要","学術的ホームページの使用シナリオに限定される"],"ko":["사용자 정의를 위해 HTML 및 CSS 지식이 필요함","학술 홈페이지 사용 사례에만 제한됨"],"es":["Requiere conocimiento de HTML y CSS para la personalización","Limitado a casos de uso de páginas de inicio académicas"],"fr":["Nécessite des connaissances en HTML et CSS pour la personnalisation","Limité aux cas d''utilisation des pages d''accueil académiques"],"de":["Benötigt HTML- und CSS-Kenntnisse für die Anpassung","Begrenzt auf Einsatzfälle für akademische Startseiten"],"pt":["Exige conhecimento de HTML e CSS para personalização","Limitado a casos de uso de páginas iniciais acadêmicas"],"ru":["Требует знания HTML и CSS для настройки","Ограничен до случаев использования академических домашних страниц"],"ar":["يتطلب معرفة HTML و CSS للتعديل","محدود لاستخدامات صفحات رئيسية أكاديمية"]},"version":4},"contentHash":"3dc46e2a029dfef5971d1a3dc4e3108f4265f85a90befdc69648ba99a1c1c9bd","qualityScore":26}');
