INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SBY7219/homepage/academic-homepage', 'academic-homepage', 'SBY7219', 'homepage', 'community', 'academic-homepage SBY7219 homepage community The academic-homepage skill helps maintain an academic homepage with top navigation and research summary, benefiting researchers and academics. It provides a structured format for showcasing research and publications. academic-homepage技能帮助您创建结构化的学术主页，包括顶部导航、研究摘要和关键链接 アカデミックホームページの構築を支援するacademic-homepageスキル。トップナビゲーション、研究サマリー、キーリンクなどを含みます academic-homepage 스킬은 학술 홈페이지를 구조화된 형태로 생성하는 것을 도와줍니다. 상단 내비게이션, 연구 요약, 주요 링크 등이 포함됩니다 La página académica es un componente crucial para los investigadores, con secciones como investigación, publicaciones y enseñanza. Utiliza herramientas de AI para mejorar su página. La page académique est un composant essentiel pour les chercheurs, avec des sections comme recherche, publications et enseignement. Utilisez des outils d''IA pour améliorer votre page. Die akademische Homepage ist ein wichtiger Bestandteil für Forscher, mit Abschnitten wie Forschung, Veröffentlichungen und Lehre. Nutzen Sie AI-Tools, um Ihre Seite zu verbessern. A página de início acadêmica é uma ferramenta essencial para pesquisadores e acadêmicos, fornecendo informações de navegação e resumo de pesquisa. Страница академического дома является важнейшим инструментом для исследователей и академиков, предоставляя информацию о навигации и резюме исследований. الصفحة الرئيسية الأكاديمية هي أداة أساسية للباحثين والأكاديميين، حيث توفر معلومات التنقل وملخص البحث. how to use academic-homepage academic-homepage setup guide what is academic-homepage academic-homepage alternative academic-homepage vs website builders academic-homepage install maintaining an academic homepage academic homepage design research summary template 学术主页 academic-homepage 结构化信息 研究摘要 顶部导航 AI工具 学术网站建设 Provides top navigation with Home, Research, Publications, Teaching, Notes, Blog, CV, and Contact sections Displays a one-paragraph research summary on the Home section Includes a compact list of key links such as email, CV, GitHub, and Google Scholar Supports a visible placeholder for a profile photo Follows specific technical guidelines for information architecture academic-homepage is a repository for maintaining an academic''s online presence, featuring information architecture and technical guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shoma-endo/GrowMate/server-actions-and-routes', 'community', 'shoma-endo', 'GrowMate', 'shoma-endo/GrowMate', 'server-actions-and-routes', 0, 0, 26, '2026-03-08T01:57:15.434Z', '2026-03-08T02:07:35.390Z', '8381985216e07fec7fb9bb900d87080624f8ccf25f7bd953db95f248aaf746c6', '{"id":"shoma-endo/GrowMate/server-actions-and-routes","name":"server-actions-and-routes","description":{"en":"Server-actions-and-routes ensures consistency, security, and development efficiency in Next.js server-side communication. It provides a set of rules for using Server Actions and Route Handlers effectively.","zh":"Server Actions 与 Routes 是 Next.js 服务器端通信的技术规约，确保一致性、安全性和开发效率","ja":"Server Actions & Routes は Next.js のサーバーサイド通信のためのルールで、一貫性、セキュリティ、開発効率を担保する","ko":"서버 액션 및 라우트는 Next.js 서버 측 통신의 기술 규약으로 일관성, 보안, 개발 효율을 제공합니다","es":"Server Actions y Rutas es una técnica para garantizar la coherencia, la seguridad y la eficiencia del desarrollo en Next.js, utilizando Server Actions como primera opción y Route Handlers para casos especiales","fr":"Les Actions Serveur et les Routes sont une technique pour garantir la cohérence, la sécurité et l''efficacité du développement dans Next.js, en utilisant les Actions Serveur comme première option et les Route Handlers pour les cas particuliers","de":"Server-Aktionen und -Routes sind eine Technik, um die Konsistenz, die Sicherheit und die Entwicklungseffizienz in Next.js zu gewährleisten, indem Server-Aktionen als erste Option und Route-Handler für spezielle Fälle verwendet werden","pt":"Server actions e rotas com Next.js visam garantir a consistência, segurança e eficiência de desenvolvimento. Aprenda a configurá-los corretamente","ru":"Server actions и маршруты с Next.js обеспечивают согласованность, безопасность и эффективность разработки. Узнайте, как их настроить","ar":"إجراءات الخادم وتوجيهه