INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shoma-endo/GrowMate/server-actions-and-routes', 'server-actions-and-routes', 'shoma-endo', 'GrowMate', 'community', 'server-actions-and-routes shoma-endo GrowMate community Server-actions-and-routes ensures consistency, security, and development efficiency in Next.js server-side communication. It provides a set of rules for using Server Actions and Route Handlers effectively. Server Actions 与 Routes 是 Next.js 服务器端通信的技术规约，确保一致性、安全性和开发效率 Server Actions & Routes は Next.js のサーバーサイド通信のためのルールで、一貫性、セキュリティ、開発効率を担保する 서버 액션 및 라우트는 Next.js 서버 측 통신의 기술 규약으로 일관성, 보안, 개발 효율을 제공합니다 Server Actions y Rutas es una técnica para garantizar la coherencia, la seguridad y la eficiencia del desarrollo en Next.js, utilizando Server Actions como primera opción y Route Handlers para casos especiales Les Actions Serveur et les Routes sont une technique pour garantir la cohérence, la sécurité et l''efficacité du développement dans Next.js, en utilisant les Actions Serveur comme première option et les Route Handlers pour les cas particuliers Server-Aktionen und -Routes sind eine Technik, um die Konsistenz, die Sicherheit und die Entwicklungseffizienz in Next.js zu gewährleisten, indem Server-Aktionen als erste Option und Route-Handler für spezielle Fälle verwendet werden Server actions e rotas com Next.js visam garantir a consistência, segurança e eficiência de desenvolvimento. Aprenda a configurá-los corretamente Server actions и маршруты с Next.js обеспечивают согласованность, безопасность и эффективность разработки. Узнайте, как их настроить إجراءات الخادم وتوجيهها مع Next.js تهدف إلى ضمان الاتساق والأمان وكفاءة التطوير. تعرف على كيفية إعدادها بشكل صحيح how to use server-actions-and-routes server-actions-and-routes setup guide next.js server-side communication server-actions-and-routes vs route handlers server-actions-and-routes install what is server-actions-and-routes server-actions-and-routes best practices next.js server-actions-and-routes tutorial server-actions-and-routes alternative Server Actions Routes Next.js 服务器端通信 一致性 安全性 开发效率 CRUD 操作 Route Handlers Uses Server Actions as the primary choice for CRUD operations and form handling Employs Route Handlers for special cases, ensuring flexibility and customization Follows a set of rules for communication, including configuration paths and naming conventions Supports Next.js server-side rendering for improved performance and SEO Provides a standardized approach to server-side development, reducing errors and inconsistencies Server-actions-and-routes is a technical specification for Next.js server-side communication, outlining rules for using Server Actions and Route Handlers to ensure consistency, security, and development efficiency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lumaui/luma-ui/angular', 'community', 'lumaui', 'luma-ui', 'lumaui/luma-ui', 'angular', 0, 0, 26, '2026-03-08T01:57:15.444Z', '2026-03-08T02:08:53.116Z', '451062f565be9b6568f1d3563f866f16cfd03895fedaf90e1abd5873ee113262', '{"id":"lumaui/luma-ui/angular","name":"angular","description":{"en":"The Angular skill provides expert guidance on modern design systems, benefiting developers who want to optimize their Angular projects with best practices.","zh":"Angular是一种现代设计系统，提供了TypeScript和Angular的最佳实践指南","ja":"Angularはモダンなデザインシステムで、TypeScriptとAngularのベストプラクティスを提供します","ko":"Angular는 현대적인 디자인 시스템으로 TypeScript와 Angular의 베스트 프랙티스를 제공합니다","es":"Angular es un sistema de diseño moderno que utiliza TypeScript y señales para la gestión de estado","fr":"Angular est un système de conception moderne qui utilise TypeScript et des signaux pour la gestion d''état","de":"Angular ist ein modernes Designsystem, das TypeScript und Signale für die Zustandsverwaltung verwendet","pt":"O Angular é um framework de design moderno que permite criar aplicações web robustas e escaláveis","ru":"Angular - это современный фреймворк дизайна, который позволяет создавать прочные и масштабируемые веб-приложения","ar":"Angular هو إطار تصميم حديث يسمح بإنشاء تطبيقات ويب قوية وقابلة للتوسيع"},"seo":{"title":{"en":"Angular: Best Practices Setup Guide | AI Agent Skill","zh":"Angular最佳实践指南","ja":"Angularセットアップガイド - AIエージェント","ko":"Angular 개발 가이드 - AI Tools","es":"Guía de configuración de Angular","fr":"Guide de mise en route d''Angular","de":"Angular Einrichtungsleitfaden","pt":"Guia de Configuração do Angular: Melhores Práticas","ru":"Настройка Angular: Лучшие практики для ИИ Агентов","ar":"دليل إعداد Angular: أفضل الممارسات لآلات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient Angular development with expert-approved best practices - learn how to optimize your workflow and improve code quality today!","zh":"了解Angular的最佳实践，包括TypeScript和Angular特有的技巧，以提高开发效率","ja":"Angularのセットアップとベストプラクティスを学び、開発効率を向上させる - AIエージェント","ko":"Angular 개발을 위한 베스트 프랙티스와 기술적인 요약을 알아보세요 - AI Tools","es":"Aprende a utilizar las mejores prácticas de Angular para crear aplicaciones escalables y mantenibles con TypeScript y señales","fr":"Découvrez comment utiliser les meilleures pratiques d''Angular pour créer des applications évolutives et maintenables avec TypeScript et des signaux","de":"Erfahren Sie, wie Sie die besten Praktiken von Angular verwenden, um skalierbare und wartbare Anwendungen mit TypeScript und Signalen zu erstellen","pt":"Aprenda as melhores práticas para trabalhar com Angular, incluindo tipos strictos e gerenciamento de estado com sinais","ru":"Узнайте лучшие практики для работы с Angular, включая строгую типизацию и управление состоянием с помощью сигналов","ar":"تعرف على أفضل الممارسات للعمل مع Angular، بما في ذلك أنواع صارمة وإدارة الحالة باستخدام الإشارات"},"definition":{"en":"Angular is a modern design system that utilizes TypeScript and standalone components for efficient development.","zh":"Angular是一种JavaScript框架，用于构建复杂的Web应用程序","ja":"AngularはJavaScriptフレームワークで、複雑なWebアプリケーションを構築するために使用されます","ko":"Angular는 JavaScript 프레임워크로 복잡한 Web 애플리케이션을 구축하는 데 사용됩니다","es":"Angular es un framework de JavaScript para crear aplicaciones web con un enfoque en la reutilización de componentes","fr":"Angular est un framework JavaScript pour créer des applications web avec un focus sur la réutilisation de composants","de":"Angular ist ein JavaScript-Framework zur Erstellung von Webanwendungen mit Fokus auf die Wiederverwendung von Komponenten","pt":"O Angular é um framework de JavaScript para criar aplicações web","ru":"Angular - это фреймворк JavaScript для создания веб-приложений","ar":"Angular هو إطار عمل JavaScript لإنشاء تطبيقات ويب"},"features":{"en":["Enforces strict type checking with TypeScript","Utilizes standalone components over NgModules","Implements signals for state management","Supports lazy loading for feature routes","Avoids the use of `any` type and `@HostBinding` decorators"],"zh":["使用严格的类型检查","优先使用类型推断","避免使用any类型","使用独立组件","实现懒加载"],"ja":["厳密な型チェックを使用","型推論を優先","any型の使用を避ける","スタンドアロンコンポーネントを使用","レイジーローディングを実装"],"ko":["严格한 타입 체크 사용","타입 추론을 우선","any 타입의 사용을避ける","독립 컴포넌트를 사용","레이지 로딩을 구현"],"es":["Uso de comprobación de tipos estricta con TypeScript","Preferencia de la inferencia de tipo cuando el tipo es obvio","Uso de señales para la gestión de estado","Implementación de carga diferida para rutas de características","Uso de componentes autónomos en lugar de NgModules"],"fr":["Utilisation de la vérification de type stricte avec TypeScript","Préférence pour l''inférence de type lorsque le type est évident","Utilisation de signaux pour la gestion d''état","Mise en œuvre du chargement différé pour les routes de fonctionnalités","Utilisation de composants autonomes au lieu de NgModules"],"de":["Verwendung von strenger Typüberprüfung mit TypeScript","Bevorzugung der Typinferenz, wenn der Typ offensichtlich ist","Verwendung von Signalen für die Zustandsverwaltung","Implementierung der verzögerten Ladung für Funktionsrouten","Verwendung von eigenständigen Komponenten anstelle von NgModules"],"pt":["Uso de tipos strictos","Preferência por inferência de tipo quando o tipo é óbvio","Uso de sinais para gerenciamento de estado","Implementação de carregamento lento para rotas de recurso","Uso de componentes autônomos em vez de NgModules"],"ru":["Использование строгой типизации","Предпочтение выводу типа, когда тип очевиден","Использование сигналов для управления состоянием","Реализация ленивой загрузки для маршрутов функций","Использование самостоятельных компонентов вместо NgModules"],"ar":["استخدام أنواع صارمة","تفضيل استنتاج النوع عندما يكون النوع واضحًا","استخدام الإشارات لإدارة الحالة","تنفيذ التحميل الكسول لطرق الميزة","استخدام مكونات مستقلة بدلاً من NgModules"]},"keywords":{"en":["how to use angular","angular best practices","angular vs react","angular setup guide","angular install","typescript angular tutorial","angular standalone components","angular state management"],"zh":["Angular","TypeScript","最佳实践","JavaScript框架","Web开发","Angular开发","TypeScript开发"],"ja":["Angular","TypeScript","ベストプラクティス","JavaScriptフレームワーク","Web開発","Angular開発","TypeScript開発","AIエージェント"],"ko":["Angular","TypeScript","베스트 프랙티스","JavaScript 프레임워크","Web 개발","Angular 개발","TypeScript 개발","AI Tools"],"es":["angular","typescript","señales","gestión de estado","componentes autónomos","carga diferida","ngmodules","mejores prácticas de angular","desarrollo de aplicaciones web con angular"],"fr":["angular","typescript","signaux","gestion d''état","composants autonomes","chargement différé","ngmodules","meilleures pratiques d''angular","développement d''applications web avec angular"],"de":["angular","typescript","signale","zustandsverwaltung","eigenständige komponenten","verzögerte ladung","ngmodules","beste praktiken von angular","entwicklung von webanwendungen mit angular"],"pt":["angular","typescript","melhores práticas","gerenciamento de estado","carregamento lento","componentes autônomos","NgModules","desenvolvimento web","frameworks javascript"],"ru":["angular","typescript","лучшие практики","управление состоянием","ленивая загрузка","самостоятельные компоненты","NgModules","разработка веб-приложений","фреймворки javascript","ИИ Агенты"],"ar":["angular","typescript","أفضل الممارسات","إدارة الحالة","التحميل الكسول","مكونات مستقلة","NgModules","تطوير تطبيقات الويب","إطارات عمل جافاسكريبت","آلات الذكاء الاصطناعي"]}},"owner":"lumaui","repo":"luma-ui","repoPath":"lumaui/luma-ui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.444Z","topics":[],"category":"community","skillMd":{"name":"angular","description":"You are an expert in TypeScript, Angular, and scalable web application development. You write functional, maintainable, performant, and accessible code following Angular and TypeScript best practices.","bodyPreview":"## TypeScript Best Practices\n\n- Use strict type checking\n- Prefer type inference when the type is obvious\n- Avoid the `any` type; use `unknown` when type is uncertain\n\n## Angular Best Practices\n\n- Always use standalone components over NgModules\n- Must NOT set `standalone: true` inside Angular decorators. It''s the default in Angular v20+.\n- Use signals for state management\n- Implement lazy loading for feature routes\n- Do NOT use the `@HostBinding` and `@HostListener` decorators. Put host bindings","body":"## TypeScript Best Practices\n\n- Use strict type checking\n- Prefer type inference when the type is obvious\n- Avoid the `any` type; use `unknown` when type is uncertain\n\n## Angular Best Practices\n\n- Always use standalone components over NgModules\n- Must NOT set `standalone: true` inside Angular decorators. It''s the default in Angular v20+.\n- Use signals for state management\n- Implement lazy loading for feature routes\n- Do NOT use the `@HostBinding` and `@HostListener` decorators. Put host bindings inside the `host` object of the `@Component` or `@Directive` decorator instead\n- Use `NgOptimizedImage` for all static images.\n  - `NgOptimizedImage` does not work for inline base64 images.\n\n## Accessibility Requirements\n\n- It MUST pass all AXE checks.\n- It MUST follow all WCAG AA minimums, including focus management, color contrast, and ARIA attributes.\n\n### Components\n\n- Keep components small and focused on a single responsibility\n- Use `input()` and `output()` functions instead of decorators\n- Use `computed()` for derived state\n- Set `changeDetection: ChangeDetectionStrategy.OnPush` in `@Component` decorator\n- Prefer inline templates for small components\n- Prefer Reactive forms instead of Template-driven ones\n- Do NOT use `ngClass`, use `class` bindings instead\n- Do NOT use `ngStyle`, use `style` bindings instead\n- When using external templates/styles, use paths relative to the component TS file.\n\n## State Management\n\n- Use signals for local component state\n- Use `computed()` for derived state\n- Keep state transformations pure and predictable\n- Do NOT use `mutate` on signals, use `update` or `set` instead\n\n## Templates\n\n- Keep templates simple and avoid complex logic\n- Use native control flow (`@if`, `@for`, `@switch`) instead of `*ngIf`, `*ngFor`, `*ngSwitch`\n- Use the async pipe to handle observables\n- Do not assume globals like (`new Date()`) are available.\n- Do not write arrow functions in templates (they are not supported).\n\n## Services\n\n- Design services around a single responsibility\n- Use the `providedIn: ''root''` option for singleton services\n- Use the `inject()` function instead of constructor injection\n"},"lastSynced":"2026-03-08T02:08:53.116Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents seeking expertise in modern Angular development with best practices in TypeScript and state management","zh":"适合前端代理寻求现代Angular开发专业知识并遵循TypeScript和状态管理最佳实践的代理","ja":"フロントエンドエージェントがモダンなAngular開発の専門知識を求め、TypeScriptと状態管理のベストプラクティスに従うことに適したエージェント","ko":"프론트엔드 에이전트가现代적인 Angular 개발 전문성을 탐색하고 TypeScript 및 상태 관리의 모범 사례를 준수하는 에이전트에게 적합","es":"Ideal para Agentes de Frontend que buscan experiencia en desarrollo de Angular moderno con las mejores prácticas en TypeScript y gestión de estado","fr":"Idéal pour les agents Frontend qui recherchent une expertise en développement Angular moderne avec les meilleures pratiques en TypeScript et gestion d''état","de":"Ideal für Frontend-Agenten, die Expertenwissen im modernen Angular-Entwicklung mit Best Practices in TypeScript und Statusverwaltung suchen","pt":"Ideal para Agentes Frontend que buscam especialização no desenvolvimento moderno do Angular com as melhores práticas em TypeScript e gerenciamento de estado","ru":"Идеально для Фронтенд-агентов, стремящихся к освоению современного развития Angular с лучшими практиками в TypeScript и управлении состоянием","ar":"مثالي للوكلاء الأماميين الذين يبحثون عن الخبرة في تطوير Angular الحديث مع أفضل الممارسات في TypeScript وإدارة الحالة"},"recommendation":{"en":"Empowers agents to build scalable Angular applications using standalone components, signals for state management, and lazy loading for feature routes, while adhering to TypeScript best practices such as strict type checking and avoiding the `any` type","zh":"使代理能够使用独立组件、信号进行状态管理和功能路由的懒加载构建可扩展的Angular应用，同时遵循TypeScript的最佳实践，如严格的类型检查和避免使用`any`类型","ja":"エージェントが独立コンポーネント、状態管理のためのシグナル、そして機能ルートのための遅延ロードを使用してスケーラブルなAngularアプリケーションを構築できるようにし、厳密な型チェックや`any`型の使用を避けるなどのTypeScriptのベストプラクティスに従う","ko":"에이전트가 독립 구성 요소, 상태 관리를 위한 신호 및 기능 경로의 지연 로드를 사용하여 확장 가능한 Angular 애플리케이션을 구축할 수 있도록 하며, 엄격한 형식 확인 및 `any` 형식의 사용을 피하는 등 TypeScript의 모범 사례를 따름","es":"Permite a los agentes crear aplicaciones Angular escalables utilizando componentes independientes, señales para la gestión de estado y carga diferida para rutas de características, mientras se adhieren a las mejores prácticas de TypeScript como la comprobación de tipo estricta y la evitación del tipo `any`","fr":"Permet aux agents de créer des applications Angular évolutives en utilisant des composants autonomes, des signaux pour la gestion d''état et un chargement différé pour les routes de fonctionnalités, tout en respectant les meilleures pratiques de TypeScript telles que la vérification de type stricte et l''évitement du type `any`","de":"Ermöglicht es Agenten, skalierbare Angular-Anwendungen zu erstellen, die autarke Komponenten, Signale für die Statusverwaltung und Lazy Loading für Funktionsrouten verwenden, während sie sich an die Best Practices von TypeScript halten, wie strenges Typüberprüfen und Vermeidung des `any`-Typs","pt":"Habilita os agentes a construir aplicações Angular escaláveis usando componentes autônomos, sinais para gerenciamento de estado e carregamento lento para rotas de recursos, enquanto adere às melhores práticas do TypeScript, como verificação de tipo estrita e evitando o tipo `any`","ru":"Наделяет агентов возможностью создавать масштабируемые приложения Angular, используя автономные компоненты, сигналы для управления состоянием и ленивую загрузку для маршрутов функций, при этом придерживаясь лучших практик TypeScript, таких как строгая проверка типов и избегание типа `any`","ar":"تمكّن الوكلاء من بناء تطبيقات Angular قابلة للتحجيم باستخدام المكونات المستقلة والإشارات لإدارة الحالة والتحميل الكسول لطرق الميزات، مع الالتزام بأفضل الممارسات في TypeScript مثل التحقق الصارم من النوع وتجنب نوع `any`"},"useCases":{"en":["Implementing standalone components for improved modularity","Optimizing application performance with lazy loading for feature routes","Managing state effectively using signals in Angular applications"],"zh":["实现独立组件以提高模块性","使用功能路由的懒加载优化应用程序性能","使用Angular应用程序中的信号有效管理状态"],"ja":["モジュール性の向上のためのスタンドアロンコンポーネントの実装","機能ルートの遅延ロードを使用したアプリケーション性能の最適化","Angularアプリケーションにおけるシグナルの使用による状態の効果的な管理"],"ko":["독립 구성 요소를 구현하여 모듈성을 개선","기능 경로의 지연 로드를 사용하여 애플리케이션 성능을 최적화","Angular 애플리케이션에서 신호를 사용하여 상태를 효율적으로 관리"],"es":["Implementar componentes independientes para una mayor modularidad","Optimizar el rendimiento de la aplicación con carga diferida para rutas de características","Gestionar el estado de forma efectiva utilizando señales en aplicaciones Angular"],"fr":["Mettre en œuvre des composants autonomes pour une meilleure modularité","Optimiser les performances de l''application avec un chargement différé pour les routes de fonctionnalités","Gérer efficacement l''état en utilisant des signaux dans les applications Angular"],"de":["Autarke Komponenten implementieren, um eine verbesserte Modularität zu erreichen","Die Anwendungsleistung mit Lazy Loading für Funktionsrouten optimieren","Den Status effektiv mithilfe von Signalen in Angular-Anwendungen verwalten"],"pt":["Implementação de componentes autônomos para modularidade aprimorada","Otimização do desempenho da aplicação com carregamento lento para rotas de recursos","Gerenciamento eficaz do estado usando sinais em aplicações Angular"],"ru":["Реализация автономных компонентов для улучшения модульности","Оптимизация производительности приложения с ленивой загрузкой для маршрутов функций","Эффективное управление состоянием с помощью сигналов в приложениях Angular"],"ar":["تنفيذ المكونات المستقلة لتحسين الوحدات","تحسين أداء التطبيق مع التحميل الكسول لطرق الميزات","إدارة الحالة بشكل فعال باستخدام الإشارات في تطبيقات Angular"]},"limitations":{"en":["Requires Angular version 20 or higher for default standalone components","Avoids the use of `@HostBinding` and `@HostListener` decorators"],"zh":["需要Angular版本20或更高才能使用默认的独立组件","避免使用`@HostBinding`和`@HostListener`修饰符"],"ja":["デフォルトのスタンドアロンコンポーネントを使用するにはAngularバージョン20以上が必要","`@HostBinding`と`@HostListener`デコレータの使用を避ける"],"ko":["기본 독립 구성 요소를 사용하려면 Angular 버전 20 이상이 필요","`@HostBinding` 및 `@HostListener` 데코레이터의 사용을 피함"],"es":["Requiere la versión 20 o superior de Angular para componentes independientes por defecto","Evita el uso de decoradores `@HostBinding` y `@HostListener`"],"fr":["Nécessite la version 20 ou supérieure d''Angular pour les composants autonomes par défaut","Évite l''utilisation des décorateurs `@HostBinding` et `@HostListener`"],"de":["Benötigt Angular-Version 20 oder höher für standardmäßige autarke Komponenten","Vermeidet die Verwendung von `@HostBinding`- und `@HostListener`-Decoratoren"],"pt":["Exige a versão 20 ou superior do Angular para componentes autônomos padrão","Evita o uso de decoradores `@HostBinding` e `@HostListener`"],"ru":["Требует версии 20 или выше Angular для автономных компонентов по умолчанию","Избегает использования декораторов `@HostBinding` и `@HostListener`"],"ar":["يتطلب الإصدار 20 أو الأعلى من Angular للمكونات المستقلة افتراضيًا","يتجنب استخدام المزينين `@HostBinding` و `@HostListener`"]},"version":4},"contentHash":"451062f565be9b6568f1d3563f866f16cfd03895fedaf90e1abd5873ee113262","qualityScore":26}');
