INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lumaui/luma-ui/angular', 'angular', 'lumaui', 'luma-ui', 'community', 'angular lumaui luma-ui community The Angular skill provides expert guidance on modern design systems, benefiting developers who want to optimize their Angular projects with best practices. Angular是一种现代设计系统，提供了TypeScript和Angular的最佳实践指南 Angularはモダンなデザインシステムで、TypeScriptとAngularのベストプラクティスを提供します Angular는 현대적인 디자인 시스템으로 TypeScript와 Angular의 베스트 프랙티스를 제공합니다 Angular es un sistema de diseño moderno que utiliza TypeScript y señales para la gestión de estado Angular est un système de conception moderne qui utilise TypeScript et des signaux pour la gestion d''état Angular ist ein modernes Designsystem, das TypeScript und Signale für die Zustandsverwaltung verwendet O Angular é um framework de design moderno que permite criar aplicações web robustas e escaláveis Angular - это современный фреймворк дизайна, который позволяет создавать прочные и масштабируемые веб-приложения Angular هو إطار تصميم حديث يسمح بإنشاء تطبيقات ويب قوية وقابلة للتوسيع how to use angular angular best practices angular vs react angular setup guide angular install typescript angular tutorial angular standalone components angular state management Angular TypeScript 最佳实践 JavaScript框架 Web开发 Angular开发 TypeScript开发 Enforces strict type checking with TypeScript Utilizes standalone components over NgModules Implements signals for state management Supports lazy loading for feature routes Avoids the use of `any` type and `@HostBinding` decorators Angular is a modern design system that utilizes TypeScript and standalone components for efficient development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('youdotcom-oss/dx-toolkit/code-documentation', 'community', 'youdotcom-oss', 'dx-toolkit', 'youdotcom-oss/dx-toolkit', 'code-documentation', 0, 0, 26, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:01.113Z', '2fdcd79c975f7f75a29a2be45761f31b917b99ae2a8d265093c7b76ff6a3e538', '{"id":"youdotcom-oss/dx-toolkit/code-documentation","name":"code-documentation","description":{"en":"The code-documentation skill provides TSDoc format templates and guidelines for developers to create comprehensive API documentation. It helps developers write, edit, and review TSDoc comments for functions, types, and modules.","zh":"代码文档工具提供TSDoc格式模板、类型文档指南和维护工作流程，帮助开发者提高代码质量","ja":"コード文書化スキルは、TSDoc形式のテンプレート、タイプドキュメントのガイドライン、およびメンテナンスワークフローを提供し、開発者のコード品質を向上させます","ko":"코드 문서화 도구는 TSDoc 형식의 템플릿, 유형 문서 가이드라인 및 유지 관리 워크플로우를 제공하여 개발자의 코드 품질을 향상합니다","es":"Un skill de IA Agents que proporciona plantillas TSDoc, directrices para documentación de tipos y flujos de mantenimiento. Automatiza la documentación de APIs y la sincronización con cambios en el código para funciones y módulos.","fr":"Un skill AI Agents fournissant des modèles TSDoc, des directives pour la documentation des types et des workflows de maintenance. Automatise la documentation d''API et la synchronisation avec les changements de code.","de":"Ein AI Agents Skill, der TSDoc-Vorlagen, Richtlinien für Typendokumentation und Maintenance-Workflows bereitstellt. Automatisiert die API-Dokumentation und Synchronisation mit Code-Änderungen für Funktionen und Module.","pt":"O skill de documentação de código fornece modelos de formato TSDoc, diretrizes de documentação de tipo e fluxos de trabalho de manutenção.","ru":"Навык документации кода предоставляет шаблоны формата TSDoc, руководства по документации типов и рабочие процессы обслуживания.","ar":"مهارة توثيق الشفرة توفر قوالب تنسيق TSDoc وإرشادات توثيق النوع وعمليات الصيانة."},"seo":{"title":{"en":"Code-Documentation: TSDoc Template Setup Guide | AI Agent...","zh":"代码文档工具：AI辅助开发指南","ja":"コード文書化スキル：AIエージェントを活用した開発ワークフロー","ko":"코드 문서화 도구: AI 기반 개발workflow 통합","es":"code-documentation: Guía para Documentación TSDoc y API","fr":"code-documentation : Guide des bonnes pratiques TSDoc","de":"code-documentation: TSDoc-Dokumentation für KI Agenten Setup","pt":"Guia de Configuração de Documentação de Código com Ferram...","ru":"Настройка документации кода с помощью ИИ Агентов","ar":"دليل إعداد توثيق الشفرة مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to integrate You.com''s AI capabilities into your workflow with code-documentation. Learn how to write high-quality TSDoc comments and sync them ...","zh":"使用代码文档工具，轻松集成You.com的AI能力，提高开发效率","ja":"コード文書化スキルを使って、You.comのAI機能を開発ワークフローに統合し、開発効率を向上させましょう","ko":"코드 문서화 도구를 사용하여 You.com의 AI 기능을 개발 워크플로에 통합하고 개발 효율성을 향상하세요","es":"Herramienta de IA para generar y mantener documentación TSDoc. Automatiza la creación de comentarios para funciones y tipos, sincroniza cambios y limpia come...","fr":"Outil IA pour générer et maintenir la documentation TSDoc. Automatise les commentaires pour fonctions et types, synchronise les changements et nettoie les co...","de":"KI-Tool für TSDoc-Dokumentation. Automatisiert Kommentare für Funktionen und komplexe Typen, synchronisiert Änderungen und bereinigt non-compliant comments. ...","pt":"Aprenda a integrar a documentação de código no seu fluxo de trabalho com o kit de ferramentas de código aberto da You.com","ru":"Узнайте, как интегрировать документацию кода в свой рабочий процесс с помощью открытого набора инструментов You.com","ar":"تعرف على كيفية دمج توثيق الشفرة في تدفق العمل الخاص بك باستخدام أدوات الكود المفتوح من You.com"},"definition":{"en":"Code-documentation is an open-source toolkit for integrating AI capabilities into workflows, providing TSDoc format templates and maintenance workflows for high-quality documentation.","zh":"代码文档工具是一种开源工具包，用于集成AI能力，提供TSDoc格式模板和类型文档指南","ja":"コード文書化スキルは、AIエージェントを統合するためのオープンソースツールキットであり、TSDoc形式のテンプレートとタイプドキュメントのガイドラインを提供します","ko":"코드 문서화 도구는 AI 기능을 통합하는 오픈 소스 도구 키트로, TSDoc 형식의 템플릿과 유형 문서 가이드라인을 제공합니다","es":"Code Documentation es un skill de código abierto para AI Agents que permite a los desarrolladores integrar capacidades de IA en sus flujos de trabajo. Proporciona plantillas TSDoc, guías para documentar tipos y workflows para mantener la documentación sincronizada con el código.","fr":"Code Documentation est un skill open source pour AI Agents permettant aux développeurs d''intégrer l''IA dans leurs workflows. Il fournit des modèles TSDoc, des guides pour documenter les types et des processus pour maintenir la documentation synchronisée.","de":"Code Documentation ist ein Open-Source-Skill für KI Agenten, der Entwicklern ermöglicht, KI-Fähigkeiten in Workflows zu integrieren. Er stellt TSDoc-Vorlagen, Richtlinien für Typendokumentation und Workflows zur Synchronisation mit Code bereit.","pt":"A documentação de código é uma ferramenta de IA que fornece modelos e diretrizes para documentar código de forma eficaz.","ru":"Документация кода - это инструмент ИИ, который предоставляет шаблоны и руководства для эффективной документации кода.","ar":"توثيق الشفرة هو أداة ذكاء اصطناعي توفر قوالب وإرشادات لتوثيق الشفرة بفعالية."},"features":{"en":["Provides TSDoc format templates for functions, types, and modules","Offers type documentation guidelines for complex type structures","Supports synchronization of TSDoc comments with code changes","Enables removal of non-compliant comments, such as performance notes and timestamps","Facilitates creation of comprehensive API documentation","Includes maintenance workflows for reviewing documentation quality"],"zh":["提供TSDoc格式模板","类型文档指南","维护工作流程","支持API文档创建","复杂类型结构文档","代码更改同步"],"ja":["TSDoc形式のテンプレートを提供","タイプドキュメントのガイドライン","メンテナンスワークフロー","APIドキュメントの作成をサポート","複雑なタイプ構造のドキュメント","コード変更の同期"],"ko":["TSDoc 형식의 템플릿 제공","유형 문서 가이드라인","유지 관리 워크플로우","API 문서 생성 지원","복잡한 유형 구조 문서","코드 변경 동기화"],"es":["Plantillas predefinidas para comentarios TSDoc en funciones y módulos","Directrices para documentar estructuras de tipos complejas","Workflows de mantenimiento para sincronizar TSDoc con cambios en el código","Limpieza automática de comentarios no conformes (notas de rendimiento, timestamps)","Eliminación de comentarios huérfanos y desincronizados","Herramientas para revision de calidad de documentación"],"fr":["Modèles prédéfinis pour les commentaires TSDoc sur les fonctions et modules","Directives pour documenter les structures de types complexes","Workflows de maintenance pour synchroniser TSDoc avec les changements de code","Nettoyage automatique des commentaires non conformes (notes de performance, horodatages)","Suppression des commentaires orphelins et désynchronisés","Outils pour l''analyse de la qualité de la documentation"],"de":["Vordefinierte Vorlagen für TSDoc-Kommentare in Funktionen und Modulen","Richtlinien zur Dokumentation komplexer Typstrukturen","Maintenance-Workflows zur Synchronisation von TSDoc mit Code-Änderungen","Automatische Bereinigung von non-compliant comments (Performance Notes, Timestamps)","Entfernung von verwaisten und out-of-sync Kommentaren","Werkzeuge für das Review der Dokumentationsqualität"],"pt":["Modelos de formato TSDoc para documentação de código","Diretrizes de documentação de tipo para melhorar a qualidade do código","Fluxos de trabalho de manutenção para garantir a consistência da documentação","Suporte à criação de documentação de API abrangente","Capacidade de limpar comentários não conformes e synchronizar a documentação com as alterações no código"],"ru":["Шаблоны формата TSDoc для документации кода","Руководства по документации типов для улучшения качества кода","Рабочие процессы обслуживания для обеспечения согласованности документации","Поддержка создания всесторонней документации API","Возможность очистки нестандартных комментариев и синхронизации документации с изменениями в коде"],"ar":["قوالب تنسيق TSDoc لتوثيق الشفرة","إرشادات توثيق النوع لتحسين جودة الشفرة","عمليات الصيانة لضمان الاتساق في التوثيق","دعم إنشاء توثيق واجهة برمجة التطبيقات الشامل","قدرة على تنظيف التعليقات غير المتوافقة وتنظيم التوثيق مع التغييرات في الشفرة"]},"keywords":{"en":["how to use code-documentation","what is code-documentation","code-documentation alternative","code-documentation vs JSDoc","code-documentation install","code-documentation setup guide","TSDoc template generation","API documentation best practices","code-documentation for AI agents"],"zh":["代码文档工具","AI辅助开发","TSDoc","类型文档","API文档","代码质量","开发效率","You.com AI"],"ja":["コード文書化スキル","AIエージェント","TSDoc","タイプドキュメント","APIドキュメント","コード品質","開発効率","You.com AI"],"ko":["코드 문서화 도구","AI 기반 개발","TSDoc","유형 문서","API 문서","코드 품질","개발 효율성","You.com AI"],"es":["documentación TSDoc","plantillas comentarios typescript","automatizar documentación api","sincronizar documentación código","limpiar comentarios typescript","IA Agents herramientas desarrollo","documentar tipos complejos","workflows mantenimiento docs"],"fr":["documentation TSDoc","modèles commentaires typescript","automatiser documentation api","synchroniser documentation code","nettoyer commentaires typescript","outils AI Agents développement","documenter types complexes","workflows maintenance docs"],"de":["TSDoc Dokumentation","TypeScript Kommentar Vorlagen","API Dokumentation automatisieren","Dokumentation Code synchronisieren","TypeScript Kommentare bereinigen","KI Agenten Developer Tools","komplexe Typen dokumentieren","Maintenance Workflows Docs"],"pt":["documentação de código","ferramentas de IA","kit de ferramentas de código aberto","TSDoc","documentação de tipo","fluxos de trabalho de manutenção","criação de documentação de API","limpeza de comentários não conformes"],"ru":["документация кода","инструменты ИИ","открытый набор инструментов","TSDoc","документация типов","рабочие процессы обслуживания","создание документации API","очистка нестандартных комментариев"],"ar":["توثيق الشفرة","أدوات الذكاء الاصطناعي","أدوات الكود المفتوح","TSDoc","توثيق النوع","عمليات الصيانة","إنشاء توثيق واجهة برمجة التطبيقات","تنظيف التعليقات غير المتوافقة"]}},"owner":"youdotcom-oss","repo":"dx-toolkit","repoPath":"youdotcom-oss/dx-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"code-documentation","description":"TSDoc standards for TypeScript/JavaScript code. Automatically invoked when writing, reviewing, or editing any TSDoc comments, code documentation, or API documentation. (project)","bodyPreview":"# Code Documentation Skill\n\n## Purpose\n\nThis skill provides TSDoc format templates, type documentation guidelines, and maintenance workflows. Use this when:\n- Writing or editing TSDoc comments for any function, type, or module\n- Reviewing documentation quality\n- Creating comprehensive API documentation\n- Documenting complex type structures\n- Cleaning up non-compliant comments (performance notes, timestamps, inline explanations)\n- Synchronizing out-of-sync TSDoc with code changes\n- Removing orpha","body":"# Code Documentation Skill\n\n## Purpose\n\nThis skill provides TSDoc format templates, type documentation guidelines, and maintenance workflows. Use this when:\n- Writing or editing TSDoc comments for any function, type, or module\n- Reviewing documentation quality\n- Creating comprehensive API documentation\n- Documenting complex type structures\n- Cleaning up non-compliant comments (performance notes, timestamps, inline explanations)\n- Synchronizing out-of-sync TSDoc with code changes\n- Removing orphaned documentation for deleted code\n\n**Key Standard**: No `@example` sections - tests and stories serve as living examples.\n\n## Quick Reference\n\n- **Creating TSDoc**: See [workflow.md](references/workflow.md) for the generation workflow\n- **Maintaining TSDoc**: See [maintenance.md](references/maintenance.md) for cleanup and sync guidelines\n\nThis skill contains detailed templates for:\n- Public API Functions\n- Internal Module Documentation\n- Public and Internal Types\n- Helper Functions\n- Behavioral Programming Functions\n- Special Annotations (Security, Performance, Deprecated)\n- Type Documentation (Complex Objects, Unions, Functions, Utilities, Branded Types, etc.)\n\n## Navigation\n\n- [workflow.md](references/workflow.md) - TSDoc generation workflow (4 phases)\n- [maintenance.md](references/maintenance.md) - Comment policy, sync tasks, orphaned doc handling\n- [public-api-templates.md](references/public-api-templates.md) - Templates for public-facing APIs\n- [internal-templates.md](references/internal-templates.md) - Templates for internal code and modules\n- [type-documentation.md](references/type-documentation.md) - Comprehensive type documentation templates\n\n## Related Skills\n\n- **typescript-lsp**: Use for type verification and discovery during documentation workflow. Essential for Phase 1 (type analysis) and Phase 2 (usage discovery) of the TSDoc generation process. Run `lsp-hover` to verify signatures, `lsp-references` to find usages, and `lsp-symbols` to understand file structure.\n"},"lastSynced":"2026-03-08T02:09:01.113Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced TSDoc format documentation capabilities for comprehensive API documentation.","zh":"非常适合需要高级 TSDoc 格式文档能力以生成全面 API 文档的 Developer Agents。","ja":"包括的な API ドキュメントのための高度な TSDoc フォーマットのドキュメント機能を必要とする Developer Agents に最適です。","ko":"포괄적인 API 문서화를 위한 고급 TSDoc 형식 문서 기능이 필요한 Developer Agents에 완벽합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades de documentación avanzadas en formato TSDoc para una documentación de API completa.","fr":"Parfait pour les agents de développeur ayant besoin de capacités de documentation avancées au format TSDoc pour une documentation d''API complète.","de":"Perfekt für Entwickleragenten, die erweiterte TSDoc-Format-Dokumentationsfunktionen für umfassende API-Dokumentation benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de capacidades de documentação avançadas no formato TSDoc para documentação de API abrangente.","ru":"Идеально подходит для Агентов-Разработчиков, которым необходимы расширенные возможности документирования в формате TSDoc для всесторонней документации API.","ar":"مثالي لعميل المطور الذي يحتاج إلى إمكانات توثيق متقدمة بصيغة TSDoc لتوثيق وثائق API الشاملة."},"recommendation":{"en":"Empowers agents to write, edit, and review high-quality TSDoc comments for functions, types, and modules, ensuring compliance with TSDoc format templates and guidelines, and simplifying the process of creating and maintaining comprehensive API documentation using TSDoc comments.","zh":"赋能 Agent 编写、编辑和审查函数、类型和模块的高质量 TSDoc 注释，确保符合 TSDoc 格式模板和指南，并简化使用 TSDoc 注释创建和维护全面 API 文档的过程。","ja":"Agent が関数、型、モジュールの高品質な TSDoc コメントを書き、編集し、レビューすることを可能にし、TSDoc フォーマットのテンプレートとガイドラインへの準拠を確保します。さらに、TSDoc コメントを使用して包括的な API ドキュメントを作成および維持するプロセスを簡素化します。","ko":"Agent가 함수, 타입 및 모듈에 대한 고품질 TSDoc 주석을 작성, 편집 및 검토할 수 있도록 하여 TSDoc 형식 템플릿 및 가이드라인을 준수하도록 보장하고, TSDoc 주석을 사용하여 포괄적인 API 문서를 생성 및 유지 관리하는 프로세스를 단순화합니다.","es":"Habilita a los agentes a escribir, editar y revisar comentarios de alta calidad en TSDoc para funciones, tipos y módulos, garantizando el cumplimiento de las plantillas y directrices del formato TSDoc y simplificando el proceso de creación y mantenimiento de una documentación de API completa utilizando comentarios de TSDoc.","fr":"Permet aux agents d''écrire, de modifier et de réviser des commentaires TSDoc de haute qualité pour les fonctions, les types et les modules, en garantissant la conformité aux modèles et aux directives du format TSDoc et en simplifiant le processus de création et de maintenance d''une documentation d''API complète à l''aide de commentaires TSDoc.","de":"Ermächtigt Agenten, hochwertige TSDoc-Kommentare für Funktionen, Typen und Module zu schreiben, zu bearbeiten und zu überprüfen, wodurch die Einhaltung der TSDoc-Format-Vorlagen und -Richtlinien gewährleistet und der Prozess der Erstellung und Wartung einer umfassenden API-Dokumentation unter Verwendung von TSDoc-Kommentaren vereinfacht wird.","pt":"Habilita os agentes a escrever, editar e revisar comentários de alta qualidade TSDoc para funções, tipos e módulos, garantindo a conformidade com os modelos e diretrizes do formato TSDoc, e simplificando o processo de criação e manutenção de documentação de API abrangente usando comentários TSDoc.","ru":"Наделяет агентов возможностью писать, редактировать и проверять комментарии TSDoc высокого качества для функций, типов и модулей, обеспечивая соответствие шаблонам и рекомендациям формата TSDoc, и упрощая процесс создания и поддержания всесторонней документации API с помощью комментариев TSDoc.","ar":"يمنح الوكيل khảية كتابة وتحرير ومراجعة تعليقات TSDoc عالية الجودة للأدوار والأنواع والوحدات، وضمان الامتثال للقوالب والإرشادات لصيغة TSDoc، وبذلك يسهل عملية إنشاء وضمان توثيق API الشامل باستخدام تعليقات TSDoc."},"useCases":{"en":["Generating TSDoc comments for complex type structures","Reviewing and refining documentation quality","Synchronizing TSDoc comments with code changes","Cleaning up non-compliant comments and removing orphans"],"zh":["为复杂的类型结构生成 TSDoc 注释","审查和完善文档质量","使 TSDoc 注释与代码更改保持同步","清理不合规的注释并移除孤立注释"],"ja":["複雑な型構造に対する TSDoc コメントの生成","ドキュメント品質のレビューと改善","コード変更との TSDoc コメントの同期","非準拠のコメントのクリーンアップと孤立コメントの削除"],"ko":["복잡한 타입 구조에 대한 TSDoc 주석 생성","문서 품질 검토 및 개선","TSDoc 주석을 코드 변경 사항과 동기화","비준수 주석 정리 및 불필요한 주석 제거"],"es":["Generar comentarios de TSDoc para estructuras de tipo complejas","Revisar y refinar la calidad de la documentación","Sincronizar comentarios de TSDoc con cambios de código","Limpiar comentarios no cumplidores y eliminar huérfanos"],"fr":["Générer des commentaires TSDoc pour des structures de type complexes","Réviser et affiner la qualité de la documentation","Synchroniser les commentaires TSDoc avec les modifications de code","Nettoyer les commentaires non conformes et supprimer les orphelins"],"de":["Erzeugen von TSDoc-Kommentaren für komplexe Typstrukturen","Überprüfen und Verfeinern der Dokumentationsqualität","Synchronisieren von TSDoc-Kommentaren mit Codeänderungen","Bereinigen von nicht konformen Kommentaren und Entfernen von Waisen"],"pt":["Geração de comentários TSDoc para estruturas de tipo complexas","Revisão e refinamento da qualidade da documentação","Sincronização de comentários TSDoc com alterações de código","Limpeza de comentários não conformes e remoção de órfãos"],"ru":["Генерация комментариев TSDoc для сложных структур типов","Проверка и доработка качества документации","Синхронизация комментариев TSDoc с изменениями кода","Очистка неконформных комментариев и удаление сирот"],"ar":["إنشاء تعليقات TSDoc للهياكل المعقدة","مراجعة وتحسين جودة الوثائق","تنسيق تعليقات TSDoc مع التغييرات في الكود","تنظيف التعليقات غير المتوافقة وإزالة اليتم"]},"limitations":{"en":["Requires knowledge of TSDoc format","Limited to TypeScript-based projects","Dependent on accurate and up-to-date code changes"],"zh":["需要具备 TSDoc 格式的知识","仅限于基于 TypeScript 的项目","依赖于准确且最新的代码更改"],"ja":["TSDoc フォーマットの知識が必要","TypeScript ベースのプロジェクトに限定される","正確かつ最新のコード変更に依存"],"ko":["TSDoc 형식에 대한 지식 필요","TypeScript 기반 프로젝트로 제한됨","정확하고 최신의 코드 변경 사항에 의존"],"es":["Requiere conocimiento del formato TSDoc","Limitado a proyectos basados en TypeScript","Dependiente de cambios de código precisos y actualizados"],"fr":["Nécessite une connaissance du format TSDoc","Limité aux projets basés sur TypeScript","Dépendant de modifications de code précises et à jour"],"de":["Benötigt Kenntnisse des TSDoc-Formats","Begrenzt auf TypeScript-basierte Projekte","Abhängig von genauen und aktuellen Codeänderungen"],"pt":["Exige conhecimento do formato TSDoc","Limitado a projetos baseados em TypeScript","Dependente de alterações de código precisas e atualizadas"],"ru":["Требует знания формата TSDoc","Ограничен проектами на основе TypeScript","Зависит от точных и актуальных изменений кода"],"ar":["يتطلب معرفة صيغة TSDoc","محدود بمشاريع مبنية على TypeScript","يعتمد على تغييرات دقيقة ومحدّثة للكود"]},"version":4},"contentHash":"2fdcd79c975f7f75a29a2be45761f31b917b99ae2a8d265093c7b76ff6a3e538","qualityScore":26}');
