INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('youdotcom-oss/dx-toolkit/code-documentation', 'code-documentation', 'youdotcom-oss', 'dx-toolkit', 'community', 'code-documentation youdotcom-oss dx-toolkit community The code-documentation skill provides TSDoc format templates and guidelines for developers to create comprehensive API documentation. It helps developers write, edit, and review TSDoc comments for functions, types, and modules. 代码文档工具提供TSDoc格式模板、类型文档指南和维护工作流程，帮助开发者提高代码质量 コード文書化スキルは、TSDoc形式のテンプレート、タイプドキュメントのガイドライン、およびメンテナンスワークフローを提供し、開発者のコード品質を向上させます 코드 문서화 도구는 TSDoc 형식의 템플릿, 유형 문서 가이드라인 및 유지 관리 워크플로우를 제공하여 개발자의 코드 품질을 향상합니다 Un skill de IA Agents que proporciona plantillas TSDoc, directrices para documentación de tipos y flujos de mantenimiento. Automatiza la documentación de APIs y la sincronización con cambios en el código para funciones y módulos. Un skill AI Agents fournissant des modèles TSDoc, des directives pour la documentation des types et des workflows de maintenance. Automatise la documentation d''API et la synchronisation avec les changements de code. Ein AI Agents Skill, der TSDoc-Vorlagen, Richtlinien für Typendokumentation und Maintenance-Workflows bereitstellt. Automatisiert die API-Dokumentation und Synchronisation mit Code-Änderungen für Funktionen und Module. O skill de documentação de código fornece modelos de formato TSDoc, diretrizes de documentação de tipo e fluxos de trabalho de manutenção. Навык документации кода предоставляет шаблоны формата TSDoc, руководства по документации типов и рабочие процессы обслуживания. مهارة توثيق الشفرة توفر قوالب تنسيق TSDoc وإرشادات توثيق النوع وعمليات الصيانة. how to use code-documentation what is code-documentation code-documentation alternative code-documentation vs JSDoc code-documentation install code-documentation setup guide TSDoc template generation API documentation best practices code-documentation for AI agents 代码文档工具 AI辅助开发 TSDoc 类型文档 API文档 代码质量 开发效率 You.com AI Provides TSDoc format templates for functions, types, and modules Offers type documentation guidelines for complex type structures Supports synchronization of TSDoc comments with code changes Enables removal of non-compliant comments, such as performance notes and timestamps Facilitates creation of comprehensive API documentation Includes maintenance workflows for reviewing documentation quality Code-documentation is an open-source toolkit for integrating AI capabilities into workflows, providing TSDoc format templates and maintenance workflows for high-quality documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('filiphric/hydration-error-demo/replay-mcp', 'community', 'filiphric', 'hydration-error-demo', 'filiphric/hydration-error-demo', 'replay-mcp', 0, 0, 26, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:03.622Z', 'e0d8f93268bbfd0c78fd457fde8da90fe5884989f5748321fbe01d7be1f1e400', '{"id":"filiphric/hydration-error-demo/replay-mcp","name":"replay-mcp","description":{"en":"The replay-mcp skill enables AI Agents to inspect the contents of replay.io browser recordings. It provides tools for developers to investigate and answer precise questions about web application behavior by analyzing these perfect captures of browser sessions.","zh":"Replay MCP是一种用于调试浏览器录制的工具，能够详细分析应用行为","ja":"Replay MCPは、ブラウザレコーディングを調査するために使用されるツールであり、アプリケーションの動作を詳細に分析する","ko":"Replay MCP는 브라우저 녹화 파일을 분석하여 애플리케이션의 동작을 자세히 분석하는 도구입니다","es":"Replay MCP es una herramienta para inspeccionar grabaciones de aplicaciones web, permitiendo explorar y investigar el comportamiento de la app como si fuera un detective con una máquina del tiempo","fr":"Replay MCP est un outil pour inspecter les enregistrements d''applications web, permettant d''explorer et d''enquêter sur le comportement de l''application comme si vous étiez un détective avec une machine à remonter le temps","de":"Replay MCP ist ein Tool zur Untersuchung von Aufzeichnungen von Webanwendungen, ermöglicht die Exploration und Analyse des Verhaltens der App wie ein Detektiv mit einer Zeitmaschine","pt":"O Replay MCP é uma ferramenta para inspecionar gravações de aplicativos web, permitindo que você explore e investigue o comportamento do app","ru":"Replay MCP - инструмент для изучения записей веб-приложений, позволяющий исследовать и анализировать поведение приложения с помощью ИИ Агентов","ar":"Replay MCP هو أداة لفحص تسجيلات التطبيقات الويب، مما يسمح لك بفحص وسلوك التطبيق"},"seo":{"title":{"e