INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('filiphric/hydration-error-demo/replay-mcp', 'replay-mcp', 'filiphric', 'hydration-error-demo', 'community', 'replay-mcp filiphric hydration-error-demo community The replay-mcp skill enables AI Agents to inspect the contents of replay.io browser recordings. It provides tools for developers to investigate and answer precise questions about web application behavior by analyzing these perfect captures of browser sessions. Replay MCP是一种用于调试浏览器录制的工具，能够详细分析应用行为 Replay MCPは、ブラウザレコーディングを調査するために使用されるツールであり、アプリケーションの動作を詳細に分析する Replay MCP는 브라우저 녹화 파일을 분석하여 애플리케이션의 동작을 자세히 분석하는 도구입니다 Replay MCP es una herramienta para inspeccionar grabaciones de aplicaciones web, permitiendo explorar y investigar el comportamiento de la app como si fuera un detective con una máquina del tiempo Replay MCP est un outil pour inspecter les enregistrements d''applications web, permettant d''explorer et d''enquêter sur le comportement de l''application comme si vous étiez un détective avec une machine à remonter le temps Replay MCP ist ein Tool zur Untersuchung von Aufzeichnungen von Webanwendungen, ermöglicht die Exploration und Analyse des Verhaltens der App wie ein Detektiv mit einer Zeitmaschine O Replay MCP é uma ferramenta para inspecionar gravações de aplicativos web, permitindo que você explore e investigue o comportamento do app Replay MCP - инструмент для изучения записей веб-приложений, позволяющий исследовать и анализировать поведение приложения с помощью ИИ Агентов Replay MCP هو أداة لفحص تسجيلات التطبيقات الويب، مما يسمح لك بفحص وسلوك التطبيق what is replay-mcp how to use replay-mcp for debugging replay-mcp vs browser devtools replay-mcp alternative replay-mcp install guide replay-mcp setup for AI agents investigate replay.io recordings analyze browser session replays Replay MCP 浏览器录制调试 AI工具 应用行为分析 时间机器功能 Replay IO 调试工具 Inspects contents of replay.io browser recordings Analyzes perfect captures of web page visits Provides tools for investigating app behavior Enables answering precise questions about app functionality replay-mcp is an AI Agent skill used to inspect the contents of replay.io recordings. These recordings are perfect captures of browser sessions, allowing for detailed investigation of web app behavior as if using a time machine to debug issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('1zumIQ/asched_frontend/vue-debug-guides', 'community', '1zumIQ', 'asched_frontend', '1zumIQ/asched_frontend', 'vue-debug-guides', 0, 0, 26, '2026-03-08T01:57:15.464Z', '2026-03-08T02:09:20.718Z', 'f8762cac7766d6545a0fd4b0b2a50ce9fcde010a3c9e6bfb5198cace1ea851ed', '{"id":"1zumIQ/asched_frontend/vue-debug-guides","name":"vue-debug-guides","description":{"en":"This AI Agent skill provides targeted debugging guides for Vue 3 developers. It helps diagnose runtime warnings, async operation failures, and hydration bugs by referencing specific technical documentation like reactivity-debugging-hooks and watch-async-cleanup.","zh":"Vue.js 调试指南提供了 Vue 3 的错误处理和调试技术，帮助开发者优化应用性能和稳定性","ja":"Vue.js デバッグガイドでは、Vue 3 のエラーハンドリングとデバッグのテクニックを提供し、開発者がアプリのパフォーマンスと安定性を最適化できるようにします","ko":"Vue.js 디버깅 가이드는 Vue 3의 에러 핸들링 및 디버깅 기술을 제공하여 개발자가 애플리케이션의 성능 및 안정성을 최적화할 수 있도록 합니다","es":"Una skill de AI Agent especializada en diagnosticar y resolver problemas complejos de Vue.js 3. Cubre debugging de reactividad, manejo de errores asíncronos, warnings y corrección de bugs de hidratación durante el desarrollo.","fr":"Une compétence d''agent IA spécialisée dans le diagnostic et la résolution de problèmes complexes Vue.js 3. Couvre le débogage de la réactivité, la gestion des erreurs asynchrones, les avertissements et la correction des bugs d''hydratation.","de":"Eine KI-Agenten-Fähigkeit zur Diagnose und Lösung komplexer Vue.js 3-Probleme. Deckt Reactivity-Debugging, Behandlung von Async-Fehlern, Warnungen und die Behebung von Hydration-Bugs ab.","pt":"O guia de depuração Vue 3 fornece dicas e práticas para lidar com erros em tempo de execução e melhorar a reatividade da aplicação","ru":"Руководство по отладке Vue 3 предоставляет советы и лучшие практики для обработки ошибок во время выполнения и улучшения реактивности приложения","ar":"دليل تص